// modal-navigasi.js — Domain Modal Generik & Navigasi Halaman: modal konfirmasi/prompt/pilihan/info/pin
// Dipindah ke modules/shared/modal-navigasi.js (Sesi 17-18 restrukturisasi folder — lihat docs/FILE-MAP.md & RENCANA-SESI.md; isi & nama file TIDAK berubah, cuma lokasi folder).
// (askConfirm/showPromptModal/showChoiceModal/showAlertModal/showPinPromptModal & pasangan _xxxAnswer/_xxxSubmit-nya),
// buka/tutup modal & quick-switcher (openModal/closeModal/openQS/closeQS/_syncNavVisibilityForModals),
// swipe-to-dismiss modal (enableSwipeToDismiss), pindah halaman (showPage/refreshCurrentPage), dan
// collapse/expand kartu di halaman (toggleCardCollapse/applyOneCardCollapsePref/applyCardCollapsePrefs).
// Dipindah dari features-helpers-global-security.js (v71) — potongan KETIGA stlh kalkulator-input.js
// (v69) & keamanan-pin.js (v70). Blok ini dipilih krn 1 domain UI generik yang murni, kontigu (tidak
// diselang domain lain seperti 2 potongan sebelumnya), murni DOM + localStorage, TIDAK bergantung ke D
// atau state aplikasi lain sama sekali. Cuma 2 pengecualian aman: `closeModal()` cek
// `typeof WorthIt!=='undefined'` (guarded, pola lama) sebelum akses WorthIt.pendingBuyId, dan
// `showPage()` memanggil `renderPageContent()` (di modules-render.js, GROUP_A) lewat variabel global saat
// tombol nav diklik — bukan saat file dimuat. TIDAK ada kode top-level yang jalan sendiri saat file
// di-load (semua cuma deklarasi function/let).
// Dipanggil dari HAMPIR SEMUA file lain (askConfirm/openModal/closeModal dipakai di ~20 file, dst) —
// semua lewat nama global saat runtime (klik tombol / data-action di HTML / dalam fungsi lain), bukan
// referensi lokal ke file, jadi aman dipindah ke file sendiri.
// PENTING: file ini HARUS dimuat SETELAH features-helpers-global-security.js (butuh escapeHtml(), dipakai
// showChoiceModal utk render tombol pilihan).
//
// BUGFIX (audit "tombol Bayar/Riwayat macet, 0 toast", laporan user): kelima dialog custom
// di bawah (confirm/prompt/choice/alert/pin) dulu masing-masing cuma punya SATU variabel
// resolver module-scope (mis. `_confirmResolve`). Kalau fungsi show-nya terpanggil 2x
// sebelum jawaban pertama masuk (mis. double-tap tombol "Bayar" di layar sentuh -- SANGAT
// umum -- atau 2 alur berbeda yang kebetulan sama-sama minta konfirmasi), panggilan kedua
// MENIMPA resolver panggilan pertama: Promise pertama jadi orphan, tidak pernah
// resolve/reject, tidak ada error/toast (dispatcher klik di features-helpers-global-
// security.js cuma nangkep REJECT, bukan promise yang cuma diam menggantung selamanya).
// Fix: _queueDialog() di bawah menyimpan SEMUA permintaan (bukan cuma yang terakhir) di
// antrean per-jenis dialog; permintaan berikutnya BARU ditampilkan setelah yang sebelumnya
// dijawab, jadi tidak ada satupun Promise yang hilang/orphan. 0 perubahan pada pemanggil
// (askConfirm()/showPromptModal()/dst tetap 1 pemanggilan = 1 Promise seperti sebelumnya).
// BUGFIX (audit lanjutan v1026 — celah ScannerSession self-heal, laporan
// user "confirmModalOverlay tidak melewati openModal()"): v1026 memasang
// self-heal ScannerSession (ScannerSession.isActive(), lihat komentar
// lengkap di openModal() bawah) TAPI cuma di openModal(). 5 dialog custom
// (askConfirm/showPromptModal/showChoiceModal/showAlertModal/
// showPinPromptModal) semuanya TIDAK lewat openModal() -- overlay-nya
// langsung di-classList.add('open') sendiri lewat _queueDialog() di bawah.
// Kalau body.scanner-session-active nyangkut (skenario SAMA PERSIS spt
// fix v1026: proses tutup kamera scan terputus), dialog2 ini kena gejala
// identik -- classList 'open' sukses ditambahkan scr JS, tapi CSS
// _scannerSessionEnsureStyle() men-display:none!important overlay-nya DAN
// #toast, jadi dialog "macet total" tanpa jejak. Ini serius krn askConfirm()
// dipakai di ~20 file utk konfirmasi aksi DESTRUKTIF (hapus transaksi/akun/
// dll) -- user bisa kejebak tanpa jalan keluar selain reload penuh.
// Fix: 1 titik guard (_dialogSelfHeal()) dipanggil dari _queueDialog() --
// otomatis meng-cover SEMUA 5 dialog di atas krn semuanya lewat helper ini,
// dipanggil lagi di _resolveDialog() saat dialog berikutnya di antrean
// digilir (supaya self-heal juga jalan utk dialog yang sempat menunggu di
// antrean, bukan cuma dialog pertama). Pola SAMA PERSIS openModal()/
// showPage() (fix v1026) -- 0 perubahan API, 0 breaking change ke pemanggil
// existing (askConfirm()/showPromptModal()/dst tetap 1 pemanggilan = 1
// Promise seperti sebelumnya).
function _dialogSelfHeal(){
if(typeof ScannerSession!=='undefined' && ScannerSession && typeof ScannerSession.isActive==='function'){
ScannerSession.isActive();
}
}
// FIX (audit opacity-stuck-0): helper dipakai 5 dialog custom di bawah
// (askConfirm/showPromptModal/showChoiceModal/showAlertModal/showPinPromptModal),
// semuanya classList.add('open') langsung tanpa lewat openModal() -- pola identik
// yg kena race "animation overlayIn gagal terinstansiasi, opacity macet 0
// permanen" (lihat komentar lengkap di openModal()). Titik tunggal ini dipakai
// supaya fix-nya otomatis cover semua 5 dialog sekaligus.
function _openDialogOverlay(el){
el.classList.add('open');
void el.offsetWidth;
// FIX (audit UI/UX aksesibilitas keyboard, lanjutan sesi focus-trap
// openModal/closeModal): titik tunggal ini dipakai SEMUA 5 dialog custom
// (askConfirm/showPromptModal/showChoiceModal/showAlertModal/
// showPinPromptModal, lihat komentar di atas), jadi cukup 1 pemanggilan
// di sini utk cover semuanya sekaligus -- reuse penuh
// _focusTrapActivate() yang sudah ada (dipakai openModal() juga), 0 fungsi
// baru ditambah.
_focusTrapActivate(el);
}
function _queueDialog(store,renderFn){
return new Promise((resolve)=>{
store.queue.push({resolve,renderFn});
if(store.queue.length===1){ _dialogSelfHeal(); renderFn(); }
});
}
function _resolveDialog(store,overlayId,val){
const el=document.getElementById(overlayId);
el.classList.remove('open');
_focusTrapDeactivate(el);
const cur=store.queue.shift();
if(cur)cur.resolve(val);
if(store.queue.length) setTimeout(()=>{ _dialogSelfHeal(); store.queue[0].renderFn(); },0);
}
const _confirmStore={queue:[]};
function askConfirm(message,opts){
opts=opts||{};
return _queueDialog(_confirmStore,()=>{
document.getElementById('confirmModalIcon').textContent=opts.icon||'⚠️';
document.getElementById('confirmModalTitle').textContent=opts.title||'Konfirmasi';
document.getElementById('confirmModalMsg').textContent=message;
const okBtn=document.getElementById('confirmModalOk');
okBtn.textContent=opts.okText||'Ya, Lanjutkan';
okBtn.className='btn btn-full '+(opts.danger===false?'btn-primary':'btn-danger');
document.getElementById('confirmModalCancel').textContent=opts.cancelText||'Batal';
_openDialogOverlay(document.getElementById('confirmModalOverlay'));
});
}
function _confirmModalAnswer(val){
_resolveDialog(_confirmStore,'confirmModalOverlay',val);
}
const _promptStore={queue:[]};
function showPromptModal(opts){
opts=opts||{};
const overlay=document.getElementById('promptModalOverlay');
if(!overlay){ return Promise.resolve(prompt(opts.message||'',opts.defaultValue!=null?String(opts.defaultValue):'')); }
return _queueDialog(_promptStore,()=>{
overlay._validateFn=opts.validate||null;
document.getElementById('promptModalIcon').textContent=opts.icon||'✏️';
document.getElementById('promptModalTitle').textContent=opts.title||'Isi Data';
const msgEl=document.getElementById('promptModalMsg');
msgEl.textContent=opts.message||'';
msgEl.style.display=opts.message?'':'none';
const input=document.getElementById('promptModalInput');
input.type=opts.inputType||'text';
input.inputMode=opts.inputMode||(opts.inputType==='number'?'decimal':'text');
input.placeholder=opts.placeholder||'';
input.value=opts.defaultValue!=null?String(opts.defaultValue):'';
document.getElementById('promptModalError').textContent='';
document.getElementById('promptModalOkBtn').textContent=opts.okText||'Simpan';
document.getElementById('promptModalCancelBtn').textContent=opts.cancelText||'Batal';
_openDialogOverlay(overlay);
setTimeout(()=>{input.focus();input.select();},50);
});
}
function _promptModalSubmit(){
const overlay=document.getElementById('promptModalOverlay');
const input=document.getElementById('promptModalInput');
const val=input.value;
if(overlay._validateFn){
const err=overlay._validateFn(val);
if(err){ document.getElementById('promptModalError').textContent=err; return; }
}
_resolveDialog(_promptStore,'promptModalOverlay',val);
}
function _promptModalAnswer(val){
_resolveDialog(_promptStore,'promptModalOverlay',val);
}
const _choiceStore={queue:[]};
function showChoiceModal(opts){
opts=opts||{};
const choices=opts.choices||[];
const overlay=document.getElementById('choiceModalOverlay');
if(!overlay){
const pilihan=choices.map((c,i)=>`${i+1}. ${c.label}`).join('\n');
const idxStr=prompt((opts.message||'Pilih:')+'\n'+pilihan+'\n\nKetik nomor:','1');
if(idxStr===null)return Promise.resolve(null);
const idx=parseInt(idxStr)-1;
return Promise.resolve(choices[idx]?idx:null);
}
return _queueDialog(_choiceStore,()=>{
document.getElementById('choiceModalTitle').textContent=opts.title||'Pilih';
const msgEl=document.getElementById('choiceModalMsg');
msgEl.textContent=opts.message||'';
msgEl.style.display=opts.message?'':'none';
const list=document.getElementById('choiceModalList');
list.innerHTML=choices.map((c,i)=>`<button class="btn btn-ghost btn-full" style="justify-content:flex-start;text-align:left" data-action="_choiceModalAnswer" data-args="${escapeHtml(JSON.stringify([i]))}">${escapeHtml(c.label)}</button>`).join('');
_openDialogOverlay(document.getElementById('choiceModalOverlay'));
});
}
function _choiceModalAnswer(idx){
_resolveDialog(_choiceStore,'choiceModalOverlay',idx);
}
const _infoStore={queue:[]};
function showAlertModal(message,opts){
opts=opts||{};
const overlay=document.getElementById('infoModalOverlay');
if(!overlay){ alert(message); return Promise.resolve(); }
return _queueDialog(_infoStore,()=>{
document.getElementById('infoModalIcon').textContent=opts.icon||'⚠️';
document.getElementById('infoModalTitle').textContent=opts.title||'Perhatian';
document.getElementById('infoModalMsg').textContent=message;
document.getElementById('infoModalOk').textContent=opts.okText||'Mengerti';
_openDialogOverlay(overlay);
});
}
function _infoModalAnswer(){
_resolveDialog(_infoStore,'infoModalOverlay',true);
}
const _pinPromptStore={queue:[]};
function showPinPromptModal(opts){
opts=opts||{};
const overlay=document.getElementById('pinPromptModalOverlay');
if(!overlay){ return Promise.resolve(prompt(opts.message||'PIN baru (4 digit):')); }
return _queueDialog(_pinPromptStore,()=>{
document.getElementById('pinPromptModalTitle').textContent=opts.title||'Ganti PIN';
document.getElementById('pinPromptModalMsg').textContent=opts.message||'Masukkan PIN baru (4 digit angka)';
const input=document.getElementById('pinPromptInput');
input.value='';
document.getElementById('pinPromptError').textContent='';
_openDialogOverlay(overlay);
setTimeout(()=>input.focus(),50);
});
}
function _pinPromptSubmit(){
const input=document.getElementById('pinPromptInput');
const val=(input.value||'').trim();
if(val.length!==4){ document.getElementById('pinPromptError').textContent='PIN harus 4 digit angka.'; return; }
_resolveDialog(_pinPromptStore,'pinPromptModalOverlay',val);
}
function _pinPromptAnswer(val){
_resolveDialog(_pinPromptStore,'pinPromptModalOverlay',val);
}
// AUDIT UI/UX 2026-08 (bug: "klik tab Laporan tidak mengarah ke data yang
// sedang ditampilkan", laporan user, + audit menyeluruh lanjutan): SEMUA
// fungsi ganti-subtab di app ini (setLaporanTab/setKelolaTab/setAsetTab/
// setCnInsightTab/setCnBbmTab/setPjkTab/setKeuanganTab/setShopTab/setCnTab/
// setPajakTab/setSettingsTab/setBillListTab/BudgetTabs.switchTo/
// DashboardHub.applySectionTab) murni toggle class 'u-dnone' -- TIDAK
// PERNAH scroll ke tombol/tab yang baru aktif. Kalau user sudah scroll
// turun sebelum klik, halaman tetap di posisi scroll lama & konten baru
// bisa jatuh di luar viewport -- kelihatan seperti klik "tidak ngefek".
// Helper generik, dipanggil dari 14 titik di atas dgn tombol yang baru
// jadi aktif -- diberi 2 lapis guard (typeof method + try/catch) supaya
// aman dipanggil dari sandbox test manapun (banyak test pakai fake
// document/element minimal yang tidak selalu punya scrollIntoView) tanpa
// perlu tahu detail tiap mock. 0 perubahan DOM/behaviour lain.
function scrollTabBarIntoView(el){
// S679 (rekomendasi #3 audit S677): tambah flash-highlight setelah scroll,
// pola SAMA PERSIS dgn goToList()/DashboardHub.jumpToTarget() (remove ->
// void offsetWidth (force reflow) -> add -> setTimeout remove 1200ms).
// Ditaruh DI SINI (1 titik, bukan diulang di 14 fungsi pemanggil) supaya
// otomatis berlaku ke semua 14 titik ganti-tab yang sudah panggil helper
// ini -- 0 perubahan di 14 fungsi tsb.
try{
if(el && typeof el.scrollIntoView==='function'){
const run=()=>{
try{ el.scrollIntoView({behavior:'smooth',block:'start'}); }catch(e){}
try{
if(el.classList && typeof el.classList.add==='function'){
el.classList.remove('flash-highlight');
void el.offsetWidth;
el.classList.add('flash-highlight');
if(typeof setTimeout==='function') setTimeout(()=>{ try{ el.classList.remove('flash-highlight'); }catch(e){} },1200);
}
}catch(e){}
};
if(typeof requestAnimationFrame==='function') requestAnimationFrame(run);
else run();
}
}catch(e){}
}
function showPage(name,el){
// BUGFIX (audit "semua tombol di Car Notes tidak respon", laporan user, v1025):
// root cause -- showPage() (dipanggil tiap pindah tab bawah) TIDAK PERNAH
// membersihkan overlay/modal yang masih class="open" (mis. catalogModal
// ditinggal terbuka krn user pindah tab lewat nav/gesture back, bukan lewat
// tombol ✕ / closeModal() eksplisit). Overlay itu full-viewport & selalu di
// atas konten halaman manapun -- dispatcher klik global
// (features-helpers-global-security.js) resolve lewat
// e.target.closest('[data-action]'); overlay yg nyangkut selalu jadi target
// duluan & TIDAK match [data-action], jadi handler `return` diam-diam (nol
// error, nol toast) utk SEMUA tombol di halaman manapun, bukan cuma tab yg
// sedang dibuka. Fix: paksa tutup semua overlay yg masih 'open'/'closing'
// tiap kali user pindah tab bawah -- pindah tab = keluar dari konteks modal
// manapun, jadi aman ditutup paksa tanpa animasi (bukan closeModal() biasa,
// supaya tidak nunggu 260ms/animationend & tidak konflik state modal lain).
document.querySelectorAll('.overlay.open,.calc-overlay.open,.qs-modal-overlay.open').forEach(o=>{
o.classList.remove('open');
o.classList.remove('closing');
});
document.body.classList.remove('has-open-modal');
// BUGFIX (audit video user -- lihat komentar dismissAllToasts() di
// modules/shared/format-tema.js): toast basi dari halaman sebelumnya bisa
// tetap tampil/mengantre & menutupi tombol di halaman/tab baru. Titik ini
// (showPage, dipanggil tiap pindah tab bawah) pola sama dgn paksa-tutup
// overlay yg nyangkut di atas -- pindah tab = keluar dari konteks toast lama,
// aman dibersihkan tanpa animasi.
if(typeof dismissAllToasts==='function')dismissAllToasts();
// BUGFIX (audit "semua tombol Car Notes & Tagihan tidak respon, 0 toast",
// laporan user): ScannerSession bisa nyangkut _scannerSessionActive=true
// permanen kalau proses tutup kamera terputus (app di-minimize saat prompt
// izin kamera, tab di-suspend, dll) -- lihat modules/shared/scanner-session.js.
// Selama itu, body.scanner-session-active nempel & CSS
// (_scannerSessionEnsureStyle) men-display:none SEMUA .overlay/.qs-modal-
// overlay/.calc-overlay/.keu-fab/#toast SELAMANYA -- termasuk toast error
// dispatcher sendiri, jadi tombol kelihatan "mati total" tanpa jejak apa pun.
// Self-heal (_scannerSessionSelfHeal) sebelumnya CUMA jalan lewat
// ScannerSession.enter()/isActive(), yang cuma dipanggil saat user coba buka
// scanner LAGI -- kalau user cuma pindah tab (showPage(), seperti di laporan
// ini), state nyangkut ini tidak pernah ke-heal. Fix: panggil isActive() di
// sini juga -- pindah tab = titik aman utk self-heal (bukan lagi dalam
// konteks scanner manapun), 0 perubahan API ScannerSession, 0 breaking
// change ke pemanggil existing.
if(typeof ScannerSession!=='undefined' && ScannerSession && typeof ScannerSession.isActive==='function'){
ScannerSession.isActive();
}
document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));
document.querySelectorAll('.nav-item').forEach(n=>{n.classList.remove('active');n.setAttribute('aria-current','false');});
const pageEl=document.getElementById('page-'+name);
if(!pageEl){
console.warn(`showPage: halaman #page-${name} tidak ditemukan di DOM -- cek nama page/id (mis. typo, atau halaman belum dirender).`);
return;
}
pageEl.classList.add('active');
const activeBtn=el||document.querySelector(`.nav-item[onclick*="'${name}'"]`);
if(activeBtn){activeBtn.classList.add('active');activeBtn.setAttribute('aria-current','page');}
renderPageContent(name);
const sr=document.getElementById('scrollRoot');
if(sr)sr.scrollTop=0;
}
/* moved to modules-render.js: renderPageContent */
function refreshCurrentPage(){
const active=document.querySelector('.page.active');
if(!active)return;
renderPageContent(active.id.replace('page-',''));
}
function _syncNavVisibilityForModals(){
const anyOpen=document.querySelector('.overlay.open,.qs-modal-overlay.open,.calc-overlay.open');
document.body.classList.toggle('has-open-modal',!!anyOpen);
}
// FOCUS TRAP (audit UI/UX aksesibilitas keyboard, Agustus 2026): sebelum ini,
// Tab/Shift+Tab masih bisa "bocor" dari dalam modal ke elemen di belakang
// overlay (elemen halaman yang tertutup visual tapi tetap ada di DOM & masih
// fokusable) — menyulitkan pengguna keyboard/screen reader, fokus terasa
// hilang/lompat tak terduga. Implementasi MINIMAL & additive: TIDAK mengubah
// alur openModal()/closeModal() yang sudah ada (cuma 1 baris panggilan
// ditambah di titik yang sudah ada, lihat _focusTrapActivate/_focusTrapDeactivate
// di bawah), 0 perubahan pada pemanggil openModal/closeModal di file lain.
// Ditumpuk pakai array (bukan 1 variabel tunggal) supaya modal bertumpuk
// (lihat komentar `_stacked` di openModal() bawah) tetap benar: Tab dikunci
// ke modal PALING ATAS saja, & saat modal teratas ditutup, trap otomatis
// kembali berlaku ke modal di bawahnya kalau masih ada yg terbuka.
// Cakupan sengaja dibatasi ke openModal()/closeModal() (modal fitur generik)
// dulu di sesi ini — 5 dialog custom (askConfirm/showPromptModal/
// showChoiceModal/showAlertModal/showPinPromptModal) yang lewat
// _queueDialog() BELUM disentuh, supaya perubahan tetap kecil & mudah
// diverifikasi. Bisa disusulkan sesi terpisah kalau audit ini terbukti aman.
const _focusTrapStack=[];
function _focusTrapFocusableEls(container){
if(!container||typeof container.querySelectorAll!=='function')return [];
return Array.prototype.slice.call(container.querySelectorAll(
'a[href],button:not([disabled]),textarea:not([disabled]),input:not([disabled]),select:not([disabled]),[tabindex]:not([tabindex="-1"])'
)).filter(function(el){return !!(el.offsetWidth||el.offsetHeight||el.getClientRects().length);});
}
function _focusTrapKeydown(e){
if(e.key!=='Tab')return;
const top=_focusTrapStack[_focusTrapStack.length-1];
if(!top)return;
const focusables=_focusTrapFocusableEls(top.container);
if(!focusables.length)return;
const first=focusables[0],last=focusables[focusables.length-1];
if(e.shiftKey && document.activeElement===first){
e.preventDefault();last.focus();
}else if(!e.shiftKey && document.activeElement===last){
e.preventDefault();first.focus();
}
}
function _focusTrapActivate(container){
if(!container)return;
_focusTrapStack.push({container:container,lastFocused:document.activeElement});
if(_focusTrapStack.length===1){
document.addEventListener('keydown',_focusTrapKeydown,true);
}
const focusables=_focusTrapFocusableEls(container);
if(focusables.length){
focusables[0].focus();
}else if(typeof container.focus==='function'){
if(typeof container.setAttribute==='function'&&(typeof container.hasAttribute!=='function'||!container.hasAttribute('tabindex')))container.setAttribute('tabindex','-1');
container.focus();
}
}
function _focusTrapDeactivate(container){
const idx=_focusTrapStack.map(function(x){return x.container;}).lastIndexOf(container);
if(idx===-1)return;
const entry=_focusTrapStack[idx];
_focusTrapStack.splice(idx,1);
if(_focusTrapStack.length===0){
document.removeEventListener('keydown',_focusTrapKeydown,true);
}
if(entry.lastFocused && typeof entry.lastFocused.focus==='function' && document.contains(entry.lastFocused)){
try{entry.lastFocused.focus();}catch(e){}
}
}
function openModal(id){
const el=document.getElementById(id);
if(!el){
console.warn(`Modal #${id} tidak ditemukan di DOM — cek document.write index (lihat modals.js MODAL_HTML[] vs document.write(MODAL_HTML[i]) di index.html/app_production.html, urutan/jumlahnya harus persis sama).`);
return;
}
// FIX (audit: openModal() langsung dari tombol, mis. openVehicleModal()/
// VehicleCatalogUI.open(), tanpa lewat showPage() dulu — laporan user "tab
// Kelola Kendaraan/Katalog Suku Cadang tidak respon, 0 toast"): self-heal
// ScannerSession SEBELUMNYA cuma dipanggil dari showPage() (pindah tab) atau
// ScannerSession.enter() (coba buka scanner lagi) — kalau _scannerSessionActive
// nyangkut true (kamera scan kependam: izin ditolak/app di-minimize/tab
// di-suspend saat scan) TAPI user cuma tap tombol buka modal biasa (bukan
// pindah tab, bukan buka scanner), state nyangkut ini tidak pernah ke-heal.
// Akibatnya el.classList.add('open') di bawah tetap jalan (modal "berhasil"
// dibuka secara JS), tapi CSS body.scanner-session-active memaksa
// display:none ke SEMUA .overlay.open DAN #toast (lihat
// scanner-session.js/_scannerSessionEnsureStyle) — user tidak lihat modal
// atau toast apa pun. Fix: panggil isActive() di sini juga, pola SAMA PERSIS
// showPage() — 0 perubahan API ScannerSession, 0 breaking change.
if(typeof ScannerSession!=='undefined' && ScannerSession && typeof ScannerSession.isActive==='function'){
ScannerSession.isActive();
}
// FIX (audit: race condition scan-ocr.js async vs pindah record) — naikkan
// epoch tiap modal dibuka (termasuk dibuka ULANG utk record berbeda, mis. edit
// Tagihan A lalu edit Tagihan B, sama-sama lewat openBillModal->openModal
// 'billModal'). scan-ocr.js pakai epoch ini utk tahu kalau OCR yang sedang
// berjalan sudah "basi" krn modal/record sudah berpindah sebelum hasil scan
// selesai -- lihat komentar lengkap di _scanEpochNow()/_scanEpochStale().
window._modalEpoch=(window._modalEpoch||0)+1;
// FIX (audit "dropdown Pilih Pemilik tidak bisa dipilih", laporan user Agustus
// 2026): kalau modal ini dibuka SEBAGAI TUMPUKAN di atas modal lain yang masih
// terbuka (mis. assetOwnersModal dari dalam assetModal -- lihat
// Aset.openOwnersModal()), tandai `.modal` di dalamnya dengan class `.no-anim`
// (lihat styles.css) supaya animasi slideUp/transform TIDAK dipasang -- mencegah
// compositing layer tumpukan yang jadi pemicu native <select> di dalamnya gagal
// merespons tap opsi selain opsi yang sedang aktif. Modal yang dibuka sendirian
// (tanpa modal lain yang masih `.open`) tidak terpengaruh sama sekali -- animasi
// tetap seperti semula. querySelector('.overlay.open') dicek SEBELUM class
// 'open' baru ditambahkan ke `el` di bawah, supaya `el` sendiri tidak ikut
// terhitung sebagai "modal lain yang masih terbuka".
const _stacked=!!document.querySelector('.overlay.open');
const _modalInner=(typeof el.querySelector==='function')?el.querySelector('.modal'):null;
if(_modalInner)_modalInner.classList.toggle('no-anim',_stacked);
el.classList.remove('closing');
el.classList.add('open');
// FIX (audit opacity-stuck-0, laporan user "vehicleModal keluar tapi opacity 0
// permanen walau display:flex & class .open benar, prefers-reduced-motion OFF"):
// .overlay.open melakukan 2 perubahan sekaligus dlm 1 rule yg sama, dipicu 1
// classList.add('open') ini -- display:none->flex DAN mulai animasi CSS overlayIn
// (opacity 0->1). Kalau browser sempat menggabungkan 2 perubahan itu jadi 1 style
// recalc (tanpa reflow di antaranya), instansiasi Animation utk overlayIn bisa
// gagal total: computed style tetap "mengaku" animationName:overlayIn &
// animationPlayState:running (krn itu cuma refleksi rule CSS yg match), TAPI
// el.getAnimations() kosong & currentTime tidak pernah maju -- elemen macet
// permanen di keyframe from{opacity:0}. Fix: paksa 1 synchronous reflow di
// antara display berubah & animasi mulai, supaya browser tidak sempat
// menggabungkan 2 perubahan itu. void sengaja dipakai supaya linter/minifier
// tidak membuang baris ini krn dikira "unused expression" -- efek sampingnya
// (memaksa reflow) yg memang dibutuhkan, bukan nilainya.
void el.offsetWidth;
_syncNavVisibilityForModals();
_focusTrapActivate(el);
}
// CARD_COLLAPSE_DEFAULT_CLOSED (Sesi 156b, permintaan eksplisit user):
// key card yang defaultnya TERTUTUP kalau user belum pernah tap toggle-nya
// sama sekali (belum ada entry di localStorage cardCollapsePrefs). Card di
// luar daftar ini defaultnya tetap TERBUKA seperti sebelumnya (0 perubahan
// perilaku). Reuse penuh mekanisme toggleCardCollapse/localStorage yang
// sudah ada — TIDAK ada storage/mekanisme collapse baru, cuma nilai default
// saat prefs[key] belum pernah diset.
const CARD_COLLAPSE_DEFAULT_CLOSED=['vehAnalyticsCard','fuelDashCard','fuelCompareCard','fuelTrendCard'];
function _cardCollapseShouldBeCollapsed(key,prefs){
if(Object.prototype.hasOwnProperty.call(prefs,key))return !!prefs[key];
return CARD_COLLAPSE_DEFAULT_CLOSED.indexOf(key)!==-1;
}
function toggleCardCollapse(key,ev){
if(ev)ev.stopPropagation();
const body=document.getElementById(key+'-cbody');
const chev=document.getElementById(key+'-chev');
if(!body)return;
const collapsed=body.classList.toggle('collapsed');
if(chev)chev.classList.toggle('collapsed',collapsed);
try{
const prefs=JSON.parse(localStorage.getItem('cardCollapsePrefs')||'{}');
prefs[key]=collapsed;
localStorage.setItem('cardCollapsePrefs',JSON.stringify(prefs));
}catch(e){ }
}
function applyOneCardCollapsePref(key){
let prefs={};
try{prefs=JSON.parse(localStorage.getItem('cardCollapsePrefs')||'{}');}catch(e){}
const body=document.getElementById(key+'-cbody');
const chev=document.getElementById(key+'-chev');
if(_cardCollapseShouldBeCollapsed(key,prefs)){
if(body)body.classList.add('collapsed');
if(chev)chev.classList.add('collapsed');
}else{
if(body)body.classList.remove('collapsed');
if(chev)chev.classList.remove('collapsed');
}
}
function applyCardCollapsePrefs(){
let prefs={};
try{prefs=JSON.parse(localStorage.getItem('cardCollapsePrefs')||'{}');}catch(e){}
const keys=new Set(Object.keys(prefs).concat(CARD_COLLAPSE_DEFAULT_CLOSED));
keys.forEach(key=>applyOneCardCollapsePref(key));
}
function closeModal(id){
const el=document.getElementById(id);
if(!el)return;
if(id==='txModal'&&typeof WorthIt!=='undefined'&&WorthIt.pendingBuyId){
WorthIt.pendingBuyId=null;
}
if(el.classList.contains('closing'))return;
el.classList.add('closing');
_focusTrapDeactivate(el);
let done=false;
function finish(){
if(done)return;
done=true;
if(el.removeEventListener)el.removeEventListener('animationend',onAnimEnd);
// Kalau di antara closeModal() & sini modal ini sempat dibuka lagi
// (openModal melepas class 'closing'), jangan ikut menutup modal yang
// baru saja dibuka ulang itu.
if(el.classList.contains('closing')){
el.classList.remove('open');
el.classList.remove('closing');
_syncNavVisibilityForModals();
}
}
function onAnimEnd(e){ if(e.target===el)finish(); }
if(el.addEventListener)el.addEventListener('animationend',onAnimEnd);
setTimeout(finish,260);
}
function enableSwipeToDismiss(overlayId){
const overlay=document.getElementById(overlayId);
if(!overlay)return;
const sheet=overlay.querySelector('.modal');
const handle=overlay.querySelector('.modal-handle');
if(!sheet||!handle)return;
const THRESHOLD=90;
let startY=0,lastDy=0,dragging=false;
function pointY(e){return e.touches?e.touches[0].clientY:e.clientY;}
function onStart(e){
dragging=true;
startY=pointY(e);
lastDy=0;
sheet.style.transition='none';
}
function onMove(e){
if(!dragging)return;
const dy=pointY(e)-startY;
if(dy<=0)return;
lastDy=dy;
sheet.style.transform=`translateY(${dy}px)`;
}
function onEnd(){
if(!dragging)return;
dragging=false;
sheet.style.transition='transform 0.2s ease';
if(lastDy>THRESHOLD){
sheet.style.transform='translateY(100%)';
setTimeout(()=>{ closeModal(overlayId); sheet.style.transform=''; },160);
} else {
sheet.style.transform='';
}
lastDy=0;
}
handle.addEventListener('touchstart',onStart,{passive:true});
handle.addEventListener('touchmove',onMove,{passive:true});
handle.addEventListener('touchend',onEnd);
handle.addEventListener('touchcancel',onEnd);
handle.addEventListener('mousedown',onStart);
window.addEventListener('mousemove',onMove);
window.addEventListener('mouseup',onEnd);
}
// BUGFIX (audit lanjutan v1026, sama persis kasus _queueDialog() di atas):
// openQS() juga langsung classList.add('open') tanpa lewat openModal(),
// jadi Quick Switcher kena celah self-heal ScannerSession yang sama.
function openQS(id){
_dialogSelfHeal();
const el=document.getElementById(id);
el.classList.add('open');
void el.offsetWidth; // FIX opacity-stuck-0: pola sama persis openModal(), lihat komentar lengkap di sana
_syncNavVisibilityForModals();
}
function closeQS(id){document.getElementById(id).classList.remove('open');_syncNavVisibilityForModals();}

// SARAN (dari review sebelumnya): dukung tombol Escape utk nutup modal, tidak cuma tap ✕/backdrop.
// Urutan prioritas: kalkulator popup (di atas modal lain) -> quick-switcher (qsXxx) -> modal
// sistem generik (confirm/prompt/choice/info/pinPrompt -- ini WAJIB lewat resolver `_xxxAnswer`-nya
// masing2, BUKAN closeModal() biasa, supaya Promise yg lagi nunggu (await askConfirm(), dst) tetap
// ke-resolve, bukan nge-hang selamanya) -> modal fitur generik (.overlay.open biasa, dipilih yg
// z-index paling tinggi kalau lebih dari 1 yg terbuka bertumpuk, spt renovItemModal di atas
// renovDetailModal). Escape TIDAK dipakai kalau fokus lagi di input/textarea yg sedang autocomplete
// suggest-box terbuka (biar tidak nutup modal saat user cuma mau tutup dropdown saran).
document.addEventListener('keydown', function(e){
if(e.key!=='Escape')return;
const calc=document.getElementById('calcModal');
if(calc&&calc.classList.contains('open')){ closeCalc(); return; }
const qs=document.querySelector('.qs-modal-overlay.open');
if(qs){ closeQS(qs.id); return; }
const pinPrompt=document.getElementById('pinPromptModalOverlay');
if(pinPrompt&&pinPrompt.classList.contains('open')){ _pinPromptAnswer(null); return; }
const promptM=document.getElementById('promptModalOverlay');
if(promptM&&promptM.classList.contains('open')){ _promptModalAnswer(null); return; }
const choiceM=document.getElementById('choiceModalOverlay');
if(choiceM&&choiceM.classList.contains('open')){ _choiceModalAnswer(null); return; }
const confirmM=document.getElementById('confirmModalOverlay');
if(confirmM&&confirmM.classList.contains('open')){ _confirmModalAnswer(false); return; }
const infoM=document.getElementById('infoModalOverlay');
if(infoM&&infoM.classList.contains('open')){ _infoModalAnswer(); return; }
const openOverlays=Array.from(document.querySelectorAll('.overlay.open'));
if(!openOverlays.length)return;
openOverlays.sort((a,b)=>(parseInt(getComputedStyle(b).zIndex)||0)-(parseInt(getComputedStyle(a).zIndex)||0));
closeModal(openOverlays[0].id);
});

// PD-007 (docs/PRODUCT_DECISIONS.md "Scanner — Exclusive Scanner Mode via
// ScannerSession"): blok DOM-Detection reaktif yang dulu ada di sini
// (MutationObserver + document.querySelector('video') + setInterval 400ms +
// class body 'camera-scan-active', dipasang utk mencegah preview kamera
// scanner ketiban modal/toast lain yang masih 'open' -- lihat riwayat bugfix
// di CHANGELOG) DIHAPUS & digantikan ScannerSession.pauseUI()/resumeUI()
// (modules/shared/scanner-session.js), dipanggil EKSPLISIT dari
// ScannerSession.enter()/exit() -- satu-satunya titik masuk/keluar scanner
// (VehicleScanner.scan()/SparepartScanner.scan() & scanner masa depan).
// State "scanner aktif" sekarang eksplisit (di-set enter()/exit() sendiri),
// bukan lagi ditebak dari keberadaan elemen <video> di DOM.

// openShopKatalogDinamis() — trigger tipis utk modal shopKatalogDinamisModal
// (modals.js) + render pertama ShopKatalogDinamisPresenter (modules/vehicle/
// shop-katalog-dinamis-presenter.js). 100% REUSE openModal() yang SUDAH ADA
// di atas — TIDAK ada mekanisme modal baru dibuat.
function openShopKatalogDinamis(){
  openModal('shopKatalogDinamisModal');
  if (typeof ShopKatalogDinamisPresenter !== 'undefined') ShopKatalogDinamisPresenter.render();
}

// modules/shared/scanner-session.js — ScannerSession (Tahap 5, docs/
// PRODUCT_DECISIONS.md § "Scanner — Exclusive Scanner Mode via ScannerSession
// (FINAL — Sesi 316, PD-007)").
//
// PD-007 — Scanner WAJIB berjalan lewat ScannerSession.enter()/exit():
// - Ini SATU-SATUNYA titik masuk/keluar utk membuka scanner apa pun
//   (VehicleScanner, SparepartScanner, & scanner masa depan) — tidak ada
//   jalur lain yang boleh suspend/resume UI global (modal/toast/dashboard)
//   di luar file ini.
// - Scanner Engine (lapisan ZXing/decode di vehicle-scanner.js/
//   sparepart-scanner.js) TIDAK BOLEH menyentuh modal/toast/dashboard sama
//   sekali lagi — tanggung jawab itu 100% pindah ke sini. Alur wajib:
//     ScannerSession.enter()  ->  Scanner.start() (mis. VehicleScanner.scan())
//     ->  ScannerSession.exit()
// - State "scanner aktif" adalah state EKSPLISIT (_active di bawah), di-set
//   sendiri oleh enter()/exit() — BUKAN disimpulkan dari keberadaan elemen
//   <video> di DOM (itu cara lama yang diganti, lihat catatan di
//   modules/shared/modal-navigasi.js soal blok camera-scan-active yang
//   dihapus sesi ini).
// - Urutan enter(): suspend UI global (pauseUI()) dulu, BARU scanner engine
//   boleh membangun overlay & mulai decode. Urutan exit(): scanner engine
//   teardown dulu (overlay sudah dilepas SEBELUM exit() dipanggil), baru UI
//   global di-resume (resumeUI()) — kebalikan dari enter(), supaya tidak ada
//   jendela waktu di mana keduanya aktif bersamaan.
//
// pauseUI()/resumeUI() REUSE PENUH teknik yang sudah ada sebelum sesi ini
// (vehicleScannerHideChrome()/vehicleScannerRestoreChrome() di
// vehicle-scanner.js, & style injection ala _camScanFixStyle di
// modal-navigasi.js) — 0 CSS/selector baru, cuma dipindah ke sini & dipanggil
// EKSPLISIT (bukan lewat MutationObserver/setInterval/querySelector('video')
// lagi).
//
// HOTFIX Scanner Session/FAB (lanjutan Tahap 6): FAB (`.keu-fab`,
// position:fixed — keuFab/shopFab/laporanFab/shopLaporanFab/carNotesFab, dst)
// ikut disembunyikan pauseUI() & dikembalikan resumeUI(), pola & guard SAMA
// PERSIS #mainNav/#mainHeader (simpan style.display asli, restore persis,
// idempotent). TIDAK ada ID FAB yang di-hardcode — pakai
// `document.querySelectorAll('.keu-fab')` supaya FAB apa pun (termasuk yang
// ditambah di masa depan) otomatis tercakup. 0 perubahan API publik
// ScannerSession, 0 perubahan ke enter()/exit()/isActive(), 0 sentuhan ke
// Scanner Engine (vehicle-scanner.js/sparepart-scanner.js) atau modals.js.

let _scannerSessionActive = false;
let _scannerSessionPrevChrome = null;

// AUDIT (Reference Counter): enter()/exit() DULU murni boolean (_active),
// jadi rentan race kalau ada 2 pemanggil yang saling tidak tahu (mis.
// sparepartScannerScan() orkestrasi enter() lalu adapter camera-nya sendiri
// juga sempat enter() di path lain) — exit() pertama yang jalan akan
// langsung resumeUI() walau pemanggil lain masih menganggap sesi aktif.
// Sekarang pakai internal reference counter (_scannerSessionCount):
// enter() menaikkan counter, HANYA pauseUI() kalau counter naik dari 0->1;
// exit() menurunkan counter, HANYA resumeUI() kalau counter turun ke 0.
// Public API TIDAK berubah (enter()/exit()/isActive() tetap sama, tetap
// return boolean) — murni penguatan internal, 0 breaking change ke
// pemanggil existing (vehicle-scanner.js/sparepart-scanner.js).
let _scannerSessionCount = 0;

// AUDIT (lanjutan PD-007): CSS sekarang jadi mekanisme UTAMA utk
// menyembunyikan overlay & FAB selama Exclusive Scanner Mode aktif — bukan
// lagi JS snapshot/restore per elemen (pola lama _scannerSessionQueryFabs()+
// _scannerSessionPrevFabDisplay yang DIHAPUS sesi ini). Alasan: selector
// generik (`.overlay.open`, `.keu-fab`, dst) otomatis meng-cover elemen yang
// di-mount SETELAH enter() dipanggil (mis. FAB/modal baru), yang TIDAK bisa
// dicover snapshot sekali-jalan berbasis querySelectorAll di pauseUI().
// pauseUI()/resumeUI() jadi HANYA menangani state global sejati (toggle
// class body + #mainNav/#mainHeader, yang memang butuh restore nilai
// display ASLI, bukan sekadar '' vs 'none').
//
// Selector diperluas dari `.overlay.open` saja jadi mencakup SEMUA varian
// overlay/modal fixed yang ada di app (root cause bug ditemukan saat audit:
// `.qs-modal-overlay` & `.calc-overlay` PAKAI CLASS BERBEDA dari `.overlay`,
// jadi TIDAK ke-cover rule lama — modal QuickSelect/Kalkulator bisa tetap
// aktif di belakang scanner). Child combinator `>` juga DIHAPUS (rule lama
// `body.scanner-session-active > .overlay.open` cuma match kalau `.overlay`
// direct child <body> — modal yang nested di wrapper lain lolos dari
// suppression).
function _scannerSessionEnsureStyle() {
  if (document.getElementById('_scannerSessionStyle')) return;
  const style = document.createElement('style');
  style.id = '_scannerSessionStyle';
  style.textContent = [
    'body.scanner-session-active .overlay.open{display:none !important;}',
    'body.scanner-session-active .qs-modal-overlay{display:none !important;}',
    'body.scanner-session-active .calc-overlay{display:none !important;}',
    'body.scanner-session-active .keu-fab{display:none !important;}',
    'body.scanner-session-active #toast{display:none !important;}',
  ].join('');
  document.head.appendChild(style);
}

// pauseUI() — suspend UI global (modal/toast/dashboard chrome) SEBELUM
// scanner engine membangun overlay-nya sendiri. "Dashboard" di sini = chrome
// #mainNav/#mainHeader (REUSE penuh vehicleScannerHideChrome() lama — z-index
// #mainNav ternyata tetap kepaint di atas overlay scanner di sebagian
// browser/mode non-PWA, lihat catatan asli di vehicle-scanner.js), "modal/
// toast" = .overlay.open manapun & #toast (REUSE penuh aturan CSS
// camera-scan-active lama).
function scannerSessionPauseUI() {
  _scannerSessionEnsureStyle();
  const nav = document.getElementById('mainNav');
  const header = document.getElementById('mainHeader');
  _scannerSessionPrevChrome = {
    navDisplay: nav ? nav.style.display : null,
    headerDisplay: header ? header.style.display : null,
  };
  if (nav) nav.style.display = 'none';
  if (header) header.style.display = 'none';
  // FAB (.keu-fab) TIDAK lagi di-snapshot/di-hide di sini — ditangani CSS
  // (`_scannerSessionEnsureStyle()`) via class body.scanner-session-active,
  // di-toggle di baris berikut.
  document.body.classList.add('scanner-session-active');
}

// resumeUI() — kebalikan pauseUI(), dipanggil SESUDAH scanner engine teardown
// (overlay-nya sendiri sudah dilepas dari DOM) supaya tidak ada jendela waktu
// scanner & UI global aktif bersamaan.
function scannerSessionResumeUI() {
  const nav = document.getElementById('mainNav');
  const header = document.getElementById('mainHeader');
  if (_scannerSessionPrevChrome) {
    if (nav) nav.style.display = _scannerSessionPrevChrome.navDisplay || '';
    if (header) header.style.display = _scannerSessionPrevChrome.headerDisplay || '';
  }
  _scannerSessionPrevChrome = null;
  document.body.classList.remove('scanner-session-active');
}

// enter() — satu-satunya titik masuk Exclusive Scanner Mode. Guard anti-
// dobel (mis. Scanner.start() ke-trigger 2x sebelum exit() pertama sempat
// jalan) — no-op kalau sudah aktif, supaya _scannerSessionPrevChrome asli
// tidak ketiban nilai 'none' dari sesi scanner sebelumnya.
function scannerSessionEnter() {
  // Jaring pengaman kedua: kalau pemanggil langsung enter() tanpa cek
  // isActive() dulu (jalur lain di masa depan), tetap self-heal di sini
  // sebelum counter dinaikkan, supaya enter() baru ini tidak numpuk di atas
  // state nyangkut lama.
  _scannerSessionSelfHeal();
  _scannerSessionCount++;
  if (_scannerSessionCount > 1) {
    // Sudah ada sesi aktif (nested enter()) — cuma naikkan counter, TIDAK
    // pauseUI() lagi (supaya _scannerSessionPrevChrome asli tidak ketiban
    // nilai dari enter() ke-2), no-op sama seperti guard lama.
    return false;
  }
  _scannerSessionActive = true;
  scannerSessionPauseUI();
  if (typeof AIBus !== 'undefined' && AIBus && typeof AIBus.emit === 'function') {
    AIBus.emit('Scanner:opened', {});
  }
  return true;
}

// exit() — satu-satunya titik keluar Exclusive Scanner Mode. Aman dipanggil
// walau enter() belum pernah/gagal (mis. Scanner Engine error sebelum sempat
// enter()) — no-op kalau memang belum aktif.
function scannerSessionExit() {
  if (_scannerSessionCount <= 0) {
    // exit() dipanggil walau tidak ada enter() yang "berhutang" (belum
    // pernah enter(), atau sudah di-exit() sampai 0 sebelumnya) — no-op,
    // JANGAN turun ke negatif (kalau tidak, enter() berikutnya butuh 2x
    // exit() baru resumeUI(), padahal counter seharusnya sudah balik ke 0).
    return false;
  }
  _scannerSessionCount--;
  if (_scannerSessionCount > 0) {
    // Masih ada sesi lain yang "berhutang" exit() (nested enter()) — belum
    // boleh resumeUI(), tunggu exit() yang menurunkan counter ke 0.
    return false;
  }
  _scannerSessionActive = false;
  scannerSessionResumeUI();
  if (typeof AIBus !== 'undefined' && AIBus && typeof AIBus.emit === 'function') {
    AIBus.emit('Scanner:closed', {});
  }
  return true;
}

// SELF-HEALING GUARD (bugfix: ScannerSession nyangkut aktif selamanya) —
// _scannerSessionActive bisa nyangkut `true` PERMANEN kalau proses tutup
// kamera terputus di tengah jalan (app di-minimize pas prompt izin kamera
// muncul, tab di-suspend browser, dll): finally{} di Scanner Engine (vehicle-
// scanner.js/sparepart-scanner.js) tidak sempat jalan sampai selesai ->
// ScannerSession.exit() tidak pernah terpanggil, TAPI overlay scanner-nya
// (.vehicle-scanner-fullscreen) sudah lenyap dari DOM (browser sudah
// mematikan halaman/stream duluan). Akibatnya body.scanner-session-active
// nempel permanen -> CSS (_scannerSessionEnsureStyle) men-display:none SEMUA
// .overlay/.qs-modal-overlay/.calc-overlay/.keu-fab/#toast SELAMANYA, dan
// isActive() selalu return true -> scanner baru pun ditolak terus ("Scanner
// lain sedang aktif", lihat vehicle-scanner.js/sparepart-scanner.js) tanpa
// jalan keluar selain reload penuh.
//
// Guard: overlay scanner (VehicleScanner & SparepartScanner PAKAI CLASS SAMA
// PERSIS, `.vehicle-scanner-fullscreen`, lihat vehicleScannerBuildOverlay())
// adalah bukti fisik satu-satunya bahwa sesi scanner BENERAN masih hidup di
// layar. Kalau flag bilang aktif tapi overlay itu sudah tidak ada -> state
// dianggap nyangkut, paksa reset PENUH (counter, flag, class body, restore
// chrome via resumeUI()) sebelum lanjut. Dipanggil di titik-titik yang
// dicek pemanggil SEBELUM membuka scanner baru (isActive()) & di awal
// enter() itu sendiri, supaya pemanggil manapun tidak pernah ketiban state
// nyangkut ini.
function _scannerSessionHasLiveOverlay() {
  if (typeof document === 'undefined' || !document.querySelector) return true;
  return !!document.querySelector('.vehicle-scanner-fullscreen');
}

function _scannerSessionSelfHeal() {
  if (_scannerSessionActive && !_scannerSessionHasLiveOverlay()) {
    _scannerSessionCount = 0;
    _scannerSessionActive = false;
    scannerSessionResumeUI();
    return true;
  }
  return false;
}

function scannerSessionIsActive() {
  _scannerSessionSelfHeal();
  return _scannerSessionActive;
}

// ------------------------------------------------------------------------
// Namespace publik — pola sama persis VehicleScanner/SparepartScanner (const
// object, expose eksplisit ke window krn Node vm & browser non-module script
// TIDAK otomatis menempelkan binding const/let ke global object).
// ------------------------------------------------------------------------
const ScannerSession = {
  enter: scannerSessionEnter,
  exit: scannerSessionExit,
  pauseUI: scannerSessionPauseUI,
  resumeUI: scannerSessionResumeUI,
  isActive: scannerSessionIsActive,
};

if (typeof window !== 'undefined') {
  window.ScannerSession = ScannerSession;
}

// WATCHDOG GLOBAL (audit lanjutan v1027 — rekomendasi tier-1, gap "whack-a-
// mole"): fix v1026 (openModal()) & v1027 (_queueDialog()/openQS()) menutup
// celah dengan menambahkan panggilan self-heal SATU PER SATU di titik masuk
// overlay yang SUDAH DIKETAHUI. Pola ini rapuh — kalau ADA titik masuk baru
// di masa depan (mis. modul fitur baru yang buka overlay-nya sendiri tanpa
// lewat openModal()/_queueDialog()/openQS()), state nyangkut yang sama bisa
// lolos lagi tanpa terdeteksi sampai ada laporan user berikutnya.
//
// Root cause aslinya adalah TIMING: proses tutup kamera terputus paling
// sering terjadi persis saat app di-minimize/tab di-suspend (browser
// mematikan halaman sebelum finally{} sempat jalan). Titik paling andal
// untuk self-heal BUKAN "setiap fungsi yang buka overlay", tapi "setiap kali
// app kembali terlihat/aktif" — karena itu momen paling mungkin state
// nyangkut baru saja terjadi, TERLEPAS dari overlay/modul mana yang nanti
// mau dibuka user. Guard ini mencakup SEMUA jalur (termasuk yang belum
// ditulis) tanpa perlu tahu titik masuk spesifiknya.
//
// 0 perubahan API ScannerSession, 0 breaking change — cuma memanggil
// isActive() (yang sudah idempotent & aman dipanggil kapan saja) di momen
// tambahan. Tidak menggantikan guard yang sudah ada di openModal()/
// _queueDialog()/openQS() (defense-in-depth, bukan pengganti).
if (typeof document !== 'undefined' && typeof document.addEventListener === 'function') {
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'visible') scannerSessionIsActive();
  });
}
if (typeof window !== 'undefined' && typeof window.addEventListener === 'function') {
  window.addEventListener('pageshow', function () { scannerSessionIsActive(); });
  window.addEventListener('focus', function () { scannerSessionIsActive(); });
}

// RECOVERY BANNER (tier-3, rekomendasi FIX-s362-scannersession-global-
// watchdog.md yg belum dikerjakan sesi s363-s365): watchdog Tier-1 di atas
// sudah mengurangi kemungkinan state nyangkut lolos, TAPI kalau user
// kejadian PERSIS di celah kecil sebelum watchdog sempat jalan (mis.
// browser sangat lawas tanpa visibilitychange/pageshow/focus), satu-satunya
// jalan keluar user awam SEBELUMNYA adalah reload penuh atau trik console
// manual (lihat "Unblock cepat" di FIX-s360). Elemen di bawah kasih jalan
// keluar VISUAL yang TIDAK ikut disembunyikan CSS suppression
// (body.scanner-session-active .overlay/.qs-modal-overlay/.calc-overlay/
// #toast{display:none!important}) krn SENGAJA dibuat bukan .overlay/
// .qs-modal-overlay/.calc-overlay/#toast — style-nya inline, bukan lewat
// class apa pun.
//
// Poll ringan tiap RECOVERY_POLL_MS: tampil HANYA kalau _scannerSessionActive
// sudah true LEBIH LAMA dari RECOVERY_STUCK_MS **dan** overlay scanner
// sungguhan (.vehicle-scanner-fullscreen) sudah tidak ada di DOM (indikator
// fisik sesi memang nyangkut, dipakai bareng _scannerSessionHasLiveOverlay()
// yang sudah ada — 0 logic baru soal "apa itu nyangkut", REUSE penuh).
// Sesi scanner yang BENERAN aktif (overlay masih hidup) TIDAK pernah
// memicu banner ini, berapa lama pun durasinya.
const RECOVERY_STUCK_MS = 10000; // 10 detik -- jauh di atas durasi wajar buka kamera/render overlay
const RECOVERY_POLL_MS = 3000;
let _scannerSessionEnteredAt = null;
let _scannerSessionRecoveryEl = null;

function _scannerSessionShowRecoveryBanner() {
  if (typeof document === 'undefined' || _scannerSessionRecoveryEl) return;
  const el = document.createElement('div');
  el.id = '_scannerSessionRecoveryBanner';
  el.textContent = '⚠️ Gangguan terdeteksi — ketuk untuk reset tampilan';
  el.setAttribute('role', 'button');
  // Inline style murni (BUKAN class .overlay/.qs-modal-overlay/.calc-overlay/
  // #toast) -- itu SATU-SATUNYA alasan elemen ini lolos dari suppression
  // CSS. Jangan ganti jadi class card/modal/toast apa pun yang sudah ada.
  el.style.cssText = 'position:fixed;left:12px;right:12px;bottom:16px;z-index:999999;' +
    'background:#b91c1c;color:#fff;padding:12px 16px;border-radius:10px;' +
    'font:14px/1.4 -apple-system,system-ui,sans-serif;text-align:center;' +
    'box-shadow:0 4px 16px rgba(0,0,0,.3);cursor:pointer;';
  el.onclick = function () {
    _scannerSessionEnteredAt = null;
    scannerSessionIsActive(); // trigger self-heal (overlay sudah tidak live -> pasti reset)
    if (el.parentNode) el.parentNode.removeChild(el);
    _scannerSessionRecoveryEl = null;
  };
  (document.body || document.documentElement).appendChild(el);
  _scannerSessionRecoveryEl = el;
}

function _scannerSessionHideRecoveryBanner() {
  if (_scannerSessionRecoveryEl && _scannerSessionRecoveryEl.parentNode) {
    _scannerSessionRecoveryEl.parentNode.removeChild(_scannerSessionRecoveryEl);
  }
  _scannerSessionRecoveryEl = null;
}

function _scannerSessionRecoveryTick() {
  if (!_scannerSessionActive) { _scannerSessionEnteredAt = null; _scannerSessionHideRecoveryBanner(); return; }
  if (_scannerSessionEnteredAt === null) { _scannerSessionEnteredAt = Date.now(); return; }
  const stuckLongEnough = (Date.now() - _scannerSessionEnteredAt) >= RECOVERY_STUCK_MS;
  const overlayGone = !_scannerSessionHasLiveOverlay();
  if (stuckLongEnough && overlayGone) _scannerSessionShowRecoveryBanner();
}

if (typeof window !== 'undefined' && typeof window.setInterval === 'function') {
  window.setInterval(_scannerSessionRecoveryTick, RECOVERY_POLL_MS);
}

// reset-gaji-mingguan.js — Domain Reset Gaji Mingguan: hitung rentang minggu berjalan (getWeekRange),
// Dipindah ke modules/business/reset-gaji-mingguan.js (Sesi 15 restrukturisasi folder — lihat docs/FILE-MAP.md & RENCANA-SESI.md; isi & nama file TIDAK berubah, cuma lokasi folder).
// deteksi & tawarkan reset absensi tiap Sabtu (checkWeeklySalaryReset), buka modal reset manual
// (openWeeklyResetManual), dan proses konfirmasi reset + catat pemasukan gaji otomatis (confirmWeeklyReset).
// Dipindah dari features-helpers-global-security.js (v72) — potongan KEEMPAT stlh kalkulator-input.js
// (v69), keamanan-pin.js (v70), modal-navigasi.js (v71). Blok ini kontigu di file asal (langsung sebelum
// showMain), 1 domain murni (fitur "gajian mingguan dari Absensi harian" di modul Tukang/Gaji), TIDAK
// direferensi modul lain kecuali lewat variabel global: D.workDays/D.transactions/D.accounts/D.categories/
// D.lastResetPromptDate (state, tetap di features-helpers-global-security.js), uid()/save()/toast()/
// fmtFull() (tetap di file itu juga), openModal()/closeModal() (modal-navigasi.js), populateAccFilters()
// (akun.js), renderWorkDays()/renderDashboard()/renderKeuangan() (modules-render.js), dateToISO()
// (helper-teks.js) — semua diakses saat runtime (klik tombol/modal
// dibuka), bukan saat file dimuat.
// CATATAN: `todayStr()` SENGAJA TIDAK ikut dipindah (tetap di features-helpers-global-security.js)
// walau ada tepat di antara getWeekRange & _wrLastTotal di file lama — krn itu utilitas tanggal generik
// yang dipakai 12+ file lain di luar domain reset gaji mingguan (mirip fmt/escapeHtml), bukan spesifik
// domain ini. Dipanggil dari sini lewat variabel global seperti biasa.
// PENTING: file ini HARUS dimuat SETELAH features-helpers-global-security.js (butuh D, save, toast,
// fmtFull, uid, todayStr) & modal-navigasi.js (butuh openModal/closeModal).
function getWeekRange(d){
const day=d.getDay();
const start=new Date(d); start.setDate(d.getDate()-day); start.setHours(0,0,0,0);
const end=new Date(start); end.setDate(start.getDate()+6); end.setHours(23,59,59,999);
return {start,end};
}
let _wrLastTotal=0,_wrLastCount=0,_wrLastStart=null,_wrLastEnd=null;
// FIX (audit kategori gaji absensi): sebelumnya kalau tidak ada kategori income
// yang namanya match /gaji/i, sistem fallback diam-diam ke D.categories.income[0]
// (kategori pemasukan PERTAMA apa adanya — bisa kategori bisnis, dll). Ini bikin
// gaji mingguan dari absensi tercatat di kategori yang salah tanpa notifikasi
// apapun, terutama kalau user pernah menghapus/mengganti nama kategori "Gaji toko"
// bawaan (kategori.js SENGAJA membolehkan rename/hapus kategori apa saja, termasuk
// kategori default — lihat saveCat/delCat). Fix: kalau tidak ketemu, buat kategori
// "Gaji" baru otomatis alih-alih fallback ke kategori pertama sembarang. Dipakai
// bareng oleh confirmWeeklyReset() di file ini & saveGajiAsIncome() di gaji-calc.js
// (file itu dimuat SETELAH file ini di scripts/build.js, jadi aman diakses dari sana).
function ensureGajiCategory(){
const found=D.categories.income.find(c=>/gaji/i.test(c.name));
if(found) return found;
const created={id:'cat_gaji_'+uid(),name:'Gaji',emoji:'💼',subs:[]};
D.categories.income.push(created);
return created;
}
function checkWeeklySalaryReset(){
const now=new Date();
if(now.getDay()!==6) return;
const ts=todayStr();
if(D.lastResetPromptDate===ts) return;
const {start,end}=getWeekRange(now);
const weekDays=D.workDays.filter(w=>{const d=new Date(w.date);return d>=start&&d<=end;});
if(!weekDays.length){ D.lastResetPromptDate=ts; save(); return; }
const total=weekDays.reduce((s,w)=>s+w.total,0);
_wrLastTotal=total;_wrLastCount=weekDays.length;_wrLastStart=start;_wrLastEnd=end;
document.getElementById('wrCount').textContent=weekDays.length;
document.getElementById('wrTotal').textContent=fmtFull(total);
const ckEl=document.getElementById('wrAutoIncome'); if(ckEl) ckEl.checked=true;
const accWrapEl=document.getElementById('wrAccWrap'); if(accWrapEl) accWrapEl.style.display=D.accounts.length?'block':'none';
const accEl=document.getElementById('wrAcc'); if(accEl&&D.accounts.length) accEl.value=D.accounts[0].id;
openModal('weeklyResetModal');
}
// v181: dulu SELALU pakai minggu real sekarang (new Date()), padahal tombol "💰 Sudah Gajian?"
// di tab Absensi muncul per MINGGU YANG SEDANG DIBROWSE (lihat panah ‹ › / Payroll.weekStart di
// payroll-absensi.js) — akibatnya kalau user browse ke minggu LAMA yang masih pending & tap tombol
// itu, yang ke-reset/dicatat malah minggu sekarang (salah/kosong), bukan minggu lama yang dimaksud.
// Ini bikin notif "⚠️ N minggu pending" tidak pernah bisa benar-benar diselesaikan lewat tombol ini.
// Fix: pakai Payroll.weekStart (minggu yang sedang tampil di layar) sbg target, fallback ke minggu
// real sekarang kalau dipanggil di luar konteks itu (mis. modul Payroll belum sempat dimuat).
function openWeeklyResetManual(){
const target=(typeof Payroll!=='undefined'&&Payroll.weekStart)?new Date(Payroll.weekStart):new Date();
const {start,end}=getWeekRange(target);
const weekDays=D.workDays.filter(w=>{const d=new Date(w.date);return d>=start&&d<=end;});
if(!weekDays.length){toast('⚠️ Belum ada absensi minggu ini untuk dicatat');return;}
const total=weekDays.reduce((s,w)=>s+w.total,0);
_wrLastTotal=total;_wrLastCount=weekDays.length;_wrLastStart=start;_wrLastEnd=end;
populateAccFilters();
document.getElementById('wrCount').textContent=weekDays.length;
document.getElementById('wrTotal').textContent=fmtFull(total);
const ckEl=document.getElementById('wrAutoIncome'); if(ckEl) ckEl.checked=true;
const accWrapEl=document.getElementById('wrAccWrap'); if(accWrapEl) accWrapEl.style.display=D.accounts.length?'block':'none';
const accEl=document.getElementById('wrAcc'); if(accEl&&D.accounts.length) accEl.value=D.accounts[0].id;
closeModal('absensiModal');
closeModal('gajiCalcModal');
openModal('weeklyResetModal');
}
function confirmWeeklyReset(yes){
// Pakai minggu yang di-"kunci" saat modal ini dibuka (_wrLastStart/_wrLastEnd), BUKAN dihitung
// ulang dari new Date() — supaya konsisten dgn minggu yang ditampilkan ke user di modal
// (termasuk kalau itu minggu lama yang sedang di-reset lewat notif pending), & aman dari race
// condition kalau tanggal berganti persis saat modal ini terbuka.
const {start,end}=(_wrLastStart&&_wrLastEnd)?{start:_wrLastStart,end:_wrLastEnd}:getWeekRange(new Date());
const now=new Date();
let incomeSaved=false;
if(yes){
const autoEl=document.getElementById('wrAutoIncome');
const autoIncome=autoEl&&autoEl.checked&&_wrLastTotal>0;
if(autoIncome){
const accEl=document.getElementById('wrAcc');
const accId=(accEl&&accEl.value)||(D.accounts.length?D.accounts[0].id:null);
const gajiCat=ensureGajiCategory();
const catName=gajiCat.name;
// Auto-pilih subkategori yang paling cocok (mis. "Gaji Toko") kalau kategori
// yang match punya subs — dulu subcategory SELALU dikosongkan walau user
// sudah punya subkategori yang sesuai, jadi harus dipilih manual tiap minggu.
// Prioritas: sub yang namanya mengandung "toko" > mengandung "gaji" > sub
// pertama yang ada. Kalau kategori tidak punya subs sama sekali (termasuk
// kategori "Gaji" yang baru dibuat otomatis oleh ensureGajiCategory()), tetap
// kosong seperti sebelumnya — tidak ada regresi.
let subName='';
if(Array.isArray(gajiCat.subs) && gajiCat.subs.length){
const subMatch=gajiCat.subs.find(s=>/toko/i.test(s.name))||gajiCat.subs.find(s=>/gaji/i.test(s.name))||gajiCat.subs[0];
if(subMatch) subName=subMatch.name;
}
D.transactions.push({id:uid(),type:'income',amount:_wrLastTotal,category:catName,subcategory:subName,accountId:accId,payMethod:'tunai',note:`Gaji mingguan dari absensi (${_wrLastCount} hari kerja, ${dateToISO(start)} s/d ${dateToISO(end)})`,date:dateToISO(now)});
incomeSaved=true;
}
if(!Array.isArray(D.gajiMingguanHistory))D.gajiMingguanHistory=[];
D.gajiMingguanHistory.push({id:uid(),weekStart:dateToISO(start),weekEnd:dateToISO(end),total:_wrLastTotal,count:_wrLastCount,resetDate:todayStr(),incomeSaved});
if(D.gajiMingguanHistory.length>26) D.gajiMingguanHistory=D.gajiMingguanHistory.slice(-26);
D.workDays=D.workDays.filter(w=>{const d=new Date(w.date);return !(d>=start&&d<=end);});
toast(incomeSaved?`✅ Absensi direset & ${fmtFull(_wrLastTotal)} dicatat sebagai Pemasukan! 🎉`:'✅ Absensi minggu ini direset, selamat gajian! 🎉');
} else {
toast('Oke, data absensi minggu ini tetap disimpan');
}
D.lastResetPromptDate=todayStr();
_wrLastStart=null;_wrLastEnd=null;
save();
closeModal('weeklyResetModal');
renderWorkDays();
Payroll.renderDashMini();
renderDashboard();
if(incomeSaved) renderKeuangan();
}

// debug-console.js — Domain Debug Console: toggle tombol status (updateDebugConsoleBtn) & aktifkan/matikan
// Dipindah ke modules/shared/debug-console.js (Sesi 17-18 restrukturisasi folder — lihat docs/FILE-MAP.md & RENCANA-SESI.md; isi & nama file TIDAK berubah, cuma lokasi folder).
// panel debug pihak ketiga "eruda" (toggleDebugConsole), termasuk lazy-load skrip eruda dari CDN kalau
// belum pernah dipakai.
// Dipindah dari features-helpers-global-security.js (v73) — potongan KELIMA stlh kalkulator-input.js
// (v69), keamanan-pin.js (v70), modal-navigasi.js (v71), reset-gaji-mingguan.js (v72). Dipilih krn
// domain kecil & mandiri: cuma pakai localStorage/window.eruda/document (DOM), TIDAK bergantung ke D
// atau modul lain kecuali toast() (tetap di features-helpers-global-security.js, dipanggil saat
// runtime tombol diklik).
// Dipanggil dari: tombol "Aktifkan/Matikan Debug Console" di Pengaturan (data-action="toggleDebugConsole"
// di index.html/app_production.html), dan updateDebugConsoleBtn() dipanggil dari modules-render.js saat
// render halaman Pengaturan.
// PENTING: file ini HARUS dimuat SETELAH features-helpers-global-security.js (butuh toast()).
function updateDebugConsoleBtn(){
const btn=document.getElementById('btnToggleDebugConsole');
if(!btn)return;
const active=localStorage.getItem('kw_debug_console')==='1';
btn.textContent=active?'🐞 Matikan Debug Console':'🐞 Aktifkan Debug Console';
}
function toggleDebugConsole(){
const active=localStorage.getItem('kw_debug_console')==='1';
if(active){
localStorage.removeItem('kw_debug_console');
try{ if(window.eruda) eruda.destroy(); }catch(e){}
toast('🐞 Debug console dimatikan');
updateDebugConsoleBtn();
return;
}
localStorage.setItem('kw_debug_console','1');
if(window.eruda){
try{ eruda.init(); }catch(e){}
toast('🐞 Debug console diaktifkan');
updateDebugConsoleBtn();
return;
}
const s=document.createElement('script');
s.src='https://cdn.jsdelivr.net/npm/eruda';
s.onload=function(){
try{ eruda.init(); toast('🐞 Debug console diaktifkan'); }
catch(e){ toast('⚠️ Gagal menyalakan debug console: '+e.message); }
updateDebugConsoleBtn();
};
s.onerror=function(){
localStorage.removeItem('kw_debug_console');
toast('⚠️ Gagal memuat debug console (butuh internet saat pertama kali aktif)');
updateDebugConsoleBtn();
};
(document.head||document.documentElement).appendChild(s);
}

// pengaturan-search.js — Domain Pencarian Pengaturan: buka/tutup grup pengaturan (toggleStgGroup), cari
// Dipindah ke modules/shared/pengaturan-search.js (Sesi 17-18 restrukturisasi folder — lihat docs/FILE-MAP.md & RENCANA-SESI.md; isi & nama file TIDAK berubah, cuma lokasi folder).
// & sorot kartu pengaturan yang cocok teks pencarian (stgSearch), dan dukungan keyboard (Enter/Spasi)
// utk buka grup pengaturan lewat kepala grup yang sedang fokus.
// Dipindah dari features-helpers-global-security.js (v73) — potongan KEENAM stlh kalkulator-input.js
// (v69), keamanan-pin.js (v70), modal-navigasi.js (v71), reset-gaji-mingguan.js (v72),
// debug-console.js (v73, potongan sebelum ini di sesi yang sama). Dipilih krn domain kecil & mandiri:
// cuma pakai document.querySelectorAll/getElementById (DOM murni), TIDAK bergantung ke D atau modul
// lain sama sekali.
// CATATAN: blok ini menyertakan 1 `document.addEventListener('keydown',...)` top-level yang jalan saat
// file dimuat (bukan cuma deklarasi function) — ini AMAN dipindah krn cuma daftarkan event listener
// baru ke window/document, tidak bergantung urutan modul lain siap atau tidak.
// Dipanggil dari: `onclick="toggleStgGroup(...)"` & `oninput="stgSearch(...)"` di halaman Pengaturan
// (index.html/app_production.html).
// PENTING: file ini HARUS dimuat SETELAH features-helpers-global-security.js.
// setSettingsTab: split-tab utk halaman Pengaturan (#page-settings), gantiin accordion 6 grup
// lama (stgGroup1..6) yang sekarang jadi .stg-tabpanel + .cn-tabs. Pola PERSIS SAMA dgn
// setKeuanganTab/setShopTab/setPajakTab/setAsetTab (lihat aset.js) -- toggle 'active' di tombol
// .cn-tab & toggle 'u-dnone' di panel yg cocok data-tab. toggleStgGroup() di bawah TETAP ada &
// TIDAK diubah -- masih dipakai apa adanya utk accordion lain (dashSecondaryGroup di Beranda,
// pzPiutangUtangGroup di Pajak & Zakat), cuma sudah tidak dipakai lagi utk stgGroup1..6.
// FIX (audit lanjutan S679): array ini sebelumnya cuma 6 entry, hilang
// 'pengingat' -- padahal ada 7 tombol .cn-tab nyata di #page-settings
// (urutan DOM: profil, keuangan, pengingat, notifbackup, keamanan,
// kepemilikan, diagnostik). Array ini dipakai sbg fallback index saat
// setSettingsTab(tab) dipanggil TANPA `el` eksplisit (bukan dari klik
// tombol) -- terbukti terjadi dari 3 pemanggil: stgSearch() di file ini
// (baris di bawah), DashboardHub deep-link (dashboard-hub.js, blok
// `target.group`), & _lifeOSHighlightSettingsCard (lifeos-nav.js). Saat
// tab='pengingat', indexOf() sebelumnya balikin -1 -> fallback ke index 0
// -> tombol 'Profil' yang ke-highlight active, padahal panel yang
// ditampilkan tetap 'Pengingat' (baris `p.dataset.tab!==tab` di bawah
// pakai `tab` asli, jadi ini bug visual: tombol aktif salah, bukan salah
// panel). Urutan array HARUS sama persis dgn urutan tombol di DOM krn
// `settingsTabBtns[idx]` mengandalkan itu.
const SETTINGS_TAB_ORDER=['profil','keuangan','pengingat','notifbackup','keamanan','kepemilikan','diagnostik'];
const SETTINGS_TAB_LABEL={profil:'Profil',keuangan:'Keuangan',pengingat:'Pengingat',notifbackup:'Notif&Backup',keamanan:'Keamanan',kepemilikan:'Kepemilikan',diagnostik:'Diagnostik'};
function setSettingsTab(tab,el){
// BUGFIX (audit bug serupa S619 -- lihat dismissAllToasts() di
// modules/shared/format-tema.js & setAsetTab() di modules/asset/aset-misc.js):
// toast basi dari halaman/aksi sebelumnya bisa nyangkut menutupi tombol di
// sub-tab baru begitu user pindah sub-tab TANPA lewat showPage() (mis. ganti
// sub-tab di dalam halaman Settings yang sama). Pola sama persis dgn semua
// fungsi set*Tab lain, lihat CHANGELOG-S620.md.
if(typeof dismissAllToasts==='function')dismissAllToasts();
const settingsTabBtns=document.querySelectorAll('#page-settings .cn-tabs .cn-tab');
settingsTabBtns.forEach(b=>b.classList.remove('active'));
let _activeBtn=el;
if(el) el.classList.add('active');
else { const idx=SETTINGS_TAB_ORDER.indexOf(tab); const btn=settingsTabBtns[idx>=0?idx:0]; if(btn){btn.classList.add('active');_activeBtn=btn;} }
if(typeof scrollTabBarIntoView==='function') scrollTabBarIntoView(_activeBtn);
const settingsBc=document.getElementById('settingsBreadcrumbSub');
if(settingsBc)settingsBc.textContent=SETTINGS_TAB_LABEL[tab]||tab;
document.querySelectorAll('#page-settings .stg-tabpanel').forEach(p=>{
p.classList.toggle('u-dnone', p.dataset.tab!==tab);
p.style.display='';
});
}
function toggleStgGroup(id){
var g=document.getElementById(id);
if(!g)return;
const isOpen=g.classList.toggle('open');
const head=g.querySelector('.stg-group-head');
if(head)head.setAttribute('aria-expanded',isOpen?'true':'false');
}
// Collapse per-kartu (beda dari toggleStgGroup yg collapse seluruh grup) — dipakai kartu tunggal
// yg isinya panjang, mis. "Kartu di Beranda". `id` = id elemen .card-collapse pembungkusnya.
// PENTING: nama fungsi ini SENGAJA dibedakan dari toggleCardCollapse(key,ev) di modal-navigasi.js
// (dipakai ~40+ kartu lain lewat data-action="toggleCardCollapse" dengan skema id `key+'-cbody'`/
// `key+'-chev'`). SEBELUMNYA file ini juga mendeklarasikan global bernama `toggleCardCollapse`
// dengan signature & skema DOM yang beda (toggle class 'open' di elemen pembungkus + cari child
// `.card-collapse-head`) — karena file ini dimuat SETELAH modal-navigasi.js, deklarasi function
// di sini MENIMPA punya modal-navigasi.js secara global, jadi SEMUA kartu lain (Beranda, Keuangan,
// Laporan, Car Notes, Pajak/Zakat, dst) yang pakai data-action="toggleCardCollapse" ikut manggil
// fungsi versi sini yang salah skema — akibatnya tombol collapse-nya diam saja / tidak berfungsi.
// Jangan pakai nama `toggleCardCollapse` lagi di file ini.
function toggleSingleCardCollapse(id){
var c=document.getElementById(id);
if(!c)return;
const isOpen=c.classList.toggle('open');
const head=c.querySelector('.card-collapse-head');
if(head)head.setAttribute('aria-expanded',isOpen?'true':'false');
}
// STG_EXTERNAL_SETTINGS_INDEX — daftar kecil "pengaturan referensi" yang TIDAK
// tinggal di dalam #page-settings (dipindah ke halaman fiturnya masing-masing,
// pola yang sama dgn kartu "🔗 Pengaturan Lanjutan per Fitur"). stgSearch() ikut
// mencocokkan query ke sini supaya orang yang cari "emas"/"self reward"/"pbb"/
// dsb di kotak cari Pengaturan tetap dapat hasil (arahkan ke halaman tujuan),
// bukan "Tidak ada pengaturan yang cocok" padahal fiturnya beneran ada.
// Setiap entry: label (teks tombol), keywords (dicocokkan ke q, lowercase),
// lalu SALAH SATU dari:
//   - page: dibuka lewat showPage(page, navBtn) — navBtn diambil otomatis dari
//     .nav-item yang data-args-nya match nama page tsb.
//   - action: dipanggil langsung (dieval sbg "Namespace.method" atau nama
//     fungsi global), dipakai utk fitur yang bentuknya modal (bukan halaman),
//     sama kayak target FEATURE_REGISTRY.
const STG_EXTERNAL_SETTINGS_INDEX=[
{label:'💰 Kategori & Import Transaksi → Keuangan',keywords:'kategori import transaksi csv excel',page:'keuangan'},
{label:'🏍️ Kategori Sparepart → Car Notes',keywords:'kategori sparepart mobil motor car notes',page:'carnotes'},
{label:'🛒 Katalog Sparepart per Kendaraan (Shop)',keywords:'katalog sparepart kendaraan shop dinamis interval servis',action:'openShopKatalogDinamis'},
{label:'🕌 Harga Emas, Nisab & PBB → Pajak & Zakat',keywords:'emas nisab zakat pbb pajak njoptkp tarif referensi harga emas',page:'pajak'},
{label:'🎁 Level & Toleransi → Self Reward',keywords:'self reward hadiah level toleransi telat',action:'SelfRewardView.open'},
{label:'📊 Pengaturan Anggaran → Keuangan (tab Budget)',keywords:'budget anggaran atur anggaran',page:'keuangan'}
];
function _stgOpenExternal(item){
if(item.action){
try{
const fn=item.action.split('.').reduce((o,k)=>o&&o[k],window);
if(typeof fn==='function') fn();
else console.warn('stgSearch: action tidak ditemukan -',item.action);
}catch(e){console.warn('stgSearch: gagal panggil action -',item.action,e);}
return;
}
if(item.page && typeof showPage==='function'){
const navBtn=document.querySelector('.nav-item[data-args*="\\"'+item.page+'\\""]');
showPage(item.page,navBtn);
}
}
let _stgSearchHighlighted=[];
function stgSearch(qRaw){
const q=(qRaw||'').trim().toLowerCase();
const resultEl=document.getElementById('stgSearchResult');
_stgSearchHighlighted.forEach(c=>{c.style.outline='';c.style.outlineOffset='';});
_stgSearchHighlighted=[];
if(!q){ if(resultEl){resultEl.style.display='none';resultEl.innerHTML='';} return; }
const cards=document.querySelectorAll('#page-settings .stg-group-body-inner .card');
let matches=[];
cards.forEach(card=>{
if(card.textContent.toLowerCase().indexOf(q)!==-1) matches.push(card);
});
const externalMatches=STG_EXTERNAL_SETTINGS_INDEX.filter(item=>item.keywords.indexOf(q)!==-1);
if(resultEl){
resultEl.classList.remove('u-dnone');resultEl.style.display='block';
let html='';
if(matches.length) html+='✅ '+matches.length+' hasil ditemukan di sini<br>';
else if(!externalMatches.length) html+='⚠️ Tidak ada pengaturan yang cocok';
if(externalMatches.length){
html+='🔗 Ditemukan di halaman lain:<br>'+externalMatches.map(item=>
'<button type="button" class="btn btn-ghost btn-sm u-mt6" style="display:block;width:100%;text-align:left" data-stg-ext-idx="'+STG_EXTERNAL_SETTINGS_INDEX.indexOf(item)+'">'+item.label+'</button>'
).join('');
}
resultEl.innerHTML=html;
resultEl.querySelectorAll('[data-stg-ext-idx]').forEach(btn=>{
btn.addEventListener('click',function(){
const item=STG_EXTERNAL_SETTINGS_INDEX[parseInt(btn.dataset.stgExtIdx,10)];
if(item) _stgOpenExternal(item);
});
});
}
matches.forEach((card,i)=>{
const panel=card.closest('.stg-tabpanel');
if(i===0 && panel && panel.classList.contains('u-dnone')) setSettingsTab(panel.dataset.tab);
if(card.classList.contains('card-collapse') && !card.classList.contains('open')) toggleSingleCardCollapse(card.id);
card.style.outline='2px solid var(--accent)';
card.style.outlineOffset='3px';
_stgSearchHighlighted.push(card);
if(i===0) setTimeout(()=>card.scrollIntoView({behavior:'smooth',block:'center'}),120);
});
}
document.addEventListener('keydown',function(e){
if(e.key!=='Enter'&&e.key!==' ')return;
const head=e.target.closest&&e.target.closest('.stg-group-head,.card-collapse-head');
if(!head)return;
e.preventDefault();
head.click();
});

// onboarding.js — Domain Onboarding: preview perkiraan kasar gaji/kiriman saat setup awal
// Dipindah ke modules/shared/onboarding.js (Sesi 17-18 restrukturisasi folder — lihat docs/FILE-MAP.md & RENCANA-SESI.md; isi & nama file TIDAK berubah, cuma lokasi folder).
// (updateOnboardPreview) & proses selesai onboarding — simpan profil awal + PIN (finishOnboard).
// Dipindah dari features-helpers-global-security.js (v74) — potongan KETUJUH stlh
// kalkulator-input.js (v69), keamanan-pin.js (v70), modal-navigasi.js (v71),
// reset-gaji-mingguan.js (v72), debug-console.js & pengaturan-search.js (v73). Dipilih krn
// domain kecil & mandiri: cuma dipakai saat layar onboarding pertama kali dibuka, tidak ada
// modul lain yang gantung ke fungsi ini selain lewat data-action/oninput di HTML.
// Bergantung ke (semua diakses lewat variabel global saat runtime, BUKAN referensi lokal file):
// D/save() (features-helpers-global-security.js), fmtFull/fmtFullSigned/safeSetItem/showMain
// (features-helpers-global-security.js), hashPin/_sessionRawPin (keamanan-pin.js),
// showAlertModal (modals.js).
// Dipanggil dari: `oninput="updateOnboardPreview()"` di input gaji/kiriman onboarding &
// `data-action="finishOnboard"` di tombol "Mulai Sekarang" (index.html/app_production.html),
// juga dipanggil sekali dari features-sheets-pwa-selftest.js saat cek status setup pertama load.
// PENTING: file ini HARUS dimuat SETELAH features-helpers-global-security.js (butuh fmtFull/
// fmtFullSigned/safeSetItem/showMain) & keamanan-pin.js (butuh hashPin/_sessionRawPin).
function updateOnboardPreview(){
const box=document.getElementById('obPreviewBox'); if(!box)return;
const gaji=parseInt(document.getElementById('ob_gaji').value)||0;
const kirim=parseInt(document.getElementById('ob_kirim').value)||0;
const estBulanan=gaji*26;
const estSisaKirim=estBulanan-(kirim*4);
box.innerHTML='📊 <b>Perkiraan kasar</b> (26 hari kerja/bulan):<br>'
+'Gaji sebulan: <b>'+fmtFull(estBulanan)+'</b><br>'
+'Setelah kiriman rutin: <b style="color:'+(estSisaKirim>=0?'#22c55e':'#ef4444')+'">'+fmtFullSigned(estSisaKirim)+'</b><br>'
+'<span class="u-ctext3">Nanti bisa diatur presisi lewat Absensi harian</span>';
}
async function finishOnboard(){
// FIX (2026-07-26): guard SW controllerchange-reload dipindah ke PALING AWAL finishOnboard(),
// SEBELUM operasi async apa pun (hashPin, dsb). Sebelumnya guard ini baru diset di akhir fungsi,
// jadi ada celah waktu (selama await hashPin() dkk) di mana event 'controllerchange' bisa keburu
// nembak reload() sebelum guard sempat terpasang -- itu penyebab PIN "muncul 2x" (init() jalan
// ulang, lihat kw_pin baru tersimpan, showPinScreen() lagi sebelum user lihat halaman utama).
// Set guard duluan di sini menutup celah race tsb; reload SW normal utk update berikutnya tetap
// jalan seperti biasa (guard cuma berlaku sekali per sesi transisi onboarding->main ini).
try{sessionStorage.setItem('kw_sw_reloaded','1');}catch(e){}
const nama=document.getElementById('ob_nama').value||'W';
const gaji=parseInt(document.getElementById('ob_gaji').value)||65000;
const kirim=parseInt(document.getElementById('ob_kirim').value)||500000;
const pin=document.getElementById('ob_pin').value;
const tema=document.getElementById('ob_tema').value;
if(pin.length!==4){showAlertModal('PIN harus 4 digit!',{icon:'🔒',title:'PIN Belum Valid'});return;}
try{
D.profile={nama,gajiPokok:gaji,kiriman:kirim,theme:tema,tanggalLahir:null,statusKawin:false,tanggungan:0,statusPekerjaan:null};
safeSetItem('kw_pin',await hashPin(pin));
_sessionRawPin=pin;
safeSetItem('kw_setup','1');
save(); document.getElementById('onboard').style.display='none'; showMain();
}catch(e){
console.error('finishOnboard gagal:',e);
showAlertModal('Gagal menyimpan profil awal: '+(e&&e.message?e.message:'error tidak diketahui')+'. Coba lagi, atau buka app ini di browser biasa (bukan preview) kalau masalah berlanjut.',{icon:'⚠️',title:'Gagal Setup'});
}
}

// kalkulator-input.js — Kalkulator ekspresi angka: parser aman (safeCalc), popup kalkulator (openCalc/calcPress/dst),
// Dipindah ke modules/shared/kalkulator-input.js (Sesi 17-18 restrukturisasi folder — lihat docs/FILE-MAP.md & RENCANA-SESI.md; isi & nama file TIDAK berubah, cuma lokasi folder).
// dan preview nilai input jumlah (calcPreviewValue/updateAmtPreview/evalAmtExpr).
// Dipindah dari features-helpers-global-security.js (v69) — domain mandiri, cuma pakai document.getElementById
// & openModal/closeModal (variabel global dari features-helpers-global-security.js, diakses saat runtime lewat
// klik tombol, bukan saat file dimuat, jadi aman ada di file terpisah). Dipanggil dari banyak file lain
// (modals.js, renovasi.js, transaksi.js, tukang-absensi.js, dst) lewat
// nama global (data-action="openCalc" dll di HTML modal, atau evalAmtExpr('id') di onblur).
// PENTING: file ini HARUS dimuat SETELAH features-helpers-global-security.js (butuh fmt(), openModal/closeModal).
function calcPreviewValue(str){
if(!str)return 0;
const r=safeCalc(String(str));
return isNaN(r)?0:r;
}
function updateAmtPreview(inputId,previewId){
const el=document.getElementById(inputId);
const prev=document.getElementById(previewId);
if(!el||!prev)return;
const v=calcPreviewValue(el.value);
prev.textContent=(v&&v>0)?('= '+fmt(v)):'';
}
function normalizeAmtToken(tok){
if(tok.indexOf('.')===-1)return tok;
const parts=tok.split('.');
const last=parts[parts.length-1];
if(last.length>=1&&last.length<=2){
const intPart=parts.slice(0,-1).join('');
return intPart+'.'+last;
}
return parts.join('');
}
function safeCalc(expr){
if(typeof expr!=='string')return NaN;
expr=expr.trim();
if(!expr)return NaN;
if(!/^[0-9+\-*/().\s]+$/.test(expr))return NaN;
expr=expr.replace(/\d+(?:\.\d+)*/g,m=>normalizeAmtToken(m));
let i=0;
function skipWs(){while(expr[i]===' ')i++;}
function parseExpr(){
let v=parseTerm();
while(true){
skipWs();
if(expr[i]==='+'){i++;v+=parseTerm();}
else if(expr[i]==='-'){i++;v-=parseTerm();}
else break;
}
return v;
}
function parseTerm(){
let v=parseFactor();
while(true){
skipWs();
if(expr[i]==='*'){i++;v*=parseFactor();}
else if(expr[i]==='/'){i++;const d=parseFactor();v=d===0?NaN:v/d;}
else break;
}
return v;
}
function parseFactor(){
skipWs();
if(expr[i]==='('){i++;const v=parseExpr();skipWs();if(expr[i]===')')i++;return v;}
if(expr[i]==='-'){i++;return -parseFactor();}
if(expr[i]==='+'){i++;return parseFactor();}
const start=i;
while(i<expr.length&&/[0-9.]/.test(expr[i]))i++;
if(start===i)return NaN;
return parseFloat(expr.slice(start,i));
}
try{
const result=parseExpr();
skipWs();
if(i<expr.length)return NaN;
return result;
}catch(e){return NaN;}
}
function evalAmtExpr(id){
const el=document.getElementById(id);
if(!el)return;
const raw=el.value;
if(!raw||!/[+\-*/.]/.test(raw))return;
const r=safeCalc(raw);
if(!isNaN(r)&&isFinite(r)){
el.value=String(Math.round(r*100)/100);
el.dispatchEvent(new Event('input',{bubbles:true}));
}
}
let calcTargetId=null, calcExpr='';
function openCalc(targetId){
calcTargetId=targetId;
const el=document.getElementById(targetId);
calcExpr=(el&&el.value&&/^[0-9.]+$/.test(el.value))?el.value:'';
calcRenderDisplay();
openModal('calcModal');
}
function closeCalc(){ closeModal('calcModal'); }
function calcRenderDisplay(){
const exprEl=document.getElementById('calcExprEl');
const valEl=document.getElementById('calcValEl');
if(!exprEl||!valEl)return;
if(!calcExpr){ exprEl.textContent=''; valEl.textContent='0'; return; }
if(/[+\-*/]$/.test(calcExpr)||(!/[+\-*/]/.test(calcExpr)&&!/\./.test(calcExpr))){
exprEl.textContent='';
valEl.textContent=calcExpr;
}else{
const r=safeCalc(calcExpr);
exprEl.textContent=calcExpr;
valEl.textContent=isNaN(r)?calcExpr:String(Math.round(r*100)/100);
}
}
function calcPress(ch){
if('+-*/'.includes(ch)){
if(!calcExpr)calcExpr='0';
if(/[+\-*/]$/.test(calcExpr))calcExpr=calcExpr.slice(0,-1);
calcExpr+=ch;
}else{
calcExpr+=ch;
}
calcRenderDisplay();
}
function calcClear(){ calcExpr=''; calcRenderDisplay(); }
function calcBackspace(){ calcExpr=calcExpr.slice(0,-1); calcRenderDisplay(); }
function calcEquals(){
const r=safeCalc(calcExpr);
if(!isNaN(r)&&isFinite(r)) calcExpr=String(Math.round(r*100)/100);
calcRenderDisplay();
}
function calcUseResult(){
if(!calcTargetId){ closeCalc(); return; }
let val=calcExpr;
if(/[+\-*/.]/.test(val)){
const r=safeCalc(val);
val=isNaN(r)?'':String(Math.round(r*100)/100);
}
const el=document.getElementById(calcTargetId);
if(el&&val!==''){
el.value=val;
el.dispatchEvent(new Event('input',{bubbles:true}));
}
closeCalc();
}

// scan-ocr.js — Scan struk belanja (OCR): struk belanja, bukti transfer, tanggal dari foto, odometer, portofolio aset, kategori & sparepart otomatis dari struk
// Dipindah ke modules/shared/scan-ocr.js (Sesi 17-18 restrukturisasi folder — lihat docs/FILE-MAP.md & RENCANA-SESI.md; isi & nama file TIDAK berubah, cuma lokasi folder).
// Domain terakhir hasil pembedahan features-filter-scanstruk-ocr.js (v84-v87 sudah memindahkan Akun, lookup Kategori,
// Filter/Laporan, dan Form Transaksi+Cicilan ke file domain masing2 — lihat PEMISAHAN-FILE-ROADMAP.md). Sisa file lama
// ini murni scan OCR, jadi di v88 filenya di-rename jadi scan-ocr.js (isi tidak berubah, cuma nama file + komentar).
// PENTING: file ini HARUS dimuat sesuai urutan build.js (GROUP_A/GROUP_B) karena beberapa modul saling referensi. Urutan grup ini: data-default.js, features-helpers-global-security.js, diagnostik-versi.js, format-tema.js, error-handler.js, helper-teks.js, keamanan-pin.js, modal-navigasi.js, reset-gaji-mingguan.js, debug-console.js, pengaturan-search.js, onboarding.js, kalkulator-input.js, scan-ocr.js, filter-laporan.js, akun.js, gaji-calc.js, transaksi.js, profil-pengaturan.js, kategori.js, tagihan-kalender.js, backup-restore.js, payroll-absensi.js, tukang-absensi.js

// _amc015: fallback lokal addMonthsClamped() (BUG-015, s406) -- file ini kadang dimuat berdiri
// sendiri lewat harness test (tests/helpers/loadSource.js) TANPA modules/shared/
// features-helpers-global-security.js ikut dimuat di sandbox yang sama, jadi addMonthsClamped()
// global belum tentu ada. Fallback ini pakai algoritma identik dgn versi global supaya hasil
// selalu sama persis di manapun dipanggil (bukan re-implementasi logic baru).
function _amc015(base,months){
if(typeof addMonthsClamped==='function')return addMonthsClamped(base,months);
if(!(base instanceof Date)||isNaN(base.getTime()))return base;
const day=base.getDate();
base.setDate(1);
base.setMonth(base.getMonth()+months);
const lastDayOfTargetMonth=new Date(base.getFullYear(),base.getMonth()+1,0).getDate();
base.setDate(Math.min(day,lastDayOfTargetMonth));
return base;
}

// BUGFIX: semua fungsi scan* di file ini dulu punya pengecekan `if(typeof Tesseract==='undefined')`
// SEBELUM memanggil ocrRecognize() -- niatnya kasih pesan jelas kalau modul OCR belum siap. Tapi
// Tesseract cuma didaftarkan sbg global lewat ensureTesseract() di DALAM getOcrWorker() di bawah,
// yang HANYA dipanggil dari ocrRecognize(). Jadi di scan pertama kali (fresh session, Tesseract
// belum pernah dimuat), pengecekan itu selalu true & langsung return SEBELUM ocrRecognize/
// ensureTesseract sempat jalan -- OCR jadi tidak akan pernah bisa jalan sama sekali di scan
// pertama manapun (chicken-egg deadlock). Fix: pengecekan itu dihapus dari semua scan* function;
// biarkan ocrRecognize() yang coba muat modulnya, kegagalan (termasuk modul gagal dimuat) tetap
// ditangani & dikasih pesan jelas lewat scanErrorMessage() di catch block masing2 fungsi.
// FIX (audit: race condition async scan vs pindah record) — semua fungsi scan* di
// bawah ini menulis hasil OCR ke ID field TETAP (mis. #billAmt, #bbmCost,
// #servisCost) yang dipakai ulang oleh modal yang sama utk record APAPUN yang
// sedang diedit (mis. billEditId di tagihan-kalender.js). ocrRecognize() (Tesseract)
// makan waktu beberapa detik -- kalau user menutup modal & membuka record LAIN
// (mis. Tagihan lain) SEBELUM OCR selesai, hasil scan yang telat itu dulu tetap
// ditulis ke field yang sekarang sudah terikat ke record baru, diam-diam menimpa
// nominal/tanggal/catatan record yang salah tanpa peringatan apa pun.
// Fix: openModal() (modal-navigasi.js) menaikkan window._modalEpoch tiap kali
// modal dibuka/dibuka-ulang (termasuk modal yang sama utk record berbeda, krn
// openBillModal() dkk selalu memanggil ulang openModal() di akhir). Tiap scan*
// menangkap epoch SEBELUM await OCR lewat _scanEpochNow(), lalu _scanEpochStale()
// dipanggil PERSIS setelah OCR selesai -- kalau epoch sudah berubah (modal/record
// sudah berpindah), penulisan hasil OCR dibatalkan & user diberi tahu lewat toast,
// bukan ditulis diam-diam ke record yang salah.
function _scanEpochNow(){return window._modalEpoch||0;}
function _scanEpochStale(epoch){
if(_scanEpochNow()!==epoch){
toast('⚠️ Hasil scan dibatalkan — tab/form sudah berpindah sebelum scan selesai');
return true;
}
return false;
}
// FIX (audit UI/UX 2026-08, Ronde 7): tombol scan (OCR) & tombol Backup dulu
// TIDAK punya state disabled+spinner yang bertahan SELAMA proses berjalan --
// toast "mohon tunggu" transient (6 detik) hilang duluan sebelum OCR/upload
// benar2 selesai (bisa 10-20+ detik di koneksi lambat), jadi tombol masih
// bisa di-tap ulang berkali-kali (memicu worker OCR/upload dobel/tumpang
// tindih). Fix: helper generik _scanBtnCapture/_scanBtnBusy/_scanBtnIdle di
// bawah ini -- dipanggil dari SETIAP titik scan* (bukan 1 komponen yang
// ditempel global, sesuai catatan audit sebelumnya: per titik pemanggil).
// Tombol yang memicu scan* SELALU tombol <button> yang barusan di-klik
// (onclick="scanXxx(...)" inline), jadi document.activeElement pas fungsi
// scan* dipanggil (SEBELUM dialog file async) reliable jadi referensi tombol
// itu tanpa perlu ubah tiap markup HTML pemanggil satu-satu. Busy state baru
// benar2 dipasang saat user SUDAH pilih file (bukan saat baru buka dialog),
// supaya kalau dialog file di-Cancel tombol tidak nyangkut disabled.
function _scanBtnCapture(){
const el=(typeof document!=='undefined')?document.activeElement:null;
return(el&&el.tagName==='BUTTON'&&!el.disabled)?el:null;
}
function _scanBtnBusy(btn,label){
if(!btn||btn.dataset.scanBusy==='1')return;
btn.dataset.scanBusy='1';
btn.dataset.scanOrigHtml=btn.innerHTML;
btn.disabled=true;
btn.setAttribute('aria-busy','true');
btn.innerHTML='<span class="btn-spinner" aria-hidden="true"></span> '+(label||'Memproses...');
}
function _scanBtnIdle(btn){
if(!btn||btn.dataset.scanBusy!=='1')return;
btn.disabled=false;
btn.removeAttribute('aria-busy');
if(btn.dataset.scanOrigHtml!=null)btn.innerHTML=btn.dataset.scanOrigHtml;
delete btn.dataset.scanBusy;
delete btn.dataset.scanOrigHtml;
}
let _ocrWorkerPromise=null;
function getOcrWorker(){
if(!_ocrWorkerPromise){
_ocrWorkerPromise=ensureTesseract().then(()=>Tesseract.createWorker('eng')).catch(err=>{
console.error('[OCR] gagal membuat worker Tesseract:',err);
_ocrWorkerPromise=null;
throw err;
});
}
return _ocrWorkerPromise;
}
async function resetOcrWorker(){
const old=_ocrWorkerPromise;
_ocrWorkerPromise=null;
if(old){
try{const w=await old; if(w&&typeof w.terminate==='function')await w.terminate();}catch(e){ }
}
}
function withTimeout(promise,ms,label){
return Promise.race([
promise,
new Promise((_,reject)=>setTimeout(()=>reject(new Error('TIMEOUT:'+label)),ms))
]);
}
function scanErrorMessage(err){
console.error('[OCR] gagal scan:',err);
const raw=(err&&err.message)||(err&&err.error&&err.error.message)||(typeof err==='string'?err:'');
const name=(err&&err.name)||'';
// BUGFIX: sebelumnya izin kamera ditolak (NotAllowedError) jatuh ke pesan generik di paling
// bawah ("error tidak diketahui...") yang menyuruh user cek internet/restart app -- padahal
// masalahnya murni izin kamera di browser/OS, bukan OCR/koneksi. User jadi bingung & coba-coba
// hal yang salah. Fix: deteksi NotAllowedError/PermissionDeniedError secara eksplisit & kasih
// instruksi yang langsung relevan (cek izin kamera di browser + Android), bukan pesan OCR umum.
if(name==='NotAllowedError'||name==='PermissionDeniedError'||/permission denied|not allowed/i.test(raw)){
return 'izin kamera ditolak — buka pengaturan situs di browser (ikon gembok/Shields di address bar) lalu izinkan Kamera untuk situs ini, dan pastikan izin Kamera utk aplikasi browser juga diizinkan di Pengaturan HP (Apps → nama browser → Permissions → Camera), lalu coba scan lagi';
}
if(name==='NotFoundError'||name==='OverconstrainedError')return 'kamera tidak ditemukan/tidak cocok di perangkat ini — coba pakai "Scan dari Galeri" sbg alternatif';
if(name==='NotReadableError')return 'kamera sedang dipakai aplikasi lain — tutup aplikasi kamera/video call lain, lalu coba scan lagi';
if(raw&&raw.startsWith('TIMEOUT:'))return 'koneksi lambat/putus saat mengunduh modul OCR — cek internet & coba lagi (hindari download lain bareng)';
if(raw&&/fetch|network|load/i.test(raw))return 'gagal mengunduh modul OCR, cek koneksi internet & coba lagi';
if(raw&&/SetImageFile|SetImage|null/i.test(raw))return 'modul OCR sempat gagal muat sempurna, sudah dicoba ulang otomatis tapi masih gagal — coba scan sekali lagi';
if(raw)return raw;
return 'error tidak diketahui — cek koneksi internet, lalu coba lagi (kalau masih gagal, coba tutup & buka lagi aplikasinya)';
}
function downscaleImage(file,maxWidth){
return new Promise((resolve)=>{
try{
const img=new Image();
const url=URL.createObjectURL(file);
img.onload=()=>{
URL.revokeObjectURL(url);
const scale=Math.min(1,maxWidth/img.width);
if(scale>=1){resolve(file);return;}
const canvas=document.createElement('canvas');
canvas.width=Math.round(img.width*scale);
canvas.height=Math.round(img.height*scale);
const ctx=canvas.getContext('2d');
ctx.drawImage(img,0,0,canvas.width,canvas.height);
canvas.toBlob((blob)=>{resolve(blob||file);},'image/jpeg',0.85);
};
img.onerror=()=>{URL.revokeObjectURL(url);resolve(file);};
img.src=url;
}catch(err){resolve(file);}
});
}
async function ocrRecognize(file){
const scaled=await downscaleImage(file,1600);
try{
const worker=await withTimeout(getOcrWorker(),45000,'worker-init');
return await withTimeout(worker.recognize(scaled),30000,'recognize');
}catch(err){
if(err&&err.message&&err.message.startsWith('TIMEOUT:'))throw err;
console.warn('[OCR] worker tampak bermasalah, mencoba bikin ulang & scan sekali lagi:',err);
await resetOcrWorker();
const worker2=await withTimeout(getOcrWorker(),45000,'worker-init-retry');
return withTimeout(worker2.recognize(scaled),30000,'recognize-retry');
}
}
const _bulanIndoMap={jan:1,januari:1,feb:2,februari:2,mar:3,maret:3,apr:4,april:4,mei:5,jun:6,juni:6,jul:7,juli:7,agu:8,agt:8,agustus:8,sep:9,sept:9,september:9,okt:10,oktober:10,nov:11,november:11,des:12,desember:12};
function extractDateFromText(text){
const numMatch=text.match(/(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})/);
if(numMatch){
let[,d,m,y]=numMatch;if(y.length===2)y='20'+y;
const iso=`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
if(!isNaN(new Date(iso).getTime()))return iso;
}
const bulanRegex=new RegExp('(\\d{1,2})\\s+([A-Za-z]{3,10})\\s+(\\d{4})','i');
const textMatch=text.match(bulanRegex);
if(textMatch){
const[,d,bulanRaw,y]=textMatch;
const bulan=_bulanIndoMap[bulanRaw.toLowerCase()];
if(bulan){
const iso=`${y}-${String(bulan).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
if(!isNaN(new Date(iso).getTime()))return iso;
}
}
return null;
}
// BUGFIX: struk/riwayat pesanan marketplace (mis. "Detail Pesanan" Tokopedia/Shopee) sering
// punya banyak angka bertingkat -- harga produk, ongkir, voucher, asuransi, dst -- dan yang
// BENERAN dibayar (mis. "Total Belanja"/"Total Tagihan"/"Total Pembayaran") bisa LEBIH KECIL
// dari harga produk doang (karena voucher/diskon). scanReceipt()/scanReceiptBelanja() dulu
// cuma ambil Math.max(...nums) dari SEMUA angka di struk -- jadi salah ambil harga produk
// (lebih besar) padahal yang harus diisi ke nominal transaksi itu total akhir yang lebih kecil.
// Fix: kalau ada baris berlabel total akhir yang jelas, prioritaskan itu; fallback ke angka
// terbesar kalau labelnya tidak ketemu (struk kasir biasa/format lain). Sengaja TIDAK match
// "Subtotal ..." atau "Total ongkos kirim" dsb (butuh kata "total" LANGSUNG diikuti salah satu
// kata kunci di bawah, bukan cuma mengandung substring "total").
// BUGFIX: e-wallet/dompet digital (GoPay dkk) pakai label "Total Transaksi" utk
// nominal akhir yg beneran dibayar (bukan "Total belanja/tagihan/pembayaran"
// spt marketplace) -- ditambahkan supaya tidak fallback salah ke harga barang.
const RECEIPT_TOTAL_LABEL_RE=/total\s*(belanja|tagihan|pembayaran|transaksi|bayar|(?:yang\s*)?harus\s*dibayar)\b/i;
// BUGFIX: catatan transaksi (txNote) diisi dari "baris pertama" hasil OCR yang bukan angka murni.
// Itu cocok untuk struk kasir fisik (baris pertama = nama toko), tapi SALAH untuk screenshot
// marketplace (Tokopedia/Shopee/dll) seperti "Detail Pesanan" -- baris paling atas di situ malah
// jam status bar HP ("20:53"), judul halaman, nomor pesanan, atau "Lihat Invoice", bukan nama
// barang. Akibatnya catatan hasil scan jadi terisi teks acak, bukan nama produk yang dibeli.
// Fix: skip baris "chrome" umum ini saat mencari firstLine, supaya jatuh ke baris nama produk.
const RECEIPT_NOISE_LINE_RE=/^\d{1,2}[:.]\d{2}$|^\d{1,3}\s*%$|detail\s*pesanan|no\.?\s*pesanan|lihat\s*invoice|tanggal\s*pembelian|^selesai$|^diproses$|^dikirim$|^dibatalkan$|detail\s*produk|beli\s*lagi|chat\s*penjual|info\s*pengiriman|\bwib\b|\d{1,2}\s+(jan(?:uari)?|feb(?:ruari)?|mar(?:et)?|apr(?:il)?|mei|jun(?:i)?|jul(?:i)?|agu(?:stus)?|sep(?:t|tember)?|okt(?:ober)?|nov(?:ember)?|des(?:ember)?)\s+\d{4}/i;
function scanReceipt(amtId,dateId,noteId){
const _btn=_scanBtnCapture();
const inp=document.createElement('input');
inp.type='file'; inp.accept='image/*';
inp.onchange=async(e)=>{
const file=e.target.files[0]; if(!file)return;
_scanBtnBusy(_btn,'Memindai...');
toast('🔍 Memindai gambar, mohon tunggu...',6000);
try{
const _scanEpoch=_scanEpochNow();
const result=await ocrRecognize(file);
if(_scanEpochStale(_scanEpoch))return;
const text=result&&result.data?result.data.text:'';
const rawNums=text.match(/\d{1,3}(?:[.,]\d{3})+(?:[.,]\d{1,2})?|\d{4,}/g)||[];
const nums=rawNums.map(s=>parseFloat(s.replace(/[.,](?=\d{3}(\D|$))/g,'').replace(',','.'))).filter(n=>n>=500&&n<500000000);
const labeledTotal=extractLabeledAmount(text,RECEIPT_TOTAL_LABEL_RE);
const bestAmt=labeledTotal!=null?Math.round(labeledTotal):(nums.length?Math.round(Math.max(...nums)):null);
if(bestAmt!=null&&amtId){const el=document.getElementById(amtId);if(el){el.value=bestAmt;if(el.oninput)el.oninput();}}
const isoForBill=extractDateFromText(text);
if(dateId&&isoForBill){const el=document.getElementById(dateId);if(el)el.value=isoForBill;}
const firstLine=text.split('\n').map(l=>l.trim()).find(l=>l.length>3&&!/^\d+$/.test(l));
if(firstLine){const el=document.getElementById(noteId);if(el)el.value=firstLine.slice(0,60);}
toast(bestAmt!=null?'✅ Scan selesai, cek & koreksi hasilnya':'⚠️ Nominal tidak terbaca, isi manual ya');
await maybeOfferPaylaterReminder(text,bestAmt,isoForBill);
}catch(err){
toast('❌ Gagal scan: '+scanErrorMessage(err));
}finally{
_scanBtnIdle(_btn);
}
};
inp.click();
}
function guessTransferNameFromText(text){
const lines=text.split('\n').map(l=>l.trim()).filter(Boolean);
const kw=/(kepada|penerima|nama\s*penerima|tujuan|a\.?n\.?|acc(?:ount)?\s*name|beneficiary|received?\s*by)/i;
for(let i=0;i<lines.length;i++){
if(kw.test(lines[i])){
const m=lines[i].match(/(?:kepada|penerima|nama\s*penerima|tujuan|a\.?n\.?|acc(?:ount)?\s*name|beneficiary|received?\s*by)\s*[:\-]?\s*(.+)/i);
if(m&&m[1]&&m[1].trim().length>2&&!/^\d+$/.test(m[1].trim()))return m[1].trim().slice(0,40);
const next=lines[i+1];
if(next&&next.length>2&&!/^\d+$/.test(next))return next.slice(0,40);
}
}
return null;
}
