if(ocrMinConfEl&&typeof setOcrMinConfidence==='function') setOcrMinConfidence(ocrMinConfEl.value);
document.getElementById('hNama').textContent=D.profile.nama;
updateProfilPTKPPreview();
updateUsiaPreview();
