// finance-intelligence.js — Finance Intelligence Foundation (Sesi 74, Batch 6).
// Target sesi: Cash Flow Summary, Budget Summary, Income vs Expense,
// Financial Health Score, Insight dasar — lihat docs/BATCH_PLAN.md § Batch 6.
//
// PRINSIP (RULE #1 sesi ini): 100% REUSE, TIDAK ada framework/state baru,
// TIDAK duplikasi logic, TIDAK mengubah struktur data D. Semua angka di
// bawah dihitung dari service yang SUDAH ADA:
//   - computeCashflowForecast()      (modules/finance/tx-list-cashflow.js)
//   - Budget.getUsed()/getEffectiveLimit()   (budget.js)
//   - totalSaldoAkun()               (modules/finance/akun.js)
//   - totalDebtValue()               (pajak-aset-ui-wrappers.js)
// FinanceIntelligence TIDAK menghitung ulang rata-rata income/expense,
// proyeksi saldo, pemakaian anggaran, atau saldo akun — semua itu dibaca
// apa adanya lewat pemanggilan fungsi/objek di atas. Satu-satunya logic
// yang genuinely baru di sini adalah agregasi income vs expense per
// rentang tanggal EKSPLISIT (`incomeVsExpense({from,to})`) — sebelumnya
// tidak ada fungsi murni (non-DOM) utk itu, yang ada cuma versi yang baca
// input filter dari DOM (getRange()/getTxListRange(), filter-laporan.js).
//
// Semua fungsi di bawah PURE (read-only) — tidak pernah memanggil save()
// atau menulis ke D/localStorage, tidak menyentuh DOM. Dipakai sbg lapisan
// data utk widget/dashboard masa depan & AI briefing (di luar scope sesi
// ini — TIDAK ada UI/wiring baru sesi ini, murni fondasi data/service).
const FinanceIntelligence = {

// KW perf fix lanjutan: incomeVsExpense()/budgetSummary() (tanpa argumen = rentang/bulan
// default) dipanggil BERULANG dalam 1 siklus render yang sama -- summary()/healthScore()/
// insights() saling manggil salah satu/​ketiganya lagi dari dalam (lihat komentar di method
// masing2 di bawah), DITAMBAH dipanggil independen oleh banyak presenter lain
// (FinanceDashboard/BudgetRecommendationPresenter/FinancialHealthScorePresenter/
// FinancialRiskDashboardPresenter/CrossDashboardCard dst) di render burst yang sama. Cache di
// sini HANYA utk panggilan tanpa argumen eksplisit (kasus paling sering) -- kalau range/month/
// year eksplisit dioper (mis. lihat bulan lain), SELALU dihitung fresh, tidak pernah cache (0
// risiko data periode salah). Invalidate lewat invalidateCache() di bawah, dipanggil dari hook
// yang sama dgn cache saldo akun (save()/renderPageContent()).
_ivxCache: undefined,
_budgetSummaryCache: undefined,
invalidateCache() {
  this._ivxCache = undefined;
  this._budgetSummaryCache = undefined;
},

// _isTxAccountSelf(t) — Sesi 192 (Ownership Sync Akun & Keuangan): helper
// REUSE OwnershipEngine, dipakai HANYA utk exclude transaksi dari akun
// ber-ownership INVESTOR/CUSTOMER/THIRD_PARTY/FAMILY di agregat "Total
// Keuangan" (incomeVsExpense, yang jadi dasar cashflowSummary/healthScore/
// insights di bawah). D.transactions itu sendiri TIDAK disentuh/dihapus —
// transaksi & histori akun tetap tersimpan apa adanya, cuma tidak ikut
// dijumlah ke total income/expense.
// Toleran: transaksi tanpa accountId, atau accountId yg akunnya sudah
// tidak ada di D.accounts, tetap dihitung (fallback dianggap SELF) —
// SAMA prinsip toleran dgn OwnershipEngine.resolve() thd data lama.
_isTxAccountSelf(t) {
  if (typeof OwnershipEngine === 'undefined') return true;
  if (!t || !t.accountId) return true;
  const acc = (D.accounts || []).find((a) => a.id === t.accountId);
  if (!acc) return true;
  return OwnershipEngine.resolve(acc).type === 'SELF';
},

_resolveRange(range) {
  if (range && range.from && range.to) {
    return { from: new Date(range.from), to: new Date(range.to) };
  }
  const now = new Date();
  const m = (typeof curMonth === 'number') ? curMonth : now.getMonth();
  const y = (typeof curYear === 'number') ? curYear : now.getFullYear();
  const from = new Date(y, m, 1);
  const to = new Date(y, m + 1, 0);
  to.setHours(23, 59, 59, 999);
  return { from, to };
},

// incomeVsExpense(range?) — total income/expense murni dalam rentang
// [from,to] (default bulan berjalan lewat _resolveRange di atas). Baca
// D.transactions apa adanya, TIDAK mengubah/menambah field apa pun.
incomeVsExpense(range) {
  if (!range && this._ivxCache !== undefined) return this._ivxCache;
  const { from, to } = this._resolveRange(range);
  const txs = (D.transactions || []).filter((t) => {
    const d = new Date(t.date);
    return d >= from && d <= to && this._isTxAccountSelf(t);
  });
  const income = txs.filter((t) => t.type === 'income').reduce((s, t) => s + t.amount, 0);
  const expense = txs.filter((t) => t.type === 'expense').reduce((s, t) => s + t.amount, 0);
  const net = income - expense;
  const savingsRate = income > 0 ? net / income : 0;
  const result = { from, to, income, expense, net, savingsRate, txCount: txs.length };
  if (!range) this._ivxCache = result;
  return result;
},

// cashflowSummary() — wrapper TIPIS atas computeCashflowForecast() yang
// sudah ada (0 duplikasi rumus rata-rata/proyeksi), digabung dgn
// incomeVsExpense() bulan berjalan supaya jadi satu ringkasan siap-pakai.
// {ok:false} kalau computeCashflowForecast belum dimuat (guard urutan
// load, pola sama persis predictIncome/predictExpense/predictCashflow di
// tx-list-cashflow.js).
cashflowSummary() {
  if (typeof computeCashflowForecast !== 'function') {
    return { ok: false, reason: 'computeCashflowForecast belum dimuat' };
  }
  const cf = computeCashflowForecast();
  const currentMonth = this.incomeVsExpense();
  return { ok: true, ...cf, currentMonth };
},

// budgetSummary(month?, year?) — reuse Budget.getUsed()/getEffectiveLimit()
// (budget.js) atas D.budgets apa adanya (0 duplikasi rumus rollover/
// matchesPeriod/matchesTx). {ok:false} kalau Budget/D.budgets belum ada.
budgetSummary(month, year) {
  if (month == null && year == null && this._budgetSummaryCache !== undefined) return this._budgetSummaryCache;
  if (typeof Budget === 'undefined' || !D.budgets) {
    return { ok: false, reason: 'Budget belum dimuat' };
  }
  const now = new Date();
  const m = month != null ? month : ((typeof curMonth === 'number') ? curMonth : now.getMonth());
  const y = year != null ? year : ((typeof curYear === 'number') ? curYear : now.getFullYear());
  const items = D.budgets.map((b) => {
    const limit = Budget.getEffectiveLimit(b, m, y);
    const used = Budget.getUsed(b, m, y);
    const pct = limit > 0 ? used / limit : 0;
    return { id: b.id, name: b.name, limit, used, sisa: limit - used, pct, over: used > limit };
  });
  const totalLimit = items.reduce((s, b) => s + b.limit, 0);
  const totalUsed = items.reduce((s, b) => s + b.used, 0);
  const overCount = items.filter((b) => b.over).length;
  const result = {
    ok: true,
    month: m,
    year: y,
    items,
    totalLimit,
    totalUsed,
    totalSisa: totalLimit - totalUsed,
    overallPct: totalLimit > 0 ? totalUsed / totalLimit : 0,
    overCount,
  };
  if (month == null && year == null) this._budgetSummaryCache = result;
  return result;
},

// healthScore() — skor 0-100, komposit dari komponen yang TERSEDIA (bukan
// dihitung ulang, murni dibaca dari service yang sudah ada):
//   (1) savings rate bulan berjalan   — incomeVsExpense()
//   (2) budget adherence               — budgetSummary() (1 - overallPct)
//   (3) rasio utang thd saldo akun     — totalDebtValue()/totalSaldoAkun()
//   (4) proyeksi cashflow 30 hari      — computeCashflowForecast().projected
// Tiap komponen bobot 25, HANYA disertakan kalau service-nya tersedia
// (guard typeof, pola sama persis predictIncome dkk) — skor akhir
// diskalakan ulang dari bobot yang benar-benar tersedia (bukan gagal
// total kalau 1 service belum dimuat). Rule-based murni, TIDAK ada
// panggilan AI/ML, konsisten dgn gaya _financeOverspendCheck() dkk yang
// sudah ada di tx-list-cashflow.js.
healthScore() {
  const parts = [];
  const ie = this.incomeVsExpense();
  parts.push({
    key: 'savings',
    weight: 25,
    score: Math.max(0, Math.min(1, ie.income > 0 ? ie.savingsRate : 0)) * 25,
  });
  if (typeof Budget !== 'undefined' && D.budgets && D.budgets.length) {
    const bs = this.budgetSummary();
    parts.push({ key: 'budget', weight: 25, score: Math.max(0, Math.min(1, 1 - bs.overallPct)) * 25 });
  }
  // BUG FIX (S269, Finance Engine Validation): sebelumnya komponen "debt" di
  // sini pakai totalDebtValue() SAJA sbg "total utang" -> TIDAK menyertakan
  // sisa cicilan/paylater (totalCicilanOutstanding()), beda dari SSOT
  // resmi "total utang" project ini (`FI.totalDebt()`, sudah dipakai
  // Kekayaan.currentNetWorth() sejak S268 & DebtOptimizerAPI.dsr()) ->
  // Skor Kesehatan Finansial/Financial Risk Dashboard bisa meremehkan
  // beban utang kalau user punya cicilan aktif. Sekarang reuse
  // FI.totalDebt() (0 rumus baru) supaya konsisten dgn engine lain.
  if (typeof totalSaldoAkun === 'function' && typeof FI !== 'undefined' && typeof FI.totalDebt === 'function') {
    const saldo = totalSaldoAkun();
    const debt = FI.totalDebt();
    const debtRatio = saldo > 0 ? Math.min(1, debt / saldo) : (debt > 0 ? 1 : 0);
    parts.push({ key: 'debt', weight: 25, score: Math.max(0, 1 - debtRatio) * 25 });
  }
  if (typeof computeCashflowForecast === 'function') {
    const cf = computeCashflowForecast();
    parts.push({ key: 'cashflow', weight: 25, score: (cf.projected > 0 ? 1 : 0) * 25 });
  }
  const maxScore = parts.reduce((s, p) => s + p.weight, 0);
  const rawScore = parts.reduce((s, p) => s + p.score, 0);
  const score = maxScore > 0 ? Math.round((rawScore / maxScore) * 100) : 0;
  const label = score >= 80 ? 'Sehat' : score >= 60 ? 'Cukup Sehat' : score >= 40 ? 'Waspada' : 'Perlu Perhatian';
  return { score, label, parts };
},

// insights() — insight dasar, murni derivasi ambang batas dari 4 fungsi di
// atas. BUKAN duplikasi FinCoach (modules-calc.js) — FinCoach itu widget
// Dashboard proaktif dgn state dismiss/persist & mencakup banyak domain di
// luar finance murni (tagihan, servis, piutang, dst); di sini HANYA 4 rule
// dasar yang derivatif langsung dari cashflowSummary/budgetSummary/
// incomeVsExpense/healthScore milik FinanceIntelligence sendiri, tidak
// membaca ulang D atau menghitung ulang rumus apa pun.
insights() {
  const out = [];
  const ie = this.incomeVsExpense();
  if (ie.income > 0 && ie.net < 0) {
    const fmtNominal = typeof fmt === 'function' ? fmt : (n => 'Rp ' + Math.round(n || 0).toLocaleString('id-ID'));
    out.push({ type: 'warning', code: 'deficit', message: `Pengeluaran bulan ini (${fmtNominal(ie.expense)}) melebihi pemasukan (${fmtNominal(ie.income)}).` });
  } else if (ie.income > 0 && ie.savingsRate >= 0.2) {
    out.push({ type: 'positive', code: 'good_savings', message: `Tingkat tabungan bulan ini ${Math.round(ie.savingsRate * 100)}% dari pemasukan — di atas 20%.` });
  }
  if (typeof Budget !== 'undefined' && D.budgets && D.budgets.length) {
    const bs = this.budgetSummary();
    if (bs.overCount > 0) {
      out.push({ type: 'warning', code: 'budget_over', message: `${bs.overCount} anggaran sudah melebihi limit bulan ini.` });
    }
  }
  if (typeof computeCashflowForecast === 'function') {
    const cf = computeCashflowForecast();
    if (cf.projected < 0) {
      out.push({ type: 'warning', code: 'cashflow_negative', message: 'Proyeksi saldo 30 hari ke depan diperkirakan minus.' });
    }
  }
  const hs = this.healthScore();
  out.push({ type: 'info', code: 'health_score', message: `Skor kesehatan finansial: ${hs.score}/100 (${hs.label}).` });
  return out;
},

// summary() — satu pintu masuk gabungan (dipakai widget/AI briefing masa
// depan), murni memanggil ke-5 fungsi di atas, TIDAK ada logic tambahan.
summary() {
  return {
    cashflow: this.cashflowSummary(),
    budget: this.budgetSummary(),
    incomeVsExpense: this.incomeVsExpense(),
    healthScore: this.healthScore(),
    insights: this.insights(),
  };
},

};

// modules/finance/finance-dashboard.js — Finance Dashboard & AI Hook Foundation
// (Sesi 75, Batch 6). Lihat docs/BATCH_PLAN.md § Batch 6.
//
// PRINSIP (RULE #1 sesi ini): UI HANYA presenter. 100% REUSE
// FinanceIntelligence.summary() (modules/finance/finance-intelligence.js,
// Sesi 74) — TIDAK ada rumus baru, TIDAK menghitung ulang cashflow/budget/
// income-vs-expense/health score, TIDAK membaca D langsung utk angka apa
// pun (satu-satunya pembacaan D langsung di file ini murni presentasional:
// totalSaldoAkun()/totalDebtValue() utk Net Worth Card, KEDUANYA fungsi yang
// SUDAH ADA & juga dipakai FinanceIntelligence.healthScore() sendiri — bukan
// duplikasi rumus, cuma dipanggil ulang apa adanya krn FinanceIntelligence
// tidak expose angka net worth mentah sbg field summary()).
//
// Dipanggil dari renderKeuangan() (DIPINDAH dari DashboardHub.render() di Sesi 133; pola "tambahan murni" sama persis
// EIEDashboard.render()/DashboardHubAnalytics.render() — lihat komentar di
// dashboard-hub.js). Live-wiring renderDashboard() DIHAPUS di Sesi 134 (gap fix,
// sudah dobel dgn renderKeuangan(), lihat CHANGELOG.md Sesi 134), TIDAK ada mekanisme render baru.
//
// AI Hook (getAIHook()): satu pintu masuk read-only utk konsumen AI/briefing
// masa depan (ai-chat.js dst) — WRAPPER TIPIS ke FinanceIntelligence.summary(),
// 0 logic tambahan, 0 transformasi data. Nama "hook" di sini murni istilah
// UI (titik akses data), BUKAN React hook / lifecycle hook apa pun.

// AUDIT Sesi T2 (RENCANA-KERJA-toggle-hitungkas-dan-proyeksi-kas.md, Track 1): file ini
// terdaftar di scope T2 ("titik laporan utama Dashboard"), TAPI per RULE #1 di header file
// (100% REUSE FinanceIntelligence.summary(), 0 pembacaan D langsung utk angka apa pun kecuali
// totalSaldoAkun()/totalDebtValue() di _netWorthCard()) — 0 baris di file ini yang perlu diubah:
//   - _netWorthCard(): sudah otomatis ikut guard tx.hitungKas (Sesi T1) krn totalSaldoAkun()
//     memanggil recalcAccBalance() (modules/finance/akun.js) yang sudah di-guard sesi T1.
//   - _cashFlowCard()/_budgetCard()/_healthCard(): angkanya dari FinanceIntelligence.summary()
//     (incomeVsExpense()/budgetSummary()/healthScore(), modules/finance/finance-intelligence.js)
//     — jalur query TERPISAH dari dashCtx renderDashboard(), BELUM di-guard sesi ini. Disengaja
//     ditinggal ke sesi laporan sekunder (Sesi T4+ per RENCANA KERJA) supaya tiap file laporan
//     diaudit dulu satu-satu sebelum diubah (0 regresi tak terduga), bukan luput/lupa.
const FinanceDashboard = {

  // getAIHook() — reuse 100% FinanceIntelligence.summary(). Guard: kalau
  // FinanceIntelligence belum dimuat (urutan load / dipakai headless di
  // test), balikin {ok:false} alih-alih throw (pola sama persis
  // cashflowSummary()/budgetSummary() di finance-intelligence.js sendiri).
  getAIHook() {
    if (typeof FinanceIntelligence === 'undefined') {
      return { ok: false, reason: 'FinanceIntelligence belum dimuat' };
    }
    return { ok: true, ...FinanceIntelligence.summary() };
  },

  render() {
    const el = document.getElementById('findashGrid');
    if (!el) return; // container belum ada di halaman ini, aman diam2.

    const hook = this.getAIHook();
    if (!hook.ok) {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data finance intelligence belum tersedia</div></div>';
      return;
    }

    const cards = [
      this._netWorthCard(),
      this._cashFlowCard(hook.cashflow),
      this._budgetCard(hook.budget),
      this._healthCard(hook.healthScore),
      ...this._sparepartCards(),
    ];

    el.innerHTML = cards.map((c) => `
      <div class="findash-card${c.onClick ? ' u-pointer' : ''}"${c.onClick ? ` data-action="${escapeHtml(c.onClick.action)}" data-args="${escapeHtml(JSON.stringify(c.onClick.args))}"` : ''}>
        <div class="findash-card-icon">${c.icon}</div>
        <div class="findash-card-body">
          <div class="findash-card-label">${escapeHtml(c.label)}</div>
          <div class="findash-card-val${c.cls ? ' ' + c.cls : ''}">${escapeHtml(c.value)}</div>
          ${c.sub ? `<div class="findash-card-sub">${escapeHtml(c.sub)}</div>` : ''}
        </div>
      </div>
    `).join('');
  },

  // _sparepartCards() — Tahap 8D: integrasi Dashboard Keuangan + Sparepart.
  // 100% REUSE Sparepart.calcFinanceStats() (modules/vehicle/sparepart-
  // servis.js, dipanggil dgn D.partsStock/D.servisLogs apa adanya, 0 rumus
  // baru di sini) — file ini HANYA presenter, sama prinsip RULE #1 di
  // header file. Tiap kartu klik -> goToList() (fungsi yang sudah ada,
  // modules/finance/filter-laporan.js) membuka #page-carnotes tab Servis
  // (tempat Dashboard Sparepart & Stok Sparepart berada).
  _sparepartCards() {
    const money = (n) => (typeof fmt === 'function') ? fmt(n) : ('Rp ' + Math.round(n || 0));
    if (typeof Sparepart === 'undefined' || typeof Sparepart.calcFinanceStats !== 'function') return [];
    const stats = Sparepart.calcFinanceStats(D.partsStock, D.servisLogs);
    const trendSub = (tren) => {
      if (!tren.length) return undefined;
      const last = tren[tren.length - 1];
      const prev = tren.length > 1 ? tren[tren.length - 2] : null;
      if (!prev || prev.total <= 0) return last.label;
      const pct = Math.round(((last.total - prev.total) / prev.total) * 100);
      return `${last.label}: ${pct >= 0 ? '▲' : '▼'}${Math.abs(pct)}% vs ${prev.label}`;
    };
    const goSparepart = (targetId) => ({ action: 'goToList', args: [targetId, 'carnotes', 4, null, 'servis'] });
    return [
      {
        icon: '🛒', label: 'Total Pembelian Sparepart', value: money(stats.totalPembelian),
        onClick: goSparepart('stockList'),
      },
      {
        icon: '📦', label: 'Total Nilai Stok', value: money(stats.totalNilaiStok),
        onClick: goSparepart('stockList'),
      },
      {
        icon: '🔧', label: 'Total Nilai Sparepart Terpakai', value: money(stats.totalNilaiTerpakai),
        onClick: goSparepart('servisList'),
      },
      {
        icon: '🧾', label: 'Biaya Servis Sparepart', value: money(stats.biayaServisSparepart),
        onClick: goSparepart('servisList'),
      },
      {
        icon: '📈', label: 'Tren Pembelian Bulanan',
        value: stats.trenPembelianBulanan.length ? money(stats.trenPembelianBulanan[stats.trenPembelianBulanan.length - 1].total) : '—',
        sub: trendSub(stats.trenPembelianBulanan),
        onClick: goSparepart('sparepartDashboard'),
      },
      {
        icon: '📉', label: 'Tren Pemakaian Bulanan',
        value: stats.trenPemakaianBulanan.length ? money(stats.trenPemakaianBulanan[stats.trenPemakaianBulanan.length - 1].total) : '—',
        sub: trendSub(stats.trenPemakaianBulanan),
        onClick: goSparepart('sparepartDashboard'),
      },
    ];
  },

  // _netWorthCard() — BUG FIX (S268, SSOT Dashboard/Net Worth audit): card
  // ini sebelumnya menghitung "Kekayaan Bersih" sendiri lewat totalSaldoAkun()
  // - totalDebtValue() SAJA (tanpa aset/inventori bisnis/piutang, & tanpa
  // utangJT/cicilan) — beda dari SATU-SATUNYA rumus resmi Net Worth project
  // ini, `Kekayaan.currentNetWorth()` (modules/shared/modules-calc.js), yang
  // juga dipakai panel "Kekayaan Bersih" lain (renderBersih()), wealth
  // snapshot, actualCAGR, & AssetPortfolioAPI. Akibatnya kartu berlabel
  // "Kekayaan Bersih" di Finance Dashboard bisa tampilkan ANGKA BERBEDA dari
  // panel Kekayaan Bersih lain utk data yang sama. Sekarang reuse
  // `Kekayaan.currentNetWorth()` apa adanya (0 rumus baru) supaya
  // Dashboard/Report/Home konsisten (SSOT).
  _netWorthCard() {
    const money = (n) => (typeof fmt === 'function') ? fmt(n) : ('Rp ' + Math.round(n || 0));
    if (typeof Kekayaan === 'undefined' || typeof Kekayaan.currentNetWorth !== 'function'
      || typeof totalSaldoAkun !== 'function' || typeof totalDebtValue !== 'function') {
      return { icon: '💰', label: 'Kekayaan Bersih', value: '—', cls: '' };
    }
    const saldo = totalSaldoAkun();
    const debt = totalDebtValue();
    const net = Kekayaan.currentNetWorth();
    return {
      icon: '💰',
      label: 'Kekayaan Bersih',
      value: (net < 0 ? '-' : '') + money(Math.abs(net)),
      cls: net < 0 ? 'red' : 'green',
      sub: `Saldo ${money(saldo)} · Utang ${money(debt)}`,
    };
  },

  // _cashFlowCard(cf) — cf = FinanceIntelligence.summary().cashflow, dipakai
  // APA ADANYA (currentMonth.net dari incomeVsExpense() bulan berjalan,
  // projected dari computeCashflowForecast() — 0 recompute di sini).
  _cashFlowCard(cf) {
    const money = (n) => (typeof fmt === 'function') ? fmt(n) : ('Rp ' + Math.round(n || 0));
    if (!cf || !cf.ok) {
      return { icon: '💸', label: 'Arus Kas', value: '—', cls: '', sub: cf && cf.reason };
    }
    const net = cf.currentMonth.net;
    const projected = cf.projected;
    return {
      icon: '💸',
      label: 'Arus Kas Bulan Ini',
      value: (net < 0 ? '-' : '') + money(Math.abs(net)),
      cls: net < 0 ? 'red' : 'green',
      sub: projected != null ? `Proyeksi 30 hari: ${(projected < 0 ? '-' : '') + money(Math.abs(projected))}` : undefined,
    };
  },

  // _budgetCard(bs) — bs = FinanceIntelligence.summary().budget, dipakai APA
  // ADANYA (totalUsed/totalLimit/overallPct/overCount dari Budget.getUsed()/
  // getEffectiveLimit() — 0 recompute di sini).
  _budgetCard(bs) {
    const money = (n) => (typeof fmt === 'function') ? fmt(n) : ('Rp ' + Math.round(n || 0));
    if (!bs || !bs.ok) {
      return { icon: '📊', label: 'Anggaran', value: '—', cls: '', sub: bs && bs.reason };
    }
    const pct = Math.round((bs.overallPct || 0) * 100);
    return {
      icon: '📊',
      label: 'Pemakaian Anggaran',
      value: pct + '%',
      cls: bs.overCount > 0 ? 'red' : (pct >= 80 ? 'orange' : 'green'),
      sub: `${money(bs.totalUsed)} dari ${money(bs.totalLimit)}${bs.overCount > 0 ? ` · ${bs.overCount} lewat batas` : ''}`,
    };
  },

  // _healthCard(hs) — hs = FinanceIntelligence.summary().healthScore, dipakai
  // APA ADANYA (score/label sudah final dari healthScore() — 0 recompute).
  _healthCard(hs) {
    if (!hs) {
      return { icon: '❤️', label: 'Skor Kesehatan Finansial', value: '—', cls: '' };
    }
    const cls = hs.score >= 80 ? 'green' : hs.score >= 60 ? '' : hs.score >= 40 ? 'orange' : 'red';
    return {
      icon: '❤️',
      label: 'Skor Kesehatan Finansial',
      value: `${hs.score}/100`,
      cls,
      sub: hs.label,
    };
  },

};

// modules/finance/financial-forecast-api.js — Financial Forecast API
// (Sesi 91, Batch 10). Target sesi: Financial Forecast Foundation — lihat
// docs/BATCH_PLAN.md § Batch 10.
//
// PRINSIP (RULE #1 sesi ini): 100% REUSE FinanceDashboard.getAIHook()
// (modules/finance/finance-dashboard.js, Sesi 75 — WRAPPER TIPIS ke
// FinanceIntelligence.summary(), Sesi 74) — TIDAK ada rumus baru, TIDAK
// duplikasi logic, TIDAK framework baru, TIDAK mengubah struktur data D,
// TIDAK membaca D langsung sama sekali di file ini.
//
// Income Forecast/Expense Forecast/Cash Flow Projection di bawah BUKAN
// hasil hitungan baru — ketiganya murni membaca ulang field yang SUDAH
// FINAL dari `FinanceDashboard.getAIHook().cashflow` (yang sendiri 100%
// reuse `computeCashflowForecast()`, modules/finance/tx-list-cashflow.js,
// via `FinanceIntelligence.cashflowSummary()`):
//   - incAvg     -> Income Forecast (rata-rata pemasukan/bulan)
//   - expAvg     -> Expense Forecast (rata-rata pengeluaran/bulan)
//   - saldoNow/projected/billsDue/upcoming -> Cash Flow Projection
// Pola arsitektur SAMA PERSIS DecisionCenterAPI (modules/cross/
// decision-center-api.js, Sesi 90) — satu pintu masuk data gabungan yang
// meneruskan field dari layer di bawahnya apa adanya, ditambah
// pengelompokan/pemberian nama presentasional (BUKAN kategori/rumus baru).
//
// Semua fungsi di bawah PURE (read-only) — tidak pernah memanggil save()
// atau menulis ke D/localStorage, tidak menyentuh DOM. TIDAK ada UI di
// file ini — presenternya (FinancialForecastPresenter) ada di file
// terpisah, sesi ini juga, 100% konsumsi objek ini.
const FinancialForecastAPI = {

// _cashflow() — helper internal: satu titik akses ke
// FinanceDashboard.getAIHook().cashflow (yang sendiri, kalau ok, adalah
// hasil FinanceIntelligence.cashflowSummary() apa adanya). Guard berlapis
// (FinanceDashboard belum dimuat / getAIHook() {ok:false} /
// cashflow {ok:false}) — SEMUA diteruskan apa adanya, pola sama persis
// DecisionCenterAPI.summary() meneruskan {ok:false} dari
// LifeDashboardSummaryAPI.summary().
_cashflow() {
  if (typeof FinanceDashboard === 'undefined') {
    return { ok: false, reason: 'FinanceDashboard belum dimuat' };
  }
  const hook = FinanceDashboard.getAIHook();
  if (!hook.ok) return hook;
  if (!hook.cashflow || !hook.cashflow.ok) {
    return hook.cashflow || { ok: false, reason: 'cashflow tidak tersedia' };
  }
  return hook.cashflow;
},

// incomeForecast() — Income Forecast. `avgMonthly`/`months` dibaca APA
// ADANYA dari `incAvg`/`months` (computeCashflowForecast()), `currentMonth`
// dari `currentMonth.income` (incomeVsExpense() bulan berjalan,
// FinanceIntelligence) — 0 rata-rata dihitung ulang di sini.
incomeForecast() {
  const cf = this._cashflow();
  if (!cf.ok) return cf;
  return {
    ok: true,
    avgMonthly: cf.incAvg,
    months: cf.months,
    currentMonthIncome: cf.currentMonth.income,
  };
},

// expenseForecast() — Expense Forecast. Pola SAMA PERSIS incomeForecast()
// di atas, cuma sisi expense (`expAvg`/`currentMonth.expense`).
expenseForecast() {
  const cf = this._cashflow();
  if (!cf.ok) return cf;
  return {
    ok: true,
    avgMonthly: cf.expAvg,
    months: cf.months,
    currentMonthExpense: cf.currentMonth.expense,
  };
},

// cashflowProjection() — Cash Flow Projection. `saldoNow`/`projected`/
// `billsDue` dibaca APA ADANYA dari computeCashflowForecast() (proyeksi
// saldo 30 hari = saldoNow + incAvg - expAvg - billsDue, SUDAH final di
// sana — TIDAK dihitung ulang di sini). `upcomingCount` murni
// `.length` dari array `upcoming` yang sudah ada (0 filter/agregasi baru).
cashflowProjection() {
  const cf = this._cashflow();
  if (!cf.ok) return cf;
  return {
    ok: true,
    saldoNow: cf.saldoNow,
    projected: cf.projected,
    billsDue: cf.billsDue,
    upcomingCount: (cf.upcoming || []).length,
  };
},

// summary() — satu pintu masuk gabungan (dipakai presenter/AI briefing
// masa depan), murni memanggil ke-3 fungsi di atas, TIDAK ada logic
// tambahan. `ok` true hanya kalau ketiganya ok (pola sama persis
// FinanceIntelligence.summary() yang juga menggabungkan sub-hasil apa
// adanya, tapi di sini ditambah 1 flag gabungan supaya presenter bisa
// cek sekali saja alih-alih 3x, pola sama DecisionCenterAPI.summary()
// yang juga expose `ok` gabungan di level teratas).
summary() {
  const income = this.incomeForecast();
  const expense = this.expenseForecast();
  const cashflowProjection = this.cashflowProjection();
  return {
    ok: !!(income.ok && expense.ok && cashflowProjection.ok),
    income,
    expense,
    cashflowProjection,
  };
},

};

// modules/finance/financial-forecast-presenter.js — Financial Forecast
// Presenter (Sesi 91, Batch 10). Target sesi: Financial Forecast
// Foundation — lihat docs/BATCH_PLAN.md § Batch 10.
//
// PRINSIP (RULE #1 sesi ini): UI HANYA presenter. 100% REUSE
// FinancialForecastAPI.summary() (modules/finance/financial-forecast-api.js,
// sesi ini — sendiri 100% reuse FinanceDashboard.getAIHook()/
// FinanceIntelligence, Sesi 74/75) — TIDAK ada rumus baru, TIDAK
// menghitung ulang rata-rata income/expense atau proyeksi saldo, TIDAK
// membaca D langsung sama sekali. Pola SAMA PERSIS FinanceDashboard.render()
// (3 kartu, bukan 4 — Net Worth Card sengaja TIDAK diulang di sini, sudah
// ada di #findashGrid).
//
// Dipanggil dari renderKeuangan() (DIPINDAH dari DashboardHub.render() di Sesi 133; pola "tambahan murni" sama persis
// FinanceDashboard.render()/VehicleDashboard.render() — lihat komentar di
// dashboard-hub.js). Live-wiring renderDashboard() DIHAPUS di Sesi 134 (gap fix,
// sudah dobel dgn renderKeuangan(), lihat CHANGELOG.md Sesi 134), TIDAK ada mekanisme render baru.
// CSS TIDAK baru — reuse penuh class findash-grid/findash-card (grid
// generik, sudah dipakai FinanceDashboard/VehicleDashboard/dst).
//
// FORECAST_NAV_TARGETS (S254B — Batch Finance Navigation Consistency) —
// tujuan navigasi tiap kartu #forecastGrid. MURNI DATA (0 logic navigasi
// baru), format {page,goTo} SAMA PERSIS format target
// dashHubNavigateToFeature() yang SUDAH ADA (dashboard-hub.js). Nama
// disendirikan per-file supaya tidak bentrok dgn const global lain
// (lihat kasus S251/S253/S254A). Ketiga kartu murni komposit 1 forecast
// keuangan yang sama — TIDAK ada 1 daftar spesifik per pos, jadi target
// = container section-nya sendiri (forecastWrap, dashboard-hub,
// TERVERIFIKASI ADA di index.html/app_production.html), pola sama
// persis FINHEALTH_NAV_TARGETS.self (S254A, self-scroll utk kartu
// komposit).
const FORECAST_NAV_TARGETS = Object.freeze({
  self: { page: 'keuangan', tab: 'laporan', goTo: 'forecastWrap' },
});
const FinancialForecastPresenter = {

  render() {
    const el = document.getElementById('forecastGrid');
    if (!el) return; // container belum ada di halaman ini, aman diam2.

    if (typeof FinancialForecastAPI === 'undefined') {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data forecast keuangan belum tersedia</div></div>';
      return;
    }

    const s = FinancialForecastAPI.summary();
    if (!s.ok) {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data forecast keuangan belum tersedia</div></div>';
      return;
    }

    const cards = [
      this._incomeCard(s.income),
      this._expenseCard(s.expense),
      this._cashflowCard(s.cashflowProjection),
    ];

    // S254B (Batch Finance Navigation Consistency): SELURUH kartu
    // clickable lewat mekanisme SAMA PERSIS FinanceDashboard.render()/
    // FinancialHealthScorePresenter.render() (S254A) — tiap kartu carry
    // field onClick:{action,args} sendiri (ditempel di masing2 _xxxCard()
    // di bawah), template di sini CUMA mengecek `c.onClick` (0 logic
    // navigasi baru, 0 percabangan per-index, JANGAN openCard(index)).
    el.innerHTML = cards.map((c) => `
      <div class="findash-card${c.onClick ? ' u-pointer' : ''}"${c.onClick ? ` data-action="${escapeHtml(c.onClick.action)}" data-args="${escapeHtml(JSON.stringify(c.onClick.args))}"` : ''}>
        <div class="findash-card-icon">${c.icon}</div>
        <div class="findash-card-body">
          <div class="findash-card-label">${escapeHtml(c.label)}</div>
          <div class="findash-card-val${c.cls ? ' ' + c.cls : ''}">${escapeHtml(c.value)}</div>
          ${c.sub ? `<div class="findash-card-sub">${escapeHtml(c.sub)}</div>` : ''}
        </div>
      </div>
    `).join('');
  },

  // _incomeCard(f) — f = FinancialForecastAPI.summary().income, dipakai
  // APA ADANYA (avgMonthly/months/currentMonthIncome — 0 recompute).
  _incomeCard(f) {
    const money = (n) => (typeof fmt === 'function') ? fmt(n) : ('Rp ' + Math.round(n || 0));
    const onClick = { action: 'dashHubNavigateToFeature', args: [FORECAST_NAV_TARGETS.self] };
    if (!f || !f.ok) {
      return { icon: '📈', label: 'Perkiraan Pemasukan', value: '—', cls: '', sub: f && f.reason, onClick };
    }
    return {
      icon: '📈',
      label: 'Perkiraan Pemasukan',
      value: money(f.avgMonthly) + '/bln',
      cls: 'green',
      sub: `Rata-rata ${f.months} bulan terakhir · bulan ini ${money(f.currentMonthIncome)}`,
      onClick,
    };
  },

  // _expenseCard(f) — f = FinancialForecastAPI.summary().expense, dipakai
  // APA ADANYA (avgMonthly/months/currentMonthExpense — 0 recompute).
  _expenseCard(f) {
    const money = (n) => (typeof fmt === 'function') ? fmt(n) : ('Rp ' + Math.round(n || 0));
    const onClick = { action: 'dashHubNavigateToFeature', args: [FORECAST_NAV_TARGETS.self] };
    if (!f || !f.ok) {
      return { icon: '📉', label: 'Perkiraan Pengeluaran', value: '—', cls: '', sub: f && f.reason, onClick };
    }
    return {
      icon: '📉',
      label: 'Perkiraan Pengeluaran',
      value: money(f.avgMonthly) + '/bln',
      cls: 'red',
      sub: `Rata-rata ${f.months} bulan terakhir · bulan ini ${money(f.currentMonthExpense)}`,
      onClick,
    };
  },

  // _cashflowCard(f) — f = FinancialForecastAPI.summary().cashflowProjection,
  // dipakai APA ADANYA (saldoNow/projected/billsDue/upcomingCount — 0
  // recompute, `projected` sudah final dari computeCashflowForecast()).
  _cashflowCard(f) {
    const money = (n) => (typeof fmt === 'function') ? fmt(n) : ('Rp ' + Math.round(n || 0));
    const onClick = { action: 'dashHubNavigateToFeature', args: [FORECAST_NAV_TARGETS.self] };
    if (!f || !f.ok) {
      return { icon: '🔮', label: 'Proyeksi Saldo 30 Hari', value: '—', cls: '', sub: f && f.reason, onClick };
    }
    const projected = f.projected;
    return {
      icon: '🔮',
      label: 'Proyeksi Saldo 30 Hari',
      value: (projected < 0 ? '-' : '') + money(Math.abs(projected)),
      cls: projected < 0 ? 'red' : 'green',
      sub: `Saldo sekarang ${money(f.saldoNow)} · ${f.upcomingCount} tagihan jatuh tempo (${money(f.billsDue)})`,
      onClick,
    };
  },

};

// modules/finance/budget-recommendation-api.js — Budget Recommendation API
// (Sesi 92, Batch 10). Target sesi: Budget Recommendation Foundation —
// lihat docs/BATCH_PLAN.md § Batch 10.
//
// PRINSIP (RULE #1 sesi ini): 100% REUSE FinanceIntelligence.budgetSummary()
// (modules/finance/finance-intelligence.js, Sesi 74 — sendiri 100% reuse
// Budget.getUsed()/getEffectiveLimit(), budget.js) + FinancialForecastAPI
// (modules/finance/financial-forecast-api.js, Sesi 91 — sendiri 100% reuse
// FinanceDashboard.getAIHook()/FinanceIntelligence) — TIDAK ada rumus
// keuangan baru, TIDAK duplikasi logic, TIDAK framework baru, TIDAK
// mengubah struktur data D, TIDAK membaca D langsung sama sekali di file
// ini.
//
// Spending Analysis/Budget Suggestion/Budget Insight di bawah BUKAN hasil
// hitungan baru — ketiganya murni MENGELOMPOKKAN/MENYARING field yang SUDAH
// FINAL dari `FinanceIntelligence.budgetSummary()` (limit/used/sisa/pct/over
// per item, sudah dihitung Budget.getUsed()/getEffectiveLimit()) memakai
// ambang batas yang SAMA GAYA dengan yang sudah ada di codebase (label
// healthScore() 80/60/40, ambang due-soon 15% VehicleReminder) — bukan
// rumus finansial baru, murni klasifikasi presentasional atas angka yang
// sudah final. Pola arsitektur SAMA PERSIS VehicleRecommendationEngine
// (modules/vehicle/vehicle-recommendation-engine.js, Sesi 82) — MEMILIH &
// MENYERAGAMKAN item dari layer di bawahnya jadi bentuk recommendation,
// TIDAK menghitung ulang severity/status/angka apa pun.
//
// Ambang klasifikasi (dipakai bersama oleh spendingAnalysis()/
// budgetSuggestion()/budgetInsight() di bawah, SATU tempat supaya
// konsisten):
//   - over        -> item.over === true (dari Budget.getUsed()/
//                     getEffectiveLimit() apa adanya, BUKAN dihitung ulang)
//   - near-limit  -> !over && pct >= 0.8 (gaya sama healthScore() yang
//                     pakai ambang 0.8/0.6/0.4, bukan angka baru dikarang)
//   - underused   -> pct < 0.4 (kebalikan simetris ambang di atas)
//   - ok          -> selain 3 kategori di atas
//
// Semua fungsi di bawah PURE (read-only) — tidak pernah memanggil save()
// atau menulis ke D/localStorage, tidak menyentuh DOM. TIDAK ada UI di
// file ini — presenternya (BudgetRecommendationPresenter) ada di file
// terpisah, sesi ini juga, 100% konsumsi objek ini.
const BudgetRecommendationAPI = {

// _budget(month?, year?) — helper internal: satu titik akses ke
// FinanceIntelligence.budgetSummary(month, year). Guard berlapis
// (FinanceIntelligence belum dimuat / budgetSummary() {ok:false}) — SEMUA
// diteruskan apa adanya, pola sama persis FinancialForecastAPI._cashflow()
// meneruskan {ok:false} dari FinanceDashboard.getAIHook().
_budget(month, year) {
  if (typeof FinanceIntelligence === 'undefined') {
    return { ok: false, reason: 'FinanceIntelligence belum dimuat' };
  }
  const bs = FinanceIntelligence.budgetSummary(month, year);
  if (!bs || !bs.ok) {
    return bs || { ok: false, reason: 'budget summary tidak tersedia' };
  }
  return bs;
},

// _classify(item) — helper internal: klasifikasi 1 item budgetSummary()
// jadi 1 dari 4 kategori (over/near/underused/ok) memakai ambang batas yang
// didokumentasikan di komentar atas. `item.over`/`item.pct` dibaca APA
// ADANYA (0 recompute) — fungsi ini murni percabangan if/else, bukan rumus.
_classify(item) {
  if (item.over) return 'over';
  if (item.pct >= 0.8) return 'near';
  if (item.pct < 0.4) return 'underused';
  return 'ok';
},

// _CATEGORY_PRIORITY — urutan prioritas kategori (dipakai _sortBySeverity()
// di bawah). Nilai lebih kecil = lebih prioritas/mendesak. Murni tabel
// mapping, bukan rumus.
_CATEGORY_PRIORITY: { over: 0, near: 1, underused: 2, ok: 3 },

// _sortBySeverity(items) — FIX BUG-014 (docs/BUG_REGISTRY.md §0a-7):
// urutkan COPY array item (sudah dibubuhi `category` oleh _classify() di
// spendingAnalysis()) berdasarkan prioritas kategori (over -> near ->
// underused -> ok), lalu besaran DALAM kategori yang sama — over: selisih
// `used-limit` menurun (overage terbesar duluan, supaya cocok dgn label
// "Terbesar" yg dipakai presenter), near: `pct` menurun (paling dekat ke
// over duluan), underused: `pct` menaik (paling sedikit terpakai duluan,
// paling banyak sisa yg bisa dialihkan). Field yang dipakai (`category`/
// `pct`/`used`/`limit`) SUDAH final dari _classify()/budgetSummary() — 0
// rumus finansial baru, murni `Array.prototype.sort()` presentasional.
// `.slice()` dulu supaya TIDAK memutasi array asli (aman thd referensi yg
// mungkin dipegang pemanggil lain).
_sortBySeverity(items) {
  const rank = this._CATEGORY_PRIORITY;
  return items.slice().sort((a, b) => {
    const ra = rank[a.category] ?? 3;
    const rb = rank[b.category] ?? 3;
    if (ra !== rb) return ra - rb;
    if (a.category === 'over') return (b.used - b.limit) - (a.used - a.limit);
    if (a.category === 'near') return b.pct - a.pct;
    if (a.category === 'underused') return a.pct - b.pct;
    return 0;
  });
},

// spendingAnalysis(month?, year?) — Spending Analysis. Reuse
// FinanceIntelligence.budgetSummary(month, year) apa adanya, ditambah
// field `category` per item (dari _classify() di atas) & pengelompokan
// count per kategori (murni .filter().length, 0 agregasi baru selain
// hitung). `totalLimit`/`totalUsed`/`totalSisa`/`overallPct`/`overCount`
// diteruskan APA ADANYA dari budgetSummary(). `items` DIURUTKAN lewat
// _sortBySeverity() (FIX BUG-014) — sebelumnya urutan `items` mengikuti
// apa adanya urutan `D.budgets`, membuat `budgetSuggestion().
// suggestions[0]` ("Rekomendasi Utama" di presenter) & pencarian
// "Terbesar" (`.find()` kategori 'over' pertama, `_overCard()` di
// budget-recommendation-presenter.js) berpotensi keliru menunjuk item yg
// bukan prioritas/nominal tertinggi.
spendingAnalysis(month, year) {
  const bs = this._budget(month, year);
  if (!bs.ok) return bs;
  const classified = bs.items.map((it) => ({ ...it, category: this._classify(it) }));
  const items = this._sortBySeverity(classified);
  const countBy = (cat) => items.filter((it) => it.category === cat).length;
  return {
    ok: true,
    month: bs.month,
    year: bs.year,
    items,
    totalLimit: bs.totalLimit,
    totalUsed: bs.totalUsed,
    totalSisa: bs.totalSisa,
    overallPct: bs.overallPct,
    overCount: bs.overCount,
    nearCount: countBy('near'),
    underusedCount: countBy('underused'),
    okCount: countBy('ok'),
  };
},

// budgetSuggestion(month?, year?) — Budget Suggestion. 100% reuse
// spendingAnalysis() di atas (yang sendiri 100% reuse budgetSummary()) —
// MENYARING item kategori 'over'/'near'/'underused' (item 'ok' TIDAK
// butuh saran, pola sama persis VehicleRecommendationEngine yang juga
// menyaring, bukan menyertakan semua item) & MENYERAGAMKAN jadi bentuk
// suggestion `{id, name, category, limit, used, sisa, pct, message}`.
// `suggestedLimit` HANYA disertakan utk kategori 'over' — nilainya
// `item.used` APA ADANYA (dibulatkan sudah final dari Budget.getUsed(),
// 0 rumus baru; menyamakan limit baru dgn pemakaian nyata bulan ini,
// bukan menghitung proyeksi/rata-rata baru — beda dari
// FinancialForecastAPI yang proyeksi 30 hari, sesi ini TIDAK menyentuh
// itu). Teks pesan murni template string, tidak mengarang angka baru.
budgetSuggestion(month, year) {
  const sa = this.spendingAnalysis(month, year);
  if (!sa.ok) return sa;
  const suggestions = sa.items
    .filter((it) => it.category !== 'ok')
    .map((it) => {
      if (it.category === 'over') {
        return {
          id: it.id,
          name: it.name,
          category: it.category,
          limit: it.limit,
          used: it.used,
          sisa: it.sisa,
          pct: it.pct,
          suggestedLimit: it.used,
          message: `"${it.name}" sudah melebihi limit — pertimbangkan naikkan limit ke sekitar pemakaian nyata bulan ini, atau kurangi pengeluaran kategori ini bulan depan.`,
        };
      }
      if (it.category === 'near') {
        return {
          id: it.id,
          name: it.name,
          category: it.category,
          limit: it.limit,
          used: it.used,
          sisa: it.sisa,
          pct: it.pct,
          message: `"${it.name}" sudah dipakai ${Math.round(it.pct * 100)}% dari limit — pantau sisa anggaran (${it.sisa}) sebelum akhir bulan.`,
        };
      }
      // underused
      return {
        id: it.id,
        name: it.name,
        category: it.category,
        limit: it.limit,
        used: it.used,
        sisa: it.sisa,
        pct: it.pct,
        message: `"${it.name}" baru dipakai ${Math.round(it.pct * 100)}% dari limit — sisa anggaran bisa dialihkan ke kategori yang over kalau perlu.`,
      };
    });
  return { ok: true, month: sa.month, year: sa.year, suggestions };
},

// budgetInsight() — Budget Insight. Derivatif murni dari spendingAnalysis()
// bulan berjalan (default, tidak menerima parameter — pola sama persis
// FinanceIntelligence.insights() yang juga selalu bulan berjalan). BUKAN
// duplikasi FinanceIntelligence.insights() (yang cakupannya seluruh
// domain finance: deficit/savings/budget_over/cashflow/health_score) —
// di sini HANYA 3 rule turunan spesifik dari klasifikasi kategori
// spendingAnalysis() milik file ini sendiri (over count, near count,
// underused count), tidak membaca ulang D atau menghitung ulang rumus
// apa pun.
budgetInsight() {
  const sa = this.spendingAnalysis();
  if (!sa.ok) return sa;
  const out = [];
  if (sa.overCount > 0) {
    out.push({ type: 'warning', code: 'budget_over_count', message: `${sa.overCount} anggaran sudah melebihi limit bulan ini — cek Budget Suggestion utk detail per kategori.` });
  }
  if (sa.nearCount > 0) {
    out.push({ type: 'warning', code: 'budget_near_count', message: `${sa.nearCount} anggaran sudah mendekati limit (≥80%) — perlu dipantau sebelum over.` });
  }
  if (sa.underusedCount > 0) {
    out.push({ type: 'info', code: 'budget_underused_count', message: `${sa.underusedCount} anggaran baru dipakai <40% dari limit bulan ini.` });
  }
  if (sa.overCount === 0 && sa.nearCount === 0) {
    out.push({ type: 'positive', code: 'budget_healthy', message: 'Semua anggaran masih dalam batas aman bulan ini.' });
  }
  return out;
},

// summary() — satu pintu masuk gabungan (dipakai presenter/AI briefing
// masa depan), murni memanggil ke-3 fungsi di atas, TIDAK ada logic
// tambahan. `ok` true hanya kalau spendingAnalysis() & budgetSuggestion()
// ok (pola sama persis FinancialForecastAPI.summary()/
// DecisionCenterAPI.summary() yang juga expose `ok` gabungan di level
// teratas). `insight` dari budgetInsight() selalu array (bisa kosong),
// tidak ikut menentukan `ok` gabungan — pola sama
// FinanceIntelligence.summary() yang juga tidak menjadikan insights()
// syarat ok.
summary() {
  const spendingAnalysis = this.spendingAnalysis();
  const budgetSuggestion = this.budgetSuggestion();
  const insight = this.budgetInsight();
  return {
    ok: !!(spendingAnalysis.ok && budgetSuggestion.ok),
    spendingAnalysis,
    budgetSuggestion,
    insight: Array.isArray(insight) ? insight : [],
  };
},

};

// modules/finance/budget-recommendation-presenter.js — Budget
// Recommendation Presenter (Sesi 92, Batch 10). Target sesi: Budget
// Recommendation Foundation — lihat docs/BATCH_PLAN.md § Batch 10.
//
// PRINSIP (RULE #1 sesi ini): UI HANYA presenter. 100% REUSE
// BudgetRecommendationAPI.summary() (modules/finance/
// budget-recommendation-api.js, sesi ini — sendiri 100% reuse
// FinanceIntelligence.budgetSummary(), Sesi 74) — TIDAK ada rumus baru,
// TIDAK menghitung ulang pemakaian/limit/kategori, TIDAK membaca D
// langsung sama sekali. Pola SAMA PERSIS FinancialForecastPresenter.render()
// (Sesi 91 — 3 kartu, container `findash-grid` generik yang sama).
//
// Dipanggil dari renderKeuangan() (DIPINDAH dari DashboardHub.render() di Sesi 133; pola "tambahan murni" sama persis
// FinancialForecastPresenter.render()/VehicleDashboard.render() — lihat
// komentar di dashboard-hub.js). Live-wiring renderDashboard() DIHAPUS di Sesi 134 (gap fix,
// sudah dobel dgn renderKeuangan(), lihat CHANGELOG.md Sesi 134), TIDAK ada mekanisme render baru.
// CSS TIDAK baru — reuse penuh class findash-grid/findash-card (grid
// generik, sudah dipakai FinanceDashboard/FinancialForecastPresenter/
// VehicleDashboard/dst).
//
// BUDGETRECO_NAV_TARGETS (S254B — Batch Finance Navigation Consistency) —
// tujuan navigasi tiap kartu #budgetRecoGrid. MURNI DATA (0 logic
// navigasi baru), format {page,goTo} SAMA PERSIS format target
// dashHubNavigateToFeature() yang SUDAH ADA (dashboard-hub.js). Nama
// disendirikan per-file supaya tidak bentrok dgn const global lain (lihat
// kasus S251/S253/S254A). Ketiga kartu murni komposit 1 rekomendasi
// anggaran yang sama — TIDAK ada 1 daftar spesifik per kategori, jadi
// target = container section-nya sendiri (budgetRecoWrap, dashboard-hub,
// TERVERIFIKASI ADA di index.html/app_production.html), pola sama persis
// FINHEALTH_NAV_TARGETS.self (S254A, self-scroll utk kartu komposit).
const BUDGETRECO_NAV_TARGETS = Object.freeze({
  self: { page: 'keuangan', tab: 'laporan', goTo: 'budgetRecoWrap' },
});
const BudgetRecommendationPresenter = {

  render() {
    const el = document.getElementById('budgetRecoGrid');
    if (!el) return; // container belum ada di halaman ini, aman diam2.

    if (typeof BudgetRecommendationAPI === 'undefined') {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data rekomendasi anggaran belum tersedia</div></div>';
      return;
    }

    const s = BudgetRecommendationAPI.summary();
    if (!s.ok) {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data rekomendasi anggaran belum tersedia</div></div>';
      return;
    }

    const cards = [
      this._overCard(s.spendingAnalysis),
      this._underusedCard(s.spendingAnalysis),
      this._topSuggestionCard(s.budgetSuggestion),
    ];

    // S254B (Batch Finance Navigation Consistency): SELURUH kartu
    // clickable lewat mekanisme SAMA PERSIS FinanceDashboard.render()/
    // FinancialHealthScorePresenter.render() (S254A) — tiap kartu carry
    // field onClick:{action,args} sendiri (ditempel di masing2 _xxxCard()
    // di bawah), template di sini CUMA mengecek `c.onClick` (0 logic
    // navigasi baru, 0 percabangan per-index, JANGAN openCard(index)).
    el.innerHTML = cards.map((c) => `
      <div class="findash-card${c.onClick ? ' u-pointer' : ''}"${c.onClick ? ` data-action="${escapeHtml(c.onClick.action)}" data-args="${escapeHtml(JSON.stringify(c.onClick.args))}"` : ''}>
        <div class="findash-card-icon">${c.icon}</div>
        <div class="findash-card-body">
          <div class="findash-card-label">${escapeHtml(c.label)}</div>
          <div class="findash-card-val${c.cls ? ' ' + c.cls : ''}">${escapeHtml(c.value)}</div>
          ${c.sub ? `<div class="findash-card-sub">${escapeHtml(c.sub)}</div>` : ''}
        </div>
      </div>
    `).join('');
  },

  // _overCard(sa) — sa = BudgetRecommendationAPI.summary().spendingAnalysis,
  // dipakai APA ADANYA (overCount/items — 0 recompute). Nama kategori
  // over pertama (kalau ada) dipakai sbg sub-teks, murni .find() atas
  // array yang sudah ada.
  _overCard(sa) {
    const onClick = { action: 'dashHubNavigateToFeature', args: [BUDGETRECO_NAV_TARGETS.self] };
    if (!sa || !sa.ok) {
      return { icon: '🚨', label: 'Anggaran Over Limit', value: '—', cls: '', sub: sa && sa.reason, onClick };
    }
    const first = sa.items.find((it) => it.category === 'over');
    return {
      icon: '🚨',
      label: 'Anggaran Over Limit',
      value: `${sa.overCount} kategori`,
      cls: sa.overCount > 0 ? 'red' : 'green',
      sub: first ? `Terbesar: ${first.name}` : 'Tidak ada anggaran yang over bulan ini',
      onClick,
    };
  },

  // _underusedCard(sa) — pola SAMA PERSIS _overCard() di atas, sisi
  // underusedCount/kategori 'underused' (0 recompute).
  _underusedCard(sa) {
    const onClick = { action: 'dashHubNavigateToFeature', args: [BUDGETRECO_NAV_TARGETS.self] };
    if (!sa || !sa.ok) {
      return { icon: '🧊', label: 'Anggaran Kurang Terpakai', value: '—', cls: '', sub: sa && sa.reason, onClick };
    }
    const first = sa.items.find((it) => it.category === 'underused');
    return {
      icon: '🧊',
      label: 'Anggaran Kurang Terpakai',
      value: `${sa.underusedCount} kategori`,
      cls: '',
      sub: first ? `Contoh: ${first.name} (${Math.round(first.pct * 100)}%)` : 'Semua anggaran terpakai wajar',
      onClick,
    };
  },

  // _topSuggestionCard(bsg) — bsg = BudgetRecommendationAPI.summary().
  // budgetSuggestion, dipakai APA ADANYA (suggestions[0].message — 0
  // recompute, teks sudah final dari BudgetRecommendationAPI).
  _topSuggestionCard(bsg) {
    const onClick = { action: 'dashHubNavigateToFeature', args: [BUDGETRECO_NAV_TARGETS.self] };
    if (!bsg || !bsg.ok) {
      return { icon: '💡', label: 'Rekomendasi Utama', value: '—', cls: '', sub: bsg && bsg.reason, onClick };
    }
    const top = bsg.suggestions[0];
    if (!top) {
      return { icon: '💡', label: 'Rekomendasi Utama', value: 'Tidak ada saran', cls: 'green', sub: 'Semua anggaran dalam batas aman', onClick };
    }
    return {
      icon: '💡',
      label: 'Rekomendasi Utama',
      value: top.name,
      cls: top.category === 'over' ? 'red' : '',
      sub: top.message,
      onClick,
    };
  },

};

// modules/finance/cashflow-projection-settings.js — Cash Flow Projection
// Settings (lanjutan Sesi 93/Batch 10 — CashFlowProjectionAPI/Presenter).
//
// LATAR: kartu "🏦 Proyeksi Saldo Kas" (CashFlowProjectionPresenter) selama
// ini SELALU pakai jendela tagihan tetap 30 hari ke depan
// (computeCashflowForecast(), tx-list-cashflow.js) — tidak cocok utk
// tagihan yang siklus penagihannya potong di TENGAH bulan (mis. kartu
// kredit/listrik pascabayar: tagihan jatuh tempo tgl 1-15 sebenarnya masih
// bagian dari siklus pemakaian yang MULAI tgl 16 bulan sebelumnya, bukan
// bulan kalender berjalan). Modul ini murni PENYIMPANAN preferensi user
// (rentang bulan rata-rata, filter akun, mode jendela tagihan) — 0 rumus
// proyeksi baru di sini, itu tetap 100% tanggung jawab
// computeCashflowForecast() (lihat parameter opsional `opts` di sana,
// tx-list-cashflow.js).
//
// Disimpan di D.profile.cashflowProjSettings (pola sama persis
// D.profile.aiFinanceOverspendThresholdPct dkk di tx-list-cashflow.js) —
// TIDAK ada struktur data baru di luar D.profile, jadi otomatis ikut
// backup/restore yang sudah ada.
//
// Default (CASHFLOW_PROJ_SETTINGS_DEFAULT) SENGAJA identik dgn perilaku
// LAMA computeCashflowForecast() sebelum sesi ini (months:null -> fallback
// BudgetReko, accountId:'semua' -> totalSaldoAkun(), billWindowMode:
// '30hari' -> jendela 30 hari) — user yang belum pernah buka panel "⚙️
// Atur" TIDAK akan melihat perubahan angka sama sekali.
const CASHFLOW_PROJ_SETTINGS_DEFAULT = Object.freeze({
  months: null,              // null = otomatis (BudgetReko.effectiveMonths())
  accountId: 'semua',        // 'semua' atau id 1 akun spesifik
  billWindowMode: '30hari',  // '30hari' | 'kalender' | 'siklus'
  cycleStartDay: 16,         // dipakai kalau billWindowMode==='siklus' (1-28)
  // Sesi pengaturan-proyeksi-kas-lengkap — 3 field baru, KHUSUS dipakai kartu "Proyeksi
  // Kas Bulan Ini" (getMonthlyCashProjection()/_renderCashProjectionCard()), diabaikan
  // begitu saja oleh kartu "Proyeksi Saldo Kas" (CashFlowProjectionPresenter) yg tidak
  // baca field ini -- pola sama persis billWindowMode='kalender'/'siklus' yg juga cuma
  // relevan di kartu satu lagi. Default SENGAJA identik perilaku lama (true/true/null).
  includeKiriman: true,      // false = Kiriman Mingguan tidak dikurangkan ke Proyeksi Kas
  includePendingGaji: true,  // false = Proyeksi Gaji cuma gaji tercatat (exclude estimasi absensi pending)
  surplusMonths: null,       // null = ikut default global FI.effectiveMonths(); 1-24 = override khusus kartu ini
});

const CashflowProjSettings = {

  // get() — balikin setting AKTIF (tersimpan digabung dgn default utk field
  // yang belum pernah diisi user, mis. setelah update app nambah field
  // baru). Guard typeof D: aman dipanggil sebelum D ke-load (headless test).
  get() {
    const saved = (typeof D !== 'undefined' && D.profile && D.profile.cashflowProjSettings) || {};
    return Object.assign({}, CASHFLOW_PROJ_SETTINGS_DEFAULT, saved);
  },

  // set(partial) — merge partial ke setting tersimpan (bukan replace penuh,
  // supaya panel bisa nyimpan 1 field per interaksi tanpa perlu selalu kirim
  // semua field), invalidate cache computeCashflowForecast() supaya kartu
  // langsung kebaca ulang dgn setting baru, lalu save() persist ke
  // localStorage. Diam2 no-op (balikin get() apa adanya) kalau D.profile
  // belum ada (headless test) -- tidak throw.
  set(partial) {
    if (typeof D === 'undefined' || !D.profile) return this.get();
    const merged = Object.assign({}, this.get(), partial || {});
    D.profile.cashflowProjSettings = merged;
    if (typeof invalidateCashflowForecastCache === 'function') invalidateCashflowForecastCache();
    if (typeof save === 'function') save();
    return merged;
  },

  // reset() — hapus override tersimpan, balik ke default (pola sama
  // resetKeuFilter() di filter-laporan.js).
  reset() {
    if (typeof D !== 'undefined' && D.profile) delete D.profile.cashflowProjSettings;
    if (typeof invalidateCashflowForecastCache === 'function') invalidateCashflowForecastCache();
    if (typeof save === 'function') save();
    return this.get();
  },

  // isCustomized() — dipakai presenter utk nampilin badge/indikator kecil di
  // tombol "⚙️ Atur" kalau user sudah pernah ubah dari default (murni
  // presentasi, 0 kalkulasi baru — sekadar bandingkan ke default).
  isCustomized() {
    const s = this.get();
    return Object.keys(CASHFLOW_PROJ_SETTINGS_DEFAULT).some((k) => s[k] !== CASHFLOW_PROJ_SETTINGS_DEFAULT[k]);
  },

  defaults() {
    return Object.assign({}, CASHFLOW_PROJ_SETTINGS_DEFAULT);
  },

};

// modules/finance/cashflow-projection-api.js — Cash Flow Projection API
// (Sesi 93, Batch 10). Target sesi: Cash Flow Projection Foundation —
// lihat docs/BATCH_PLAN.md § Batch 10.
//
// PRINSIP (RULE #1 sesi ini): 100% REUSE FinancialForecastAPI.summary()
// (modules/finance/financial-forecast-api.js, Sesi 91 — sendiri 100%
// reuse FinanceDashboard.getAIHook()/FinanceIntelligence, Sesi 74/75) —
// TIDAK ada rumus baru, TIDAK duplikasi logic, TIDAK framework baru,
// TIDAK mengubah struktur data D, TIDAK membaca D/FinanceDashboard/
// FinanceIntelligence langsung sama sekali di file ini — SATU-SATUNYA
// titik akses adalah FinancialForecastAPI.
//
// Income Projection/Expense Projection/Cash Balance Forecast di bawah
// BUKAN hasil hitungan baru — ketiganya murni MEMBACA ULANG field yang
// SUDAH FINAL dari `FinancialForecastAPI.summary()` (yang sendiri sudah
// membaca ulang `incAvg`/`expAvg`/`saldoNow`/`projected`/`billsDue`/
// `upcoming` dari `computeCashflowForecast()`) apa adanya, ditambah
// pemberian nama presentasional (BUKAN kategori/rumus baru) yang lebih
// spesifik ke domain cash flow (dibanding penamaan umum
// income/expense/cashflowProjection milik FinancialForecastAPI sendiri).
// Pola arsitektur SAMA PERSIS FinancialForecastAPI sendiri (satu pintu
// masuk yang meneruskan field dari layer di bawahnya apa adanya) —
// lapisan wrapper di atas wrapper, konsisten dgn DecisionCenterAPI
// (modules/cross/decision-center-api.js, Sesi 90) yang juga menumpuk
// beberapa layer summary tanpa recompute.
//
// Semua fungsi di bawah PURE (read-only) — tidak pernah memanggil save()
// atau menulis ke D/localStorage, tidak menyentuh DOM. TIDAK ada UI di
// file ini — presenternya (CashFlowProjectionPresenter) ada di file
// terpisah, sesi ini juga, 100% konsumsi objek ini.
const CashFlowProjectionAPI = {

// _forecast() — helper internal: satu titik akses ke
// FinancialForecastAPI.summary(). Guard berlapis (FinancialForecastAPI
// belum dimuat / summary() {ok:false}) — SEMUA diteruskan apa adanya,
// pola sama persis FinancialForecastAPI._cashflow() meneruskan {ok:false}
// dari FinanceDashboard.getAIHook().
_forecast() {
  if (typeof FinancialForecastAPI === 'undefined') {
    return { ok: false, reason: 'FinancialForecastAPI belum dimuat' };
  }
  const s = FinancialForecastAPI.summary();
  if (!s || !s.ok) {
    return s || { ok: false, reason: 'financial forecast tidak tersedia' };
  }
  return s;
},

// incomeProjection() — Income Projection. Field dibaca APA ADANYA dari
// `FinancialForecastAPI.summary().income` (yang sendiri sudah 100% reuse
// `incAvg`/`months`/`currentMonth.income` dari computeCashflowForecast()/
// FinanceIntelligence) — 0 rata-rata dihitung ulang di sini.
incomeProjection() {
  const f = this._forecast();
  if (!f.ok) return f;
  return {
    ok: true,
    avgMonthly: f.income.avgMonthly,
    months: f.income.months,
    currentMonthIncome: f.income.currentMonthIncome,
  };
},

// expenseProjection() — Expense Projection. Pola SAMA PERSIS
// incomeProjection() di atas, cuma sisi expense (dibaca dari
// `FinancialForecastAPI.summary().expense` apa adanya).
expenseProjection() {
  const f = this._forecast();
  if (!f.ok) return f;
  return {
    ok: true,
    avgMonthly: f.expense.avgMonthly,
    months: f.expense.months,
    currentMonthExpense: f.expense.currentMonthExpense,
  };
},

// cashBalanceForecast() — Cash Balance Forecast. Field dibaca APA ADANYA
// dari `FinancialForecastAPI.summary().cashflowProjection` (yang sendiri
// sudah 100% reuse `saldoNow`/`projected`/`billsDue`/`upcomingCount` dari
// computeCashflowForecast()) — 0 proyeksi dihitung ulang di sini.
cashBalanceForecast() {
  const f = this._forecast();
  if (!f.ok) return f;
  return {
    ok: true,
    saldoNow: f.cashflowProjection.saldoNow,
    projected: f.cashflowProjection.projected,
    billsDue: f.cashflowProjection.billsDue,
    upcomingCount: f.cashflowProjection.upcomingCount,
  };
},

// summary() — satu pintu masuk gabungan (dipakai presenter/AI briefing
// masa depan), murni memanggil ke-3 fungsi di atas, TIDAK ada logic
// tambahan. `ok` true hanya kalau ketiganya ok (pola sama persis
// FinancialForecastAPI.summary() yang juga expose `ok` gabungan di level
// teratas).
summary() {
  const income = this.incomeProjection();
  const expense = this.expenseProjection();
  const cashBalance = this.cashBalanceForecast();
  return {
    ok: !!(income.ok && expense.ok && cashBalance.ok),
    income,
    expense,
    cashBalance,
  };
},

};

// modules/finance/cashflow-projection-presenter.js — Cash Flow Projection
// Presenter (Sesi 93, Batch 10). Target sesi: Cash Flow Projection
// Foundation — lihat docs/BATCH_PLAN.md § Batch 10.
//
// PRINSIP (RULE #1 sesi ini): UI HANYA presenter. 100% REUSE
// CashFlowProjectionAPI.summary() (modules/finance/
// cashflow-projection-api.js, sesi ini — sendiri 100% reuse
// FinancialForecastAPI.summary(), Sesi 91) — TIDAK ada rumus baru, TIDAK
// menghitung ulang rata-rata income/expense atau proyeksi saldo, TIDAK
// membaca D/FinancialForecastAPI langsung. Pola SAMA PERSIS
// FinancialForecastPresenter.render() (Sesi 91 — 3 kartu, container
// `findash-grid` generik yang sama).
//
// Dipanggil dari DashboardHub.render() (pola "tambahan murni" sama persis
// FinancialForecastPresenter.render()/BudgetRecommendationPresenter.render()
// — lihat komentar di dashboard-hub.js) & dari live-wiring
// renderDashboard() (modules/shared/modules-render.js), TIDAK ada
// mekanisme render baru. CSS TIDAK baru — reuse penuh class
// findash-grid/findash-card (grid generik, sudah dipakai
// FinanceDashboard/FinancialForecastPresenter/BudgetRecommendationPresenter/
// VehicleDashboard/dst).
//
// CASHFLOWPROJ_NAV_TARGETS (S254B — Batch Finance Navigation
// Consistency) — tujuan navigasi tiap kartu #cashflowProjGrid. MURNI
// DATA (0 logic navigasi baru), format {page,goTo} SAMA PERSIS format
// target dashHubNavigateToFeature() yang SUDAH ADA (dashboard-hub.js).
// Nama disendirikan per-file supaya tidak bentrok dgn const global lain
// (lihat kasus S251/S253/S254A). Ketiga kartu murni komposit 1 proyeksi
// arus kas yang sama — TIDAK ada 1 daftar spesifik per pos, jadi target
// = container section-nya sendiri (cashflowProjWrap, dashboard-hub,
// TERVERIFIKASI ADA di index.html/app_production.html), pola sama
// persis FINHEALTH_NAV_TARGETS.self (S254A, self-scroll utk kartu
// komposit).
// S95 (lanjutan Sesi 93): 3 target navigasi TERPISAH per kartu (dulu
// ketiganya cuma self-scroll ke cashflowProjWrap) -- income/expense pindah
// ke tab Kelola > sub-tab Transaksi lalu diberi filter `#kfTipe` (lihat
// `_goToTipeTx()` di bawah, reuse `resetTxPageAndRender()`/`kfTipe` yang
// sudah ada, filter-laporan.js -- 0 filter baru), bills pindah ke tab
// Tagihan (`setKeuanganTab('tagihan')` SUDAH memanggil `renderBillList()`,
// tx-list-cashflow.js, jadi cukup navigasi tab, 0 action tambahan).
const CASHFLOWPROJ_NAV_TARGETS = Object.freeze({
  income: { page: 'keuangan', tab: 'kelola', subtab: 'transaksi', goTo: 'kelolaTab-transaksi', action: 'CashFlowProjectionPresenter._goToIncomeTx' },
  expense: { page: 'keuangan', tab: 'kelola', subtab: 'transaksi', goTo: 'kelolaTab-transaksi', action: 'CashFlowProjectionPresenter._goToExpenseTx' },
  bills: { page: 'keuangan', tab: 'tagihan', goTo: 'billList' },
});
const CashFlowProjectionPresenter = {

  // _goToIncomeTx()/_goToExpenseTx() -- dipanggil via dashHubNavigateToFeature's
  // `target.action` (window[X][method](), 0 argumen) SETELAH tab/scroll
  // selesai. Set `#kfTipe` lalu reuse `resetTxPageAndRender()` (filter-laporan.js)
  // apa adanya -- 0 filter/logic baru.
  _goToIncomeTx() { CashFlowProjectionPresenter._setKfTipe('income'); },
  _goToExpenseTx() { CashFlowProjectionPresenter._setKfTipe('expense'); },
  _setKfTipe(tipe) {
    const el = document.getElementById('kfTipe');
    if (el) el.value = tipe;
    if (typeof resetTxPageAndRender === 'function') resetTxPageAndRender();
  },

  render() {
    const el = document.getElementById('cashflowProjGrid');
    if (!el) return; // container belum ada di halaman ini, aman diam2.

    this._renderSettingsToggle(el);

    if (typeof CashFlowProjectionAPI === 'undefined') {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data proyeksi arus kas belum tersedia</div></div>';
      return;
    }

    const s = CashFlowProjectionAPI.summary();
    if (!s.ok) {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data proyeksi arus kas belum tersedia</div></div>';
      return;
    }

    const cards = [
      this._incomeCard(s.income),
      this._expenseCard(s.expense),
      this._cashBalanceCard(s.cashBalance),
    ];

    // S254B (Batch Finance Navigation Consistency): SELURUH kartu
    // clickable lewat mekanisme SAMA PERSIS FinanceDashboard.render()/
    // FinancialHealthScorePresenter.render() (S254A) — tiap kartu carry
    // field onClick:{action,args} sendiri (ditempel di masing2 _xxxCard()
    // di bawah), template di sini CUMA mengecek `c.onClick` (0 logic
    // navigasi baru, 0 percabangan per-index, JANGAN openCard(index)).
    el.innerHTML = cards.map((c) => `
      <div class="findash-card${c.onClick ? ' u-pointer' : ''}"${c.onClick ? ` data-action="${escapeHtml(c.onClick.action)}" data-args="${escapeHtml(JSON.stringify(c.onClick.args))}"` : ''}>
        <div class="findash-card-icon">${c.icon}</div>
        <div class="findash-card-body">
          <div class="findash-card-label">${escapeHtml(c.label)}</div>
          <div class="findash-card-val${c.cls ? ' ' + c.cls : ''}">${escapeHtml(c.value)}</div>
          ${c.sub ? `<div class="findash-card-sub">${escapeHtml(c.sub)}</div>` : ''}
        </div>
      </div>
    `).join('');
  },

  // _incomeCard(f) — f = CashFlowProjectionAPI.summary().income, dipakai
  // APA ADANYA (avgMonthly/months/currentMonthIncome — 0 recompute).
  _incomeCard(f) {
    const money = (n) => (typeof fmt === 'function') ? fmt(n) : ('Rp ' + Math.round(n || 0));
    const onClick = { action: 'dashHubNavigateToFeature', args: [CASHFLOWPROJ_NAV_TARGETS.income] };
    if (!f || !f.ok) {
      return { icon: '💰', label: 'Proyeksi Pemasukan', value: '—', cls: '', sub: f && f.reason, onClick };
    }
    return {
      icon: '💰',
      label: 'Proyeksi Pemasukan',
      value: money(f.avgMonthly) + '/bln',
      cls: 'green',
      sub: `Rata-rata ${f.months} bulan terakhir · bulan ini ${money(f.currentMonthIncome)}`,
      onClick,
    };
  },

  // _expenseCard(f) — f = CashFlowProjectionAPI.summary().expense, dipakai
  // APA ADANYA (avgMonthly/months/currentMonthExpense — 0 recompute).
  _expenseCard(f) {
    const money = (n) => (typeof fmt === 'function') ? fmt(n) : ('Rp ' + Math.round(n || 0));
    const onClick = { action: 'dashHubNavigateToFeature', args: [CASHFLOWPROJ_NAV_TARGETS.expense] };
    if (!f || !f.ok) {
      return { icon: '💸', label: 'Proyeksi Pengeluaran', value: '—', cls: '', sub: f && f.reason, onClick };
    }
    return {
      icon: '💸',
      label: 'Proyeksi Pengeluaran',
      value: money(f.avgMonthly) + '/bln',
      cls: 'red',
      sub: `Rata-rata ${f.months} bulan terakhir · bulan ini ${money(f.currentMonthExpense)}`,
      onClick,
    };
  },

  // _cashBalanceCard(f) — f = CashFlowProjectionAPI.summary().cashBalance,
  // dipakai APA ADANYA (saldoNow/projected/billsDue/upcomingCount — 0
  // recompute, `projected` sudah final dari computeCashflowForecast()).
  _cashBalanceCard(f) {
    const money = (n) => (typeof fmt === 'function') ? fmt(n) : ('Rp ' + Math.round(n || 0));
    const onClick = { action: 'dashHubNavigateToFeature', args: [CASHFLOWPROJ_NAV_TARGETS.bills] };
    if (!f || !f.ok) {
      return { icon: '🏦', label: 'Proyeksi Saldo Kas', value: '—', cls: '', sub: f && f.reason, onClick };
    }
    const projected = f.projected;
    return {
      icon: '🏦',
      label: 'Proyeksi Saldo Kas',
      value: (projected < 0 ? '-' : '') + money(Math.abs(projected)),
      cls: projected < 0 ? 'red' : 'green',
      sub: `Saldo sekarang ${money(f.saldoNow)} · ${f.upcomingCount} tagihan jatuh tempo (${money(f.billsDue)})`,
      onClick,
    };
  },

  // ------------------------------------------------------------------
  // S95: panel inline "⚙️ Atur" (CashflowProjSettings — file terpisah
  // cashflow-projection-settings.js). Toggle & panel dirender sebagai
  // SIBLING dari #cashflowProjGrid (bukan child-nya) supaya tidak ikut
  // jadi grid-item CSS grid `findash-grid` (0 CSS baru, murni reuse
  // fg/fl/fs/fi/chip-btn/btn/btn-primary/u-fwrap/u-gap6/u-gap8/u-dnone
  // yang SUDAH ADA -- lihat keuFilterPanel di index.html, pola sama).
  // ------------------------------------------------------------------
  _renderSettingsToggle(gridEl) {
    const wrap = gridEl.parentElement;
    if (!wrap) return;
    let toggle = document.getElementById('cashflowProjSettingsToggle');
    if (!toggle) {
      toggle = document.createElement('button');
      toggle.id = 'cashflowProjSettingsToggle';
      toggle.className = 'chip-btn u-mb8';
      toggle.setAttribute('data-action', 'CashFlowProjectionPresenter.toggleSettings');
      wrap.insertBefore(toggle, gridEl);
    }
    const customized = (typeof CashflowProjSettings !== 'undefined') && CashflowProjSettings.isCustomized();
    toggle.textContent = customized ? '⚙️ Atur (aktif)' : '⚙️ Atur';
    if (!document.getElementById('cashflowProjSettingsPanel')) {
      const panel = document.createElement('div');
      panel.id = 'cashflowProjSettingsPanel';
      panel.className = 'u-dnone u-mb10 u-r10';
      panel.style.padding = '10px';
      panel.style.background = 'var(--surface3)';
      wrap.insertBefore(panel, gridEl);
    }
  },

  // toggleSettings() -- buka/tutup panel, isi ulang kontennya SETIAP dibuka
  // (supaya tidak stale kalau setting berubah dari tempat lain, mis. reset
  // filter). data-action="CashFlowProjectionPresenter.toggleSettings".
  toggleSettings() {
    const panel = document.getElementById('cashflowProjSettingsPanel');
    if (!panel) return;
    const opening = panel.classList.contains('u-dnone');
    if (opening) CashFlowProjectionPresenter._fillSettingsPanel(panel);
    panel.classList.toggle('u-dnone', !opening);
  },

  _fillSettingsPanel(panel) {
    if (typeof CashflowProjSettings === 'undefined') {
      panel.innerHTML = '<div class="empty-text">Pengaturan belum tersedia</div>';
      return;
    }
    const s = CashflowProjSettings.get();
    const escape = (typeof escapeHtml === 'function') ? escapeHtml : (x) => x;
    const accOpts = (typeof D !== 'undefined' && Array.isArray(D.accounts))
      ? D.accounts.map((a) => `<option value="${a.id}"${s.accountId === a.id ? ' selected' : ''}>${a.emoji || ''} ${escape(a.name)}</option>`).join('')
      : '';
    const monthsOpts = [3, 6, 12].map((m) => `<option value="${m}"${s.months === m ? ' selected' : ''}>${m} bulan</option>`).join('');
    const modeBtn = (mode, label) => `<button class="chip-btn${s.billWindowMode === mode ? ' active' : ''}" data-action="CashFlowProjectionPresenter._setBillWindowMode" data-args='["${mode}"]'>${label}</button>`;
    panel.innerHTML = `
      <div class="fg u-mb8"><label class="fl">Rentang Bulan (rata-rata)</label>
        <select class="fs" id="cfpMonths" onchange="CashFlowProjectionPresenter._onMonthsChange()">
          <option value=""${!s.months ? ' selected' : ''}>Otomatis</option>
          ${monthsOpts}
        </select>
      </div>
      <div class="fg u-mb8"><label class="fl">Filter Akun</label>
        <select class="fs" id="cfpAcc" onchange="CashFlowProjectionPresenter._onAccChange()">
          <option value="semua"${s.accountId === 'semua' ? ' selected' : ''}>Semua Akun</option>
          ${accOpts}
        </select>
      </div>
      <div class="fg u-mb8"><label class="fl">Mode Jendela Tagihan</label>
        <div class="u-flex u-fwrap u-gap6">
          ${modeBtn('30hari', '30 Hari')}
          ${modeBtn('kalender', 'Kalender Bulan Ini')}
          ${modeBtn('siklus', 'Siklus Custom')}
        </div>
      </div>
      <div class="fg u-mb8${s.billWindowMode === 'siklus' ? '' : ' u-dnone'}" id="cfpCycleWrap">
        <label class="fl">Tanggal Mulai Siklus</label>
        <input type="number" class="fi" id="cfpCycleDay" min="1" max="28" value="${s.cycleStartDay}" onchange="CashFlowProjectionPresenter._onCycleDayChange()">
      </div>
      <div class="u-flex u-gap8">
        <button class="btn btn-primary" data-action="CashFlowProjectionPresenter.resetSettings">↺ Reset ke Default</button>
      </div>
    `;
  },

  // _on*Change()/_setBillWindowMode() -- tiap kontrol LANGSUNG memanggil
  // CashflowProjSettings.set() (0 tombol "Simpan" terpisah, konsisten
  // dgn pola onchange="resetTxPageAndRender()" di keuFilterPanel yang
  // sudah ada) lalu re-render kartu + panel supaya angka & badge "(aktif)"
  // langsung update.
  _onMonthsChange() {
    const el = document.getElementById('cfpMonths');
    const v = el && el.value ? parseInt(el.value, 10) : null;
    CashFlowProjectionPresenter._applySettings({ months: v });
  },
  _onAccChange() {
    const el = document.getElementById('cfpAcc');
    CashFlowProjectionPresenter._applySettings({ accountId: el ? el.value : 'semua' });
  },
  _onCycleDayChange() {
    const el = document.getElementById('cfpCycleDay');
    const v = el ? parseInt(el.value, 10) : 16;
    CashFlowProjectionPresenter._applySettings({ cycleStartDay: (Number.isFinite(v) && v >= 1 && v <= 28) ? v : 16 });
  },
  _setBillWindowMode(mode) {
    CashFlowProjectionPresenter._applySettings({ billWindowMode: mode });
  },
  resetSettings() {
    if (typeof CashflowProjSettings !== 'undefined') CashflowProjSettings.reset();
    CashFlowProjectionPresenter.render();
    const panel = document.getElementById('cashflowProjSettingsPanel');
    if (panel && !panel.classList.contains('u-dnone')) CashFlowProjectionPresenter._fillSettingsPanel(panel);
    // S667B: kartu "💰 Proyeksi Kas Bulan Ini" (dashCashProjCard, modules-render.js) SEKARANG
    // ikut baca CashflowProjSettings yang SAMA (billWindowMode/cycleStartDay) -- refresh 2
    // arah spy tidak stale kalau user ubah dari panel SATUNYA. Guard typeof (aman kalau kartu
    // itu tidak ada di halaman/belum dimuat).
    if (typeof _renderCashProjectionCard === 'function') _renderCashProjectionCard();
    if (typeof toast === 'function') toast('↺ Pengaturan proyeksi arus kas direset');
  },
  _applySettings(partial) {
    if (typeof CashflowProjSettings === 'undefined') return;
    CashflowProjSettings.set(partial);
    CashFlowProjectionPresenter.render();
    const panel = document.getElementById('cashflowProjSettingsPanel');
    if (panel && !panel.classList.contains('u-dnone')) CashFlowProjectionPresenter._fillSettingsPanel(panel);
    // S667B: lihat komentar resetSettings() di atas -- refresh 2 arah dgn dashCashProjCard.
    if (typeof _renderCashProjectionCard === 'function') _renderCashProjectionCard();
  },

};
// window-expose WAJIB (verify-window-expose.js, bug class s345-s348) --
// panel "⚙️ Atur" di atas pakai data-action="CashFlowProjectionPresenter.xxx"
// langsung (toggleSettings/resetSettings/_setBillWindowMode/dst), beda
// dari kartu (yang lewat dashHubNavigateToFeature -> target.action ->
// _dashHubCallAction(), SAMA-SAMA butuh window[X] utk resolve).
window.CashFlowProjectionPresenter = CashFlowProjectionPresenter;

// modules/finance/financial-goal-api.js — Financial Goal API (Sesi 94,
// Batch 10). Target sesi: Financial Goal Planner Foundation — Financial
// Goal API, Goal Progress, Target Projection, Goal Recommendation, Goal
// Presenter.
//
// PRINSIP (RULE #1 sesi ini): 100% REUSE `goalAdapterList(D)`
// (lifeos/adapters/goal-adapter.js — READ-ONLY, sudah menyeragamkan 6
// sumber goal lama: D.targets/D.eduFunds/D.wishlist/D.pensiun/
// D.finansialFreedom/D.debts jadi 1 bentuk "goal card" dgn
// targetAmount/currentAmount/progressPct SUDAH FINAL, dihitung ulang oleh
// builder-nya sendiri lewat Pensiun.danaTerkumpul()/FI.netAssetFund()/dst
// — TIDAK dihitung ulang di sini) + `CashFlowProjectionAPI.summary()`
// (modules/finance/cashflow-projection-api.js, Sesi 93 — sendiri 100%
// reuse FinancialForecastAPI.summary(), Sesi 91) — TIDAK ada rumus
// keuangan baru, TIDAK duplikasi logic, TIDAK framework baru, TIDAK
// mengubah struktur data D, TIDAK membaca D.targets/D.eduFunds/dst
// langsung di file ini (SATU-SATUNYA titik akses goal adalah
// `goalAdapterList`, pola cross-reference LifeOS<-Finance yang SAMA
// PERSIS `_aiReminderAndTargetSummary()` di modules/ai/ai-service.js,
// arah baca AI/Finance->LifeOS sudah diizinkan eksplisit di
// docs/LIFEOS_SCOPE.md — guard `typeof goalAdapterList==='function'`
// sama persis dipakai di sana).
//
// Financial Goal/Goal Progress di bawah BUKAN hasil hitungan baru —
// murni MEMBACA ULANG & MENGELOMPOKKAN field yang SUDAH FINAL dari
// `goalAdapterList(D)` (targetAmount/currentAmount/progressPct apa
// adanya, 0 recompute), pola sama persis `spendingAnalysis()`
// (modules/finance/budget-recommendation-api.js, Sesi 92) yang juga
// murni mengelompokkan/menghitung count dari field final.
//
// Target Projection di bawah SATU-SATUNYA logic baru sesi ini —
// `remaining = targetAmount - currentAmount` (subtraksi sederhana, pola
// SAMA PERSIS `remaining=Math.max(0,(t.amount||0)-(t.saved||0))` di
// `TimelineW.goals()`, modules/asset/aset.js) & `monthsNeeded =
// surplus>0 ? Math.ceil(remaining/surplus) : null` (bentuk rumus SAMA
// PERSIS `monthsNeeded=surplus>0?Math.ceil(g.remaining/surplus):null` di
// `TimelineW.waterfall()`, modules/asset/aset.js) — BUKAN rumus finansial
// baru yang dikarang, murni bentuk yang SUDAH ADA di codebase, cuma
// `surplus` di sini diambil dari `CashFlowProjectionAPI.summary()`
// (income.avgMonthly - expense.avgMonthly, KEDUA field sudah final dari
// FinancialForecastAPI/computeCashflowForecast — pengurangan sederhana,
// pola sama `(inc-exp)/months` di `FI.monthlySurplus()`,
// modules/shared/modules-calc.js) alih-alih `Pensiun.avgSurplus()` yang
// dipakai TimelineW, KARENA sesi ini WAJIB reuse Cash Flow Projection
// (bukan modul Pensiun) — beda sumber surplus, bentuk rumus tetap sama
// persis yang sudah ada.
//
// Goal Recommendation di bawah derivatif murni dari Goal Progress +
// Target Projection milik file ini sendiri — pola sama persis
// `budgetInsight()` (budget-recommendation-api.js) yang juga cuma
// menyusun rule dari klasifikasi/angka yang sudah final, BUKAN duplikasi
// `FinanceIntelligence.insights()`/`goalAdapterList` (cakupan beda).
//
// Semua fungsi di bawah PURE (read-only) — tidak pernah memanggil save()
// atau menulis ke D/localStorage, tidak menyentuh DOM. TIDAK ada UI di
// file ini — presenternya (FinancialGoalPresenter) ada di file terpisah,
// sesi ini juga, 100% konsumsi objek ini.
const FinancialGoalAPI = {

// _goals() — helper internal: satu titik akses ke `goalAdapterList(D)`.
// Guard berlapis (goalAdapterList belum dimuat / D belum ada) — pola sama
// persis guard `typeof goalAdapterList==='function' && hasD` di
// `_aiReminderAndTargetSummary()` (modules/ai/ai-service.js).
_goals() {
  if (typeof goalAdapterList !== 'function') {
    return { ok: false, reason: 'goalAdapterList belum dimuat' };
  }
  if (typeof D === 'undefined' || !D) {
    return { ok: false, reason: 'D belum tersedia' };
  }
  let list;
  try {
    list = goalAdapterList(D);
  } catch (e) {
    return { ok: false, reason: 'goalAdapterList gagal dipanggil' };
  }
  return { ok: true, goals: Array.isArray(list) ? list : [] };
},

// financialGoals() — Financial Goal API. `goalAdapterList(D)` APA ADANYA
// (list lengkap, tidak difilter/diurutkan ulang — pola sama persis
// Target Summary di ai-service.js), ditambah `count` (murni `.length`).
financialGoals() {
  const g = this._goals();
  if (!g.ok) return g;
  return { ok: true, goals: g.goals, count: g.goals.length };
},

// goalProgress() — Goal Progress. Derivatif murni dari `financialGoals()`
// di atas — `progressPct` per item dibaca APA ADANYA (0 recompute),
// hanya dikelompokkan jadi 3 kategori (achieved/inProgress/notStarted)
// pakai perbandingan sederhana (>=100 / >0 / ===0, bukan ambang finansial
// baru) + `avgProgressPct` (rata-rata sederhana, murni aritmatika
// presentasional, pola sama `countBy()` di spendingAnalysis()).
goalProgress() {
  const fg = this.financialGoals();
  if (!fg.ok) return fg;
  const goals = fg.goals;
  const achieved = goals.filter((g) => g.progressPct >= 100);
  const notStarted = goals.filter((g) => g.progressPct <= 0);
  const inProgress = goals.filter((g) => g.progressPct > 0 && g.progressPct < 100);
  const avgProgressPct = goals.length
    ? Math.round(goals.reduce((s, g) => s + (g.progressPct || 0), 0) / goals.length)
    : 0;
  return {
    ok: true,
    count: goals.length,
    achievedCount: achieved.length,
    inProgressCount: inProgress.length,
    notStartedCount: notStarted.length,
    avgProgressPct,
  };
},

// _surplus() — helper internal: satu titik akses ke
// `CashFlowProjectionAPI.summary()`, mengembalikan `monthlySurplus`
// (income.avgMonthly - expense.avgMonthly, KEDUA field sudah final —
// pola pengurangan sama `(inc-exp)/months` di FI.monthlySurplus()).
// Guard berlapis (CashFlowProjectionAPI belum dimuat / summary() tidak
// ok) — SEMUA diteruskan apa adanya, pola sama persis
// BudgetRecommendationAPI._budget() meneruskan {ok:false}.
_surplus() {
  if (typeof CashFlowProjectionAPI === 'undefined') {
    return { ok: false, reason: 'CashFlowProjectionAPI belum dimuat' };
  }
  const s = CashFlowProjectionAPI.summary();
  if (!s || !s.ok) {
    return s || { ok: false, reason: 'cash flow projection tidak tersedia' };
  }
  return {
    ok: true,
    monthlySurplus: s.income.avgMonthly - s.expense.avgMonthly,
  };
},

// targetProjection() — Target Projection. Utk tiap goal yang BELUM
// tercapai (progressPct<100) & punya `targetAmount` (goal tanpa target
// mis. eduFund yang belum diisi -> dilewati, konsisten dgn guard
// `if(t.target)` gaya goalSourceEduFund()): `remaining =
// targetAmount-currentAmount` (pola sama TimelineW.goals()),
// `monthsNeeded = surplus>0 ? Math.ceil(remaining/surplus) : null` (pola
// SAMA PERSIS TimelineW.waterfall()). `monthlySurplus` diambil SEKALI
// dari `_surplus()` di atas, dipakai bareng utk semua goal (bukan
// dihitung ulang per goal).
targetProjection() {
  const fg = this.financialGoals();
  if (!fg.ok) return fg;
  const surplus = this._surplus();
  if (!surplus.ok) return surplus;
  const monthlySurplus = surplus.monthlySurplus;
  const projections = fg.goals
    .filter((g) => g.progressPct < 100 && (g.targetAmount || 0) > 0)
    .map((g) => {
      const remaining = Math.max(0, (g.targetAmount || 0) - (g.currentAmount || 0));
      const monthsNeeded = monthlySurplus > 0 ? Math.ceil(remaining / monthlySurplus) : null;
      return {
        id: g.id,
        sourceKind: g.sourceKind,
        name: g.name,
        emoji: g.emoji,
        targetAmount: g.targetAmount,
        currentAmount: g.currentAmount,
        remaining,
        monthsNeeded,
      };
    });
  return { ok: true, monthlySurplus, projections };
},

// goalRecommendation() — Goal Recommendation. Derivatif murni dari
// `goalProgress()` + `targetProjection()` milik file ini sendiri (BUKAN
// duplikasi FinanceIntelligence.insights()/budgetInsight() — cakupan di
// sini khusus goal). 4 rule turunan, pola sama persis budgetInsight():
//   - surplus<=0 & ada goal belum tercapai -> warning (arus kas belum
//     surplus, monthsNeeded semua null)
//   - goal progress>=80% (belum 100%) -> positive per goal (hampir
//     tercapai)
//   - goal progress===0% -> info per goal (belum ada progres)
//   - semua goal tercapai (achievedCount===count, count>0) -> positive
//     ringkasan
goalRecommendation() {
  const gp = this.goalProgress();
  if (!gp.ok) return gp;
  const tp = this.targetProjection();
  const out = [];
  if (gp.count === 0) return out;
  if (tp.ok && tp.monthlySurplus <= 0 && (gp.count - gp.achievedCount) > 0) {
    out.push({ type: 'warning', code: 'goal_no_surplus', message: 'Arus kas bulanan belum surplus — proyeksi waktu pencapaian target belum bisa dihitung utk goal yang belum tercapai.' });
  }
  {
    const fgGoals = (this.financialGoals().goals) || [];
    fgGoals.forEach((g) => {
      if (g.progressPct >= 80 && g.progressPct < 100) {
        out.push({ type: 'positive', code: 'goal_near_complete', message: `"${g.name}" sudah ${g.progressPct}% tercapai — hampir sampai target.` });
      } else if (g.progressPct <= 0) {
        out.push({ type: 'info', code: 'goal_not_started', message: `"${g.name}" belum ada progres — mulai nabung/alokasikan dana utk target ini.` });
      }
    });
  }
  if (gp.count > 0 && gp.achievedCount === gp.count) {
    out.push({ type: 'positive', code: 'goal_all_achieved', message: 'Semua target keuangan sudah tercapai.' });
  }
  return out;
},

// summary() — satu pintu masuk gabungan (dipakai presenter/AI briefing
// masa depan), murni memanggil ke-3 fungsi di atas, TIDAK ada logic
// tambahan. `ok` true kalau goalProgress() ok (pola sama persis
// BudgetRecommendationAPI.summary() — `insight`/recommendation TIDAK
// ikut menentukan `ok` gabungan, selalu array).
summary() {
  const goalProgress = this.goalProgress();
  const targetProjection = this.targetProjection();
  const recommendation = this.goalRecommendation();
  return {
    ok: !!goalProgress.ok,
    goalProgress,
    targetProjection,
    recommendation: Array.isArray(recommendation) ? recommendation : [],
  };
},

};

// modules/finance/financial-goal-presenter.js — Financial Goal Presenter
// (Sesi 94, Batch 10). Target sesi: Financial Goal Planner Foundation —
// lihat catatan lengkap di modules/finance/financial-goal-api.js.
//
// PRINSIP (RULE #1 sesi ini): UI HANYA presenter. 100% REUSE
// `FinancialGoalAPI.summary()` (modules/finance/financial-goal-api.js,
// sesi ini — sendiri 100% reuse `goalAdapterList`/
// `CashFlowProjectionAPI.summary()`) — TIDAK ada rumus baru, TIDAK
// menghitung ulang progress/proyeksi apa pun, TIDAK membaca D/
// goalAdapterList/CashFlowProjectionAPI langsung. Pola SAMA PERSIS
// `BudgetRecommendationPresenter.render()` (Sesi 92 — 3 kartu, container
// `findash-grid` generik yang sama).
//
// Dipanggil dari renderKeuangan() (DIPINDAH dari DashboardHub.render() di Sesi 133; pola "tambahan murni" sama persis
// CashFlowProjectionPresenter.render() — lihat komentar di
// dashboard-hub.js). Live-wiring renderDashboard() DIHAPUS di Sesi 134 (gap fix,
// sudah dobel dgn renderKeuangan(), lihat CHANGELOG.md Sesi 134), TIDAK ada mekanisme render baru.
// CSS TIDAK baru — reuse penuh class findash-grid/findash-card (grid
// generik, sudah dipakai FinanceDashboard/FinancialForecastPresenter/
// BudgetRecommendationPresenter/CashFlowProjectionPresenter/dst).
//
// FINGOAL_NAV_TARGETS (S254A — Batch Finance Navigation Consistency) —
// tujuan navigasi tiap kartu #financialGoalGrid. MURNI DATA (0 logic
// navigasi baru), format {page,goTo} SAMA PERSIS format target
// dashHubNavigateToFeature() yang SUDAH ADA (dashboard-hub.js). Nama
// disendirikan per-file supaya tidak bentrok dgn const global lain (lihat
// kasus S251/S253). Ketiga kartu murni komposit (progress/proyeksi/
// rekomendasi 1 set goal yang sama) — TIDAK ada 1 daftar spesifik per
// goal, jadi target = container section-nya sendiri (financialGoalWrap,
// dashboard-hub, TERVERIFIKASI ADA di index.html/app_production.html),
// pola sama persis VEHICLE_ANALYTICS_NAV_TARGETS.total/trend (self-scroll
// utk kartu komposit).
const FINGOAL_NAV_TARGETS = Object.freeze({
  self: { page: 'keuangan', tab: 'laporan', goTo: 'financialGoalWrap' },
});
const FinancialGoalPresenter = {

  render() {
    const el = document.getElementById('financialGoalGrid');
    if (!el) return; // container belum ada di halaman ini, aman diam2.

    if (typeof FinancialGoalAPI === 'undefined') {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data goal keuangan belum tersedia</div></div>';
      return;
    }

    const s = FinancialGoalAPI.summary();
    if (!s.ok) {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data goal keuangan belum tersedia</div></div>';
      return;
    }

    const cards = [
      this._progressCard(s.goalProgress),
      this._projectionCard(s.targetProjection),
      this._recommendationCard(s.recommendation),
    ];

    // S254A (Batch Finance Navigation Consistency): SELURUH kartu
    // clickable lewat mekanisme SAMA PERSIS FinanceDashboard.render()/
    // VehicleAnalyticsPresenter.render() — tiap kartu carry field
    // onClick:{action,args} sendiri (ditempel di masing2 _xxxCard() di
    // bawah), template di sini CUMA mengecek `c.onClick` (0 logic
    // navigasi baru, 0 percabangan per-index, JANGAN openCard(index)).
    el.innerHTML = cards.map((c) => `
      <div class="findash-card${c.onClick ? ' u-pointer' : ''}"${c.onClick ? ` data-action="${escapeHtml(c.onClick.action)}" data-args="${escapeHtml(JSON.stringify(c.onClick.args))}"` : ''}>
        <div class="findash-card-icon">${c.icon}</div>
        <div class="findash-card-body">
          <div class="findash-card-label">${escapeHtml(c.label)}</div>
          <div class="findash-card-val${c.cls ? ' ' + c.cls : ''}">${escapeHtml(c.value)}</div>
          ${c.sub ? `<div class="findash-card-sub">${escapeHtml(c.sub)}</div>` : ''}
        </div>
      </div>
    `).join('');
  },

  // _progressCard(p) — p = FinancialGoalAPI.summary().goalProgress,
  // dipakai APA ADANYA (count/achievedCount/inProgressCount/
  // avgProgressPct — 0 recompute).
  _progressCard(p) {
    const onClick = { action: 'dashHubNavigateToFeature', args: [FINGOAL_NAV_TARGETS.self] };
    if (!p || !p.ok) {
      return { icon: '🎯', label: 'Progres Target Keuangan', value: '—', cls: '', sub: p && p.reason, onClick };
    }
    if (p.count === 0) {
      return { icon: '🎯', label: 'Progres Target Keuangan', value: 'Belum ada target', cls: '', sub: 'Buat target tabungan/dana pendidikan/dst utk mulai memantau progres.', onClick };
    }
    return {
      icon: '🎯',
      label: 'Progres Target Keuangan',
      value: `${p.avgProgressPct}% rata-rata`,
      cls: p.avgProgressPct >= 80 ? 'green' : (p.avgProgressPct <= 20 ? 'red' : ''),
      sub: `${p.count} target · ${p.achievedCount} tercapai · ${p.inProgressCount} berjalan · ${p.notStartedCount} belum mulai`,
      onClick,
    };
  },

  // _projectionCard(t) — t = FinancialGoalAPI.summary().targetProjection,
  // dipakai APA ADANYA (monthlySurplus/projections — 0 recompute).
  // Menampilkan goal dengan monthsNeeded tercepat (paling dekat tercapai)
  // sbg highlight, murni Math.min/sort atas field yang sudah final (0
  // rumus baru).
  _projectionCard(t) {
    const money = (n) => (typeof fmt === 'function') ? fmt(n) : ('Rp ' + Math.round(n || 0));
    const onClick = { action: 'dashHubNavigateToFeature', args: [FINGOAL_NAV_TARGETS.self] };
    if (!t || !t.ok) {
      return { icon: '📈', label: 'Proyeksi Target', value: '—', cls: '', sub: t && t.reason, onClick };
    }
    const withEstimate = t.projections.filter((p) => p.monthsNeeded !== null);
    if (!t.projections.length) {
      return { icon: '📈', label: 'Proyeksi Target', value: 'Semua target tercapai', cls: 'green', sub: `Surplus bulanan ${money(t.monthlySurplus)}`, onClick };
    }
    if (!withEstimate.length) {
      return { icon: '📈', label: 'Proyeksi Target', value: 'Belum bisa diproyeksikan', cls: 'red', sub: `Surplus bulanan ${money(t.monthlySurplus)} — arus kas belum surplus`, onClick };
    }
    const nearest = withEstimate.reduce((a, b) => (b.monthsNeeded < a.monthsNeeded ? b : a));
    return {
      icon: '📈',
      label: 'Proyeksi Target Terdekat',
      value: `${nearest.name} · ${nearest.monthsNeeded} bln lagi`,
      cls: 'green',
      sub: `Surplus bulanan ${money(t.monthlySurplus)} · sisa ${money(nearest.remaining)}`,
      onClick,
    };
  },

  // _recommendationCard(r) — r = FinancialGoalAPI.summary().recommendation
  // (array, dipakai APA ADANYA — 0 recompute). Menampilkan rekomendasi
  // pertama sbg highlight (pola sama BudgetRecommendationPresenter kalau
  // mau ringkas 1 pesan utama), sisanya dihitung sbg `sub`.
  _recommendationCard(r) {
    const onClick = { action: 'dashHubNavigateToFeature', args: [FINGOAL_NAV_TARGETS.self] };
    if (!Array.isArray(r) || !r.length) {
      return { icon: '💡', label: 'Rekomendasi Goal', value: 'Belum ada rekomendasi', cls: '', sub: '', onClick };
    }
    const main = r[0];
    const clsMap = { warning: 'red', positive: 'green', info: '' };
    return {
      icon: '💡',
      label: 'Rekomendasi Goal',
      value: main.message,
      cls: clsMap[main.type] || '',
      sub: r.length > 1 ? `+${r.length - 1} rekomendasi lain` : '',
      onClick,
    };
  },

};

// modules/finance/investment-planner-api.js — Investment Planner API
// (Sesi 95, Batch 10; REWIRED Sesi 161 dari `Investment.*` ke
// `Aset.investmentPerformance()`; REWIRED KEMBALI s476b — lihat catatan
// panjang di atas `_portfolio()`/`_allocation()`/`watchlistAlerts()` di
// bawah). Target sesi: Investment Planner Foundation — Portfolio
// Overview, Asset Allocation, Watchlist Alerts, Investment
// Recommendation, Presenter.
//
// PRINSIP (RULE #1, tetap berlaku): 100% REUSE modul yang SUDAH ADA —
// TIDAK ada rumus keuangan baru, TIDAK duplikasi logic, TIDAK framework
// baru, TIDAK mengubah struktur data D. `FinancialGoalAPI._surplus()`
// (modules/finance/financial-goal-api.js, Sesi 94 — SUDAH membaca
// `CashFlowProjectionAPI.summary()` & menghasilkan `monthlySurplus`)
// dipanggil ULANG apa adanya, sama seperti sebelumnya — tidak berubah
// sesi ini.
//
// SESI s476b — REWIRE KEMBALI ke `Investment.*` (docs/
// s476-PLAN-migrate-investasi-to-holdings.md, bagian "s476b — Investment
// Planner"): premis Sesi 161 (`Investment.addHolding()` tidak pernah
// dipanggil dari UI mana pun, jadi `D.investments` selalu kosong) SUDAH
// TIDAK BERLAKU sejak s476a — `D.investments` sekarang jadi SSOT data
// investasi (migrasi 1x-jalan dari `D.assets` via
// `migrateAssetInvestmentsToHoldings()`, + tab "💹 Investasi"
// (`InvestmentListUI`, Sesi 466-468) adalah UI penulis data yang nyata,
// beda dari kondisi Sesi 161). `Aset.investmentPerformance()` (yang
// dipakai sejak Sesi 161) MASIH membaca `D.assets` MENTAH — TIDAK
// mengecualikan aset yang sudah `_migratedToInvestmentId` (beda dari
// `Aset.totalValue()` yang sudah dikecualikan sejak s476a) — jadi kalau
// dibiarkan, Investment Planner akan terus membaca salinan data LAMA yang
// makin lama makin menyimpang dari `D.investments` (SSOT sekarang),
// terutama begitu ada holding yang murni ditambah/diedit lewat tab
// Investasi (Investment.addHolding()/updateHolding()) TANPA lewat Buku
// Aset sama sekali — perubahan itu TIDAK PERNAH kelihatan di Investment
// Planner selama masih baca `Aset.investmentPerformance()`.
//
// Sama seperti pola `AssetPortfolioAPI._investment()` (modules/asset/
// asset-portfolio-api.js, S101 — SUDAH lebih dulu baca
// `Investment.portfolioSummary()`/`Investment.assetAllocation()` dgn
// guard sama persis di bawah) — 0 pola baru, cuma menyamakan sumber data
// Investment Planner dgn API sejenis yang sudah ada.
//
// Portfolio Overview/Asset Allocation di bawah BUKAN hasil hitungan baru
// — murni MEMBACA ULANG hasil `Investment.portfolioSummary()`/
// `Investment.assetAllocation()` apa adanya (0 recompute), pola sama
// persis `financialGoals()` (financial-goal-api.js) yang murni membaca
// ulang `goalAdapterList(D)`.
//
// `topAllocation` di bawah SATU-SATUNYA "logic" baru sesi ini — murni
// `array.reduce((a,b)=>b.value>a.value?b:a)` (cari item bernilai
// terbesar), bentuk yang SAMA PERSIS dipakai `_projectionCard()` di
// financial-goal-presenter.js (`withEstimate.reduce((a,b)=>
// b.monthsNeeded<a.monthsNeeded?b:a)`) — bukan rumus finansial baru,
// murni pencarian max/min atas field yang sudah final.
//
// Investment Recommendation di bawah derivatif murni dari Portfolio
// Overview + Asset Allocation + Watchlist Alerts + surplus (semua milik
// file ini sendiri) — pola sama persis `goalRecommendation()`
// (financial-goal-api.js) yang juga cuma menyusun rule dari
// klasifikasi/angka yang sudah final, BUKAN duplikasi
// `FinanceIntelligence.insights()`/`Investment` (cakupan beda: khusus
// investasi).
//
// Semua fungsi di bawah PURE (read-only) — tidak pernah memanggil save()
// atau menulis ke D/localStorage, tidak menyentuh DOM. TIDAK ada UI di
// file ini — presenternya (InvestmentPlannerPresenter) ada di file
// terpisah, 100% konsumsi objek ini, TIDAK diubah sesi ini (bentuk
// summary() tidak berubah).
const InvestmentPlannerAPI = {

// _portfolio() — helper internal: satu titik akses ke
// `Investment.portfolioSummary()` (modules/asset/investasi.js, SSOT data
// investasi sejak s476a). Guard berlapis (Investment belum dimuat) —
// pola sama persis `AssetPortfolioAPI._investment()`
// (modules/asset/asset-portfolio-api.js). Field di-mapping APA ADANYA
// dari hasil portfolioSummary() (0 recompute) ke bentuk yang sama
// seperti sebelumnya (holdingsCount/totalValue/totalCost/
// totalGainLoss/roiPct/totalDividend/totalRealizedGain) supaya presenter
// & investmentRecommendation() di bawah TIDAK perlu diubah sama sekali.
// `yieldPct` (CAGR, s476a2) ikut diteruskan apa adanya — bonus field,
// belum dikonsumsi presenter/recommendation, tapi tersedia utk sesi
// depan tanpa perlu ubah _portfolio() lagi.
_portfolio() {
  if (typeof Investment === 'undefined' || typeof Investment.portfolioSummary !== 'function') {
    return { ok: false, reason: 'Investment belum dimuat' };
  }
  let p;
  try {
    p = Investment.portfolioSummary();
  } catch (e) {
    return { ok: false, reason: 'Investment.portfolioSummary() gagal dipanggil' };
  }
  return {
    ok: true,
    holdingsCount: p.holdingsCount,
    totalValue: p.totalValue,
    totalCost: p.totalCost,
    totalGainLoss: p.totalGainLoss,
    roiPct: p.roiPct,
    yieldPct: p.yieldPct,
    totalDividend: p.totalDividend || 0,
    totalRealizedGain: p.totalRealizedGain || 0,
  };
},

// portfolioOverview() — Investment Portfolio Overview. `Investment.
// portfolioSummary()` APA ADANYA (lewat _portfolio() — 0 recompute).
portfolioOverview() {
  return this._portfolio();
},

// _allocation() — helper internal: satu titik akses ke
// `Investment.assetAllocation()` (modules/asset/investasi.js) — SUDAH
// mengembalikan bentuk {type,value,pct} terurut value terbesar (0
// recompute perlu di sini, beda dari versi Sesi 161 yang harus
// grouping manual dari `tracked` krn `Aset.investmentPerformance()`
// tidak punya breakdown per-tipe siap pakai). Guard berlapis sama pola
// `_portfolio()` di atas.
_allocation() {
  if (typeof Investment === 'undefined' || typeof Investment.assetAllocation !== 'function') {
    return { ok: false, reason: 'Investment belum dimuat' };
  }
  let allocation;
  try {
    allocation = Investment.assetAllocation();
  } catch (e) {
    return { ok: false, reason: 'Investment.assetAllocation() gagal dipanggil' };
  }
  return { ok: true, allocation: Array.isArray(allocation) ? allocation : [] };
},

// assetAllocation() — Asset Allocation. `Investment.assetAllocation()`
// APA ADANYA (list lengkap per tipe instrumen, sudah terurut value
// terbesar dari Investment sendiri), ditambah `topAllocation` (item
// bernilai terbesar — murni reduce max, pola sama persis `nearest`
// goal di FinancialGoalPresenter._projectionCard()).
assetAllocation() {
  const a = this._allocation();
  if (!a.ok) return a;
  const topAllocation = a.allocation.length
    ? a.allocation.reduce((max, item) => (item.value > max.value ? item : max))
    : null;
  return { ok: true, allocation: a.allocation, topAllocation };
},

// watchlistAlerts() — Watchlist Alerts. s476b: `D.investments` (SSOT
// sekarang) SELALU punya konsep watchlist (`D.investmentWatchlist`,
// `Investment.getWatchlist()`/`Investment.watchlistAlerts()` — modul
// investasi.js, sudah ada sejak awal, TIDAK pernah dipakai Investment
// Planner sebelum sesi ini krn premis Sesi 161 di atas). Sekarang
// dibaca APA ADANYA (0 recompute) — `Investment.watchlistAlerts()`
// sendiri sudah memfilter item watchlist yang `lastPrice<=targetPrice`
// (harga sudah menyentuh/lewat target beli). Guard berlapis sama pola
// `_portfolio()`/`_allocation()` — TIDAK lagi selalu {alerts:[],count:0}
// seperti versi Sesi 161 (itu cuma benar selama sumbernya Buku Aset yang
// memang tidak punya watchlist).
watchlistAlerts() {
  if (typeof Investment === 'undefined' || typeof Investment.watchlistAlerts !== 'function') {
    return { ok: false, reason: 'Investment belum dimuat' };
  }
  let alerts;
  try {
    alerts = Investment.watchlistAlerts();
  } catch (e) {
    return { ok: false, reason: 'Investment.watchlistAlerts() gagal dipanggil' };
  }
  alerts = Array.isArray(alerts) ? alerts : [];
  return { ok: true, alerts, count: alerts.length };
},

// _surplus() — helper internal: satu titik akses ke
// `FinancialGoalAPI._surplus()` (Sesi 94 — SUDAH membaca
// CashFlowProjectionAPI.summary() & menghasilkan `monthlySurplus`,
// dipakai ULANG di sini apa adanya supaya TIDAK duplikasi helper yang
// sudah ada). Guard berlapis (FinancialGoalAPI belum dimuat/method
// tidak ada) — kalau tidak tersedia, `ok:false` diteruskan apa adanya
// (bukan dianggap fatal — investmentRecommendation() tetap jalan tanpa
// bagian surplus, lihat di bawah).
_surplus() {
  if (typeof FinancialGoalAPI === 'undefined' || typeof FinancialGoalAPI._surplus !== 'function') {
    return { ok: false, reason: 'FinancialGoalAPI._surplus() belum dimuat' };
  }
  let s;
  try {
    s = FinancialGoalAPI._surplus();
  } catch (e) {
    return { ok: false, reason: 'FinancialGoalAPI._surplus() gagal dipanggil' };
  }
  return s || { ok: false, reason: 'surplus tidak tersedia' };
},

// investmentRecommendation() — Investment Recommendation. Derivatif
// murni dari portfolioOverview() + assetAllocation() + watchlistAlerts()
// + _surplus() milik file ini sendiri — pola sama persis
// goalRecommendation() (financial-goal-api.js). 5 rule turunan, murni
// perbandingan sederhana atas field yang sudah final (0 rumus baru):
//   - holdingsCount===0 -> info (belum ada portofolio)
//   - roiPct<0 -> warning (portofolio rugi)
//   - roiPct>=10 -> positive (portofolio tumbuh baik)
//   - topAllocation.pct>=70 (holdingsCount>1) -> info (konsentrasi tinggi
//     di satu jenis instrumen, saran diversifikasi)
//   - watchlist alerts count>0 -> info (ada instrumen watchlist sudah
//     capai target beli)
//   - monthlySurplus>0 (dari _surplus(), kalau tersedia) -> positive
//     (ada surplus bulanan yang bisa dialokasikan ke investasi)
investmentRecommendation() {
  const p = this.portfolioOverview();
  const out = [];
  if (!p.ok) return out;
  if (p.holdingsCount === 0) {
    // s476b: sumber data sekarang Investment.* (D.investments) — pesan
    // diarahkan ke tab "💹 Investasi" (tempat holding sebenarnya
    // ditambah/dimigrasi), BUKAN lagi Buku Aset (pesan versi Sesi 161).
    out.push({ type: 'info', code: 'invest_no_holdings', message: 'Belum ada holding investasi — tambah holding di tab 💹 Investasi utk mulai memantau ROI & alokasi aset.' });
  } else {
    if (p.roiPct < 0) {
      out.push({ type: 'warning', code: 'invest_negative_roi', message: `Portofolio sedang rugi (ROI ${p.roiPct.toFixed(1)}%) — pertimbangkan tinjau ulang alokasi.` });
    } else if (p.roiPct >= 10) {
      out.push({ type: 'positive', code: 'invest_good_roi', message: `Portofolio tumbuh baik (ROI ${p.roiPct.toFixed(1)}%).` });
    }
    const a = this.assetAllocation();
    if (a.ok && a.topAllocation && p.holdingsCount > 1 && a.topAllocation.pct >= 70) {
      out.push({ type: 'info', code: 'invest_concentration', message: `${Math.round(a.topAllocation.pct)}% portofolio terkonsentrasi di "${a.topAllocation.type}" — pertimbangkan diversifikasi.` });
    }
  }
  const w = this.watchlistAlerts();
  if (w.ok && w.count > 0) {
    out.push({ type: 'info', code: 'invest_watchlist_alert', message: `${w.count} instrumen di watchlist sudah menyentuh harga target beli.` });
  }
  const s = this._surplus();
  if (s.ok && s.monthlySurplus > 0) {
    out.push({ type: 'positive', code: 'invest_surplus_available', message: `Ada surplus bulanan yang bisa dialokasikan ke investasi.` });
  }
  return out;
},

// summary() — satu pintu masuk gabungan (dipakai presenter), murni
// memanggil ke-4 fungsi di atas, TIDAK ada logic tambahan. `ok` true
// kalau portfolioOverview() ok (pola sama persis FinancialGoalAPI.
// summary()/BudgetRecommendationAPI.summary() — recommendation/alerts
// TIDAK ikut menentukan `ok` gabungan).
summary() {
  const portfolioOverview = this.portfolioOverview();
  const assetAllocation = this.assetAllocation();
  const watchlistAlerts = this.watchlistAlerts();
  const recommendation = this.investmentRecommendation();
  return {
    ok: !!portfolioOverview.ok,
    portfolioOverview,
    assetAllocation,
    watchlistAlerts,
    recommendation: Array.isArray(recommendation) ? recommendation : [],
  };
},

};

// modules/finance/investment-planner-presenter.js — Investment Planner
// Presenter (Sesi 95, Batch 10). Target sesi: Investment Planner
// Foundation — lihat catatan lengkap di
// modules/finance/investment-planner-api.js.
//
// PRINSIP (RULE #1 sesi ini): UI HANYA presenter. 100% REUSE
// `InvestmentPlannerAPI.summary()` (modules/finance/
// investment-planner-api.js, sesi ini — sendiri 100% reuse
// `Investment`/`FinancialGoalAPI._surplus()`) — TIDAK ada rumus baru,
// TIDAK menghitung ulang ROI/alokasi/proyeksi apa pun, TIDAK membaca D/
// Investment/FinancialGoalAPI langsung. Pola SAMA PERSIS
// `FinancialGoalPresenter.render()` (Sesi 94 — 3 kartu, container
// `findash-grid` generik yang sama).
//
// Dipanggil dari renderKeuangan() (DIPINDAH dari DashboardHub.render() di Sesi 133; pola "tambahan murni" sama
// persis FinancialGoalPresenter.render() — lihat komentar di
// dashboard-hub.js). Live-wiring renderDashboard() DIHAPUS di Sesi 134 (gap fix,
// sudah dobel dgn renderKeuangan(), lihat CHANGELOG.md Sesi 134), TIDAK ada mekanisme render baru.
// CSS TIDAK baru — reuse penuh class findash-grid/findash-card (grid
// generik, sudah dipakai FinanceDashboard/.../FinancialGoalPresenter/dst).
//
// INVESTPLANNER_NAV_TARGETS (S254B — Batch Finance Navigation
// Consistency) — tujuan navigasi tiap kartu #investPlannerGrid. MURNI
// DATA (0 logic navigasi baru), format {page,goTo} SAMA PERSIS format
// target dashHubNavigateToFeature() yang SUDAH ADA (dashboard-hub.js).
// Nama disendirikan per-file supaya tidak bentrok dgn const global lain
// (lihat kasus S251/S253/S254A). Ketiga kartu murni komposit 1
// ringkasan investasi yang sama — TIDAK ada 1 daftar spesifik per
// instrumen, jadi target = container section-nya sendiri
// (investPlannerWrap, dashboard-hub, TERVERIFIKASI ADA di index.html/
// app_production.html), pola sama persis FINHEALTH_NAV_TARGETS.self
// (S254A, self-scroll utk kartu komposit).
const INVESTPLANNER_NAV_TARGETS = Object.freeze({
  self: { page: 'keuangan', tab: 'laporan', goTo: 'investPlannerWrap' },
  // investasiTab (S469) — target navigasi BARU, TERPISAH dari `self`.
  // Awalnya (S469) Investment Planner & tab "💹 Investasi"
  // (`InvestmentListUI`, Sesi 466-468/BUG-INV-001) adalah 2 fitur BEDA
  // sumber data (Planner baca D.assets via Aset.investmentPerformance(),
  // tab Investasi baca D.investments via Investment.*). SEJAK s476b,
  // Investment Planner SUDAH direwire baca `Investment.*` juga (SSOT
  // sekarang, lihat modules/finance/investment-planner-api.js) — target
  // `investasiTab` di bawah TETAP dipertahankan apa adanya (tetap tujuan
  // yang benar utk "tambah holding", cuma sekarang keduanya baca sumber
  // data yang SAMA, bukan lagi beda). 0 perubahan pada `self`/kartu
  // allocation/recommendation. Dipakai KHUSUS di _overviewCard() saat
  // `holdingsCount===0`, mengarahkan user ke tab yang bisa dipakai
  // mencatat holding (celah navigasi yang dicatat
  // REKOMENDASI-SESI-467-FASE2-TRANSAKSI.md §3).
  investasiTab: { page: 'aset', tab: 'investasi', goTo: 'asetTab-investasi' },
});
const InvestmentPlannerPresenter = {

  render() {
    const el = document.getElementById('investPlannerGrid');
    if (!el) return; // container belum ada di halaman ini, aman diam2.

    if (typeof InvestmentPlannerAPI === 'undefined') {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data investasi belum tersedia</div></div>';
      return;
    }

    const s = InvestmentPlannerAPI.summary();
    if (!s.ok) {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data investasi belum tersedia</div></div>';
      return;
    }

    const cards = [
      this._overviewCard(s.portfolioOverview),
      this._allocationCard(s.assetAllocation),
      this._recommendationCard(s.recommendation),
    ];

    // S254B (Batch Finance Navigation Consistency): SELURUH kartu
    // clickable lewat mekanisme SAMA PERSIS FinanceDashboard.render()/
    // FinancialHealthScorePresenter.render() (S254A) — tiap kartu carry
    // field onClick:{action,args} sendiri (ditempel di masing2 _xxxCard()
    // di bawah), template di sini CUMA mengecek `c.onClick` (0 logic
    // navigasi baru, 0 percabangan per-index, JANGAN openCard(index)).
    el.innerHTML = cards.map((c) => `
      <div class="findash-card${c.onClick ? ' u-pointer' : ''}"${c.onClick ? ` data-action="${escapeHtml(c.onClick.action)}" data-args="${escapeHtml(JSON.stringify(c.onClick.args))}"` : ''}>
        <div class="findash-card-icon">${c.icon}</div>
        <div class="findash-card-body">
          <div class="findash-card-label">${escapeHtml(c.label)}</div>
          <div class="findash-card-val${c.cls ? ' ' + c.cls : ''}">${escapeHtml(c.value)}</div>
          ${c.sub ? `<div class="findash-card-sub">${escapeHtml(c.sub)}</div>` : ''}
        </div>
      </div>
    `).join('');
  },

  // _overviewCard(p) — p = InvestmentPlannerAPI.summary().portfolioOverview,
  // dipakai APA ADANYA (holdingsCount/totalValue/roiPct/totalGainLoss —
  // 0 recompute).
  _overviewCard(p) {
    const money = (n) => (typeof fmt === 'function') ? fmt(n) : ('Rp ' + Math.round(n || 0));
    const onClick = { action: 'dashHubNavigateToFeature', args: [INVESTPLANNER_NAV_TARGETS.self] };
    if (!p || !p.ok) {
      return { icon: '📈', label: 'Portofolio Investasi', value: '—', cls: '', sub: p && p.reason, onClick };
    }
    if (p.holdingsCount === 0) {
      // S469: arahkan langsung ke tab "💹 Investasi" (bukan `self`) —
      // di situ sekarang ADA jalur nyata mencatat holding
      // (`InvestmentListUI`), beda dari `self` yang cuma scroll ke
      // section komposit Investment Planner tanpa form isi data.
      return {
        icon: '📈',
        label: 'Portofolio Investasi',
        value: 'Belum ada data modal',
        cls: '',
        sub: 'Belum ada data. Buka tab 💹 Investasi di Buku Aset untuk mulai mencatat holding.',
        onClick: { action: 'dashHubNavigateToFeature', args: [INVESTPLANNER_NAV_TARGETS.investasiTab] },
      };
    }
    return {
      icon: '📈',
      label: 'Portofolio Investasi',
      value: money(p.totalValue),
      cls: p.totalGainLoss > 0 ? 'green' : (p.totalGainLoss < 0 ? 'red' : ''),
      sub: `${p.holdingsCount} instrumen · ROI ${p.roiPct.toFixed(1)}% · Gain/Loss ${money(p.totalGainLoss)}`,
      onClick,
    };
  },

  // _allocationCard(a) — a = InvestmentPlannerAPI.summary().assetAllocation,
  // dipakai APA ADANYA (allocation/topAllocation — 0 recompute).
  _allocationCard(a) {
    const money = (n) => (typeof fmt === 'function') ? fmt(n) : ('Rp ' + Math.round(n || 0));
    const onClick = { action: 'dashHubNavigateToFeature', args: [INVESTPLANNER_NAV_TARGETS.self] };
    if (!a || !a.ok) {
      return { icon: '🥧', label: 'Alokasi Aset', value: '—', cls: '', sub: a && a.reason, onClick };
    }
    if (!a.allocation.length || !a.topAllocation) {
      return { icon: '🥧', label: 'Alokasi Aset', value: 'Belum ada data', cls: '', sub: '', onClick };
    }
    const t = a.topAllocation;
    return {
      icon: '🥧',
      label: 'Alokasi Aset Terbesar',
      value: `${t.type} · ${Math.round(t.pct)}%`,
      cls: '',
      sub: `${money(t.value)} dari ${a.allocation.length} jenis instrumen`,
      onClick,
    };
  },

  // _recommendationCard(r) — r = InvestmentPlannerAPI.summary().recommendation
  // (array, dipakai APA ADANYA — 0 recompute). Menampilkan rekomendasi
  // pertama sbg highlight (pola sama FinancialGoalPresenter/
  // BudgetRecommendationPresenter), sisanya dihitung sbg `sub`.
  _recommendationCard(r) {
    const onClick = { action: 'dashHubNavigateToFeature', args: [INVESTPLANNER_NAV_TARGETS.self] };
    if (!Array.isArray(r) || !r.length) {
      return { icon: '💡', label: 'Rekomendasi Investasi', value: 'Belum ada rekomendasi', cls: '', sub: '', onClick };
    }
    const main = r[0];
    const clsMap = { warning: 'red', positive: 'green', info: '' };
    return {
      icon: '💡',
      label: 'Rekomendasi Investasi',
      value: main.message,
      cls: clsMap[main.type] || '',
      sub: r.length > 1 ? `+${r.length - 1} rekomendasi lain` : '',
      onClick,
    };
  },

};

// modules/finance/debt-optimizer-api.js — Debt Optimizer API (Sesi 96,
// Batch 10). Target sesi: Debt Optimizer Foundation — Debt Overview,
// DSR (Debt Service Ratio), Payoff Plan, Debt Recommendation, Presenter.
//
// PRINSIP (RULE #1 sesi ini): 100% REUSE `Debt`/`DebtStrategy`
// (modules/finance/piutang-utang.js, MODUL LAMA — sudah punya
// totalValue()/totalCicilanBulanan()/activeDebts()/computeOrder()/
// computeDSR()/simulate(), field-field & rumus di dalamnya SUDAH FINAL,
// dihitung ulang oleh Debt/DebtStrategy sendiri — TIDAK dihitung ulang
// di sini) — TIDAK ada rumus keuangan baru, TIDAK duplikasi logic,
// TIDAK framework baru, TIDAK mengubah struktur data D (murni membaca
// D.debts/D.debtStrategy lewat Debt/DebtStrategy, yang sudah ada sejak
// Sesi 16). Pola file/komentar sama persis
// modules/finance/investment-planner-api.js (Sesi 95).
//
// Debt Overview/DSR di bawah BUKAN hasil hitungan baru — murni MEMBACA
// ULANG hasil `Debt.totalValue()`/`Debt.totalCicilanBulanan()`/
// `DebtStrategy.activeDebts()`/`DebtStrategy.computeDSR()` apa adanya
// (0 recompute), pola sama persis `portfolioOverview()`
// (investment-planner-api.js) yang murni membaca ulang
// `Investment.portfolioSummary()`.
//
// Payoff Plan di bawah murni memanggil `DebtStrategy.computeOrder()` +
// `DebtStrategy.simulate()` APA ADANYA dengan method/extra yang SUDAH
// tersimpan di `D.debtStrategy` (state yang sama dipakai `DebtStrategy.
// render()` sendiri) — 0 rumus baru, 0 duplikasi loop simulasi bunga.
//
// Debt Recommendation di bawah derivatif murni dari Debt Overview + DSR
// + Payoff Plan (semua milik file ini sendiri) — pola sama persis
// `investmentRecommendation()` (investment-planner-api.js) yang juga
// cuma menyusun rule dari klasifikasi/angka yang sudah final, BUKAN
// duplikasi `FinanceIntelligence.insights()`/`DebtStrategy.render()`
// (cakupan beda: khusus utang, tanpa DOM).
//
// Semua fungsi di bawah PURE (read-only) — tidak pernah memanggil save()
// atau menulis ke D/localStorage, tidak menyentuh DOM. TIDAK ada UI di
// file ini — presenternya (DebtOptimizerPresenter) ada di file
// terpisah, sesi ini juga, 100% konsumsi objek ini.
const DebtOptimizerAPI = {

// _overview() — helper internal: satu titik akses ke
// `Debt.totalValue()`/`Debt.totalCicilanBulanan()`/
// `DebtStrategy.activeDebts()`. Guard berlapis (Debt/DebtStrategy belum
// dimuat) — pola sama persis guard `typeof Investment==='undefined'`
// di InvestmentPlannerAPI._portfolio().
_overview() {
  if (typeof Debt === 'undefined' || typeof DebtStrategy === 'undefined') {
    return { ok: false, reason: 'Debt/DebtStrategy belum dimuat' };
  }
  let totalValue, totalCicilanBulanan, activeCount;
  try {
    // KW-170: DebtStrategy.activeDebts() SEKARANG SUDAH gabung Utang
    // formal (D.debts) + cicilan barang aktif (Buku Tagihan
    // kind:'cicilan', lihat DebtStrategy.billCicilanAsDebtLike()) — 1
    // sumber utk activeCount, TIDAK dijumlah manual lagi di sini spy
    // tidak dobel hitung (sebelum KW-170 ini masih dijumlah terpisah,
    // krn dulu activeDebts() cuma D.debts).
    activeCount = DebtStrategy.activeDebts().length;
    // Cicilan non-utang (Buku Tagihan kind:'cicilan') — filter SAMA
    // PERSIS dgn DebtStrategy.computeDSR() (totalCicilanLain), 0 rumus
    // baru, biar Ringkasan Utang & DSR konsisten sumbernya. totalValue
    // ikut ditambah outstanding-nya (amount×sisaTenor, sama persis
    // formula di Debt.renderList()/getBillStats()) biar konsisten sama
    // total yang sekarang tampil di header Buku Utang.
    const billCicilan = (D.bills || []).filter(b => b.kind === 'cicilan' && b.sisaTenor != null);
    totalValue = Debt.totalValue() + billCicilan.reduce((s, b) => s + (b.amount || 0) * (b.sisaTenor || 0), 0);
    totalCicilanBulanan = Debt.totalCicilanBulanan() + billCicilan.reduce((s, b) => s + (b.amount || 0), 0);
  } catch (e) {
    return { ok: false, reason: 'Debt/DebtStrategy gagal dipanggil' };
  }
  return { ok: true, activeCount, totalValue, totalCicilanBulanan };
},

// debtOverview() — Debt Overview. `Debt.totalValue()`/
// `Debt.totalCicilanBulanan()`/`DebtStrategy.activeDebts().length` APA
// ADANYA (0 recompute).
debtOverview() {
  return this._overview();
},

// _dsr() — helper internal: satu titik akses ke
// `DebtStrategy.computeDSR()`. Guard sama pola dgn _overview().
_dsr() {
  if (typeof DebtStrategy === 'undefined') {
    return { ok: false, reason: 'DebtStrategy belum dimuat' };
  }
  let d;
  try {
    d = DebtStrategy.computeDSR();
  } catch (e) {
    return { ok: false, reason: 'DebtStrategy.computeDSR() gagal dipanggil' };
  }
  return { ok: true, ...d };
},

// dsr() — Debt Service Ratio. `DebtStrategy.computeDSR()` APA ADANYA
// (totalCicilanUtang/totalCicilanLain/totalCicilan/incAvg/pct — 0
// recompute, rumus & sumber income sama persis dipakai `DebtStrategy.
// render()` sendiri).
dsr() {
  return this._dsr();
},

// payoffPlan() — Payoff Plan. `DebtStrategy.computeOrder()` +
// `DebtStrategy.simulate()` APA ADANYA, dengan method/extra dari
// `D.debtStrategy` (state yang sama dipakai `DebtStrategy.render()`
// sendiri, default 'avalanche'/0 sama persis pola default di
// `DebtStrategy.render()`) — 0 rumus baru.
payoffPlan() {
  if (typeof DebtStrategy === 'undefined' || typeof D === 'undefined') {
    return { ok: false, reason: 'DebtStrategy/D belum dimuat' };
  }
  let active;
  try {
    active = DebtStrategy.activeDebts();
  } catch (e) {
    return { ok: false, reason: 'DebtStrategy.activeDebts() gagal dipanggil' };
  }
  const ds = (D && D.debtStrategy) || {};
  const method = ds.method === 'snowball' ? 'snowball' : 'avalanche';
  const extra = ds.extra || 0;
  if (!active.length) {
    return { ok: true, method, extra, order: [], simulation: { months: null, totalInterest: 0, payoffMonth: {} } };
  }
  let order, simulation;
  try {
    order = DebtStrategy.computeOrder(active, method);
    simulation = DebtStrategy.simulate(order, extra);
  } catch (e) {
    return { ok: false, reason: 'DebtStrategy.computeOrder()/simulate() gagal dipanggil' };
  }
  return { ok: true, method, extra, order, simulation };
},

// debtRecommendation() — Debt Recommendation. Derivatif murni dari
// debtOverview() + dsr() + payoffPlan() milik file ini sendiri — pola
// sama persis investmentRecommendation() (investment-planner-api.js).
// 5 rule turunan, murni perbandingan sederhana atas field yang sudah
// final (0 rumus baru):
//   - activeCount===0 -> info (belum ada utang aktif)
//   - dsr.pct>35 -> warning (DSR lewat batas aman)
//   - dsr.pct>30 (<=35) -> info (DSR mendekati batas aman)
//   - dsr.pct<=30 (incAvg>0) -> positive (DSR masih di zona aman)
//   - payoffPlan.simulation.months tersedia -> info (estimasi lunas
//     semua & total bunga yang masih akan dibayar)
debtRecommendation() {
  const o = this.debtOverview();
  const out = [];
  if (!o.ok) return out;
  if (o.activeCount === 0) {
    out.push({ type: 'info', code: 'debt_none', message: 'Belum ada utang aktif — Debt Optimizer akan aktif begitu ada utang tercatat di 📕 Buku Utang.' });
    return out;
  }
  const d = this.dsr();
  if (d.ok && d.incAvg > 0 && typeof d.pct === 'number') {
    if (d.pct > 35) {
      out.push({ type: 'warning', code: 'debt_dsr_high', message: `DSR (rasio cicilan) ${d.pct.toFixed(0)}% sudah lewat batas aman (30–35%) — pertimbangkan percepat pelunasan atau tunda kewajiban baru.` });
    } else if (d.pct > 30) {
      out.push({ type: 'info', code: 'debt_dsr_watch', message: `DSR (rasio cicilan) ${d.pct.toFixed(0)}% mendekati batas aman 30–35% — mulai hati-hati sebelum nambah utang baru.` });
    } else {
      out.push({ type: 'positive', code: 'debt_dsr_safe', message: `DSR (rasio cicilan) ${d.pct.toFixed(0)}% masih di zona aman.` });
    }
  }
  const p = this.payoffPlan();
  if (p.ok && p.simulation && p.simulation.months != null) {
    out.push({ type: 'info', code: 'debt_payoff_estimate', message: `Estimasi lunas semua utang: ${p.simulation.months} bulan lagi, dengan total bunga ${Math.round(p.simulation.totalInterest).toLocaleString('id-ID')} (metode ${p.method}).` });
  }
  return out;
},

// summary() — satu pintu masuk gabungan (dipakai presenter), murni
// memanggil ke-4 fungsi di atas, TIDAK ada logic tambahan. `ok` true
// kalau debtOverview() ok (pola sama persis InvestmentPlannerAPI.
// summary() — dsr/payoffPlan/recommendation TIDAK ikut menentukan `ok`
// gabungan).
summary() {
  const debtOverview = this.debtOverview();
  const dsr = this.dsr();
  const payoffPlan = this.payoffPlan();
  const recommendation = this.debtRecommendation();
  return {
    ok: !!debtOverview.ok,
    debtOverview,
    dsr,
    payoffPlan,
    recommendation: Array.isArray(recommendation) ? recommendation : [],
  };
},

};

// modules/finance/debt-optimizer-presenter.js — Debt Optimizer Presenter
// (Sesi 96, Batch 10). Target sesi: Debt Optimizer Foundation — lihat
// catatan lengkap di modules/finance/debt-optimizer-api.js.
//
// PRINSIP (RULE #1 sesi ini): UI HANYA presenter. 100% REUSE
// `DebtOptimizerAPI.summary()` (modules/finance/debt-optimizer-api.js,
// sesi ini — sendiri 100% reuse `Debt`/`DebtStrategy`) — TIDAK ada
// rumus baru, TIDAK menghitung ulang DSR/simulasi pelunasan apa pun,
// TIDAK membaca D/Debt/DebtStrategy langsung. Pola SAMA PERSIS
// `InvestmentPlannerPresenter.render()` (Sesi 95 — 3 kartu, container
// `findash-grid` generik yang sama).
//
// Dipanggil dari renderKeuangan() (DIPINDAH dari DashboardHub.render() di Sesi 133; pola "tambahan murni" sama
// persis InvestmentPlannerPresenter.render() — lihat komentar di
// dashboard-hub.js). Live-wiring renderDashboard() DIHAPUS di Sesi 134 (gap fix,
// sudah dobel dgn renderKeuangan(), lihat CHANGELOG.md Sesi 134), TIDAK ada mekanisme render baru.
// CSS TIDAK baru — reuse penuh class findash-grid/findash-card (grid
// generik, sudah dipakai FinanceDashboard/.../InvestmentPlannerPresenter/dst).
//
// DEBTOPTIMIZER_NAV_TARGETS (S254B — Batch Finance Navigation
// Consistency) — tujuan navigasi tiap kartu #debtOptimizerGrid. MURNI
// DATA (0 logic navigasi baru), format {page,goTo} SAMA PERSIS format
// target dashHubNavigateToFeature() yang SUDAH ADA (dashboard-hub.js).
// Nama disendirikan per-file supaya tidak bentrok dgn const global lain
// (lihat kasus S251/S253/S254A). Ketiga kartu murni komposit 1 ringkasan
// utang yang sama — TIDAK ada 1 daftar spesifik per utang, jadi target =
// container section-nya sendiri (debtOptimizerWrap, dashboard-hub,
// TERVERIFIKASI ADA di index.html/app_production.html), pola sama
// persis FINHEALTH_NAV_TARGETS.self (S254A, self-scroll utk kartu
// komposit).
const DEBTOPTIMIZER_NAV_TARGETS = Object.freeze({
  self: { page: 'keuangan', tab: 'laporan', goTo: 'debtOptimizerWrap' },
});
const DebtOptimizerPresenter = {

  render() {
    const el = document.getElementById('debtOptimizerGrid');
    if (!el) return; // container belum ada di halaman ini, aman diam2.

    if (typeof DebtOptimizerAPI === 'undefined') {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data utang belum tersedia</div></div>';
      return;
    }

    const s = DebtOptimizerAPI.summary();
    if (!s.ok) {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data utang belum tersedia</div></div>';
      return;
    }

    const cards = [
      this._overviewCard(s.debtOverview),
      this._dsrCard(s.dsr),
      this._recommendationCard(s.recommendation),
    ];

    // S254B (Batch Finance Navigation Consistency): SELURUH kartu
    // clickable lewat mekanisme SAMA PERSIS FinanceDashboard.render()/
    // FinancialHealthScorePresenter.render() (S254A) — tiap kartu carry
    // field onClick:{action,args} sendiri (ditempel di masing2 _xxxCard()
    // di bawah), template di sini CUMA mengecek `c.onClick` (0 logic
    // navigasi baru, 0 percabangan per-index, JANGAN openCard(index)).
    el.innerHTML = cards.map((c) => `
      <div class="findash-card${c.onClick ? ' u-pointer' : ''}"${c.onClick ? ` data-action="${escapeHtml(c.onClick.action)}" data-args="${escapeHtml(JSON.stringify(c.onClick.args))}"` : ''}>
        <div class="findash-card-icon">${c.icon}</div>
        <div class="findash-card-body">
          <div class="findash-card-label">${escapeHtml(c.label)}</div>
          <div class="findash-card-val${c.cls ? ' ' + c.cls : ''}">${escapeHtml(c.value)}</div>
          ${c.sub ? `<div class="findash-card-sub">${escapeHtml(c.sub)}</div>` : ''}
        </div>
      </div>
    `).join('');
  },

  // _overviewCard(o) — o = DebtOptimizerAPI.summary().debtOverview,
  // dipakai APA ADANYA (activeCount/totalValue/totalCicilanBulanan — 0
  // recompute).
  _overviewCard(o) {
    const money = (n) => (typeof fmt === 'function') ? fmt(n) : ('Rp ' + Math.round(n || 0));
    const onClick = { action: 'dashHubNavigateToFeature', args: [DEBTOPTIMIZER_NAV_TARGETS.self] };
    if (!o || !o.ok) {
      return { icon: '📕', label: 'Ringkasan Utang', value: '—', cls: '', sub: o && o.reason, onClick };
    }
    if (o.activeCount === 0) {
      return { icon: '📕', label: 'Ringkasan Utang', value: 'Belum ada utang aktif', cls: '', sub: 'Tambahkan catatan pertama di menu 📕 Buku Utang.', onClick };
    }
    return {
      icon: '📕',
      label: 'Ringkasan Utang',
      value: money(o.totalValue),
      cls: 'red',
      sub: `${o.activeCount} utang aktif · Cicilan ${money(o.totalCicilanBulanan)}/bln`,
      onClick,
    };
  },

  // _dsrCard(d) — d = DebtOptimizerAPI.summary().dsr, dipakai APA
  // ADANYA (pct/incAvg/totalCicilan — 0 recompute).
  _dsrCard(d) {
    const money = (n) => (typeof fmt === 'function') ? fmt(n) : ('Rp ' + Math.round(n || 0));
    const onClick = { action: 'dashHubNavigateToFeature', args: [DEBTOPTIMIZER_NAV_TARGETS.self] };
    if (!d || !d.ok) {
      return { icon: '💳', label: 'DSR (Rasio Cicilan)', value: '—', cls: '', sub: d && d.reason, onClick };
    }
    if (!(d.incAvg > 0) || typeof d.pct !== 'number') {
      return { icon: '💳', label: 'DSR (Rasio Cicilan)', value: 'Belum cukup data', cls: '', sub: 'Butuh rata-rata pemasukan bulanan utk hitung DSR.', onClick };
    }
    const cls = d.pct > 35 ? 'red' : (d.pct > 30 ? '' : 'green');
    return {
      icon: '💳',
      label: 'DSR (Rasio Cicilan)',
      value: `${d.pct.toFixed(0)}%`,
      cls,
      sub: `Cicilan/tagihan ${money(d.totalCicilan)} dari income ${money(d.incAvg)}/bln`,
      onClick,
    };
  },

  // _recommendationCard(r) — r = DebtOptimizerAPI.summary().recommendation
  // (array, dipakai APA ADANYA — 0 recompute). Menampilkan rekomendasi
  // pertama sbg highlight (pola sama InvestmentPlannerPresenter/
  // FinancialGoalPresenter), sisanya dihitung sbg `sub`.
  _recommendationCard(r) {
    const onClick = { action: 'dashHubNavigateToFeature', args: [DEBTOPTIMIZER_NAV_TARGETS.self] };
    if (!Array.isArray(r) || !r.length) {
      return { icon: '💡', label: 'Rekomendasi Utang', value: 'Belum ada rekomendasi', cls: '', sub: '', onClick };
    }
    const main = r[0];
    const clsMap = { warning: 'red', positive: 'green', info: '' };
    return {
      icon: '💡',
      label: 'Rekomendasi Utang',
      value: main.message,
      cls: clsMap[main.type] || '',
      sub: r.length > 1 ? `+${r.length - 1} rekomendasi lain` : '',
      onClick,
    };
  },

};

// modules/finance/retirement-planner-api.js — Retirement Planner API
// (Sesi 97, Batch 10). Target sesi: Retirement Planner Foundation —
// Retirement Overview, Gap Analysis, Contribution Recommendation,
// Retirement Recommendation, Presenter.
//
// PRINSIP (RULE #1 sesi ini): 100% REUSE `Pensiun` (modules/shared/
// modules-calc.js, MODUL LAMA — sudah punya danaTerkumpul()/proyeksi()/
// sisaBulan()/rekomendasiKontribusi(), field-field & rumus (FV anuitas
// bertumbuh) di dalamnya SUDAH FINAL, dihitung ulang oleh Pensiun
// sendiri — TIDAK dihitung ulang di sini) — TIDAK ada rumus keuangan
// baru, TIDAK duplikasi logic, TIDAK framework baru, TIDAK mengubah
// struktur data D (murni membaca D.pensiun lewat Pensiun, yang sudah
// ada sejak lama). Pola file/komentar sama persis modules/finance/
// debt-optimizer-api.js (Sesi 96)/investment-planner-api.js (Sesi 95).
//
// Retirement Overview di bawah BUKAN hasil hitungan baru — murni
// MEMBACA ULANG hasil `Pensiun.danaTerkumpul()`/`Pensiun.proyeksi()`/
// `Pensiun.sisaBulan()` apa adanya (0 recompute) + field konfigurasi
// `D.pensiun.targetDana`/`usiaSekarang`/`usiaPensiun`/
// `kontribusiBulanan` dibaca APA ADANYA (bukan hitungan, field mentah
// yang JUGA dibaca langsung apa adanya oleh `Pensiun.render()` sendiri
// — lihat `const p=D.pensiun||{}` di sana), pola sama persis
// `payoffPlan()` (debt-optimizer-api.js) yang membaca `D.debtStrategy`
// langsung.
//
// Gap Analysis di bawah SATU-SATUNYA "logic" baru sesi ini — murni
// `proyeksi - target` (selisih sederhana), bentuk yang SAMA PERSIS
// dipakai `Pensiun.render()` sendiri (`proyeksi>=target` -> status
// surplus/gap) — bukan rumus finansial baru, murni perbandingan atas
// field yang sudah final.
//
// Retirement Recommendation di bawah derivatif murni dari Retirement
// Overview + Gap Analysis + Contribution Recommendation (semua milik
// file ini sendiri) — pola sama persis `debtRecommendation()`
// (debt-optimizer-api.js) yang juga cuma menyusun rule dari
// klasifikasi/angka yang sudah final, BUKAN duplikasi
// `Pensiun.render()` (cakupan beda: khusus rekomendasi ringkas, tanpa
// DOM).
//
// Semua fungsi di bawah PURE (read-only) — tidak pernah memanggil save()
// atau menulis ke D/localStorage, tidak menyentuh DOM. TIDAK ada UI di
// file ini — presenternya (RetirementPlannerPresenter) ada di file
// terpisah, sesi ini juga, 100% konsumsi objek ini.
const RetirementPlannerAPI = {

// _overview() — helper internal: satu titik akses ke
// `Pensiun.danaTerkumpul()`/`Pensiun.proyeksi()`/`Pensiun.sisaBulan()` +
// field konfigurasi `D.pensiun`. Guard berlapis (Pensiun belum dimuat)
// — pola sama persis guard `typeof DebtStrategy==='undefined'` di
// DebtOptimizerAPI._overview().
_overview() {
  if (typeof Pensiun === 'undefined') {
    return { ok: false, reason: 'Pensiun belum dimuat' };
  }
  let terkumpul, proyeksi, sisaBulan;
  try {
    terkumpul = Pensiun.danaTerkumpul();
    proyeksi = Pensiun.proyeksi();
    sisaBulan = Pensiun.sisaBulan();
  } catch (e) {
    return { ok: false, reason: 'Pensiun gagal dipanggil' };
  }
  const p = (typeof D !== 'undefined' && D.pensiun) || {};
  const usiaSekarang = Number(p.usiaSekarang) || 0;
  const usiaPensiun = Number(p.usiaPensiun) || 0;
  const target = Number(p.targetDana) || 0;
  const kontribusiBulanan = Number(p.kontribusiBulanan) || 0;
  const configured = !!(p.usiaSekarang && p.usiaPensiun && p.accId);
  return { ok: true, configured, terkumpul, proyeksi, sisaBulan, target, usiaSekarang, usiaPensiun, kontribusiBulanan };
},

// retirementOverview() — Retirement Overview. `Pensiun.danaTerkumpul()`/
// `Pensiun.proyeksi()`/`Pensiun.sisaBulan()` APA ADANYA (0 recompute) +
// field konfigurasi `D.pensiun` apa adanya.
retirementOverview() {
  return this._overview();
},

// _contribution() — helper internal: satu titik akses ke
// `Pensiun.rekomendasiKontribusi()`. Guard sama pola dgn _overview().
_contribution() {
  if (typeof Pensiun === 'undefined') {
    return { ok: false, reason: 'Pensiun belum dimuat' };
  }
  let r;
  try {
    r = Pensiun.rekomendasiKontribusi();
  } catch (e) {
    return { ok: false, reason: 'Pensiun.rekomendasiKontribusi() gagal dipanggil' };
  }
  return { ok: true, ...r };
},

// contributionRecommendation() — Contribution Recommendation.
// `Pensiun.rekomendasiKontribusi()` APA ADANYA (reko/surplus/months/pct
// — 0 recompute, rumus & sumber surplus sama persis dipakai `Pensiun.
// render()` sendiri).
contributionRecommendation() {
  return this._contribution();
},

// gapAnalysis() — Gap Analysis. Derivatif murni dari
// retirementOverview() (`proyeksi - target`, pola sama persis status
// surplus/gap di `Pensiun.render()`) — 0 rumus baru.
gapAnalysis() {
  const o = this.retirementOverview();
  if (!o.ok) return o;
  if (!(o.target > 0)) {
    return { ok: true, hasTarget: false, gap: 0, onTrack: false };
  }
  const gap = o.proyeksi - o.target;
  return { ok: true, hasTarget: true, gap, onTrack: gap >= 0 };
},

// retirementRecommendation() — Retirement Recommendation. Derivatif
// murni dari retirementOverview() + gapAnalysis() + _contribution()
// milik file ini sendiri — pola sama persis debtRecommendation()
// (debt-optimizer-api.js). Rule turunan, murni perbandingan sederhana
// atas field yang sudah final (0 rumus baru):
//   - !configured -> info (belum diatur usia/target/akun)
//   - configured & !hasTarget -> info (belum isi target dana)
//   - configured & hasTarget & onTrack -> positive (proyeksi melampaui
//     target)
//   - configured & hasTarget & !onTrack -> warning (proyeksi masih
//     kurang dari target)
//   - reko>kontribusiBulanan (dari _contribution(), kalau tersedia) ->
//     info (kontribusi bulanan saat ini di bawah rekomendasi)
retirementRecommendation() {
  const o = this.retirementOverview();
  const out = [];
  if (!o.ok) return out;
  if (!o.configured) {
    out.push({ type: 'info', code: 'retire_not_configured', message: 'Dana Pensiun belum diatur — isi usia sekarang, usia pensiun & akun tabungan dulu di menu 🏖️ Dana Pensiun.' });
    return out;
  }
  const g = this.gapAnalysis();
  if (g.ok) {
    if (!g.hasTarget) {
      out.push({ type: 'info', code: 'retire_no_target', message: 'Target Dana Pensiun belum diisi — isi dulu supaya gap terhadap proyeksi bisa dihitung.' });
    } else if (g.onTrack) {
      out.push({ type: 'positive', code: 'retire_on_track', message: `Proyeksi dana pensiun sudah melampaui target sebesar ${Math.round(g.gap).toLocaleString('id-ID')}.` });
    } else {
      out.push({ type: 'warning', code: 'retire_gap', message: `Proyeksi dana pensiun masih kurang ${Math.round(-g.gap).toLocaleString('id-ID')} dari target.` });
    }
  }
  const c = this._contribution();
  if (c.ok && c.reko > o.kontribusiBulanan) {
    out.push({ type: 'info', code: 'retire_contribution_below_reko', message: `Kontribusi bulanan saat ini di bawah rekomendasi (${Math.round(c.reko).toLocaleString('id-ID')}/bln berdasarkan surplus).` });
  }
  return out;
},

// summary() — satu pintu masuk gabungan (dipakai presenter), murni
// memanggil ke-4 fungsi di atas, TIDAK ada logic tambahan. `ok` true
// kalau retirementOverview() ok (pola sama persis DebtOptimizerAPI.
// summary() — gapAnalysis/contributionRecommendation/recommendation
// TIDAK ikut menentukan `ok` gabungan).
summary() {
  const retirementOverview = this.retirementOverview();
  const gapAnalysis = this.gapAnalysis();
  const contributionRecommendation = this.contributionRecommendation();
  const recommendation = this.retirementRecommendation();
  return {
    ok: !!retirementOverview.ok,
    retirementOverview,
    gapAnalysis,
    contributionRecommendation,
    recommendation: Array.isArray(recommendation) ? recommendation : [],
  };
},

};

// modules/finance/retirement-planner-presenter.js — Retirement Planner
// Presenter (Sesi 97, Batch 10). Target sesi: Retirement Planner
// Foundation — lihat catatan lengkap di modules/finance/
// retirement-planner-api.js.
//
// PRINSIP (RULE #1 sesi ini): UI HANYA presenter. 100% REUSE
// `RetirementPlannerAPI.summary()` (modules/finance/
// retirement-planner-api.js, sesi ini — sendiri 100% reuse `Pensiun`,
// modules/shared/modules-calc.js) — TIDAK ada rumus baru, TIDAK
// menghitung ulang proyeksi/gap/rekomendasi apa pun, TIDAK membaca D/
// Pensiun langsung. Pola SAMA PERSIS `DebtOptimizerPresenter.render()`
// (Sesi 96 — 3 kartu, container `findash-grid` generik yang sama).
//
// Dipanggil dari renderKeuangan() (DIPINDAH dari DashboardHub.render() di Sesi 133; pola "tambahan murni" sama
// persis DebtOptimizerPresenter.render() — lihat komentar di
// dashboard-hub.js). Live-wiring renderDashboard() DIHAPUS di Sesi 134 (gap fix,
// sudah dobel dgn renderKeuangan(), lihat CHANGELOG.md Sesi 134), TIDAK ada mekanisme render baru.
// CSS TIDAK baru — reuse penuh class findash-grid/findash-card (grid
// generik, sudah dipakai FinanceDashboard/.../DebtOptimizerPresenter/dst).
//
// RETIRE_NAV_TARGETS (S254A — Batch Finance Navigation Consistency) —
// tujuan navigasi tiap kartu #retirementPlannerGrid. MURNI DATA (0 logic
// navigasi baru), format {page,goTo} SAMA PERSIS format target
// dashHubNavigateToFeature() yang SUDAH ADA (dashboard-hub.js). Nama
// disendirikan per-file supaya tidak bentrok dgn const global lain (lihat
// kasus S251/S253). Ketiga kartu murni komposit 1 proyeksi dana pensiun
// yang sama — TIDAK ada 1 daftar spesifik per komponen, jadi target =
// container section-nya sendiri (retirementPlannerWrap, dashboard-hub,
// TERVERIFIKASI ADA di index.html/app_production.html), pola sama persis
// VEHICLE_ANALYTICS_NAV_TARGETS.total/trend (self-scroll utk kartu
// komposit).
const RETIRE_NAV_TARGETS = Object.freeze({
  self: { page: 'keuangan', tab: 'laporan', goTo: 'retirementPlannerWrap' },
});
const RetirementPlannerPresenter = {

  render() {
    const el = document.getElementById('retirementPlannerGrid');
    if (!el) return; // container belum ada di halaman ini, aman diam2.

    if (typeof RetirementPlannerAPI === 'undefined') {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data dana pensiun belum tersedia</div></div>';
      return;
    }

    const s = RetirementPlannerAPI.summary();
    if (!s.ok) {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data dana pensiun belum tersedia</div></div>';
      return;
    }

    const cards = [
      this._overviewCard(s.retirementOverview),
      this._gapCard(s.gapAnalysis),
      this._recommendationCard(s.recommendation),
    ];

    // S254A (Batch Finance Navigation Consistency): SELURUH kartu
    // clickable lewat mekanisme SAMA PERSIS FinanceDashboard.render()/
    // VehicleAnalyticsPresenter.render() — tiap kartu carry field
    // onClick:{action,args} sendiri (ditempel di masing2 _xxxCard() di
    // bawah), template di sini CUMA mengecek `c.onClick` (0 logic
    // navigasi baru, 0 percabangan per-index, JANGAN openCard(index)).
    el.innerHTML = cards.map((c) => `
      <div class="findash-card${c.onClick ? ' u-pointer' : ''}"${c.onClick ? ` data-action="${escapeHtml(c.onClick.action)}" data-args="${escapeHtml(JSON.stringify(c.onClick.args))}"` : ''}>
        <div class="findash-card-icon">${c.icon}</div>
        <div class="findash-card-body">
          <div class="findash-card-label">${escapeHtml(c.label)}</div>
          <div class="findash-card-val${c.cls ? ' ' + c.cls : ''}">${escapeHtml(c.value)}</div>
          ${c.sub ? `<div class="findash-card-sub">${escapeHtml(c.sub)}</div>` : ''}
        </div>
      </div>
    `).join('');
  },

  // _overviewCard(o) — o = RetirementPlannerAPI.summary().retirementOverview,
  // dipakai APA ADANYA (configured/terkumpul/proyeksi/sisaBulan — 0
  // recompute).
  _overviewCard(o) {
    const money = (n) => (typeof fmt === 'function') ? fmt(n) : ('Rp ' + Math.round(n || 0));
    const onClick = { action: 'dashHubNavigateToFeature', args: [RETIRE_NAV_TARGETS.self] };
    if (!o || !o.ok) {
      return { icon: '🏖️', label: 'Dana Pensiun', value: '—', cls: '', sub: o && o.reason, onClick };
    }
    if (!o.configured) {
      return { icon: '🏖️', label: 'Dana Pensiun', value: 'Belum diatur', cls: '', sub: 'Isi usia, target & akun tabungan di menu 🏖️ Dana Pensiun.', onClick };
    }
    const years = Math.floor((o.sisaBulan || 0) / 12), months = (o.sisaBulan || 0) % 12;
    return {
      icon: '🏖️',
      label: 'Proyeksi Dana Pensiun',
      value: money(o.proyeksi),
      cls: 'purple',
      sub: `Terkumpul ${money(o.terkumpul)} · ${years > 0 ? years + ' th ' : ''}${months} bln lagi`,
      onClick,
    };
  },

  // _gapCard(g) — g = RetirementPlannerAPI.summary().gapAnalysis,
  // dipakai APA ADANYA (hasTarget/gap/onTrack — 0 recompute).
  _gapCard(g) {
    const money = (n) => (typeof fmt === 'function') ? fmt(n) : ('Rp ' + Math.round(n || 0));
    const onClick = { action: 'dashHubNavigateToFeature', args: [RETIRE_NAV_TARGETS.self] };
    if (!g || !g.ok) {
      return { icon: '🎯', label: 'Gap vs Target', value: '—', cls: '', sub: g && g.reason, onClick };
    }
    if (!g.hasTarget) {
      return { icon: '🎯', label: 'Gap vs Target', value: 'Belum ada target', cls: '', sub: 'Isi Target Dana Pensiun utk lihat gap-nya.', onClick };
    }
    return {
      icon: '🎯',
      label: g.onTrack ? 'Surplus vs Target' : 'Gap vs Target',
      value: money(Math.abs(g.gap)),
      cls: g.onTrack ? 'green' : 'red',
      sub: g.onTrack ? 'Proyeksi sudah melampaui target' : 'Proyeksi masih kurang dari target',
      onClick,
    };
  },

  // _recommendationCard(r) — r = RetirementPlannerAPI.summary().recommendation
  // (array, dipakai APA ADANYA — 0 recompute). Menampilkan rekomendasi
  // pertama sbg highlight (pola sama DebtOptimizerPresenter/
  // InvestmentPlannerPresenter), sisanya dihitung sbg `sub`.
  _recommendationCard(r) {
    const onClick = { action: 'dashHubNavigateToFeature', args: [RETIRE_NAV_TARGETS.self] };
    if (!Array.isArray(r) || !r.length) {
      return { icon: '💡', label: 'Rekomendasi Pensiun', value: 'Belum ada rekomendasi', cls: '', sub: '', onClick };
    }
    const main = r[0];
    const clsMap = { warning: 'red', positive: 'green', info: '' };
    return {
      icon: '💡',
      label: 'Rekomendasi Pensiun',
      value: main.message,
      cls: clsMap[main.type] || '',
      sub: r.length > 1 ? `+${r.length - 1} rekomendasi lain` : '',
      onClick,
    };
  },

};

// modules/finance/financial-health-score-api.js — Financial Health Score
// API (Sesi 98, Batch 10). Target sesi: Financial Health Score Foundation
// — Score Overview, Component Breakdown, Recommendation, Presenter.
//
// PRINSIP (RULE #1 sesi ini): 100% REUSE `FinanceIntelligence.healthScore()`
// (modules/finance/finance-intelligence.js, Sesi 74 — sudah komposit skor
// 0-100 dari savings/budget/debt/cashflow, field `score`/`label`/`parts`
// SUDAH FINAL, dihitung oleh FinanceIntelligence sendiri — TIDAK dihitung
// ulang di sini) — TIDAK ada rumus keuangan baru, TIDAK duplikasi logic,
// TIDAK framework baru, TIDAK mengubah struktur data D (file ini TIDAK
// pernah membaca D langsung, murni membaca ulang hasil FinanceIntelligence).
// Pola file/komentar sama persis modules/finance/retirement-planner-api.js
// (Sesi 97)/debt-optimizer-api.js (Sesi 96).
//
// Score Overview di bawah BUKAN hasil hitungan baru — murni MEMBACA ULANG
// `FinanceIntelligence.healthScore()` apa adanya (0 recompute), pola sama
// persis `debtOverview()` (debt-optimizer-api.js) yang murni membaca ulang
// `Debt.totalValue()` dkk.
//
// Component Breakdown di bawah SATU-SATUNYA "logic" baru sesi ini — murni
// pemetaan LABEL tampilan (Bahasa Indonesia) per `key` komponen + `pct`
// (score/weight, pembagian sederhana atas angka yang sudah final dari
// healthScore().parts) — bukan rumus finansial baru, murni presentasi atas
// field yang sudah dihitung FinanceIntelligence sendiri. Bentuk yang SAMA
// PERSIS dipakai `gapAnalysis()` (retirement-planner-api.js, `proyeksi -
// target`) — perbandingan/pembagian sederhana, bukan rumus baru.
//
// Financial Health Recommendation di bawah derivatif murni dari Score
// Overview + Component Breakdown (semua milik file ini sendiri) — pola
// sama persis `debtRecommendation()` (debt-optimizer-api.js) yang juga
// cuma menyusun rule dari klasifikasi/angka yang sudah final (threshold
// pct<0.5 per komponen, gaya sama persis threshold `d.pct>35` di
// debtRecommendation()), BUKAN duplikasi label 'Sehat'/'Cukup Sehat'/dst
// yang SUDAH dihitung `FinanceIntelligence.healthScore()` sendiri (label
// itu dipakai APA ADANYA, tidak dihitung ulang di sini).
//
// Semua fungsi di bawah PURE (read-only) — tidak pernah memanggil save()
// atau menulis ke D/localStorage, tidak menyentuh DOM. TIDAK ada UI di
// file ini — presenternya (FinancialHealthScorePresenter) ada di file
// terpisah, sesi ini juga, 100% konsumsi objek ini.
const FinancialHealthScoreAPI = {

// _score() — helper internal: satu titik akses ke
// `FinanceIntelligence.healthScore()`. Guard berlapis (FinanceIntelligence
// belum dimuat) — pola sama persis guard `typeof Pensiun==='undefined'`
// di RetirementPlannerAPI._overview().
_score() {
  if (typeof FinanceIntelligence === 'undefined') {
    return { ok: false, reason: 'FinanceIntelligence belum dimuat' };
  }
  let hs;
  try {
    hs = FinanceIntelligence.healthScore();
  } catch (e) {
    return { ok: false, reason: 'FinanceIntelligence.healthScore() gagal dipanggil' };
  }
  return { ok: true, ...hs };
},

// scoreOverview() — Score Overview. `FinanceIntelligence.healthScore()`
// APA ADANYA (score/label/parts — 0 recompute).
scoreOverview() {
  return this._score();
},

// componentBreakdown() — Component Breakdown. Derivatif murni dari
// scoreOverview().parts (key/weight/score dari FinanceIntelligence.
// healthScore(), 0 recompute) + pemetaan LABEL tampilan per key + `pct`
// (score/weight, pembagian sederhana) — 0 rumus finansial baru.
componentBreakdown() {
  const o = this.scoreOverview();
  if (!o.ok) return o;
  const LABELS = {
    savings: 'Tingkat Tabungan',
    budget: 'Kepatuhan Anggaran',
    debt: 'Rasio Utang',
    cashflow: 'Proyeksi Arus Kas',
  };
  const items = (Array.isArray(o.parts) ? o.parts : []).map((p) => ({
    key: p.key,
    label: LABELS[p.key] || p.key,
    weight: p.weight,
    score: p.score,
    pct: p.weight > 0 ? p.score / p.weight : 0,
  }));
  return { ok: true, items };
},

// financialHealthRecommendation() — Financial Health Recommendation.
// Derivatif murni dari scoreOverview() + componentBreakdown() milik file
// ini sendiri — pola sama persis `debtRecommendation()`
// (debt-optimizer-api.js). Rule turunan, murni perbandingan sederhana
// atas field yang sudah final (0 rumus baru):
//   - overall: type berdasar `score` (>=80 positive, >=60 info, <60
//     warning), message pakai `label` APA ADANYA (tidak dihitung ulang)
//   - tiap komponen dgn pct<0.5 (kontribusi di bawah separuh bobot
//     maksimalnya) -> warning per komponen
financialHealthRecommendation() {
  const o = this.scoreOverview();
  const out = [];
  if (!o.ok) return out;
  out.push({
    type: o.score >= 80 ? 'positive' : o.score >= 60 ? 'info' : 'warning',
    code: 'health_score_overall',
    message: `Skor kesehatan finansial ${o.score}/100 (${o.label}).`,
  });
  const b = this.componentBreakdown();
  if (b.ok) {
    b.items.filter((i) => i.pct < 0.5).forEach((i) => {
      out.push({
        type: 'warning',
        code: 'health_component_low',
        message: `${i.label} masih rendah — kontribusi ${Math.round(i.pct * 100)}% dari bobot maksimal.`,
      });
    });
  }
  return out;
},

// summary() — satu pintu masuk gabungan (dipakai presenter), murni
// memanggil ke-3 fungsi di atas, TIDAK ada logic tambahan. `ok` true
// kalau scoreOverview() ok (pola sama persis RetirementPlannerAPI.
// summary() — componentBreakdown/recommendation TIDAK ikut menentukan
// `ok` gabungan).
summary() {
  const scoreOverview = this.scoreOverview();
  const componentBreakdown = this.componentBreakdown();
  const recommendation = this.financialHealthRecommendation();
  return {
    ok: !!scoreOverview.ok,
    scoreOverview,
    componentBreakdown,
    recommendation: Array.isArray(recommendation) ? recommendation : [],
  };
},

};

// modules/finance/financial-health-score-presenter.js — Financial Health
// Score Presenter (Sesi 98, Batch 10). Target sesi: Financial Health
// Score Foundation — lihat catatan lengkap di modules/finance/
// financial-health-score-api.js.
//
// PRINSIP (RULE #1 sesi ini): UI HANYA presenter. 100% REUSE
// `FinancialHealthScoreAPI.summary()` (modules/finance/
// financial-health-score-api.js, sesi ini — sendiri 100% reuse
// `FinanceIntelligence.healthScore()`, modules/finance/
// finance-intelligence.js) — TIDAK ada rumus baru, TIDAK menghitung
// ulang skor/komponen/rekomendasi apa pun, TIDAK membaca D/
// FinanceIntelligence langsung. Pola SAMA PERSIS
// `RetirementPlannerPresenter.render()` (Sesi 97 — 3 kartu, container
// `findash-grid` generik yang sama).
//
// Dipanggil dari renderKeuangan() (DIPINDAH dari DashboardHub.render() di Sesi 133; pola "tambahan murni" sama
// persis RetirementPlannerPresenter.render() — lihat komentar di
// dashboard-hub.js). Live-wiring renderDashboard() DIHAPUS di Sesi 134 (gap fix,
// sudah dobel dgn renderKeuangan(), lihat CHANGELOG.md Sesi 134), TIDAK ada mekanisme render baru.
// CSS TIDAK baru — reuse penuh class findash-grid/findash-card (grid
// generik, sudah dipakai FinanceDashboard/.../RetirementPlannerPresenter/dst).
//
// FINHEALTH_NAV_TARGETS (S254A — Batch Finance Navigation Consistency) —
// tujuan navigasi tiap kartu #financialHealthScoreGrid. MURNI DATA (0
// logic navigasi baru), format {page,goTo} SAMA PERSIS format target
// dashHubNavigateToFeature() yang SUDAH ADA (dashboard-hub.js). Nama
// disendirikan per-file supaya tidak bentrok dgn const global lain (lihat
// kasus S251/S253). Ketiga kartu murni komposit 1 skor kesehatan finansial
// yang sama — TIDAK ada 1 daftar spesifik per komponen, jadi target =
// container section-nya sendiri (financialHealthScoreWrap, dashboard-hub,
// TERVERIFIKASI ADA di index.html/app_production.html), pola sama persis
// VEHICLE_ANALYTICS_NAV_TARGETS.total/trend (self-scroll utk kartu
// komposit).
const FINHEALTH_NAV_TARGETS = Object.freeze({
  self: { page: 'keuangan', tab: 'laporan', goTo: 'financialHealthScoreWrap' },
});
const FinancialHealthScorePresenter = {

  render() {
    const el = document.getElementById('financialHealthScoreGrid');
    if (!el) return; // container belum ada di halaman ini, aman diam2.

    if (typeof FinancialHealthScoreAPI === 'undefined') {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data skor kesehatan finansial belum tersedia</div></div>';
      return;
    }

    const s = FinancialHealthScoreAPI.summary();
    if (!s.ok) {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data skor kesehatan finansial belum tersedia</div></div>';
      return;
    }

    const cards = [
      this._scoreCard(s.scoreOverview),
      this._breakdownCard(s.componentBreakdown),
      this._recommendationCard(s.recommendation),
    ];

    // S254A (Batch Finance Navigation Consistency): SELURUH kartu
    // clickable lewat mekanisme SAMA PERSIS FinanceDashboard.render()/
    // VehicleAnalyticsPresenter.render() — tiap kartu carry field
    // onClick:{action,args} sendiri (ditempel di masing2 _xxxCard() di
    // bawah), template di sini CUMA mengecek `c.onClick` (0 logic
    // navigasi baru, 0 percabangan per-index, JANGAN openCard(index)).
    el.innerHTML = cards.map((c) => `
      <div class="findash-card${c.onClick ? ' u-pointer' : ''}"${c.onClick ? ` data-action="${escapeHtml(c.onClick.action)}" data-args="${escapeHtml(JSON.stringify(c.onClick.args))}"` : ''}>
        <div class="findash-card-icon">${c.icon}</div>
        <div class="findash-card-body">
          <div class="findash-card-label">${escapeHtml(c.label)}</div>
          <div class="findash-card-val${c.cls ? ' ' + c.cls : ''}">${escapeHtml(c.value)}</div>
          ${c.sub ? `<div class="findash-card-sub">${escapeHtml(c.sub)}</div>` : ''}
        </div>
      </div>
    `).join('');
  },

  // _scoreCard(o) — o = FinancialHealthScoreAPI.summary().scoreOverview,
  // dipakai APA ADANYA (score/label — 0 recompute).
  _scoreCard(o) {
    const onClick = { action: 'dashHubNavigateToFeature', args: [FINHEALTH_NAV_TARGETS.self] };
    if (!o || !o.ok) {
      return { icon: '❤️', label: 'Skor Kesehatan Finansial', value: '—', cls: '', sub: o && o.reason, onClick };
    }
    const cls = o.score >= 80 ? 'green' : o.score >= 60 ? '' : o.score >= 40 ? 'orange' : 'red';
    return {
      icon: '❤️',
      label: 'Skor Kesehatan Finansial',
      value: `${o.score}/100`,
      cls,
      sub: o.label,
      onClick,
    };
  },

  // _breakdownCard(b) — b = FinancialHealthScoreAPI.summary().componentBreakdown,
  // dipakai APA ADANYA (items[].label/pct — 0 recompute). Menampilkan
  // komponen dgn kontribusi terendah sbg highlight (pola sama
  // RetirementPlannerPresenter._recommendationCard menampilkan item
  // pertama), sisanya dihitung sbg `sub`.
  _breakdownCard(b) {
    const onClick = { action: 'dashHubNavigateToFeature', args: [FINHEALTH_NAV_TARGETS.self] };
    if (!b || !b.ok || !Array.isArray(b.items) || !b.items.length) {
      return { icon: '🧩', label: 'Rincian Komponen', value: 'Belum ada data', cls: '', sub: b && b.reason, onClick };
    }
    const sorted = [...b.items].sort((x, y) => x.pct - y.pct);
    const lowest = sorted[0];
    return {
      icon: '🧩',
      label: 'Komponen Terlemah',
      value: `${lowest.label} (${Math.round(lowest.pct * 100)}%)`,
      cls: lowest.pct < 0.5 ? 'red' : lowest.pct < 0.8 ? 'orange' : 'green',
      sub: b.items.length > 1 ? `${b.items.length} komponen dinilai` : '',
      onClick,
    };
  },

  // _recommendationCard(r) — r = FinancialHealthScoreAPI.summary().recommendation
  // (array, dipakai APA ADANYA — 0 recompute). Menampilkan rekomendasi
  // pertama sbg highlight (pola sama DebtOptimizerPresenter/
  // RetirementPlannerPresenter), sisanya dihitung sbg `sub`.
  _recommendationCard(r) {
    const onClick = { action: 'dashHubNavigateToFeature', args: [FINHEALTH_NAV_TARGETS.self] };
    if (!Array.isArray(r) || !r.length) {
      return { icon: '💡', label: 'Rekomendasi Kesehatan Finansial', value: 'Belum ada rekomendasi', cls: '', sub: '', onClick };
    }
    const main = r[0];
    const clsMap = { warning: 'red', positive: 'green', info: '' };
    return {
      icon: '💡',
      label: 'Rekomendasi Kesehatan Finansial',
      value: main.message,
      cls: clsMap[main.type] || '',
      sub: r.length > 1 ? `+${r.length - 1} rekomendasi lain` : '',
      onClick,
    };
  },

};

// modules/finance/financial-risk-dashboard-api.js — Financial Risk
// Dashboard API (Sesi 99, Batch 10). Target sesi: Financial Risk
// Dashboard — Risk Factors, Risk Level, Presenter.
//
// PRINSIP (RULE #1 sesi ini): 100% REUSE fungsi rekomendasi/insight yang
// SUDAH ADA di domain finance — TIDAK ada rumus keuangan baru, TIDAK
// duplikasi logic (threshold DSR/budget/cashflow/skor kesehatan SUDAH
// final di modul masing2, dibaca ulang apa adanya di sini, TIDAK
// dihitung ulang), TIDAK framework baru, TIDAK mengubah struktur data D
// (file ini TIDAK pernah membaca D langsung, murni membaca ulang hasil
// 4 sumber di bawah):
//   - DebtOptimizerAPI.debtRecommendation()      (debt-optimizer-api.js,
//     Sesi 96 — DSR/payoff, threshold pct>35/>30 SUDAH final di sana)
//   - FinancialHealthScoreAPI.financialHealthRecommendation()
//     (financial-health-score-api.js, Sesi 98 — skor komposit &
//     komponen lemah, threshold score/pct SUDAH final di sana)
//   - FinanceIntelligence.insights()             (finance-intelligence.js,
//     Sesi 74 — defisit bulanan/anggaran lewat batas/proyeksi arus kas
//     minus, threshold SUDAH final di sana)
//   - _emergencyFundRisk()                       (helper di file ini —
//     status "Dana Darurat 3-6 Bulan" dari D.targets, threshold `saved
//     >= amount`; sebelumnya dibaca dari TanggaKeuangan.compute() [fitur
//     "Tangga Ternak Uang", sudah dihapus], logic dipindah ke sini apa
//     adanya, 0 perubahan threshold)
//
// Risk Factors di bawah BUKAN hasil hitungan baru — murni MEMFILTER
// item bertipe 'warning' dari ke-3 fungsi rekomendasi/insight di atas +
// satu status non-'warning' (Dana Darurat) yang dibungkus jadi bentuk
// item yang sama (domain/icon/type/code/message) tanpa mengubah pesan
// aslinya (Dana Darurat) atau menghitung ulang klasifikasi
// warning/positive/info (DebtOptimizer/FinancialHealthScore/
// FinanceIntelligence) — pola sama persis `recommendation`/`insights`
// yang sudah ada di planner2 lain, sekadar digabung lintas-domain di
// sini.
//
// Risk Level di bawah SATU-SATUNYA "logic" baru sesi ini — murni
// KATEGORISASI dari JUMLAH riskFactors() (0/1-2/3+ -> Rendah/Sedang/
// Tinggi), bentuk yang SAMA PERSIS dipakai `financialHealthRecommendation()`
// (financial-health-score-api.js, kategorisasi score>=80/>=60/<60 ->
// positive/info/warning) — bukan rumus finansial baru, murni klasifikasi
// atas angka (count) yang sudah final.
//
// Semua fungsi di bawah PURE (read-only) — tidak pernah memanggil save()
// atau menulis ke D/localStorage, tidak menyentuh DOM. TIDAK ada UI di
// file ini — presenternya (FinancialRiskDashboardPresenter) ada di file
// terpisah, sesi ini juga, 100% konsumsi objek ini.
const FinancialRiskDashboardAPI = {

// _debtRisk() — helper internal: reuse `DebtOptimizerAPI.
// debtRecommendation()` apa adanya, filter type==='warning' saja. Guard
// (DebtOptimizerAPI belum dimuat / gagal dipanggil) -> array kosong,
// pola sama persis guard `typeof X==='undefined'` di planner2 lain,
// TIDAK pernah throw.
_debtRisk() {
  if (typeof DebtOptimizerAPI === 'undefined') return [];
  let items;
  try {
    items = DebtOptimizerAPI.debtRecommendation();
  } catch (e) {
    return [];
  }
  return (Array.isArray(items) ? items : [])
    .filter((i) => i && i.type === 'warning')
    .map((i) => ({ domain: 'debt', icon: '📕', ...i }));
},

// _healthRisk() — helper internal: reuse `FinancialHealthScoreAPI.
// financialHealthRecommendation()` apa adanya, filter type==='warning'
// saja. Guard sama pola dgn _debtRisk().
_healthRisk() {
  if (typeof FinancialHealthScoreAPI === 'undefined') return [];
  let items;
  try {
    items = FinancialHealthScoreAPI.financialHealthRecommendation();
  } catch (e) {
    return [];
  }
  return (Array.isArray(items) ? items : [])
    .filter((i) => i && i.type === 'warning')
    .map((i) => ({ domain: 'health', icon: '❤️', ...i }));
},

// _cashflowBudgetRisk() — helper internal: reuse `FinanceIntelligence.
// insights()` apa adanya, filter type==='warning' saja (defisit bulanan/
// anggaran lewat batas/proyeksi arus kas minus). Guard sama pola dgn
// _debtRisk().
_cashflowBudgetRisk() {
  if (typeof FinanceIntelligence === 'undefined') return [];
  let items;
  try {
    items = FinanceIntelligence.insights();
  } catch (e) {
    return [];
  }
  return (Array.isArray(items) ? items : [])
    .filter((i) => i && i.type === 'warning')
    .map((i) => ({ domain: 'cashflow_budget', icon: '💸', ...i }));
},

// _emergencyFundRisk() — helper internal: cek status "Dana Darurat 3-6
// Bulan" langsung dari D.targets (isDanaDarurat, saved>=amount) — logic
// & threshold SAMA PERSIS dgn bekas step 3 TanggaKeuangan.compute()
// (fitur "Tangga Ternak Uang" sudah dihapus, lihat CHANGELOG; logic Dana
// Darurat ini dipindah ke sini SEBELUM file dihapus supaya Financial
// Risk Dashboard tidak kehilangan faktor risiko ini). Dibungkus jadi 1
// item warning kalau belum tercapai. Guard sama pola dgn _debtRisk().
_emergencyFundRisk() {
  let dd;
  try {
    dd = (D.targets || []).find(t => t.isDanaDarurat);
  } catch (e) {
    return [];
  }
  // FIX (BUG-013, audit 2026-08): dulu pakai `dd.saved` mentah -- untuk Target Dana
  // Darurat yang tertaut ke akun (dd.accountId), `dd.saved` adalah snapshot manual yang
  // BISA STALE (saldo akun sebenarnya sudah naik lewat transaksi, tapi field `saved`
  // tidak ikut ter-update tanpa ada aksi eksplisit -- lihat DanaDaruratAI.updateSaved()/
  // baris 417 modules-calc.js: "Target ini tertaut ke akun, saldo ikut otomatis dari
  // akunnya" -- yang "otomatis" itu maksudnya HARUS dibaca lewat recalcAccBalance(),
  // bukan dari field `saved`). Akibatnya Financial Risk Dashboard bisa salah nampilin
  // "Dana Darurat belum tercapai" padahal saldo akun real sudah capai/lewat target.
  // Fix: reuse pola SAMA PERSIS DanaDaruratAI.currentSaved() (modules-calc.js) /
  // invest-ai-widget.js._checkDanaDarurat() -- kalau dd.accountId ada & recalcAccBalance
  // tersedia, baca saldo real-time; kalau tidak (saldo manual), tetap fallback ke
  // dd.saved apa adanya (0 regresi untuk target Dana Darurat yang belum tertaut akun).
  const saved = (dd && dd.accountId && typeof recalcAccBalance === 'function')
    ? recalcAccBalance(dd.accountId)
    : (dd ? (dd.saved || 0) : 0);
  const done = !!(dd && dd.amount && saved >= dd.amount);
  if (done) return [];
  const note = dd ? (Math.min(100, Math.round((saved / (dd.amount || 1)) * 100)) + '% dari target') : 'Belum ada Target Dana Darurat';
  return [{
    domain: 'emergency_fund',
    icon: '🚨',
    type: 'warning',
    code: 'risk_emergency_fund_low',
    message: `Dana Darurat belum tercapai — ${note}.`,
  }];
},

// riskFactors() — Risk Factors. Gabungan APA ADANYA dari ke-4 helper di
// atas (0 recompute, 0 logic tambahan selain filter+gabung).
riskFactors() {
  return [
    ...this._debtRisk(),
    ...this._healthRisk(),
    ...this._cashflowBudgetRisk(),
    ...this._emergencyFundRisk(),
  ];
},

// riskLevel() — Risk Level. Derivatif murni dari riskFactors() milik
// file ini sendiri — kategorisasi sederhana atas JUMLAH faktor risiko
// (0 -> Rendah, 1-2 -> Sedang, 3+ -> Tinggi), pola sama persis
// kategorisasi score->label di `financialHealthRecommendation()`
// (financial-health-score-api.js) — 0 rumus baru.
riskLevel() {
  const factors = this.riskFactors();
  const count = factors.length;
  const level = count === 0 ? 'low' : count <= 2 ? 'medium' : 'high';
  const label = count === 0 ? 'Rendah' : count <= 2 ? 'Sedang' : 'Tinggi';
  return { count, level, label };
},

// summary() — satu pintu masuk gabungan (dipakai presenter), murni
// memanggil ke-2 fungsi di atas, TIDAK ada logic tambahan. `ok` selalu
// true (berbeda dari planner2 lain yang bergantung ke 1 sumber wajib —
// di sini TIDAK ada sumber tunggal yang wajib, kalau ke-4 sumber
// sekalipun belum dimuat, riskFactors() tetap balikin array kosong &
// riskLevel() tetap balikin 'Rendah' apa adanya, bukan gagal).
summary() {
  const riskFactors = this.riskFactors();
  const riskLevel = this.riskLevel();
  return { ok: true, riskFactors, riskLevel };
},

};

// modules/finance/financial-risk-dashboard-presenter.js — Financial Risk
// Dashboard Presenter (Sesi 99, Batch 10). Target sesi: Financial Risk
// Dashboard — lihat catatan lengkap di modules/finance/
// financial-risk-dashboard-api.js.
//
// PRINSIP (RULE #1 sesi ini): UI HANYA presenter. 100% REUSE
// `FinancialRiskDashboardAPI.summary()` (modules/finance/
// financial-risk-dashboard-api.js, sesi ini — sendiri 100% reuse
// DebtOptimizerAPI/FinancialHealthScoreAPI/FinanceIntelligence/status
// Dana Darurat) — TIDAK ada rumus baru, TIDAK menghitung ulang faktor
// risiko/level apa pun, TIDAK membaca D/modul sumber langsung. Pola SAMA
// PERSIS `FinancialHealthScorePresenter.render()` (Sesi 98 — 3 kartu,
// container `findash-grid` generik yang sama).
//
// Dipanggil dari renderKeuangan() (DIPINDAH dari DashboardHub.render() di Sesi 133; pola "tambahan murni" sama
// persis FinancialHealthScorePresenter.render() — lihat komentar di
// dashboard-hub.js). Live-wiring renderDashboard() DIHAPUS di Sesi 134 (gap fix,
// sudah dobel dgn renderKeuangan(), lihat CHANGELOG.md Sesi 134), TIDAK ada mekanisme render baru.
// CSS TIDAK baru — reuse penuh class findash-grid/findash-card (grid
// generik, sudah dipakai FinanceDashboard/.../FinancialHealthScorePresenter/dst).
//
// FINRISK_NAV_TARGETS (S254A — Batch Finance Navigation Consistency) —
// tujuan navigasi tiap kartu #financialRiskDashboardGrid. MURNI DATA (0
// logic navigasi baru), format {page,goTo} SAMA PERSIS format target
// dashHubNavigateToFeature() yang SUDAH ADA (dashboard-hub.js). Nama
// disendirikan per-file supaya tidak bentrok dgn const global lain (lihat
// kasus S251/S253). Ketiga kartu murni komposit lintas-domain (debt/
// health/cashflow/emergency fund) — TIDAK ada 1 halaman/daftar spesifik
// per faktor, jadi target = container section-nya sendiri
// (financialRiskDashboardWrap, dashboard-hub, TERVERIFIKASI ADA di
// index.html/app_production.html), pola sama persis
// VEHICLE_ANALYTICS_NAV_TARGETS.total/trend (self-scroll utk kartu
// komposit).
const FINRISK_NAV_TARGETS = Object.freeze({
  self: { page: 'keuangan', tab: 'laporan', goTo: 'financialRiskDashboardWrap' },
});
const FinancialRiskDashboardPresenter = {

  // DOMAIN_LABELS — pemetaan label tampilan (Bahasa Indonesia) per
  // `domain` (murni presentasi, sama pola dgn LABELS di
  // FinancialHealthScoreAPI.componentBreakdown() — bukan logic baru).
  DOMAIN_LABELS: {
    debt: 'Utang',
    health: 'Kesehatan Finansial',
    cashflow_budget: 'Arus Kas & Anggaran',
    emergency_fund: 'Dana Darurat',
  },

  render() {
    const el = document.getElementById('financialRiskDashboardGrid');
    if (!el) return; // container belum ada di halaman ini, aman diam2.

    if (typeof FinancialRiskDashboardAPI === 'undefined') {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data risiko finansial belum tersedia</div></div>';
      return;
    }

    const s = FinancialRiskDashboardAPI.summary();
    if (!s.ok) {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data risiko finansial belum tersedia</div></div>';
      return;
    }

    const cards = [
      this._levelCard(s.riskLevel),
      this._topFactorCard(s.riskFactors),
      this._breakdownCard(s.riskFactors),
    ];

    // S254A (Batch Finance Navigation Consistency): SELURUH kartu
    // clickable lewat mekanisme SAMA PERSIS FinanceDashboard.render()/
    // VehicleAnalyticsPresenter.render() — tiap kartu carry field
    // onClick:{action,args} sendiri (ditempel di masing2 _xxxCard() di
    // bawah), template di sini CUMA mengecek `c.onClick` (0 logic
    // navigasi baru, 0 percabangan per-index, JANGAN openCard(index)).
    el.innerHTML = cards.map((c) => `
      <div class="findash-card${c.onClick ? ' u-pointer' : ''}"${c.onClick ? ` data-action="${escapeHtml(c.onClick.action)}" data-args="${escapeHtml(JSON.stringify(c.onClick.args))}"` : ''}>
        <div class="findash-card-icon">${c.icon}</div>
        <div class="findash-card-body">
          <div class="findash-card-label">${escapeHtml(c.label)}</div>
          <div class="findash-card-val${c.cls ? ' ' + c.cls : ''}">${escapeHtml(c.value)}</div>
          ${c.sub ? `<div class="findash-card-sub">${escapeHtml(c.sub)}</div>` : ''}
        </div>
      </div>
    `).join('');
  },

  // _levelCard(rl) — rl = FinancialRiskDashboardAPI.summary().riskLevel,
  // dipakai APA ADANYA (count/level/label — 0 recompute).
  _levelCard(rl) {
    const onClick = { action: 'dashHubNavigateToFeature', args: [FINRISK_NAV_TARGETS.self] };
    if (!rl) {
      return { icon: '🛡️', label: 'Tingkat Risiko Finansial', value: '—', cls: '', onClick };
    }
    const cls = rl.level === 'low' ? 'green' : rl.level === 'medium' ? 'orange' : 'red';
    return {
      icon: '🛡️',
      label: 'Tingkat Risiko Finansial',
      value: rl.label,
      cls,
      sub: `${rl.count} faktor risiko terdeteksi`,
      onClick,
    };
  },

  // _topFactorCard(rf) — rf = FinancialRiskDashboardAPI.summary().riskFactors
  // (array, dipakai APA ADANYA — 0 recompute). Menampilkan faktor
  // pertama sbg highlight (pola sama RetirementPlannerPresenter/
  // FinancialHealthScorePresenter), sisanya dihitung sbg `sub`.
  _topFactorCard(rf) {
    const onClick = { action: 'dashHubNavigateToFeature', args: [FINRISK_NAV_TARGETS.self] };
    if (!Array.isArray(rf) || !rf.length) {
      return { icon: '⚠️', label: 'Faktor Risiko Utama', value: 'Tidak ada faktor risiko terdeteksi', cls: 'green', sub: '', onClick };
    }
    const main = rf[0];
    return {
      icon: '⚠️',
      label: 'Faktor Risiko Utama',
      value: main.message,
      cls: 'red',
      sub: rf.length > 1 ? `+${rf.length - 1} faktor lain` : '',
      onClick,
    };
  },

  // _breakdownCard(rf) — rf = FinancialRiskDashboardAPI.summary().riskFactors
  // (array, dipakai APA ADANYA — 0 recompute). Menghitung jumlah faktor
  // per `domain` murni presentasional (count sederhana, bukan rumus
  // baru), pola sama RetirementPlannerPresenter menampilkan sub-count.
  _breakdownCard(rf) {
    const onClick = { action: 'dashHubNavigateToFeature', args: [FINRISK_NAV_TARGETS.self] };
    if (!Array.isArray(rf) || !rf.length) {
      return { icon: '🗂️', label: 'Sebaran Risiko', value: 'Belum ada data', cls: '', sub: '', onClick };
    }
    const counts = {};
    rf.forEach((f) => {
      counts[f.domain] = (counts[f.domain] || 0) + 1;
    });
    const parts = Object.keys(counts).map((k) => `${this.DOMAIN_LABELS[k] || k} ${counts[k]}`);
    return {
      icon: '🗂️',
      label: 'Sebaran Risiko',
      value: parts.join(' · '),
      cls: '',
      sub: `${rf.length} total faktor`,
      onClick,
    };
  },

};

// vehicle-intelligence.js — Vehicle Intelligence Foundation (Sesi 76, Batch 7).
// Target sesi: lapisan agregasi domain VEHICLE — vehicle overview, health
// score per kendaraan, ringkasan armada (fleet), insight dasar — lihat
// docs/BATCH_PLAN.md § Batch 7. Pola SAMA PERSIS modules/finance/
// finance-intelligence.js (Sesi 74, Batch 6) — cuma dipindah ke domain
// vehicle, tidak ada arsitektur baru.
//
// PRINSIP (RULE #1 sesi ini): 100% REUSE, TIDAK ada framework/state baru,
// TIDAK duplikasi logic, TIDAK mengubah struktur data D. Semua angka di
// bawah dihitung dari service yang SUDAH ADA:
//   - getVehicleKm()      (modules/vehicle/vehicle-core.js)
//   - fuelEfficiency()    (modules/vehicle/vehicle-core.js)
//   - predictService()    (modules/vehicle/sparepart-servis.js)
//   - maintenanceForecast() (modules/vehicle/sparepart-servis.js)
// VehicleIntelligence TIDAK menghitung ulang estimasi KM/hari, konsumsi
// BBM, interval servis, atau jadwal servis berikutnya — semua itu dibaca
// apa adanya lewat pemanggilan fungsi di atas. Satu-satunya logic yang
// genuinely baru di sini adalah skoring komposit `healthScore()` (bobot
// per komponen, pola sama persis FinanceIntelligence.healthScore()) &
// agregasi lintas-kendaraan `fleetSummary()` (belum ada versi murninya
// sebelum sesi ini — yang ada baru per-kendaraan lewat predictService()/
// fuelEfficiency()).
//
// Semua fungsi di bawah PURE (read-only) — tidak pernah memanggil save()
// atau menulis ke D/localStorage, tidak menyentuh DOM. Dipakai sbg lapisan
// data utk widget/dashboard masa depan & AI briefing (di luar scope sesi
// ini — TIDAK ada UI/panel/wiring baru sesi ini, murni fondasi data/
// service, sama seperti finance-intelligence.js di Sesi 74).
const VehicleIntelligence = {

// _vehicles() — helper internal: baca D.vehicles apa adanya (array kosong
// kalau D/D.vehicles belum ada — guard typeof, pola sama persis guard
// D.budgets di FinanceIntelligence.budgetSummary()).
_vehicles() {
  return (typeof D !== 'undefined' && D.vehicles) ? D.vehicles : [];
},

// vehicleOverview(vehicleId) — ringkasan 1 kendaraan: KM saat ini
// (getVehicleKm), prediksi servis (predictService), efisiensi BBM
// (fuelEfficiency). Reuse murni, TIDAK ada rumus baru. {ok:false} kalau
// kendaraan tidak ditemukan (pola sama persis {ok:false} predictService()
// saat vehicleId tidak ketemu).
vehicleOverview(vehicleId) {
  const veh = this._vehicles().find((v) => v.id === vehicleId);
  if (!veh) return { ok: false, reason: 'Kendaraan tidak ditemukan' };
  const curKm = (typeof getVehicleKm === 'function') ? getVehicleKm(vehicleId) : 0;
  const service = (typeof predictService === 'function')
    ? predictService({ vehicleId })
    : { ok: false, reason: 'predictService belum dimuat' };
  const fuel = (typeof fuelEfficiency === 'function')
    ? fuelEfficiency(vehicleId)
    : { ok: false, reason: 'fuelEfficiency belum dimuat' };
  return { ok: true, vehicleId, name: veh.name, emoji: veh.emoji, curKm, service, fuel };
},

// healthScore(vehicleId) — skor 0-100, komposit dari komponen yang
// TERSEDIA (bukan dihitung ulang, murni dibaca dari service yang sudah
// ada):
//   (1) service adherence — dari predictService().items, status per
//       kategori sparepart ('aman'=1, 'segera'=0.5, 'lewat'=0), status
//       ITU SENDIRI sama persis yang dipakai Servis.renderReminder() &
//       rule AIDecision 'vehicle-service-overdue' (tidak mengarang ambang
//       baru)
//   (2) ketersediaan data BBM & efisiensi terjaga — dari fuelEfficiency()
//       ok/tidak (butuh min. 2 log "Isi Full Tank" dgn km naik, syarat
//       yang sama persis dgn estimateRpPerKm())
// Tiap komponen bobot 50, HANYA disertakan kalau service-nya tersedia
// (guard ok/length, pola sama persis FinanceIntelligence.healthScore()) —
// skor akhir diskalakan ulang dari bobot yang benar-benar tersedia (bukan
// gagal total/0 kalau 1 komponen belum ada datanya). Rule-based murni,
// TIDAK ada panggilan AI/ML.
healthScore(vehicleId) {
  const parts = [];
  if (typeof predictService === 'function') {
    const pred = predictService({ vehicleId });
    if (pred.ok && Array.isArray(pred.items) && pred.items.length) {
      const scores = pred.items.map((it) => (it.status === 'aman' ? 1 : it.status === 'segera' ? 0.5 : 0));
      const avg = scores.reduce((s, x) => s + x, 0) / scores.length;
      parts.push({ key: 'service', weight: 50, score: avg * 50 });
    }
  }
  if (typeof fuelEfficiency === 'function') {
    const fuel = fuelEfficiency(vehicleId);
    if (fuel.ok) parts.push({ key: 'fuel', weight: 50, score: 50 });
  }
  const maxScore = parts.reduce((s, p) => s + p.weight, 0);
  const rawScore = parts.reduce((s, p) => s + p.score, 0);
  const score = maxScore > 0 ? Math.round((rawScore / maxScore) * 100) : 0;
  const label = maxScore === 0
    ? 'Data Kurang'
    : (score >= 80 ? 'Sehat' : score >= 60 ? 'Cukup Sehat' : score >= 40 ? 'Waspada' : 'Perlu Perhatian');
  return { score, label, parts };
},

// fleetSummary() — agregasi lintas SEMUA D.vehicles: total kendaraan,
// total item servis 'lewat' jatuh tempo (reuse predictService() per
// kendaraan — status yang SAMA dipakai _vehicleOverdueCheck() di
// sparepart-servis.js, TIDAK menduplikasi logic overdue, cuma membaca
// ulang hasil predictService() yang sudah ada), rata-rata healthScore
// seluruh armada. Belum ada versi murni (non-DOM, lintas-kendaraan) untuk
// ini sebelum sesi ini.
// fleetSummary() (Sesi 196, Ownership Sync Vehicle): TAMBAH 1 filter
// isVehicleOwnershipSelf(v.id) di atas this._vehicles() (0 logic lama
// diubah). Kendaraan ber-ownership INVESTOR/CUSTOMER/THIRD_PARTY/FAMILY
// dikecualikan dari agregat armada (Dashboard/AI briefing), TAPI
// vehicleOverview(vehicleId)/healthScore(vehicleId) per-kendaraan TIDAK
// disentuh — kendaraan itu tetap kehitung normal kalau dilihat langsung
// by id (sama pola totalSaldoAkun() Sesi 192).
fleetSummary() {
  const vehicles = this._vehicles().filter((v) => (typeof isVehicleOwnershipSelf !== 'function') || isVehicleOwnershipSelf(v.id));
  const rows = vehicles.map((v) => {
    const hs = this.healthScore(v.id);
    let overdueCount = 0;
    if (typeof predictService === 'function') {
      const pred = predictService({ vehicleId: v.id });
      if (pred.ok && Array.isArray(pred.items)) {
        overdueCount = pred.items.filter((it) => it.status === 'lewat').length;
      }
    }
    return { vehicleId: v.id, name: v.name, healthScore: hs.score, healthLabel: hs.label, overdueCount };
  });
  const totalOverdue = rows.reduce((s, r) => s + r.overdueCount, 0);
  const avgHealth = rows.length ? Math.round(rows.reduce((s, r) => s + r.healthScore, 0) / rows.length) : 0;
  return { totalVehicles: vehicles.length, totalOverdue, avgHealth, vehicles: rows };
},

// insights(vehicleId?) — insight dasar, murni derivasi ambang batas dari
// fungsi di atas. BUKAN duplikasi rule AIDecision ('vehicle-service-
// overdue'/'vehicle-fuel-efficiency-drop' di sparepart-servis.js) — rule
// itu proaktif (registered ke AIDecision.rules, ada cooldown/weight/
// severity utk briefing), insight di sini derivatif ringan tanpa
// cooldown/registrasi apa pun, murni baca ulang hasil fungsi
// VehicleIntelligence sendiri. Tanpa vehicleId: insight FLEET-LEVEL (dari
// fleetSummary()). Dengan vehicleId: insight kendaraan itu saja (dari
// vehicleOverview()/healthScore()).
insights(vehicleId) {
  const out = [];
  if (vehicleId) {
    const ov = this.vehicleOverview(vehicleId);
    if (!ov.ok) return out;
    if (ov.service.ok && Array.isArray(ov.service.items)) {
      const lewat = ov.service.items.filter((it) => it.status === 'lewat');
      if (lewat.length) {
        out.push({ type: 'warning', code: 'service_overdue', message: `${lewat.length} item servis ${ov.name} sudah lewat jatuh tempo.` });
      }
    }
    if (ov.fuel.ok && ov.fuel.estMonthlyCost) {
      out.push({ type: 'info', code: 'fuel_cost_estimate', message: `Estimasi biaya BBM ${ov.name} bulan ini \u2248 ${Math.round(ov.fuel.estMonthlyCost)}.` });
    }
    const hs = this.healthScore(vehicleId);
    out.push({ type: 'info', code: 'health_score', message: `Skor kesehatan ${ov.name}: ${hs.score}/100 (${hs.label}).` });
    return out;
  }
  const fleet = this.fleetSummary();
  if (fleet.totalOverdue > 0) {
    out.push({ type: 'warning', code: 'fleet_overdue', message: `${fleet.totalOverdue} item servis lewat jatuh tempo di seluruh kendaraan.` });
  }
  if (fleet.totalVehicles > 0) {
    out.push({ type: 'info', code: 'fleet_health', message: `Rata-rata skor kesehatan armada: ${fleet.avgHealth}/100 dari ${fleet.totalVehicles} kendaraan.` });
  }
  return out;
},

// summary(vehicleId?) — satu pintu masuk gabungan (dipakai widget/AI
// briefing masa depan), murni memanggil fungsi di atas, TIDAK ada logic
// tambahan. Tanpa vehicleId: fleet-level (fleetSummary + insights fleet).
// Dengan vehicleId: tambahkan vehicleOverview + healthScore + insights
// kendaraan itu — pola sama persis FinanceIntelligence.summary().
summary(vehicleId) {
  const base = { fleet: this.fleetSummary(), insights: this.insights() };
  if (!vehicleId) return base;
  return {
    ...base,
    vehicle: this.vehicleOverview(vehicleId),
    healthScore: this.healthScore(vehicleId),
    vehicleInsights: this.insights(vehicleId),
  };
},

};

// modules/vehicle/vehicle-dashboard.js — Vehicle Dashboard Foundation
// (Sesi 77, Batch 7). Lihat docs/BATCH_PLAN.md § Batch 7.
//
// PRINSIP (RULE #1 sesi ini): UI HANYA presenter. 100% REUSE
// VehicleIntelligence.summary() (modules/vehicle/vehicle-intelligence.js,
// Sesi 76) — TIDAK ada rumus baru, TIDAK menghitung ulang KM/servis/BBM/
// health score/fleet summary, TIDAK membaca D langsung sama sekali (beda
// dari FinanceDashboard._netWorthCard() yang masih baca totalSaldoAkun()/
// totalDebtValue() langsung — di sini SEMUA angka yang ditampilkan sudah
// tersedia lewat field fleet dari summary(), jadi tidak perlu pembacaan D
// tambahan apa pun).
//
// Dipanggil dari renderCnTab() (DIPINDAH dari DashboardHub.render() di Sesi 133; pola
// "tambahan murni" sama persis FinanceDashboard.render()/EIEDashboard.render() — lihat
// komentar di dashboard-hub.js). Live-wiring renderDashboard() DIHAPUS di Sesi 134 (gap
// fix, sudah dobel dgn renderCnTab(), lihat CHANGELOG.md Sesi 134), TIDAK ada mekanisme
// render baru.
//
// AI Hook (getAIHook()): satu pintu masuk read-only utk konsumen AI/briefing
// masa depan (ai-chat.js dst) — WRAPPER TIPIS ke VehicleIntelligence.summary()
// (fleet-level, TANPA vehicleId — pola sama persis getAIHook() FinanceDashboard
// yg juga tidak menerima parameter), 0 logic tambahan, 0 transformasi data.
//
// CSS: TIDAK ada class baru — reuse penuh .findash-grid/.findash-card*
// (styles.css, Sesi 75) apa adanya, krn strukturnya generik (grid kartu
// icon+label+value+sub) & sudah cocok tanpa modifikasi.
//
// VEHICLE_DASHBOARD_NAV_TARGETS (Sesi 253 — Batch Vehicle Navigation
// Consistency) — tujuan navigasi tiap kartu #vehdashGrid. MURNI DATA (0
// logic navigasi baru), format {page,tab,subtab,goTo} SAMA PERSIS format
// target FEATURE_REGISTRY/CARD_NAV_TARGETS, dieksekusi lewat
// dashHubNavigateToFeature() yang SUDAH ADA (dashboard-hub.js). Nama
// disendirikan per-file (bukan CARD_NAV_TARGETS) supaya tidak bentrok
// dengan const global lain (lihat kasus S251). Ketiga target menunjuk
// container yang TERVERIFIKASI ADA di index.html/app_production.html (grep
// manual, 0 halaman/tab/container baru dibuat):
//   fleet -> halaman Kendaraan (Car Notes) apa adanya, belum ada container
//     daftar kendaraan spesifik yang lebih relevan dari halaman itu sendiri
//   service -> Kendaraan > tab Servis > servisList (SAMA PERSIS target
//     'cn-servis' di dashboard-hub-registry.js)
//   health -> Kendaraan > tab Insight AI > sub-tab Ringkasan > vehdashWrap
//     (container kartu ini sendiri — skor kesehatan armada = ringkasan,
//     tidak ada daftar/halaman lain yang lebih spesifik)
const VEHICLE_DASHBOARD_NAV_TARGETS = Object.freeze({
  fleet: { page: 'carnotes' },
  service: { page: 'carnotes', tab: 'servis', goTo: 'servisList' },
  health: { page: 'carnotes', tab: 'insight', subtab: 'ringkasan', goTo: 'vehdashWrap' },
});

const VehicleDashboard = {

  // getAIHook() — reuse 100% VehicleIntelligence.summary() (fleet-level,
  // tanpa vehicleId). Guard: kalau VehicleIntelligence belum dimuat (urutan
  // load / dipakai headless di test), balikin {ok:false} alih-alih throw
  // (pola sama persis getAIHook() FinanceDashboard).
  getAIHook() {
    if (typeof VehicleIntelligence === 'undefined') {
      return { ok: false, reason: 'VehicleIntelligence belum dimuat' };
    }
    return { ok: true, ...VehicleIntelligence.summary() };
  },

  render() {
    const el = document.getElementById('vehdashGrid');
    if (!el) return; // container belum ada di halaman ini, aman diam2.

    const hook = this.getAIHook();
    if (!hook.ok) {
      el.innerHTML = '<div class="empty"><div class="empty-text">Data vehicle intelligence belum tersedia</div></div>';
      return;
    }
    if (!hook.fleet || !hook.fleet.totalVehicles) {
      el.innerHTML = '<div class="empty"><div class="empty-text">Belum ada data kendaraan</div></div>';
      return;
    }

    const cards = [
      this._fleetCard(hook.fleet),
      this._serviceCard(hook.fleet),
      this._healthCard(hook.fleet),
    ];

    // S253 (Batch Vehicle Navigation Consistency): SELURUH kartu clickable
    // lewat mekanisme SAMA PERSIS FinanceDashboard.render()/
    // AssetPortfolioPresenter.render() (S251-252) — tiap kartu carry field
    // onClick:{action,args} sendiri (ditempel di masing2 _xxxCard() di
    // bawah), template di sini CUMA mengecek `c.onClick` (0 logic navigasi
    // baru, 0 percabangan per-index, JANGAN openCard(index)).
    el.innerHTML = cards.map((c) => `
      <div class="findash-card${c.onClick ? ' u-pointer' : ''}"${c.onClick ? ` data-action="${escapeHtml(c.onClick.action)}" data-args="${escapeHtml(JSON.stringify(c.onClick.args))}"` : ''}>
        <div class="findash-card-icon">${c.icon}</div>
        <div class="findash-card-body">
          <div class="findash-card-label">${escapeHtml(c.label)}</div>
          <div class="findash-card-val${c.cls ? ' ' + c.cls : ''}">${escapeHtml(c.value)}</div>
          ${c.sub ? `<div class="findash-card-sub">${escapeHtml(c.sub)}</div>` : ''}
        </div>
      </div>
    `).join('');
  },

  // _fleetCard(fleet) — fleet = VehicleIntelligence.summary().fleet (hasil
  // fleetSummary() apa adanya), totalVehicles murni jumlah D.vehicles.
  _fleetCard(fleet) {
    return {
      icon: '🚗',
      label: 'Total Kendaraan',
      value: String(fleet.totalVehicles),
      cls: '',
      onClick: { action: 'dashHubNavigateToFeature', args: [VEHICLE_DASHBOARD_NAV_TARGETS.fleet] },
    };
  },

  // _serviceCard(fleet) — totalOverdue dari fleetSummary() apa adanya
  // (jumlah item servis status 'lewat' lintas seluruh kendaraan, reuse
  // predictService() yang sudah dipanggil VehicleIntelligence sendiri — 0
  // recompute di sini).
  _serviceCard(fleet) {
    return {
      icon: '🔧',
      label: 'Servis Lewat Jatuh Tempo',
      value: String(fleet.totalOverdue),
      cls: fleet.totalOverdue > 0 ? 'red' : 'green',
      onClick: { action: 'dashHubNavigateToFeature', args: [VEHICLE_DASHBOARD_NAV_TARGETS.service] },
    };
  },

  // _healthCard(fleet) — avgHealth dari fleetSummary() apa adanya (rata-rata
  // healthScore() seluruh kendaraan — 0 recompute di sini).
  _healthCard(fleet) {
    const score = fleet.avgHealth;
    const cls = score >= 80 ? 'green' : score >= 60 ? '' : score >= 40 ? 'orange' : 'red';
    return {
      icon: '❤️',
      label: 'Skor Kesehatan Armada',
      value: `${score}/100`,
      cls,
      onClick: { action: 'dashHubNavigateToFeature', args: [VEHICLE_DASHBOARD_NAV_TARGETS.health] },
    };
  },

};

// vehicle-reminder.js — Vehicle Reminder Foundation (Sesi 78, Batch 7).
// Target sesi: lapisan reminder domain VEHICLE — Service Reminder, Tax
// Reminder, Fuel Reminder, + Reminder Summary API. Lihat docs/BATCH_PLAN.md
// § Batch 7. Pola SAMA PERSIS modules/vehicle/vehicle-intelligence.js
// (Sesi 76) & modules/finance/finance-intelligence.js (Sesi 74) — lapisan
// agregasi PURE (read-only) di atas service yang SUDAH ADA.
//
// PRINSIP (RULE #1 sesi ini): 100% REUSE sebisa mungkin, TIDAK ada
// framework/state baru, TIDAK duplikasi logic, TIDAK mengubah struktur
// data D. Sumber data dipakai apa adanya:
//   - predictService()        (modules/vehicle/sparepart-servis.js)
//   - VEHTAX_ITEMS            (car-notes.js)
//   - dateStatusBadge()/daysUntilDate() (modules/vehicle/vehicle-core.js)
//   - fuelEfficiency()/getVehicleKm()/estimateServiceDateISO() (vehicle-core.js)
//   - D.bbmLogs (mentah, HANYA untuk fuelReminders() — lihat catatan di sana)
//
// serviceReminders()/taxReminders() TIDAK menghitung ulang status apa pun —
// status 'lewat'/'segera' (servis) & warna 'red'/'orange' (pajak, dari
// dateStatusBadge() yang SUDAH ADA & sudah dipakai UI) dibaca apa adanya,
// sama persis ambang yang sudah dipakai _vehicleOverdueCheck() (rule AI
// 'vehicle-service-overdue') & checkAndFireReminders() (reminder-notif.js)
// masing-masing — reminder di sini murni membungkus ulang hasil yang sama
// jadi bentuk list yang seragam lintas 3 tipe.
//
// fuelReminders() SATU-SATUNYA logic yang genuinely baru sesi ini (belum
// ada versi murninya sebelum sesi ini, sama seperti fleetSummary() jadi
// logic baru satu-satunya di VehicleIntelligence Sesi 76) — lihat komentar
// detail di fungsi itu.
//
// TIDAK ada wiring ke reminder-notif.js/checkAndFireReminders() (yang
// nembak Notification browser), TIDAK ada UI/panel/dashboard card, TIDAK
// ada AI Hook — eksplisit di luar scope sesi ini (murni fondasi data/
// service, pola sama persis vehicle-intelligence.js Sesi 76 sebelum
// vehicle-dashboard.js Sesi 77 menyusul). Semua fungsi di bawah PURE — tidak
// pernah memanggil save() atau menulis ke D/localStorage, tidak menyentuh
// DOM/Notification.
const VehicleReminder = {

// _vehicles(vehicleId) — helper internal: baca D.vehicles apa adanya
// (array kosong kalau D/D.vehicles belum ada — guard typeof, pola sama
// persis VehicleIntelligence._vehicles()), difilter ke 1 kendaraan kalau
// vehicleId diberikan.
// _vehicles(vehicleId) (Sesi 196, Ownership Sync Vehicle): dengan
// vehicleId -> tetap balikin kendaraan itu apa adanya (TIDAK peduli
// ownership, sama pola per-akun/per-aset Sesi 192-193). TANPA vehicleId
// (fleet-wide, dipakai reminder-notif.js/VehicleNotifBridge/
// FuelNotifBridge/Dashboard) -> HANYA kendaraan ownership SELF (default/
// tanpa field ownership ikut SELF), kendaraan INVESTOR/CUSTOMER/
// THIRD_PARTY/FAMILY dikecualikan dari reminder lintas-armada.
_vehicles(vehicleId) {
  const all = (typeof D !== 'undefined' && D.vehicles) ? D.vehicles : [];
  if (vehicleId) return all.filter((v) => v.id === vehicleId);
  return all.filter((v) => (typeof isVehicleOwnershipSelf !== 'function') || isVehicleOwnershipSelf(v.id));
},

// serviceReminders(vehicleId?) — reminder servis lintas kendaraan (atau 1
// kendaraan kalau vehicleId diberikan), reuse predictService() apa adanya.
// Item status 'aman' TIDAK dijadikan reminder (tidak perlu diingatkan).
// status 'lewat' => severity 'overdue', status 'segera' => severity
// 'due-soon' — ambang ITU SENDIRI (sisaKm<=0 / sisaKm<=intervalKm*0.15)
// sudah dihitung di dalam predictService(), TIDAK dihitung ulang di sini.
serviceReminders(vehicleId) {
  const out = [];
  if (typeof predictService !== 'function') return out;
  this._vehicles(vehicleId).forEach((v) => {
    const pred = predictService({ vehicleId: v.id });
    if (!pred.ok || !Array.isArray(pred.items)) return;
    pred.items.filter((it) => it.status !== 'aman').forEach((it) => {
      const severity = it.status === 'lewat' ? 'overdue' : 'due-soon';
      const message = severity === 'overdue'
        ? `Servis ${it.categoryName} ${v.name} sudah lewat jatuh tempo (${Math.abs(it.sisaKm)} km lewat batas).`
        : `Servis ${it.categoryName} ${v.name} segera jatuh tempo (sisa ${it.sisaKm} km).`;
      out.push({
        type: 'service',
        vehicleId: v.id,
        vehicleName: v.name,
        severity,
        categoryName: it.categoryName,
        sisaKm: it.sisaKm,
        estDateISO: it.estDateISO,
        message,
      });
    });
  });
  return out;
},

// taxReminders(vehicleId?) — reminder pajak/dokumen kendaraan (STNK
// Tahunan, Ganti Plat 5th, Uji Kelayakan — dari VEHTAX_ITEMS apa adanya),
// reuse dateStatusBadge() (vehicle-core.js, SUDAH dipakai renderCnTab()
// & checkAndFireReminders()) utk klasifikasi status — TIDAK menghitung
// ulang ambang "H-30 hari"/lewat, cuma membaca ulang warna badge yang
// sudah ada. col 'red' (lewat) => severity 'overdue', col 'orange'
// (<=30 hari) => severity 'due-soon'. col 'green'/'' (aktif jauh/belum
// diisi) TIDAK dijadikan reminder.
taxReminders(vehicleId) {
  const out = [];
  if (typeof VEHTAX_ITEMS === 'undefined' || typeof dateStatusBadge !== 'function' || typeof daysUntilDate !== 'function') return out;
  this._vehicles(vehicleId).forEach((v) => {
    Object.entries(VEHTAX_ITEMS).forEach(([key, cfg]) => {
      const tgl = v[cfg.tglKey];
      if (!tgl) return;
      const badge = dateStatusBadge(tgl);
      if (badge.col !== 'red' && badge.col !== 'orange') return;
      const severity = badge.col === 'red' ? 'overdue' : 'due-soon';
      const label = cfg.label.replace(/^\S+\s/, '');
      out.push({
        type: 'tax',
        vehicleId: v.id,
        vehicleName: v.name,
        severity,
        taxKey: key,
        label,
        tgl,
        daysUntil: daysUntilDate(tgl),
        message: `${label} ${v.name} — ${badge.label}.`,
      });
    });
  });
  return out;
},

// fuelReminders(vehicleId?) — LOGIC BARU sesi ini (belum ada versi
// murninya sebelum sesi ini). Tujuan: ingatkan kalau kendaraan
// diperkirakan hampir mencapai jangkauan (range) BBM-nya sejak pengisian
// Full Tank terakhir, ATAU kalau histori BBM belum cukup utk estimasi
// apa pun.
//
// TIDAK menghitung ulang kmPerLiter/kmPerDay (dibaca apa adanya dari
// fuelEfficiency(), vehicle-core.js) & TIDAK menyimpan/menambah field D
// baru (tidak ada "kapasitas tangki" per kendaraan di data model — lihat
// docs/BATCH_PLAN.md, TIDAK ditambahkan sesi ini krn di luar scope
// "Foundation"). Sebagai gantinya, "jangkauan per Full Tank" diestimasi
// dari RATA-RATA liter tiap pengisian Full Tank historis (data mentah
// D.bbmLogs yang SUDAH difilter fullTank, pola filter SAMA PERSIS yang
// dipakai estimateRpPerKm()/_vehicleFuelEfficiencyDropCheck() di
// vehicle-core.js/sparepart-servis.js) dikali kmPerLiter (reuse
// fuelEfficiency()). Km yang sudah ditempuh sejak pengisian Full Tank
// TERAKHIR (curKm - lastFull.km, curKm dari getVehicleKm() yang SUDAH
// ADA) dibandingkan ke estimasi jangkauan itu. Ambang "due-soon" pakai
// rasio 15% SAMA PERSIS yang sudah dipakai predictService() (bukan
// ambang baru yang diciptakan sendiri) — supaya konsisten dgn semantik
// "segera" di seluruh app. estDateISO reuse estimateServiceDateISO()
// (vehicle-core.js — formula proyeksi tanggal dari sisaKm/kmPerDay,
// generik, bukan spesifik servis) apa adanya, TIDAK ditulis ulang.
fuelReminders(vehicleId) {
  const out = [];
  this._vehicles(vehicleId).forEach((v) => {
    const fuel = (typeof fuelEfficiency === 'function') ? fuelEfficiency(v.id) : { ok: false, reason: 'fuelEfficiency belum dimuat' };
    if (!fuel.ok) {
      out.push({
        type: 'fuel',
        vehicleId: v.id,
        vehicleName: v.name,
        severity: 'info',
        message: `Data BBM ${v.name} belum cukup utk estimasi pengingat isi BBM (${fuel.reason}).`,
      });
      return;
    }
    const fullLogs = ((typeof D !== 'undefined' && D.bbmLogs) ? D.bbmLogs : [])
      .filter((b) => b.vehicleId === v.id && b.fullTank && isFinite(b.km) && b.km > 0 && b.liter > 0)
      .sort((a, b) => a.km - b.km);
    if (!fullLogs.length) return; // fuel.ok tapi tanpa log fullTank valid (edge-case) -- tidak cukup dasar utk estimasi range.
    const lastFull = fullLogs[fullLogs.length - 1];
    const avgLiter = fullLogs.reduce((s, b) => s + b.liter, 0) / fullLogs.length;
    const rangeKm = avgLiter * fuel.kmPerLiter;
    if (!(rangeKm > 0)) return;
    const curKm = (typeof getVehicleKm === 'function') ? getVehicleKm(v.id) : lastFull.km;
    const kmSinceLastFull = curKm - lastFull.km;
    const sisaKm = rangeKm - kmSinceLastFull;
    if (sisaKm > rangeKm * 0.15) return; // masih jauh dari batas jangkauan, belum perlu diingatkan.
    const severity = sisaKm <= 0 ? 'overdue' : 'due-soon';
    const estDateISO = (typeof estimateServiceDateISO === 'function') ? estimateServiceDateISO(sisaKm, fuel.kmPerDay) : null;
    const message = severity === 'overdue'
      ? `Berdasarkan histori, ${v.name} kemungkinan sudah melewati estimasi jangkauan BBM sejak isi Full Tank terakhir.`
      : `${v.name} diperkirakan perlu isi BBM lagi dalam \u2248${Math.round(sisaKm)} km.`;
    out.push({
      type: 'fuel',
      vehicleId: v.id,
      vehicleName: v.name,
      severity,
      sisaKm: Math.round(sisaKm),
      rangeKm: Math.round(rangeKm),
      estDateISO,
      message,
    });
  });
  return out;
},

// summary(vehicleId?) — Reminder Summary API, satu pintu masuk gabungan
// (dipakai widget/AI briefing masa depan, di luar scope sesi ini), murni
// memanggil 3 fungsi di atas & menggabungkan hasilnya, TIDAK ada logic
// tambahan. all = gabungan urut service+tax+fuel (bukan diurutkan ulang
// by severity/tanggal -- pengurutan tampilan didelegasikan ke konsumen
// UI masa depan, sama seperti VehicleIntelligence.summary() yang juga
// tidak mengurutkan insights()).
summary(vehicleId) {
  const service = this.serviceReminders(vehicleId);
  const tax = this.taxReminders(vehicleId);
  const fuel = this.fuelReminders(vehicleId);
  const all = [...service, ...tax, ...fuel];
  return {
    total: all.length,
    overdueCount: all.filter((r) => r.severity === 'overdue').length,
    dueSoonCount: all.filter((r) => r.severity === 'due-soon').length,
    infoCount: all.filter((r) => r.severity === 'info').length,
    service,
    tax,
    fuel,
    all,
  };
},

};

// vehicle-notif-bridge.js — Vehicle Notification Bridge (Sesi 84, Batch 7).
// Target sesi: **Vehicle Dashboard Final Integration** — menutup gap
// terakhir yang tercatat di docs/BATCH_PLAN.md Sesi 83 ("wiring
// VehicleAutomationAPI/VehicleReminderScheduler ke reminder-notif.js/
// notifikasi browser ... BELUM ada wiring ke notifikasi nyata").
//
// KONTEKS: reminder-notif.js (checkAndFireReminders()) SUDAH menembak
// notifikasi browser nyata utk tagihan/LDR/pajak-kendaraan(VEHTAX_ITEMS)/
// SIM/SPT -- TAPI baca D.vehicles+VEHTAX_ITEMS langsung (ad-hoc, mendahului
// VehicleReminder Sesi 78, TIDAK diubah sesi ini krn sudah berjalan &
// mengubahnya cuma menambah risiko regresi tanpa manfaat baru). Service
// Reminder & Fuel Reminder (VehicleReminder.serviceReminders()/
// .fuelReminders(), Sesi 78) BELUM PERNAH menembak notifikasi nyata --
// itu satu-satunya gap yang ditutup sesi ini.
//
// PRINSIP (RULE #1): 100% REUSE VehicleReminder (Sesi 78) apa adanya --
// TIDAK ada ambang/rumus baru, TIDAK menghitung ulang status 'overdue' apa
// pun (severity sudah final dari layer di bawahnya). Modul ini PURE --
// tidak pernah memanggil fireNotif()/Notification/localStorage sendiri,
// tidak menyentuh DOM. Hanya MENERJEMAHKAN reminder severity 'overdue'
// (service+fuel) jadi bentuk generik {fireKey,title,body} siap pakai
// pemanggil (reminder-notif.js checkAndFireReminders(), yang SUDAH
// memanggil fireNotif()+menyimpan kw_notif_fired sendiri) -- pola sama
// persis lapisan presenter/API murni lain di modules/vehicle/* (mis.
// VehicleActionRecommendation.actionFor(), Sesi 82).
//
// taxReminders() SENGAJA TIDAK disertakan di sini -- jalur lama ad-hoc di
// reminder-notif.js sudah menembak notif pajak, menyertakannya lagi lewat
// modul ini akan dobel-tembak utk tipe yang sama (fireKey beda format,
// firedIds tidak akan saling mendeteksi).
//
// severity 'due-soon'/'info' SENGAJA TIDAK ditembak jadi notifikasi push --
// pola sama ambang tagihan/pajak yang sudah ada (hanya H-0 s/d lewat yang
// aktif menembak notif; due-soon tetap murni domain dashboard/insight feed,
// BUKAN push notification).
const VehicleNotifBridge = {

// items(vehicleId?, firedIds?) — daftar {fireKey,title,body} siap tembak
// notifikasi, dari VehicleReminder.serviceReminders()/.fuelReminders()
// severity 'overdue', difilter firedIds (default []) supaya item yang
// sudah pernah ditembak (hari yang sama, disuplai pemanggil dari
// kw_notif_fired.ids) tidak diulang.
items(vehicleId, firedIds) {
  const fired = Array.isArray(firedIds) ? firedIds : [];
  if (typeof VehicleReminder === 'undefined') return [];
  const out = [];

  const service = (typeof VehicleReminder.serviceReminders === 'function')
    ? VehicleReminder.serviceReminders(vehicleId).filter((r) => r.severity === 'overdue')
    : [];
  service.forEach((r) => {
    const fireKey = 'vehsvc_' + r.vehicleId + '_' + r.categoryName;
    if (fired.includes(fireKey)) return;
    out.push({ fireKey, title: '🔧 Servis Lewat Jatuh Tempo', body: r.message });
  });

  const fuel = (typeof VehicleReminder.fuelReminders === 'function')
    ? VehicleReminder.fuelReminders(vehicleId).filter((r) => r.severity === 'overdue')
    : [];
  fuel.forEach((r) => {
    const fireKey = 'vehfuel_' + r.vehicleId;
    if (fired.includes(fireKey)) return;
    out.push({ fireKey, title: '⛽ Estimasi BBM Terlewati', body: r.message });
  });

  return out;
},

};

// modules/vehicle/vehicle-ai-hook.js — Vehicle AI Hook Foundation
// (Sesi 79, Batch 7). Lihat docs/BATCH_PLAN.md § Batch 7.
//
// PRINSIP (RULE #1 sesi ini): 100% REUSE, TIDAK ada rumus baru, TIDAK
// duplikasi logic, TIDAK mengubah struktur data D. VehicleAIHook HANYA
// menggabungkan hasil yang SUDAH ADA dari 2 lapisan agregasi vehicle:
//   - VehicleIntelligence.summary()/.fleetSummary() (Sesi 76)
//   - VehicleReminder.summary()                     (Sesi 78)
// getAIHook()-style wrapper SUDAH ADA per-modul (FinanceDashboard/
// VehicleDashboard, masing2 fleet-level saja, TANPA reminder). VehicleAIHook
// BUKAN pengganti keduanya — objek BARU yg tugasnya SATU: jadi satu pintu
// masuk read-only gabungan Intelligence+Reminder utk konsumen AI/briefing
// masa depan (ai-chat.js dst, di luar scope sesi ini — TIDAK ada wiring AI
// baru sesi ini), sesuai kandidat lama yg tercatat di BATCH_PLAN.md
// ("wiring VehicleReminder.summary() ke UI/notifikasi/AI briefing").
//
// 2 API baru sesi ini:
//   - fleetSummary()        — gabungan VehicleIntelligence.summary() (fleet-
//                              level, tanpa vehicleId) + VehicleReminder.
//                              summary() (fleet-level, tanpa vehicleId)
//   - vehicleInsight(id)    — gabungan VehicleIntelligence.summary(id) +
//                              VehicleReminder.summary(id) utk 1 kendaraan
// Keduanya WRAPPER TIPIS — 0 transformasi angka, 0 sorting/filtering
// tambahan atas hasil summary() masing2 modul, cuma disatukan jadi satu
// objek. Guard {ok:false} kalau salah satu/kedua modul belum dimuat (pola
// sama persis getAIHook() FinanceDashboard/VehicleDashboard).
//
// TIDAK ada UI/panel/dashboard di file ini — presenter-nya file terpisah
// (modules/vehicle/vehicle-insight-presenter.js, sesi ini juga tapi murni
// presenter, 100% reuse VehicleAIHook di sini, lihat komentar di file itu).
const VehicleAIHook = {

// fleetSummary() — Fleet Summary API. Gabungan VehicleIntelligence.
// summary() (fleet + insights fleet-level) dan VehicleReminder.summary()
// (service+tax+fuel reminder + overdueCount/dueSoonCount/infoCount)
// TANPA vehicleId di kedua sisi — 0 recompute, murni pemanggilan ulang.
// {ok:false} kalau VehicleIntelligence ATAU VehicleReminder belum dimuat
// (guard urutan load / dipakai headless di test, pola sama persis
// getAIHook() FinanceDashboard/VehicleDashboard).
fleetSummary() {
  if (typeof VehicleIntelligence === 'undefined') {
    return { ok: false, reason: 'VehicleIntelligence belum dimuat' };
  }
  if (typeof VehicleReminder === 'undefined') {
    return { ok: false, reason: 'VehicleReminder belum dimuat' };
  }
  const intelligence = VehicleIntelligence.summary();
  const reminder = VehicleReminder.summary();
  return { ok: true, intelligence, reminder };
},

// vehicleInsight(vehicleId) — Vehicle Insight API. Gabungan VehicleIntelligence.
// summary(vehicleId) (vehicleOverview+healthScore+insights kendaraan itu) &
// VehicleReminder.summary(vehicleId) (reminder kendaraan itu saja) — 0
// recompute, murni pemanggilan ulang dgn vehicleId yg sama ke kedua modul.
// {ok:false} kalau VehicleIntelligence/VehicleReminder belum dimuat (guard
// sama persis fleetSummary() di atas), ATAU kalau vehicleId tidak
// ditemukan (reuse {ok:false} vehicleOverview() milik VehicleIntelligence
// sendiri — TIDAK menduplikasi pengecekan "kendaraan ada/tidak").
vehicleInsight(vehicleId) {
  if (typeof VehicleIntelligence === 'undefined') {
    return { ok: false, reason: 'VehicleIntelligence belum dimuat' };
  }
  if (typeof VehicleReminder === 'undefined') {
    return { ok: false, reason: 'VehicleReminder belum dimuat' };
  }
  const intelligence = VehicleIntelligence.summary(vehicleId);
  if (!intelligence.vehicle || !intelligence.vehicle.ok) {
    return { ok: false, reason: (intelligence.vehicle && intelligence.vehicle.reason) || 'Kendaraan tidak ditemukan' };
  }
  const reminder = VehicleReminder.summary(vehicleId);
  return { ok: true, vehicleId, intelligence, reminder };
},

};

