// fuel-prediction-engine.js — Fuel Consumption Prediction Engine (TASK-146).
//
// PRINSIP: engine-only, 0 UI, PURE (read-only, tidak pernah panggil save()
// atau menulis ke D). 100% REUSE modul fuel yang SUDAH ADA — 0 rumus
// bar/liter/persen/km/L/Rp per km baru dihitung di sini:
//   - FuelGaugeEngine (TASK-143)      -> estimateRemainingDistance()/
//                                        getReserveStatus() utk konversi
//                                        sisa BBM (liter) -> jarak (km).
//   - FuelTankProfile (TASK-142)      -> dipakai TIDAK LANGSUNG lewat
//                                        FuelGaugeEngine (yang sudah
//                                        REUSE FuelTankProfile.get()
//                                        sendiri) — modul ini TIDAK
//                                        pernah panggil FuelTankProfile
//                                        langsung.
//   - fuelEfficiency() (vehicle-core.js, global SUDAH ADA) -> km/L,
//     Rp/km, kmPerDay, DAN proyeksi estMonthlyKm/estMonthlyLiter/
//     estMonthlyCost yang SUDAH dihitung di sana (dipakai APA ADANYA
//     utk predictMonthlyFuelUsage(), bukan dihitung ulang).
//   - D.vehicles[i].fuelState (currentFuelLiter/currentFuelBar/
//     confidenceScore, field additive TASK-144, ditulis
//     FuelBarCorrection.save()) -> dibaca APA ADANYA, TIDAK PERNAH
//     ditulis/diubah oleh modul ini.
//
// TIDAK disentuh sama sekali (sesuai batasan task): FuelGaugeEngine
// (kalkulasi), D.bbmLogs (riwayat transaksi BBM), FuelTankProfile,
// business logic modul fuel-* lain mana pun.
//
// ALGORITMA (deterministik, rule-based, BUKAN machine learning):
//   Fuel Efficiency (fuelEfficiency()/FuelGaugeEngine)
//     -> Current Fuel (D.vehicles[i].fuelState.currentFuelLiter)
//     -> Recent Driving Pattern (kmPerDay dari fuelEfficiency(), yang
//        sendiri REUSE estimateKmPerDay() dari histori D.kmLogs/
//        D.bbmLogs)
//     -> Average Daily Distance (kmPerDay di atas)
//     -> Prediction (4 method publik di bawah)
//
// FUTURE READY: setiap method publik memanggil _applyAdjustments()
// (extension point) SEBELUM balikin angka akhir — stub ini SENGAJA
// selalu mengembalikan nilai apa adanya (factor 1x) sekarang. Sesi
// masa depan yang mau menambah weather/traffic/riding-style/seasonal
// adjustment tinggal isi logic di _applyAdjustments() TANPA mengubah
// signature/shape return API publik mana pun di file ini.
//
// KONTRAK ERROR: semua method publik balikin {ok:false, reason} kalau
// gagal (kendaraan tidak ditemukan, fuel state/profil tangki/histori
// belum cukup, dependency belum dimuat) — TIDAK PERNAH throw.
//
// SESI 4 (FUEL-AUTOSYNC-07, lanjutan rencana "Fuel Estimation
// Auto-Update"): predictRemainingDistance()/predictNextRefuel() sekarang
// ambil liter via _currentLiter() (BARU, di bawah) — 100% REUSE
// FuelStateEstimator.estimateCurrentLiter() (s415) kalau tersedia, jadi
// prediksi ikut "hidup" mengikuti km tanpa nunggu BBM log baru (selaras
// FuelCard s417). Fallback ke fuelState.currentFuelLiter snapshot lama
// tetap ada, 0 behavior lama hilang.
//
// SESI 5 (FUEL-AUTOSYNC-08): _confidence() sekarang REUSE
// FuelStateEstimator.estimateCurrentLiter().decayedConfidenceScore (BARU)
// — confidenceScore yang dibalikin predictRemainingDistance() sudah
// meluruh sesuai km sejak titik acuan, bukan angka statis 70/90/100 lagi.
// Fallback ke fuelState.confidenceScore apa adanya tetap ada, pola sama.
const FuelPredictionEngine = {

// RP_ROUND_PER_LITER — presisi pembulatan liter di hasil publik (2
// desimal, konsisten dgn FuelGaugeEngine.calculateFuelLiter()).
_roundLiter(n) {
  return Math.round(n * 100) / 100;
},

// _vehicles()/_vehicle(vehicleId) — pola SAMA PERSIS FuelTankProfile/
// FuelStorage/VehicleIntelligence dkk: baca D.vehicles apa adanya lewat
// guard typeof, cari 1 kendaraan by id.
_vehicles() {
  return (typeof D !== 'undefined' && D.vehicles) ? D.vehicles : [];
},
_vehicle(vehicleId) {
  return this._vehicles().find((v) => v.id === vehicleId) || null;
},

// _fuelState(vehicleId) — baca D.vehicles[i].fuelState APA ADANYA
// (field additive TASK-144, ditulis FuelBarCorrection.save()). Balikin
// null kalau kendaraan tidak ada ATAU fuelState belum ada/currentFuelLiter
// belum berupa angka valid (mis. kendaraan baru yang belum pernah
// dikoreksi lewat FuelBarCorrection) — caller publik menerjemahkan ini
// jadi {ok:false, reason} yang jelas, BUKAN menebak angka.
_fuelState(vehicleId) {
  const veh = this._vehicle(vehicleId);
  if (!veh || !veh.fuelState) return null;
  const fs = veh.fuelState;
  if (typeof fs.currentFuelLiter !== 'number' || !isFinite(fs.currentFuelLiter)) return null;
  return fs;
},

// _confidence(vehicleId, fuelState) — SESI 5 (FUEL-AUTOSYNC-08, lanjutan
// rencana "Fuel Estimation Auto-Update", confidence decay dinamis): 100%
// REUSE FuelStateEstimator.estimateCurrentLiter().decayedConfidenceScore
// (BARU, s419 estimator) kalau tersedia & ok:true — confidenceScore yang
// dibalikin sekarang sudah meluruh sesuai km sejak titik acuan, bukan
// angka statis lagi. Fallback ke fuelState.confidenceScore APA ADANYA
// (pola lama) kalau FuelStateEstimator belum dimuat ATAU estimator
// ok:false — 0 behavior lama hilang, pola guard sama persis
// _currentLiter() di bawah.
_confidence(vehicleId, fuelState) {
  if (typeof FuelStateEstimator !== 'undefined' && typeof FuelStateEstimator.estimateCurrentLiter === 'function') {
    const est = FuelStateEstimator.estimateCurrentLiter(vehicleId);
    if (est && est.ok && typeof est.decayedConfidenceScore === 'number') return est.decayedConfidenceScore;
  }
  return (fuelState && typeof fuelState.confidenceScore === 'number') ? fuelState.confidenceScore : null;
},

// _currentLiter(vehicleId, fuelState) — SESI 4 (FUEL-AUTOSYNC-07, lanjutan
// rencana "Fuel Estimation Auto-Update", selaras FuelCard._liveEstimate()
// s417): 100% REUSE FuelStateEstimator.estimateCurrentLiter() (s415) kalau
// tersedia & ok:true — balikin liter TERKINI (dihitung ulang berdasarkan
// akumulasi km sejak titik acuan SETIAP dipanggil), bukan snapshot beku
// fuelState.currentFuelLiter. Fallback ke fuelState.currentFuelLiter apa
// adanya kalau FuelStateEstimator belum dimuat ATAU estimator ok:false
// (mis. belum ada titik acuan sama sekali) — prediksi TIDAK PERNAH gagal
// gara-gara sumber baru ini, pola guard sama persis FuelCard s417.
_currentLiter(vehicleId, fuelState) {
  if (typeof FuelStateEstimator !== 'undefined' && typeof FuelStateEstimator.estimateCurrentLiter === 'function') {
    const est = FuelStateEstimator.estimateCurrentLiter(vehicleId);
    if (est && est.ok && typeof est.liter === 'number') return est.liter;
  }
  return fuelState.currentFuelLiter;
},

// _applyAdjustments(value, vehicleId, kind) — EXTENSION POINT (requirement
// "Future Ready": weather/traffic/riding style/seasonal prediction).
// SENGAJA belum diimplementasikan sesi ini — selalu balikin `value` apa
// adanya (factor 1x, deterministik). `vehicleId`/`kind` ('distance'|
// 'nextRefuel'|'monthly'|'yearly') disediakan sbg parameter supaya sesi
// masa depan yang mengisi logic ini punya konteks tanpa perlu mengubah
// signature method publik mana pun di file ini.
_applyAdjustments(value, vehicleId, kind) {
  return value;
},

// predictRemainingDistance(vehicleId) — estimasi jarak tempuh tersisa
// (km) dari sisa BBM saat ini. 100% REUSE
// FuelGaugeEngine.estimateRemainingDistance() (yang sendiri REUSE
// FuelTankProfile.get() + fuelEfficiency() global) — 0 rumus km/L baru.
// Return: {ok:true, remainingKm, currentFuelLiter, kmPerLiter,
//   confidenceScore} kalau sukses. {ok:false, reason} kalau: kendaraan
//   tidak ditemukan, fuelState/currentFuelLiter belum ada (belum pernah
//   dikoreksi lewat FuelBarCorrection), FuelGaugeEngine belum dimuat,
//   profil tangki belum diatur, atau data efisiensi BBM belum cukup
//   (reason FuelGaugeEngine diteruskan apa adanya).
predictRemainingDistance(vehicleId) {
  const veh = this._vehicle(vehicleId);
  if (!veh) return { ok: false, reason: 'Kendaraan tidak ditemukan' };
  const fuelState = this._fuelState(vehicleId);
  if (!fuelState) return { ok: false, reason: 'Data BBM saat ini belum ada (lakukan Koreksi BBM dulu)' };
  if (typeof FuelGaugeEngine === 'undefined') return { ok: false, reason: 'FuelGaugeEngine belum dimuat' };
  const liter = this._currentLiter(vehicleId, fuelState);
  const dist = FuelGaugeEngine.estimateRemainingDistance(vehicleId, liter);
  if (!dist.ok) return dist;
  return {
    ok: true,
    remainingKm: this._applyAdjustments(dist.km, vehicleId, 'distance'),
    currentFuelLiter: liter,
    kmPerLiter: dist.kmPerLiter,
    confidenceScore: this._confidence(vehicleId, fuelState),
  };
},

// predictNextRefuel(vehicleId) — estimasi kapan (tanggal) & berapa hari
// lagi kendaraan perlu isi BBM lagi, dari sisa BBM DI ATAS ambang
// reserve (100% REUSE FuelGaugeEngine.getReserveStatus() utk
// literAboveReserve + FuelGaugeEngine.estimateRemainingDistance() utk
// konversi ke km) dibagi rata-rata jarak harian (100% REUSE
// fuelEfficiency().kmPerDay, yang sendiri REUSE estimateKmPerDay() dari
// histori D.kmLogs/D.bbmLogs) — 0 rumus baru.
// Return: {ok:true, estimatedDate, estimatedRemainingDays,
//   estimatedRemainingKm} kalau sukses — estimatedDate format ISO
//   (YYYY-MM-DD, via dateToISO() global SUDAH ADA), estimatedRemainingDays
//   dibulatkan ke atas (Math.ceil, minimal 0). {ok:false, reason} kalau:
//   kendaraan tidak ditemukan, fuel state belum ada, FuelGaugeEngine/
//   fuelEfficiency belum dimuat, profil tangki belum diatur, atau pola
//   berkendara harian belum cukup data (kmPerDay null/<=0).
predictNextRefuel(vehicleId) {
  const veh = this._vehicle(vehicleId);
  if (!veh) return { ok: false, reason: 'Kendaraan tidak ditemukan' };
  const fuelState = this._fuelState(vehicleId);
  if (!fuelState) return { ok: false, reason: 'Data BBM saat ini belum ada (lakukan Koreksi BBM dulu)' };
  if (typeof FuelGaugeEngine === 'undefined') return { ok: false, reason: 'FuelGaugeEngine belum dimuat' };
  const reserve = FuelGaugeEngine.getReserveStatus(vehicleId, this._currentLiter(vehicleId, fuelState));
  if (!reserve.ok) return reserve;
  const dist = FuelGaugeEngine.estimateRemainingDistance(vehicleId, reserve.literAboveReserve);
  if (!dist.ok) return dist;
  if (typeof fuelEfficiency !== 'function') return { ok: false, reason: 'fuelEfficiency belum dimuat' };
  const eff = fuelEfficiency(vehicleId);
  if (!eff.ok) return { ok: false, reason: eff.reason || 'Data pola berkendara belum cukup' };
  if (!eff.kmPerDay || eff.kmPerDay <= 0) {
    return { ok: false, reason: 'Pola berkendara harian belum cukup utk estimasi tanggal isi ulang' };
  }
  const remainingKm = this._applyAdjustments(dist.km, vehicleId, 'nextRefuel');
  const estimatedRemainingDays = Math.max(0, Math.ceil(remainingKm / eff.kmPerDay));
  let estimatedDate = null;
  if (typeof dateToISO === 'function') {
    const d = new Date();
    d.setHours(0, 0, 0, 0);
    d.setDate(d.getDate() + estimatedRemainingDays);
    estimatedDate = dateToISO(d);
  }
  return { ok: true, estimatedDate, estimatedRemainingDays, estimatedRemainingKm: remainingKm };
},

// predictMonthlyFuelUsage(vehicleId) — proyeksi pemakaian BBM (liter) &
// biaya (Rp) SEBULAN ke depan. 100% REUSE fuelEfficiency() global —
// field estMonthlyLiter/estMonthlyCost SUDAH dihitung di sana (asumsi
// 30 hari, pemakaian flat sesuai rata-rata histori), dipakai APA ADANYA
// di sini (requirement "Do NOT create duplicate calculations" — 0 rumus
// proyeksi bulanan baru ditulis ulang).
// Return: {ok:true, estimatedLiter, estimatedCost} kalau sukses —
//   estimatedLiter dibulatkan 2 desimal, estimatedCost dibulatkan
//   (Math.round). {ok:false, reason} kalau: kendaraan tidak ditemukan,
//   fuelEfficiency belum dimuat, data BBM (min. 2 log Isi Full Tank)
//   kurang, atau histori km/pola harian belum cukup (estMonthlyLiter/
//   estMonthlyCost masih null di fuelEfficiency()).
predictMonthlyFuelUsage(vehicleId) {
  const veh = this._vehicle(vehicleId);
  if (!veh) return { ok: false, reason: 'Kendaraan tidak ditemukan' };
  if (typeof fuelEfficiency !== 'function') return { ok: false, reason: 'fuelEfficiency belum dimuat' };
  const eff = fuelEfficiency(vehicleId);
  if (!eff.ok) return { ok: false, reason: eff.reason || 'Data BBM belum cukup' };
  if (eff.estMonthlyLiter == null || eff.estMonthlyCost == null) {
    return { ok: false, reason: 'Pola berkendara harian belum cukup utk proyeksi bulanan' };
  }
  return {
    ok: true,
    estimatedLiter: this._roundLiter(this._applyAdjustments(eff.estMonthlyLiter, vehicleId, 'monthly')),
    estimatedCost: Math.round(this._applyAdjustments(eff.estMonthlyCost, vehicleId, 'monthly')),
  };
},

// predictYearlyFuelUsage(vehicleId) — proyeksi pemakaian BBM (liter) &
// biaya (Rp) SETAHUN ke depan. 100% REUSE predictMonthlyFuelUsage() di
// atas (yang sendiri REUSE fuelEfficiency()) dikali 12 — TIDAK ada
// rumus tahunan independen (mis. dari kmPerDay*365 langsung), sengaja
// diturunkan dari proyeksi bulanan yang sama supaya angka bulanan x12
// SELALU konsisten dgn angka tahunan (0 kemungkinan 2 formula
// menyimpang), sesuai requirement "Do NOT create duplicate calculations".
// Return: {ok:true, estimatedLiter, estimatedCost} kalau sukses (liter
//   2 desimal, cost dibulatkan). {ok:false, reason} — sama persis
//   predictMonthlyFuelUsage() (diteruskan apa adanya).
predictYearlyFuelUsage(vehicleId) {
  const monthly = this.predictMonthlyFuelUsage(vehicleId);
  if (!monthly.ok) return monthly;
  return {
    ok: true,
    estimatedLiter: this._roundLiter(monthly.estimatedLiter * 12),
    estimatedCost: Math.round(monthly.estimatedCost * 12),
  };
},

};

// fuel-cost-analytics.js — Fuel Cost Analytics Engine (TASK-147).
//
// PRINSIP: engine-only, 0 UI, PURE (read-only, tidak pernah panggil save()
// atau menulis ke D/D.bbmLogs/D.vehicles). 100% REUSE modul fuel yang SUDAH
// ADA — 0 rumus km/L, Rp/km, atau proyeksi bulanan/tahunan baru dihitung
// ulang di sini:
//   - FuelStorage (TASK-141)         -> akses D.bbmLogs (histori transaksi
//                                        BBM) apa adanya, dipakai utk SUM
//                                        liter/cost per periode (bulan/
//                                        tahun/seluruh histori) & hitung
//                                        interval antar transaksi.
//   - fuelEfficiency() (vehicle-core.js, global SUDAH ADA)
//                                     -> kmPerLiter/rpPerKm/avgHarga
//                                        (dipakai APA ADANYA utk
//                                        costPerKm(), 0 recompute).
//   - FuelPredictionEngine (TASK-146) -> predictMonthlyFuelUsage()/
//                                        predictYearlyFuelUsage() (dipakai
//                                        APA ADANYA utk projectedMonthlyCost()/
//                                        projectedYearlyCost(), 0 recompute
//                                        proyeksi).
//   - D.vehicles[i].fuelState.confidenceScore (field additive TASK-144)
//                                     -> dibaca APA ADANYA (pola sama
//                                        persis FuelPredictionEngine._confidence()),
//                                        TIDAK PERNAH ditulis/diubah modul ini.
//   - Finance (D.bbmLogs[].cost, field yang sudah ditulis tx-bbm.js)
//                                     -> dibaca apa adanya, 0 field baru
//                                        ditambahkan ke D, 0 transaksi
//                                        dimodifikasi.
//
// TIDAK disentuh sama sekali (sesuai batasan task): FuelGaugeEngine,
// FuelPredictionEngine (logic), FuelTankProfile, D.bbmLogs (data),
// D.vehicles (data), business logic modul fuel-* lain mana pun.
//
// LOGIC BARU sesi ini (sesuai requirement task, bukan duplikasi formula
// existing): agregasi SUM liter/cost D.bbmLogs (via FuelStorage) per
// bulan-berjalan/tahun-berjalan/seluruh histori (murni penjumlahan field
// yang sudah ada, pola sama persis VehicleTrendAPI.monthlyCostTrend() Sesi
// 81 — bukan rumus konsumsi/efisiensi baru), dan hitung interval hari
// antar transaksi BBM berurutan (refillFrequency()).
//
// FUTURE READY: shape return tiap method HANYA menambah field baru di masa
// depan (Fuel Inflation Trend/Fuel Price Comparison/Fuel Station
// Analytics/Province-City Comparison/AI Recommendations bisa jadi method
// BARU di objek ini tanpa mengubah method yang sudah ada) — TIDAK ada
// method existing yang perlu diubah shape-nya utk mendukung fitur di atas.
//
// KONTRAK ERROR: semua method publik balikin {ok:false, reason} kalau
// gagal (kendaraan tidak ditemukan, dependency belum dimuat, histori BBM
// kurang/kosong) — TIDAK PERNAH throw.
const FuelCostAnalytics = {

// _vehicles()/_vehicle(vehicleId) — pola SAMA PERSIS FuelPredictionEngine/
// FuelTankProfile/VehicleIntelligence dkk: baca D.vehicles apa adanya
// lewat guard typeof, cari 1 kendaraan by id.
_vehicles() {
  return (typeof D !== 'undefined' && D.vehicles) ? D.vehicles : [];
},
_vehicle(vehicleId) {
  return this._vehicles().find((v) => v.id === vehicleId) || null;
},

// _roundLiter(n)/_roundCost(n) — presisi pembulatan output publik, pola
// SAMA PERSIS FuelPredictionEngine._roundLiter() (2 desimal utk liter,
// dibulatkan penuh utk Rupiah).
_roundLiter(n) {
  return Math.round(n * 100) / 100;
},
_roundCost(n) {
  return Math.round(n);
},

// _validLogs(vehicleId) — 100% REUSE FuelStorage.logs() (TASK-141) utk
// baca D.bbmLogs, difilter ke baris yang punya date/liter/cost valid
// (liter>0, cost>0) — TIDAK ada transformasi/field baru, cuma guard data
// kotor (mis. log lama tanpa cost) supaya tidak merusak SUM.
_validLogs(vehicleId) {
  if (typeof FuelStorage === 'undefined') return null;
  return FuelStorage.logs(vehicleId).filter((b) => (
    typeof b.date === 'string' && b.date.length >= 7 && b.liter > 0 && b.cost > 0
  ));
},

// _confidenceScore(vehicleId) — SESI 5 (FUEL-AUTOSYNC-08, confidence
// decay dinamis, pola SAMA PERSIS FuelPredictionEngine._confidence()):
// 100% REUSE FuelStateEstimator.estimateCurrentLiter().
// decayedConfidenceScore (BARU) kalau tersedia & ok:true. Fallback ke
// D.vehicles[i].fuelState.confidenceScore APA ADANYA (ditulis
// FuelBarCorrection.save(), TASK-144, pola lama) kalau FuelStateEstimator
// belum dimuat ATAU estimator ok:false — null kalau kedua sumber tidak
// tersedia, 0 rumus confidence baru dihitung di sini.
_confidenceScore(vehicleId) {
  if (typeof FuelStateEstimator !== 'undefined' && typeof FuelStateEstimator.estimateCurrentLiter === 'function') {
    const est = FuelStateEstimator.estimateCurrentLiter(vehicleId);
    if (est && est.ok && typeof est.decayedConfidenceScore === 'number') return est.decayedConfidenceScore;
  }
  const veh = this._vehicle(vehicleId);
  const fs = veh && veh.fuelState;
  return (fs && typeof fs.confidenceScore === 'number') ? fs.confidenceScore : null;
},

// monthlyCost(vehicleId) — total liter/biaya/rata-rata harga BBM BULAN
// BERJALAN (kalender, bukan 30 hari mundur), dari SUM D.bbmLogs[].liter/
// cost via FuelStorage — 0 rumus km/L/Rp-per-km/proyeksi (beda dari
// fuelEfficiency()/FuelPredictionEngine yang MEMPREDIKSI masa depan — ini
// murni HISTORI transaksi aktual bulan ini).
// Return: {ok:true, month('YYYY-MM'), totalLiter, totalCost, averagePrice}
//   kalau ada minimal 1 transaksi valid bulan ini. {ok:false, reason}
//   kalau: kendaraan tidak ditemukan, FuelStorage belum dimuat, atau
//   belum ada transaksi BBM valid bulan ini.
monthlyCost(vehicleId) {
  const veh = this._vehicle(vehicleId);
  if (!veh) return { ok: false, reason: 'Kendaraan tidak ditemukan' };
  const logs = this._validLogs(vehicleId);
  if (logs === null) return { ok: false, reason: 'FuelStorage belum dimuat' };
  const now = new Date();
  const month = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0');
  const rows = logs.filter((b) => b.date.slice(0, 7) === month);
  if (!rows.length) return { ok: false, reason: 'Belum ada transaksi BBM bulan ini' };
  const totalLiter = this._roundLiter(rows.reduce((s, b) => s + b.liter, 0));
  const totalCost = this._roundCost(rows.reduce((s, b) => s + b.cost, 0));
  return { ok: true, month, totalLiter, totalCost, averagePrice: this._roundCost(totalCost / totalLiter) };
},

// yearlyCost(vehicleId) — sama persis monthlyCost() di atas, cuma
// dikelompokkan per TAHUN kalender berjalan (bukan bulan) — pola
// agregasi identik, 0 rumus baru.
// Return: {ok:true, year('YYYY'), totalLiter, totalCost, averagePrice}
//   / {ok:false, reason} (sama persis monthlyCost(), diteruskan apa
//   adanya kecuali pesan "tahun ini").
yearlyCost(vehicleId) {
  const veh = this._vehicle(vehicleId);
  if (!veh) return { ok: false, reason: 'Kendaraan tidak ditemukan' };
  const logs = this._validLogs(vehicleId);
  if (logs === null) return { ok: false, reason: 'FuelStorage belum dimuat' };
  const year = String(new Date().getFullYear());
  const rows = logs.filter((b) => b.date.slice(0, 4) === year);
  if (!rows.length) return { ok: false, reason: 'Belum ada transaksi BBM tahun ini' };
  const totalLiter = this._roundLiter(rows.reduce((s, b) => s + b.liter, 0));
  const totalCost = this._roundCost(rows.reduce((s, b) => s + b.cost, 0));
  return { ok: true, year, totalLiter, totalCost, averagePrice: this._roundCost(totalCost / totalLiter) };
},

// costPerKm(vehicleId) — 100% REUSE fuelEfficiency() global (vehicle-core.js)
// — rpPerKm/kmPerLiter/avgHarga SUDAH dihitung di sana (via
// estimateRpPerKm(), butuh min. 2 log "Isi Full Tank" dgn km naik),
// dipakai APA ADANYA — 0 rumus km/L atau Rp/km baru ditulis ulang.
// Return: {ok:true, costPerKm, kmPerLiter, averageFuelPrice} kalau
//   fuelEfficiency() sukses. {ok:false, reason} kalau: kendaraan tidak
//   ditemukan, fuelEfficiency belum dimuat, atau data BBM/histori km
//   kurang (reason fuelEfficiency() diteruskan apa adanya).
costPerKm(vehicleId) {
  const veh = this._vehicle(vehicleId);
  if (!veh) return { ok: false, reason: 'Kendaraan tidak ditemukan' };
  if (typeof fuelEfficiency !== 'function') return { ok: false, reason: 'fuelEfficiency belum dimuat' };
  const eff = fuelEfficiency(vehicleId);
  if (!eff.ok) return { ok: false, reason: eff.reason || 'Data BBM belum cukup' };
  return { ok: true, costPerKm: eff.rpPerKm, kmPerLiter: eff.kmPerLiter, averageFuelPrice: eff.avgHarga };
},

// averageFuelPrice(vehicleId) — rata-rata harga BBM (Rp/liter) TERTIMBANG
// (totalCost/totalLiter) dari SELURUH histori transaksi valid kendaraan
// ini (via FuelStorage) — beda cakupan dari avgHarga di costPerKm()
// (yang cuma 10 log terakhir, dari estimateRpPerKm() vehicle-core.js);
// di sini SEMUA transaksi dihitung, 0 batas N — tetap 0 rumus km/L/Rp-
// per-km baru, murni SUM liter & cost yang sudah ada.
// Return: {ok:true, averagePrice, totalLiter, transactionCount} kalau
//   ada minimal 1 transaksi valid. {ok:false, reason} kalau: kendaraan
//   tidak ditemukan, FuelStorage belum dimuat, atau belum ada transaksi
//   BBM valid sama sekali.
averageFuelPrice(vehicleId) {
  const veh = this._vehicle(vehicleId);
  if (!veh) return { ok: false, reason: 'Kendaraan tidak ditemukan' };
  const logs = this._validLogs(vehicleId);
  if (logs === null) return { ok: false, reason: 'FuelStorage belum dimuat' };
  if (!logs.length) return { ok: false, reason: 'Belum ada transaksi BBM' };
  const totalLiter = this._roundLiter(logs.reduce((s, b) => s + b.liter, 0));
  const totalCost = logs.reduce((s, b) => s + b.cost, 0);
  return { ok: true, averagePrice: this._roundCost(totalCost / totalLiter), totalLiter, transactionCount: logs.length };
},

// projectedMonthlyCost(vehicleId) — 100% REUSE
// FuelPredictionEngine.predictMonthlyFuelUsage() (TASK-146, yang sendiri
// REUSE fuelEfficiency().estMonthlyLiter/estMonthlyCost) — 0 rumus
// proyeksi baru. confidenceScore ditambahkan dari D.vehicles[i].fuelState
// (dibaca apa adanya, sama seperti FuelPredictionEngine sendiri
// membacanya) — bukan bagian shape return predictMonthlyFuelUsage(),
// jadi disatukan di sini sesuai kebutuhan API task.
// Return: {ok:true, estimatedCost, estimatedLiter, confidenceScore}
//   kalau sukses. {ok:false, reason} — diteruskan apa adanya dari
//   FuelPredictionEngine.predictMonthlyFuelUsage() (kendaraan tidak
//   ditemukan, fuelEfficiency belum dimuat, atau data BBM/pola harian
//   belum cukup).
projectedMonthlyCost(vehicleId) {
  if (typeof FuelPredictionEngine === 'undefined') return { ok: false, reason: 'FuelPredictionEngine belum dimuat' };
  const pred = FuelPredictionEngine.predictMonthlyFuelUsage(vehicleId);
  if (!pred.ok) return pred;
  return {
    ok: true,
    estimatedCost: pred.estimatedCost,
    estimatedLiter: pred.estimatedLiter,
    confidenceScore: this._confidenceScore(vehicleId),
  };
},

// projectedYearlyCost(vehicleId) — 100% REUSE
// FuelPredictionEngine.predictYearlyFuelUsage() (TASK-146, yang sendiri
// REUSE predictMonthlyFuelUsage() x12 — supaya bulanan x12 SELALU
// konsisten dgn tahunan, 0 formula tahunan independen) — pola sama
// persis projectedMonthlyCost() di atas, ditambah confidenceScore.
// Return: {ok:true, estimatedCost, estimatedLiter, confidenceScore} /
//   {ok:false, reason} (sama persis projectedMonthlyCost(), diteruskan
//   apa adanya).
projectedYearlyCost(vehicleId) {
  if (typeof FuelPredictionEngine === 'undefined') return { ok: false, reason: 'FuelPredictionEngine belum dimuat' };
  const pred = FuelPredictionEngine.predictYearlyFuelUsage(vehicleId);
  if (!pred.ok) return pred;
  return {
    ok: true,
    estimatedCost: pred.estimatedCost,
    estimatedLiter: pred.estimatedLiter,
    confidenceScore: this._confidenceScore(vehicleId),
  };
},

// refillFrequency(vehicleId) — jumlah transaksi isi BBM & rata-rata
// interval hari antar transaksi berurutan (histori penuh, via
// FuelStorage) — LOGIC BARU (bukan rumus km/L/Rp-per-km/proyeksi yang
// sudah ada di modul lain), murni selisih tanggal antar transaksi
// berurutan yang sudah tercatat. Dipakai internal (§ ANALYTICS "Refill
// frequency"/"Average interval between refills" di spesifikasi task) &
// diekspos publik supaya bisa dipakai presenter/AI recommendation masa
// depan tanpa recompute.
// Return: {ok:true, refillCount, averageIntervalDays} kalau ada minimal
//   2 transaksi bertanggal valid dgn urutan waktu naik. {ok:false, reason}
//   kalau: kendaraan tidak ditemukan, FuelStorage belum dimuat, transaksi
//   <2, atau seluruh transaksi bertanggal sama (0 interval terukur).
refillFrequency(vehicleId) {
  const veh = this._vehicle(vehicleId);
  if (!veh) return { ok: false, reason: 'Kendaraan tidak ditemukan' };
  const logs = this._validLogs(vehicleId);
  if (logs === null) return { ok: false, reason: 'FuelStorage belum dimuat' };
  if (logs.length < 2) return { ok: false, reason: 'Data BBM belum cukup (butuh minimal 2 transaksi)' };
  const asc = logs.slice().sort((a, b) => (a.date < b.date ? -1 : (a.date > b.date ? 1 : 0)));
  let totalDays = 0;
  let gaps = 0;
  for (let i = 1; i < asc.length; i++) {
    const days = (new Date(asc[i].date) - new Date(asc[i - 1].date)) / 86400000;
    if (days > 0) { totalDays += days; gaps++; }
  }
  if (!gaps) return { ok: false, reason: 'Interval tanggal antar transaksi belum cukup utk dihitung' };
  return { ok: true, refillCount: logs.length, averageIntervalDays: Math.round((totalDays / gaps) * 10) / 10 };
},

};

// fuel-maintenance-engine.js — Fuel Maintenance Intelligence Engine (TASK-148).
//
// PRINSIP: engine-only, 0 UI, PURE (read-only, tidak pernah panggil save()
// atau menulis ke D). 100% REUSE modul & fungsi yang SUDAH ADA — 0 rumus
// km/L, Rp/km, servis-jatuh-tempo, atau proyeksi baru dihitung ulang:
//   - FuelCostAnalytics (TASK-147)    -> costPerKm() (yang sendiri REUSE
//                                        fuelEfficiency()) dipakai APA
//                                        ADANYA utk baca kmPerLiter/rpPerKm
//                                        saat ini.
//   - fuelEfficiency() (vehicle-core.js, global SUDAH ADA)
//                                     -> dipakai lewat FuelCostAnalytics.costPerKm(),
//                                        TIDAK dipanggil dobel di sini.
//   - predictService({vehicleId}) (sparepart-servis.js, global SUDAH ADA)
//                                     -> "Vehicle Service History" — status
//                                        jatuh tempo tiap kategori sparepart
//                                        (lewat/segera/aman), dari
//                                        getEffectiveIntervalKm()/
//                                        getLastServiceKmForCat() yang
//                                        SUDAH ADA — dipakai APA ADANYA,
//                                        0 rumus interval baru.
//   - _vehicleFuelEfficiencyDropCheck() (sparepart-servis.js, global SUDAH
//     ADA, dipakai rule AI 'vehicle-fuel-efficiency-drop')
//                                     -> deteksi "Fuel efficiency
//                                        degradation" (drop km/L segmen
//                                        terakhir vs rata-rata segmen
//                                        sebelumnya) — SATU-SATUNYA logic
//                                        degradasi yang sudah ada di
//                                        project ini, dipakai APA ADANYA
//                                        (difilter ke 1 kendaraan), 0
//                                        rumus deteksi drop baru ditulis
//                                        ulang.
//   - findVehicleSpec() (sparepart-servis.js, global SUDAH ADA)
//                                     -> referensi statis tekanan ban
//                                        pabrikan (VEHICLE_SPEC_DB.ban) —
//                                        "Tire pressure (if available)":
//                                        TIDAK ADA histori tekanan ban
//                                        aktual tersimpan di app manapun
//                                        (0 storage baru dibuat sesuai
//                                        larangan task), jadi field ini
//                                        SELALU berupa referensi statis
//                                        (bukan bacaan real-time), null
//                                        kalau kendaraan tidak dikenali
//                                        katalognya.
//   - D.vehicles[i].name (Vehicle Profile, dibaca apa adanya)
//                                     -> dipakai findVehicleSpec() utk
//                                        cocokkan katalog.
//
// TIDAK disentuh sama sekali (sesuai batasan task): FuelGaugeEngine,
// FuelPredictionEngine, FuelCostAnalytics, FuelTankProfile (logic),
// D.bbmLogs/D.servisLogs/D.vehicles/D.sparepartCats (data), business
// logic modul fuel-*/sparepart-servis.js mana pun. 0 storage baru dibuat
// (larangan task eksplisit) — TIDAK ADA field tekanan-ban-aktual/histori
// baru ditambahkan ke D dgn alasan apa pun.
//
// LOGIC BARU sesi ini (sesuai requirement task, bukan duplikasi formula
// existing): KORELASI antara status jatuh tempo servis (predictService())
// dgn penurunan efisiensi BBM (_vehicleFuelEfficiencyDropCheck()) —
// mapping kategori sparepart yang relevan ke konsumsi BBM (oli mesin,
// saringan udara, busi, CVT/v-belt) via keyword match nama kategori (bukan
// rumus baru, murni pencocokan string), lalu menyusun rekomendasi & level
// risiko dari kombinasi kedua sinyal yang SUDAH ADA tsb.
//
// KONTRAK ERROR: semua method publik balikin {ok:false, reason} kalau
// gagal (kendaraan tidak ditemukan, dependency wajib belum dimuat, data
// BBM/servis belum cukup) — TIDAK PERNAH throw.
const FuelMaintenanceEngine = {

// KEYWORD_GROUPS — pemetaan kategori sparepart (D.sparepartCats[].name,
// dibaca apa adanya via predictService()) ke jenis part yang relevan
// dengan efisiensi BBM (§ ANALYSIS task: "Oil change overdue"/"Air
// filter"/"Spark plug"/"CVT"). Murni daftar kata kunci pencocokan nama
// (case-insensitive substring), BUKAN kategori/storage baru — kategori
// aslinya tetap 100% D.sparepartCats milik user, tidak diubah/ditambah.
KEYWORD_GROUPS: {
  oil: ['oli mesin', 'oli', 'oil'],
  airFilter: ['saringan udara', 'filter udara', 'air filter'],
  sparkPlug: ['busi', 'spark plug'],
  cvt: ['cvt', 'v-belt', 'vbelt', 'drive belt', 'van belt', 'fanbelt'],
},

// _vehicles()/_vehicle(vehicleId) — pola SAMA PERSIS FuelCostAnalytics/
// FuelPredictionEngine dkk: baca D.vehicles apa adanya lewat guard
// typeof, cari 1 kendaraan by id.
_vehicles() {
  return (typeof D !== 'undefined' && D.vehicles) ? D.vehicles : [];
},
_vehicle(vehicleId) {
  return this._vehicles().find((v) => v.id === vehicleId) || null;
},

// _serviceStatus(vehicleId) — 100% REUSE predictService() global
// (sparepart-servis.js, "Vehicle Service History") — null kalau fungsi
// belum dimuat (dependency wajib hilang, caller publik menerjemahkan
// jadi {ok:false, reason}).
_serviceStatus(vehicleId) {
  if (typeof predictService !== 'function') return null;
  return predictService({ vehicleId });
},

// _dropInfo(vehicleId) — 100% REUSE _vehicleFuelEfficiencyDropCheck()
// global (sparepart-servis.js, SATU-SATUNYA logic "Fuel efficiency
// degradation" yang sudah ada di project ini — dipakai rule AI
// 'vehicle-fuel-efficiency-drop'), difilter ke 1 kendaraan. null kalau
// fungsi belum dimuat ATAU kendaraan ini tidak masuk daftar drops (belum
// cukup data histori/tidak ada penurunan terdeteksi) — caller
// membedakan "tidak terdeteksi" (degradationDetected:false) dari
// "dependency hilang" lewat guard terpisah di method publik.
_dropInfo(vehicleId) {
  if (typeof _vehicleFuelEfficiencyDropCheck !== 'function') return null;
  const res = _vehicleFuelEfficiencyDropCheck();
  if (!res || !Array.isArray(res.drops)) return null;
  const found = res.drops.find((d) => d.vehicleId === vehicleId);
  return found ? Object.assign({ thresholdPct: res.thresholdPct }, found) : null;
},

// _tirePressureRef(veh) — "Tire pressure (if available)": TIDAK ADA
// histori tekanan ban aktual tersimpan di aplikasi mana pun (0 storage
// baru dibuat, sesuai larangan task) — satu-satunya data yang bisa
// dipakai adalah referensi STATIS pabrikan (VEHICLE_SPEC_DB.ban, via
// findVehicleSpec() global SUDAH ADA), bukan bacaan real-time. null
// kalau findVehicleSpec() belum dimuat ATAU kendaraan tidak match
// katalog (motor tidak dikenali).
_tirePressureRef(veh) {
  if (!veh || typeof findVehicleSpec !== 'function') return null;
  const spec = findVehicleSpec(veh.name);
  return (spec && spec.ban) ? spec.ban : null;
},

// _partsForItem(items) — mapping keyword (di atas) ke item predictService()
// yang statusnya BUKAN 'aman' (butuh perhatian: 'lewat' atau 'segera') —
// murni filter+cocokkan string nama kategori yang SUDAH ADA, 0 rumus
// interval/jatuh-tempo baru (status itu sendiri dari predictService()).
_relevantOverdueItems(items) {
  if (!Array.isArray(items)) return [];
  const out = [];
  Object.keys(this.KEYWORD_GROUPS).forEach((part) => {
    const keywords = this.KEYWORD_GROUPS[part];
    items.forEach((it) => {
      const name = (it.categoryName || '').toLowerCase();
      if (it.status !== 'aman' && keywords.some((k) => name.includes(k))) {
        out.push(Object.assign({ part }, it));
      }
    });
  });
  return out;
},

// maintenanceImpact(vehicleId) — korelasi status efisiensi BBM saat ini
// (reuse FuelCostAnalytics.costPerKm(), yang sendiri reuse
// fuelEfficiency()) dgn item perawatan yang jatuh tempo/mendekati jatuh
// tempo DAN relevan dgn konsumsi BBM (oli/saringan udara/busi/CVT, via
// keyword match predictService().items) + referensi tekanan ban statis
// (kalau kendaraan dikenali katalog) + jumlah TOTAL kategori servis
// lewat jatuh tempo (bukan cuma yang relevan BBM — sinyal "Service
// interval" umum).
// Return: {ok:true, vehicleId, kmPerLiter, costPerKm, overdueItems[],
//   hasMaintenanceImpact, serviceIntervalOverdueCount, tirePressureRef}
//   kalau sukses. {ok:false, reason} kalau: kendaraan tidak ditemukan,
//   FuelCostAnalytics belum dimuat, data efisiensi BBM belum cukup, atau
//   predictService()/D.sparepartCats belum ada.
maintenanceImpact(vehicleId) {
  const veh = this._vehicle(vehicleId);
  if (!veh) return { ok: false, reason: 'Kendaraan tidak ditemukan' };
  if (typeof FuelCostAnalytics === 'undefined') return { ok: false, reason: 'FuelCostAnalytics belum dimuat' };
  const costPerKm = FuelCostAnalytics.costPerKm(vehicleId);
  if (!costPerKm.ok) return { ok: false, reason: costPerKm.reason || 'Data efisiensi BBM belum cukup' };
  const svc = this._serviceStatus(vehicleId);
  if (!svc) return { ok: false, reason: 'predictService belum dimuat' };
  if (!svc.ok) return { ok: false, reason: svc.reason || 'Belum ada kategori sparepart terdaftar' };
  const overdueItems = this._relevantOverdueItems(svc.items);
  const serviceIntervalOverdueCount = svc.items.filter((it) => it.status === 'lewat').length;
  return {
    ok: true,
    vehicleId,
    kmPerLiter: costPerKm.kmPerLiter,
    costPerKm: costPerKm.costPerKm,
    overdueItems,
    hasMaintenanceImpact: overdueItems.length > 0,
    serviceIntervalOverdueCount,
    tirePressureRef: this._tirePressureRef(veh),
  };
},

// fuelEfficiencyHealth(vehicleId) — status kesehatan efisiensi BBM saat
// ini: kmPerLiter/rpPerKm (100% reuse fuelEfficiency() global) + apakah
// terdeteksi PENURUNAN (100% reuse _vehicleFuelEfficiencyDropCheck()
// global, difilter ke kendaraan ini) — 0 rumus baru.
// Return: {ok:true, vehicleId, kmPerLiter, rpPerKm, degradationDetected,
//   dropPct, thresholdPct, status:'menurun'|'baik'} kalau
//   fuelEfficiency() sukses (degradationDetected tetap bisa false/null
//   kalau _vehicleFuelEfficiencyDropCheck() belum dimuat/histori segmen
//   kurang — TIDAK dianggap gagal total, cuma sinyal tambahan yang
//   belum tersedia). {ok:false, reason} kalau: kendaraan tidak
//   ditemukan, fuelEfficiency belum dimuat, atau data BBM/histori km
//   kurang (reason fuelEfficiency() diteruskan apa adanya).
fuelEfficiencyHealth(vehicleId) {
  const veh = this._vehicle(vehicleId);
  if (!veh) return { ok: false, reason: 'Kendaraan tidak ditemukan' };
  if (typeof fuelEfficiency !== 'function') return { ok: false, reason: 'fuelEfficiency belum dimuat' };
  const eff = fuelEfficiency(vehicleId);
  if (!eff.ok) return { ok: false, reason: eff.reason || 'Data BBM belum cukup' };
  const drop = this._dropInfo(vehicleId);
  const degradationDetected = !!drop;
  return {
    ok: true,
    vehicleId,
    kmPerLiter: eff.kmPerLiter,
    rpPerKm: eff.rpPerKm,
    degradationDetected,
    dropPct: drop ? drop.dropPct : null,
    thresholdPct: drop ? drop.thresholdPct : null,
    status: degradationDetected ? 'menurun' : 'baik',
  };
},

// maintenanceRecommendation(vehicleId) — gabungkan maintenanceImpact() +
// fuelEfficiencyHealth() (keduanya 100% reuse, lihat di atas) jadi
// daftar rekomendasi teks siap tampil — LOGIC BARU (penyusunan kalimat
// dari data yang sudah dihitung kedua method di atas), 0 rumus
// efisiensi/servis baru.
// Return: {ok:true, vehicleId, recommendations[](string),
//   hasMaintenanceImpact, degradationDetected} kalau kedua dependency
//   di atas sukses. {ok:false, reason} — diteruskan dari
//   maintenanceImpact() (kendaraan tidak ditemukan, dependency wajib
//   hilang, atau data belum cukup); fuelEfficiencyHealth() TIDAK
//   memblokir hasil kalau gagal (recommendation tetap dikirim dari sisi
//   maintenance-nya saja, dengan degradationDetected:null).
maintenanceRecommendation(vehicleId) {
  const impact = this.maintenanceImpact(vehicleId);
  if (!impact.ok) return impact;
  const health = this.fuelEfficiencyHealth(vehicleId);
  const recommendations = [];
  impact.overdueItems.forEach((it) => {
    const detail = (it.status === 'lewat')
      ? `sudah lewat ${Math.abs(Math.round(it.sisaKm))} km dari jadwal`
      : `tersisa ${Math.round(it.sisaKm)} km lagi`;
    recommendations.push(`Cek/servis "${it.categoryName}" — ${detail}, berpotensi memengaruhi konsumsi BBM.`);
  });
  const degradationDetected = health.ok ? health.degradationDetected : null;
  if (degradationDetected && !impact.hasMaintenanceImpact) {
    recommendations.push('Konsumsi BBM turun tapi tidak ada jadwal servis (oli/saringan udara/busi/CVT) yang lewat — cek tekanan ban & kebiasaan berkendara (histori tekanan ban belum tersedia di aplikasi).');
  }
  if (!recommendations.length) {
    recommendations.push('Tidak ada indikasi masalah perawatan yang memengaruhi efisiensi BBM saat ini.');
  }
  return {
    ok: true,
    vehicleId,
    recommendations,
    hasMaintenanceImpact: impact.hasMaintenanceImpact,
    degradationDetected,
  };
},

// maintenanceRisk(vehicleId) — level risiko gabungan dari jumlah item
// servis lewat jatuh tempo yang relevan BBM (maintenanceImpact()) +
// status degradasi efisiensi (fuelEfficiencyHealth()) — LOGIC BARU
// (aturan gabungan 2 sinyal yang sudah ada), 0 rumus efisiensi/servis
// baru.
// Return: {ok:true, vehicleId, riskLevel:'tinggi'|'sedang'|'rendah',
//   overdueCount, overdueLewatCount, degradationDetected}. {ok:false,
//   reason} — diteruskan dari maintenanceImpact().
maintenanceRisk(vehicleId) {
  const impact = this.maintenanceImpact(vehicleId);
  if (!impact.ok) return impact;
  const health = this.fuelEfficiencyHealth(vehicleId);
  const degradationDetected = health.ok ? health.degradationDetected : false;
  const overdueLewatCount = impact.overdueItems.filter((it) => it.status === 'lewat').length;
  let riskLevel = 'rendah';
  if (overdueLewatCount > 0 && degradationDetected) riskLevel = 'tinggi';
  else if (overdueLewatCount > 0 || degradationDetected) riskLevel = 'sedang';
  return {
    ok: true,
    vehicleId,
    riskLevel,
    overdueCount: impact.overdueItems.length,
    overdueLewatCount,
    degradationDetected,
  };
},

};

// fuel-insight-engine.js — Fuel Insight Engine (TASK-149; diperluas
// TASK-150A "Expand FuelInsightEngine Summary API").
//
// PRINSIP: engine-only, 0 UI, PURE (read-only, tidak pernah panggil save()
// atau menulis ke D). 100% REUSE SELURUH engine fuel yang SUDAH ADA — 0
// rumus bar/liter/persen/km-L/Rp-per-km/interval servis/degradasi/proyeksi
// baru dihitung ulang di sini:
//   - FuelGaugeEngine (TASK-143)      -> getReserveStatus() utk status
//                                        cadangan (reserve) BBM saat ini,
//                                        + (TASK-150A) calculateFuelBar()/
//                                        calculateFuelPercent() utk field
//                                        `fuel` di getSummary() — dari
//                                        D.vehicles[i].fuelState.
//                                        currentFuelLiter (dibaca APA
//                                        ADANYA, pola sama persis
//                                        FuelPredictionEngine._fuelState()).
//   - FuelPredictionEngine (TASK-146) -> predictRemainingDistance()/
//                                        predictNextRefuel()/
//                                        predictMonthlyFuelUsage()/
//                                        predictYearlyFuelUsage() dipakai
//                                        APA ADANYA.
//   - FuelCostAnalytics (TASK-147)    -> costPerKm()/monthlyCost()/
//                                        projectedMonthlyCost() dipakai
//                                        APA ADANYA.
//   - FuelMaintenanceEngine (TASK-148) -> fuelEfficiencyHealth()/
//                                        maintenanceRisk()/
//                                        maintenanceRecommendation()
//                                        dipakai APA ADANYA.
//   - FuelTankProfile (TASK-150A)     -> get().fuelBarCount DIBACA APA
//                                        ADANYA (bukan dihitung) utk field
//                                        `fuel.maxBar` — satu-satunya
//                                        tempat fuelBarCount tersimpan,
//                                        tidak diekspos engine lain.
//   - fuelEfficiency() -> TIDAK dipanggil LANGSUNG di sini (sudah 100%
//     dibungkus lewat engine di atas) — disebut di daftar Reuse task krn
//     merupakan dependency transitif engine-engine di atas.
//
// TIDAK disentuh sama sekali (sesuai batasan task): FuelGaugeEngine,
// FuelPredictionEngine, FuelCostAnalytics, FuelMaintenanceEngine,
// FuelTankProfile, fuelEfficiency() (logic-nya masing-masing), D.bbmLogs/
// D.servisLogs/D.vehicles/D.sparepartCats (data). 0 storage baru dibuat,
// 0 UI diubah.
//
// LOGIC BARU sesi ini (sesuai requirement task, bukan duplikasi formula
// existing): (1) MENYUSUN daftar "insight" siap tampil dari hasil engine-
// engine di atas (judul/deskripsi/rekomendasi/prioritas per insight,
// murni penyusunan teks & mapping level prioritas dari nilai yang SUDAH
// dihitung, 0 rumus baru); (2) MENGURUTKAN insight berdasarkan prioritas
// (CRITICAL -> HIGH -> MEDIUM -> LOW -> INFO); (3) SKOR RINGKASAN
// (healthScore/efficiencyScore) — komposisi rule-based sederhana dari
// sinyal yang SUDAH ADA (fuelEfficiencyHealth().dropPct,
// maintenanceRisk().riskLevel), pola sama persis FuelMaintenanceEngine.
// maintenanceRisk() yang juga menggabungkan 2 sinyal existing jadi 1
// level baru — BUKAN rumus km/L/Rp-per-km/servis/degradasi baru.
//
// KONTRAK ERROR: getInsights()/getSummary() balikin {ok:false, reason}
// HANYA kalau kendaraan tidak ditemukan — TIDAK PERNAH throw. Kalau
// kendaraan valid tapi sebagian/semua engine dependency belum dimuat atau
// datanya belum cukup (profil tangki belum diatur, histori BBM kosong,
// dst), insight/field terkait itu saja yang dilewati (insight tidak
// dimasukkan ke array / field summary bernilai null) — TIDAK memblokir
// insight/field lain yang datanya tersedia.
const FuelInsightEngine = {

// _vehicles()/_vehicle(vehicleId) — pola SAMA PERSIS FuelCostAnalytics/
// FuelPredictionEngine/FuelMaintenanceEngine dkk: baca D.vehicles apa
// adanya lewat guard typeof, cari 1 kendaraan by id.
_vehicles() {
  return (typeof D !== 'undefined' && D.vehicles) ? D.vehicles : [];
},
_vehicle(vehicleId) {
  return this._vehicles().find((v) => v.id === vehicleId) || null;
},

// _currentFuelLiter(vehicleId) — SESI 4 (FUEL-AUTOSYNC-07, lanjutan
// rencana "Fuel Estimation Auto-Update", selaras FuelCard._liveEstimate()
// s417 & FuelPredictionEngine._currentLiter() sesi ini): 100% REUSE
// FuelStateEstimator.estimateCurrentLiter() (s415) kalau tersedia &
// ok:true — balikin liter TERKINI (dihitung ulang dari akumulasi km
// sejak titik acuan SETIAP dipanggil), bukan snapshot beku
// fuelState.currentFuelLiter. Fallback ke D.vehicles[i].fuelState.
// currentFuelLiter APA ADANYA (field additive TASK-144, pola lama) kalau
// FuelStateEstimator belum dimuat ATAU estimator ok:false (mis. belum
// ada titik acuan sama sekali) — null kalau kedua sumber tidak tersedia.
// Dipakai HANYA sbg input parameter FuelGaugeEngine.getReserveStatus()/
// calculateFuelBar()/calculateFuelPercent() (yang wajib terima liter) —
// bukan hasil hitungan baru di sini.
_currentFuelLiter(vehicleId) {
  if (typeof FuelStateEstimator !== 'undefined' && typeof FuelStateEstimator.estimateCurrentLiter === 'function') {
    const est = FuelStateEstimator.estimateCurrentLiter(vehicleId);
    if (est && est.ok && typeof est.liter === 'number') return est.liter;
  }
  const veh = this._vehicle(vehicleId);
  const fs = veh && veh.fuelState;
  if (!fs || typeof fs.currentFuelLiter !== 'number' || !isFinite(fs.currentFuelLiter)) return null;
  return fs.currentFuelLiter;
},

// PRIORITY_ORDER — urutan tampil insight (index lebih kecil = lebih
// prioritas). Dipakai _sortByPriority().
PRIORITY_ORDER: { CRITICAL: 0, HIGH: 1, MEDIUM: 2, LOW: 3, INFO: 4 },

// _sortByPriority(insights) — urutkan array insight menaik berdasarkan
// PRIORITY_ORDER (CRITICAL dulu, INFO terakhir). Tidak mengubah array
// asli (slice() dulu).
_sortByPriority(insights) {
  const order = this.PRIORITY_ORDER;
  return insights.slice().sort((a, b) => order[a.priority] - order[b.priority]);
},

// --- Insight builders (satu method per Supported Insight Type) ----------
// Tiap builder balikin 1 objek insight {id,type,priority,title,
// description,recommendation,confidence,source} kalau data sumbernya
// tersedia (engine sudah dimuat & method-nya sukses), atau `null` kalau
// tidak (dependency belum dimuat / data belum cukup) — getInsights()
// melewati builder yang balikin null, TIDAK menganggapnya gagal total.

// Fuel Consumption — 100% REUSE FuelCostAnalytics.costPerKm() (yang
// sendiri REUSE fuelEfficiency()).
_fuelConsumptionInsight(vehicleId) {
  if (typeof FuelCostAnalytics === 'undefined' || typeof FuelCostAnalytics.costPerKm !== 'function') return null;
  const res = FuelCostAnalytics.costPerKm(vehicleId);
  if (!res.ok) return null;
  return {
    id: 'fuel-consumption',
    type: 'Fuel Consumption',
    priority: 'INFO',
    title: 'Konsumsi BBM saat ini',
    description: 'Rata-rata ' + res.kmPerLiter.toFixed(1) + ' km/liter, biaya sekitar Rp'
      + Math.round(res.costPerKm).toLocaleString('id-ID') + '/km (harga BBM rata-rata Rp'
      + Math.round(res.averageFuelPrice).toLocaleString('id-ID') + '/liter).',
    recommendation: 'Pantau tren konsumsi BBM secara berkala untuk mendeteksi perubahan pola berkendara.',
    confidence: null,
    source: 'FuelCostAnalytics.costPerKm',
  };
},

// Monthly Cost — 100% REUSE FuelCostAnalytics.monthlyCost() (histori
// transaksi aktual bulan berjalan); kalau belum ada transaksi bulan ini,
// fallback ke FuelCostAnalytics.projectedMonthlyCost() (100% REUSE
// FuelPredictionEngine, sudah dipakai APA ADANYA di engine itu sendiri).
_monthlyCostInsight(vehicleId) {
  if (typeof FuelCostAnalytics === 'undefined') return null;
  const actual = (typeof FuelCostAnalytics.monthlyCost === 'function')
    ? FuelCostAnalytics.monthlyCost(vehicleId)
    : { ok: false, reason: 'FuelCostAnalytics.monthlyCost belum dimuat' };
  if (actual.ok) {
    return {
      id: 'monthly-cost',
      type: 'Monthly Cost',
      priority: 'INFO',
      title: 'Biaya BBM bulan ini',
      description: 'Total pengeluaran BBM bulan ' + actual.month + ': Rp'
        + actual.totalCost.toLocaleString('id-ID') + ' untuk ' + actual.totalLiter
        + ' liter (rata-rata Rp' + actual.averagePrice.toLocaleString('id-ID') + '/liter).',
      recommendation: 'Bandingkan dengan bulan-bulan sebelumnya untuk melihat tren pengeluaran BBM.',
      confidence: null,
      source: 'FuelCostAnalytics.monthlyCost',
    };
  }
  if (typeof FuelCostAnalytics.projectedMonthlyCost !== 'function') return null;
  const proj = FuelCostAnalytics.projectedMonthlyCost(vehicleId);
  if (!proj.ok) return null;
  return {
    id: 'monthly-cost',
    type: 'Monthly Cost',
    priority: 'INFO',
    title: 'Estimasi biaya BBM bulan ini',
    description: 'Belum ada transaksi BBM tercatat bulan ini. Estimasi biaya: Rp'
      + Math.round(proj.estimatedCost).toLocaleString('id-ID') + ' (' + proj.estimatedLiter
      + ' liter), berdasarkan pola berkendara historis.',
    recommendation: 'Catat transaksi BBM berikutnya agar biaya aktual bulan ini bisa dipantau.',
    confidence: proj.confidenceScore,
    source: 'FuelCostAnalytics.projectedMonthlyCost',
  };
},

// Fuel Efficiency — 100% REUSE FuelMaintenanceEngine.fuelEfficiencyHealth()
// (yang sendiri REUSE fuelEfficiency() + _vehicleFuelEfficiencyDropCheck()
// global) — mapping dropPct -> priority CRITICAL/HIGH murni ambang batas
// tampilan, 0 rumus drop baru.
_fuelEfficiencyInsight(vehicleId) {
  if (typeof FuelMaintenanceEngine === 'undefined' || typeof FuelMaintenanceEngine.fuelEfficiencyHealth !== 'function') return null;
  const health = FuelMaintenanceEngine.fuelEfficiencyHealth(vehicleId);
  if (!health.ok) return null;
  if (health.degradationDetected) {
    return {
      id: 'fuel-efficiency',
      type: 'Fuel Efficiency',
      priority: health.dropPct >= 30 ? 'CRITICAL' : 'HIGH',
      title: 'Penurunan efisiensi BBM terdeteksi',
      description: 'Efisiensi BBM turun ' + Math.round(health.dropPct) + '% dari rata-rata sebelumnya'
        + ' (ambang batas ' + health.thresholdPct + '%). Saat ini ' + health.kmPerLiter.toFixed(1) + ' km/liter.',
      recommendation: 'Cek kondisi mesin, saringan udara, busi, dan tekanan ban — penurunan efisiensi biasanya terkait perawatan yang jatuh tempo.',
      confidence: null,
      source: 'FuelMaintenanceEngine.fuelEfficiencyHealth',
    };
  }
  return {
    id: 'fuel-efficiency',
    type: 'Fuel Efficiency',
    priority: 'INFO',
    title: 'Efisiensi BBM stabil',
    description: 'Efisiensi BBM saat ini ' + health.kmPerLiter.toFixed(1) + ' km/liter, tidak ada indikasi penurunan.',
    recommendation: 'Pertahankan kebiasaan berkendara & jadwal servis saat ini.',
    confidence: null,
    source: 'FuelMaintenanceEngine.fuelEfficiencyHealth',
  };
},

// Maintenance — 100% REUSE FuelMaintenanceEngine.maintenanceRisk() +
// maintenanceRecommendation() (keduanya sendiri REUSE FuelCostAnalytics/
// predictService()/_vehicleFuelEfficiencyDropCheck()) — mapping riskLevel
// -> priority murni tabel tampilan, 0 rumus risiko baru.
_maintenanceInsight(vehicleId) {
  if (typeof FuelMaintenanceEngine === 'undefined' || typeof FuelMaintenanceEngine.maintenanceRisk !== 'function') return null;
  const risk = FuelMaintenanceEngine.maintenanceRisk(vehicleId);
  if (!risk.ok) return null;
  const rec = (typeof FuelMaintenanceEngine.maintenanceRecommendation === 'function')
    ? FuelMaintenanceEngine.maintenanceRecommendation(vehicleId)
    : { ok: false };
  const recommendation = (rec.ok && rec.recommendations.length)
    ? rec.recommendations.join(' ')
    : 'Tidak ada rekomendasi tambahan saat ini.';
  const priorityMap = { tinggi: 'CRITICAL', sedang: 'MEDIUM', rendah: 'LOW' };
  return {
    id: 'maintenance',
    type: 'Maintenance',
    priority: priorityMap[risk.riskLevel] || 'INFO',
    title: 'Risiko perawatan terkait BBM: ' + risk.riskLevel,
    description: risk.overdueCount + ' item servis relevan BBM terdeteksi (' + risk.overdueLewatCount
      + ' sudah lewat jadwal), status efisiensi: ' + (risk.degradationDetected ? 'menurun' : 'normal') + '.',
    recommendation,
    confidence: null,
    source: 'FuelMaintenanceEngine.maintenanceRisk',
  };
},

// Reserve Fuel — 100% REUSE FuelGaugeEngine.getReserveStatus(), input
// liter dibaca apa adanya dari D.vehicles[i].fuelState (lihat
// _currentFuelLiter() di atas) — 0 rumus reserve baru.
_reserveFuelInsight(vehicleId) {
  if (typeof FuelGaugeEngine === 'undefined' || typeof FuelGaugeEngine.getReserveStatus !== 'function') return null;
  const liter = this._currentFuelLiter(vehicleId);
  if (liter === null) return null;
  const reserve = FuelGaugeEngine.getReserveStatus(vehicleId, liter);
  if (!reserve.ok) return null;
  if (reserve.inReserve) {
    return {
      id: 'reserve-fuel',
      type: 'Reserve Fuel',
      priority: 'CRITICAL',
      title: 'BBM sudah masuk cadangan (reserve)',
      description: 'Sisa BBM saat ini sudah di bawah/pada ambang cadangan (' + reserve.reserveLiter + ' liter).',
      recommendation: 'Segera isi BBM untuk menghindari kehabisan di jalan.',
      confidence: null,
      source: 'FuelGaugeEngine.getReserveStatus',
    };
  }
  return {
    id: 'reserve-fuel',
    type: 'Reserve Fuel',
    priority: 'INFO',
    title: 'BBM masih di atas cadangan',
    description: 'Sisa BBM ' + reserve.literAboveReserve + ' liter di atas ambang cadangan (' + reserve.reserveLiter + ' liter).',
    recommendation: 'Tidak ada tindakan mendesak diperlukan.',
    confidence: null,
    source: 'FuelGaugeEngine.getReserveStatus',
  };
},

// Next Refuel — 100% REUSE FuelPredictionEngine.predictNextRefuel()
// (yang sendiri REUSE FuelGaugeEngine + fuelEfficiency()) — mapping
// estimatedRemainingDays -> priority murni ambang batas tampilan, 0
// rumus proyeksi tanggal baru.
_nextRefuelInsight(vehicleId) {
  if (typeof FuelPredictionEngine === 'undefined' || typeof FuelPredictionEngine.predictNextRefuel !== 'function') return null;
  const pred = FuelPredictionEngine.predictNextRefuel(vehicleId);
  if (!pred.ok) return null;
  let priority = 'LOW';
  if (pred.estimatedRemainingDays <= 1) priority = 'CRITICAL';
  else if (pred.estimatedRemainingDays <= 3) priority = 'HIGH';
  else if (pred.estimatedRemainingDays <= 7) priority = 'MEDIUM';
  return {
    id: 'next-refuel',
    type: 'Next Refuel',
    priority,
    title: 'Perkiraan waktu isi BBM berikutnya',
    description: 'Estimasi ' + pred.estimatedRemainingDays + ' hari lagi (~' + pred.estimatedRemainingKm + ' km tersisa)'
      + (pred.estimatedDate ? ', sekitar ' + pred.estimatedDate : '') + '.',
    recommendation: (priority === 'CRITICAL' || priority === 'HIGH')
      ? 'Rencanakan pengisian BBM dalam waktu dekat.'
      : 'Belum perlu tindakan, pantau kembali secara berkala.',
    confidence: null,
    source: 'FuelPredictionEngine.predictNextRefuel',
  };
},

// Prediction — 100% REUSE FuelPredictionEngine.predictMonthlyFuelUsage()
// + predictYearlyFuelUsage() (yang kedua sendiri REUSE yang pertama x12)
// — 0 rumus proyeksi baru.
_predictionInsight(vehicleId) {
  if (typeof FuelPredictionEngine === 'undefined' || typeof FuelPredictionEngine.predictMonthlyFuelUsage !== 'function') return null;
  const monthly = FuelPredictionEngine.predictMonthlyFuelUsage(vehicleId);
  if (!monthly.ok) return null;
  const yearly = (typeof FuelPredictionEngine.predictYearlyFuelUsage === 'function')
    ? FuelPredictionEngine.predictYearlyFuelUsage(vehicleId)
    : { ok: false };
  let description = 'Perkiraan bulan depan: ' + monthly.estimatedLiter + ' liter (Rp'
    + Math.round(monthly.estimatedCost).toLocaleString('id-ID') + ')';
  if (yearly.ok) {
    description += ', setahun: ' + yearly.estimatedLiter + ' liter (Rp'
      + Math.round(yearly.estimatedCost).toLocaleString('id-ID') + ')';
  }
  description += '.';
  return {
    id: 'prediction',
    type: 'Prediction',
    priority: 'INFO',
    title: 'Proyeksi pemakaian BBM',
    description,
    recommendation: 'Gunakan proyeksi ini untuk perencanaan anggaran BBM bulanan/tahunan.',
    confidence: null,
    source: 'FuelPredictionEngine.predictMonthlyFuelUsage',
  };
},

// getInsights(vehicleId) — kumpulkan SELURUH Supported Insight Type dari
// engine-engine di atas (7 builder), lewati yang balikin null (dependency
// belum dimuat/data belum cukup), lalu urutkan berdasarkan prioritas.
// Return: {ok:true, insights:[]} — insights BISA kosong (kendaraan valid
// tapi belum ada histori BBM/servis/profil tangki sama sekali, "empty
// history"/"missing profile" case) — BUKAN dianggap gagal. {ok:false,
// reason:'Kendaraan tidak ditemukan'} HANYA kalau vehicleId tidak valid.
getInsights(vehicleId) {
  const veh = this._vehicle(vehicleId);
  if (!veh) return { ok: false, reason: 'Kendaraan tidak ditemukan' };
  const builders = [
    this._fuelConsumptionInsight,
    this._monthlyCostInsight,
    this._fuelEfficiencyInsight,
    this._maintenanceInsight,
    this._reserveFuelInsight,
    this._nextRefuelInsight,
    this._predictionInsight,
  ];
  const insights = [];
  builders.forEach((fn) => {
    const insight = fn.call(this, vehicleId);
    if (insight) insights.push(insight);
  });
  return { ok: true, insights: this._sortByPriority(insights) };
},

// _fuelGaugeData(vehicleId) — TASK-150A: struktur data gauge BBM siap
// tampil, 100% REUSE FuelGaugeEngine.calculateFuelBar()/calculateFuelPercent()/
// getReserveStatus() (liter input APA ADANYA dari _currentFuelLiter(), pola
// sama persis _reserveFuelInsight()) + FuelTankProfile.get().fuelBarCount
// (dibaca APA ADANYA, bukan dihitung — satu-satunya tempat fuelBarCount
// tersimpan). 0 rumus bar/liter/persen/reserve baru — murni membungkus nilai
// yang SUDAH dihitung engine di atas jadi 1 objek terstruktur.
// Balikin `null` kalau belum ada fuelState.currentFuelLiter tersimpan sama
// sekali (kendaraan belum pernah dikoreksi — TIDAK ADA data dasar utk
// ditampilkan). Kalau liter tersedia tapi salah satu engine belum
// dimuat/gagal, field terkait itu saja `null` (tidak memblokir field lain),
// pola sama persis getSummary() utk field lain.
_fuelGaugeData(vehicleId) {
  const liter = this._currentFuelLiter(vehicleId);
  if (liter === null) return null;

  let currentBar = null;
  let fuelPercent = null;
  let reserve = null;
  let reserveLiter = null;

  if (typeof FuelGaugeEngine !== 'undefined') {
    if (typeof FuelGaugeEngine.calculateFuelBar === 'function') {
      const barRes = FuelGaugeEngine.calculateFuelBar(vehicleId, liter);
      if (barRes.ok) currentBar = barRes.bar;
    }
    if (typeof FuelGaugeEngine.calculateFuelPercent === 'function') {
      const pctRes = FuelGaugeEngine.calculateFuelPercent(vehicleId, liter);
      if (pctRes.ok) fuelPercent = pctRes.percent;
    }
    if (typeof FuelGaugeEngine.getReserveStatus === 'function') {
      const reserveRes = FuelGaugeEngine.getReserveStatus(vehicleId, liter);
      if (reserveRes.ok) {
        reserve = reserveRes.inReserve;
        reserveLiter = reserveRes.reserveLiter;
      }
    }
  }

  let maxBar = null;
  if (typeof FuelTankProfile !== 'undefined' && typeof FuelTankProfile.get === 'function') {
    const profile = FuelTankProfile.get(vehicleId);
    if (profile && typeof profile.fuelBarCount === 'number') maxBar = profile.fuelBarCount;
  }

  return {
    currentBar,
    maxBar,
    remainingLiter: liter,
    fuelPercent,
    reserve,
    reserveLiter,
  };
},

// getSummary(vehicleId) — ringkasan angka siap tampil utk Dashboard/AI
// masa depan, SELURUHNYA diturunkan dari engine yang SUDAH ADA (0 rumus
// km/L/Rp-per-km/servis/degradasi/proyeksi baru):
//   - efficiencyScore: 100 kalau tidak ada degradasi terdeteksi
//     (FuelMaintenanceEngine.fuelEfficiencyHealth()), atau
//     (100 - dropPct) di-clamp ke [0,100] kalau ada degradasi — LOGIC
//     BARU (skor tampilan), murni turunan dropPct yang SUDAH dihitung.
//   - maintenanceRisk: riskLevel APA ADANYA dari
//     FuelMaintenanceEngine.maintenanceRisk() ('tinggi'/'sedang'/'rendah').
//   - healthScore: rata-rata efficiencyScore & skor turunan
//     maintenanceRisk (tinggi=40/sedang=70/rendah=100, tabel tampilan
//     sama pola dgn priorityMap di _maintenanceInsight()) — LOGIC BARU
//     (komposisi 2 sinyal existing, pola sama persis
//     FuelMaintenanceEngine.maintenanceRisk() yg juga menggabungkan 2
//     sinyal existing jadi 1 level baru), null kalau kedua sumber tidak
//     tersedia.
//   - monthlyCost: FuelCostAnalytics.monthlyCost().totalCost (histori
//     aktual bulan ini) kalau ada, fallback ke
//     projectedMonthlyCost().estimatedCost (100% REUSE
//     FuelPredictionEngine) kalau belum ada transaksi bulan ini.
//   - remainingDistance: FuelPredictionEngine.predictRemainingDistance().
//     remainingKm (yang sendiri REUSE FuelGaugeEngine + fuelState).
//   - confidenceScore: D.vehicles[i].fuelState.confidenceScore APA ADANYA
//     (diteruskan lewat projectedMonthlyCost()/predictRemainingDistance(),
//     keduanya sudah membaca field ini di engine masing-masing) — 0 rumus
//     confidence baru dihitung di sini.
// TASK-150A (Expand Summary API): 2 field TAMBAHAN di-append di akhir
// (field lama TIDAK diubah/rename sama sekali, tetap 100% backward
// compatible dgn caller existing yg cuma baca field lama):
//   - fuel: {currentBar,maxBar,remainingLiter,fuelPercent,reserve,
//     reserveLiter} — lihat _fuelGaugeData() di atas, `null` kalau belum
//     ada fuelState.currentFuelLiter tersimpan sama sekali.
//   - highestInsight: insight prioritas tertinggi, 100% REUSE
//     this.getInsights(vehicleId) (array yang SAMA PERSIS sudah diurutkan
//     _sortByPriority()) — `insights[0]` apa adanya, atau `null` kalau
//     array kosong/kendaraan tidak valid. 0 logic sortir/prioritas baru
//     ditulis di sini, murni ambil elemen pertama dari hasil yang sudah ada.
//
// Return: {ok:true, healthScore, efficiencyScore, monthlyCost,
//   remainingDistance, maintenanceRisk, confidenceScore, fuel,
//   highestInsight} — field individu BISA null kalau dependency terkait
//   belum dimuat/data belum cukup (TIDAK memblokir field lain). {ok:false,
//   reason:'Kendaraan tidak ditemukan'} HANYA kalau vehicleId tidak valid.
getSummary(vehicleId) {
  const veh = this._vehicle(vehicleId);
  if (!veh) return { ok: false, reason: 'Kendaraan tidak ditemukan' };

  let efficiencyScore = null;
  let maintenanceRisk = null;
  let maintenanceScore = null;

  if (typeof FuelMaintenanceEngine !== 'undefined') {
    if (typeof FuelMaintenanceEngine.fuelEfficiencyHealth === 'function') {
      const health = FuelMaintenanceEngine.fuelEfficiencyHealth(vehicleId);
      if (health.ok) {
        efficiencyScore = health.degradationDetected
          ? Math.max(0, Math.min(100, Math.round(100 - health.dropPct)))
          : 100;
      }
    }
    if (typeof FuelMaintenanceEngine.maintenanceRisk === 'function') {
      const risk = FuelMaintenanceEngine.maintenanceRisk(vehicleId);
      if (risk.ok) {
        maintenanceRisk = risk.riskLevel;
        const scoreMap = { tinggi: 40, sedang: 70, rendah: 100 };
        maintenanceScore = (risk.riskLevel in scoreMap) ? scoreMap[risk.riskLevel] : null;
      }
    }
  }

  let healthScore = null;
  if (efficiencyScore !== null && maintenanceScore !== null) {
    healthScore = Math.round((efficiencyScore + maintenanceScore) / 2);
  } else if (efficiencyScore !== null) {
    healthScore = efficiencyScore;
  } else if (maintenanceScore !== null) {
    healthScore = maintenanceScore;
  }

  let monthlyCost = null;
  let confidenceScore = null;
  if (typeof FuelCostAnalytics !== 'undefined') {
    const actual = (typeof FuelCostAnalytics.monthlyCost === 'function')
      ? FuelCostAnalytics.monthlyCost(vehicleId)
      : { ok: false };
    if (actual.ok) {
      monthlyCost = actual.totalCost;
    } else if (typeof FuelCostAnalytics.projectedMonthlyCost === 'function') {
      const proj = FuelCostAnalytics.projectedMonthlyCost(vehicleId);
      if (proj.ok) {
        monthlyCost = proj.estimatedCost;
        confidenceScore = proj.confidenceScore;
      }
    }
  }

  let remainingDistance = null;
  if (typeof FuelPredictionEngine !== 'undefined' && typeof FuelPredictionEngine.predictRemainingDistance === 'function') {
    const dist = FuelPredictionEngine.predictRemainingDistance(vehicleId);
    if (dist.ok) {
      remainingDistance = dist.remainingKm;
      if (confidenceScore === null) confidenceScore = dist.confidenceScore;
    }
  }

  const fuel = this._fuelGaugeData(vehicleId);

  const insightsRes = this.getInsights(vehicleId);
  const highestInsight = (insightsRes.ok && insightsRes.insights.length) ? insightsRes.insights[0] : null;

  return {
    ok: true,
    healthScore,
    efficiencyScore,
    monthlyCost,
    remainingDistance,
    maintenanceRisk,
    confidenceScore,
    fuel,
    highestInsight,
  };
},

};

// fuel-fleet-selector.js — Fuel Fleet Brief Selector (TASK-151A).
//
// KONTEKS: TASK-151 (Fuel AI Daily Briefing Integration) di-STOP krn
// pipeline briefing yang ada beroperasi fleet-wide, sedangkan
// FuelInsightEngine.getSummary()/getInsights() wajib 1 vehicleId spesifik
// — tidak ada mekanisme "kendaraan mana yang diceritakan" (lihat
// AI_STATE.md § Sesi 151). Modul ini SATU-SATUNYA tujuannya: menutup gap
// itu dgn memilih 1 kendaraan lewat rule presentasi murni, TIDAK
// menyentuh FuelInsightEngine atau AI Briefing sama sekali (keduanya
// tetap TIDAK diubah sesi ini — wiring ke briefing sendiri jadi task
// lanjutan, di luar scope TASK-151A).
//
// PRINSIP: presentation helper only, 0 UI, PURE (read-only, tidak pernah
// panggil save() atau menulis ke D). 100% REUSE:
//   - FuelInsightEngine.getSummary(vehicleId) (TASK-149/150A) -> dipakai
//     APA ADANYA per kendaraan; `summary.highestInsight` (sudah diurutkan
//     prioritas oleh FuelInsightEngine sendiri via getInsights(), lihat
//     TASK-150A) dipakai LANGSUNG sbg insight prioritas tertinggi
//     kendaraan itu — 0 logic sortir insight baru ditulis di sini.
//   - curVehicleId (global SUDAH ADA — modules/shared/
//     features-helpers-global-security.js, dipakai sbg "kendaraan aktif"
//     di banyak modul lain: fuel-card.js/fuel-modal.js/fuel-intelligence-
//     ui.js/vehicle-core.js dst) -> DIBACA APA ADANYA sbg tie-breaker
//     "active/current vehicle" sesuai requirement task. TIDAK ADA state/
//     field baru dibuat utk konsep ini — curVehicleId sudah jadi
//     satu-satunya representasi "kendaraan aktif" di seluruh aplikasi.
//
// LOGIC BARU sesi ini (sesuai requirement task, bukan kalkulasi bisnis):
// (1) iterasi D.vehicles, kumpulkan highestInsight tiap kendaraan yang
// valid & punya insight; (2) bandingkan level prioritas
// (CRITICAL->HIGH->MEDIUM->LOW->INFO, urutan TEKS dari task, bukan rumus)
// utk cari kandidat teratas; (3) kalau seri, pilih curVehicleId kalau dia
// salah satu kandidat seri, else kandidat pertama sesuai urutan D.vehicles
// (deterministik). 0 rumus km/L/Rp/servis/degradasi/kesehatan apa pun
// dihitung di sini — murni pemilihan/perbandingan level prioritas yang
// SUDAH ADA di tiap insight.
//
// KONTRAK: selectVehicle() -> {ok:true, vehicleId, summary, insight} kalau
// ada kandidat terpilih. Balikin `null` (BUKAN {ok:false,...}) kalau tidak
// ada satu pun kendaraan dengan insight (0 kendaraan / seluruh kendaraan
// invalid / seluruh kendaraan tidak punya insight sama sekali) — sesuai
// rule#3 task "If no insights exist, Return null". TIDAK PERNAH throw.
const FuelFleetSelector = {

// Urutan prioritas SAMA PERSIS task/FuelInsightEngine._sortByPriority()
// (CRITICAL paling tinggi -> INFO paling rendah). Dibaca ulang di sini
// murni utk BANDINGKAN 2 kandidat vehicleId (bukan sortir insight per
// kendaraan — itu SUDAH dilakukan FuelInsightEngine.getInsights() sendiri,
// hasilnya dibaca apa adanya lewat summary.highestInsight).
_PRIORITY_ORDER: ['CRITICAL', 'HIGH', 'MEDIUM', 'LOW', 'INFO'],

_priorityIndex(priority) {
  const idx = this._PRIORITY_ORDER.indexOf(priority);
  return idx === -1 ? this._PRIORITY_ORDER.length : idx; // priority tidak dikenal -> dianggap paling rendah, tidak memblokir
},

_vehicles() {
  return (typeof D !== 'undefined' && Array.isArray(D.vehicles)) ? D.vehicles : [];
},

_activeVehicleId() {
  return (typeof curVehicleId !== 'undefined') ? curVehicleId : null;
},

// _candidates() — kumpulkan {vehicleId, summary, insight, priorityIdx}
// utk tiap kendaraan yang: (a) valid (FuelInsightEngine.getSummary()
// {ok:true}), (b) punya highestInsight (bukan null). Kendaraan invalid
// atau tanpa insight DILEWATI (bukan bikin seluruh seleksi gagal) — pola
// sama persis "insight yang sumbernya belum tersedia dilewati" di
// FuelInsightEngine sendiri.
_candidates() {
  const out = [];
  if (typeof FuelInsightEngine === 'undefined' || typeof FuelInsightEngine.getSummary !== 'function') {
    return out;
  }
  const vehicles = this._vehicles();
  for (let i = 0; i < vehicles.length; i++) {
    const veh = vehicles[i];
    if (!veh || !veh.id) continue; // entri kendaraan tidak valid, lewati
    let summary;
    try {
      summary = FuelInsightEngine.getSummary(veh.id);
    } catch (e) {
      continue; // tidak pernah throw ke pemanggil, lewati kendaraan ini
    }
    if (!summary || !summary.ok) continue; // kendaraan tidak ditemukan / gagal, lewati
    const insight = summary.highestInsight || null;
    if (!insight) continue; // kendaraan valid tapi tidak ada insight, lewati
    out.push({
      vehicleId: veh.id,
      summary,
      insight,
      priorityIdx: this._priorityIndex(insight.priority),
    });
  }
  return out;
},

// selectVehicle() — API publik satu-satunya. Lihat KONTRAK di atas.
selectVehicle() {
  const candidates = this._candidates();
  if (!candidates.length) return null; // rule#3: no insights exist -> null

  // Rule#1: highest priority wins (index terkecil = prioritas tertinggi).
  let bestIdx = candidates[0].priorityIdx;
  for (let i = 1; i < candidates.length; i++) {
    if (candidates[i].priorityIdx < bestIdx) bestIdx = candidates[i].priorityIdx;
  }
  const top = candidates.filter((c) => c.priorityIdx === bestIdx);

  let chosen = top[0];
  if (top.length > 1) {
    // Rule#2: seri -> pilih kendaraan aktif/current (curVehicleId) kalau
    // dia salah satu kandidat seri; kalau tidak, kandidat pertama sesuai
    // urutan D.vehicles (deterministik, bukan tebakan acak).
    const activeId = this._activeVehicleId();
    const activeMatch = top.find((c) => c.vehicleId === activeId);
    if (activeMatch) chosen = activeMatch;
  }

  return {
    ok: true,
    vehicleId: chosen.vehicleId,
    summary: chosen.summary,
    insight: chosen.insight,
  };
},

};

// fuel-notif-bridge.js — Fuel Notification Bridge (TASK-153, Fuel
// Notification & Reminder).
//
// KONTEKS: reminder-notif.js (checkAndFireReminders()) SUDAH menembak
// notifikasi browser nyata utk tagihan/LDR/pajak-kendaraan/SIM/SPT +
// (Sesi 84) servis/BBM estimasi lewat VehicleNotifBridge -- TAPI insight
// Fuel Intelligence (FuelInsightEngine, TASK-149/150A) BELUM PERNAH
// menembak notifikasi nyata. Itu satu-satunya gap yang ditutup sesi ini.
//
// PRINSIP (RULE #1 task): 100% REUSE FuelInsightEngine.getInsights() apa
// adanya -- TIDAK ada ambang/rumus baru, TIDAK menghitung ulang reserve/
// efisiensi/risiko servis/prediksi apa pun (priority & angka sudah final
// dari FuelInsightEngine, yang sendiri 100% REUSE FuelGaugeEngine/
// FuelPredictionEngine/FuelMaintenanceEngine). Modul ini PURE -- tidak
// pernah memanggil fireNotif()/Notification/localStorage sendiri, tidak
// menyentuh DOM. Hanya MENERJEMAHKAN insight FuelInsightEngine yang
// "actionable" (lihat NOTIFY_RULES di bawah) jadi bentuk generik
// {fireKey,title,body,vehicleId} siap pakai pemanggil (reminder-notif.js
// checkAndFireReminders(), yang SUDAH memanggil fireNotif()+menyimpan
// kw_notif_fired sendiri) -- pola SAMA PERSIS
// modules/vehicle/vehicle-notif-bridge.js (Sesi 84).
//
// 4 Behavior task dipetakan ke insight FuelInsightEngine yang SUDAH ADA
// (0 insight/type baru ditambahkan ke FuelInsightEngine, engine itu
// TIDAK disentuh sama sekali):
//   - "Fuel reserve reached"                  -> insight id 'reserve-fuel',
//     ditembak kalau priority CRITICAL (reserve.inReserve true, dari
//     FuelGaugeEngine.getReserveStatus()).
//   - "Fuel efficiency drops significantly"   -> insight id
//     'fuel-efficiency', ditembak kalau degradationDetected true
//     (priority CRITICAL/HIGH, dari
//     FuelMaintenanceEngine.fuelEfficiencyHealth()).
//   - "Maintenance affects fuel efficiency"   -> insight id 'maintenance',
//     ditembak kalau priority CRITICAL (riskLevel 'tinggi' --  overdue
//     servis relevan BBM DAN degradasi efisiensi terdeteksi BERSAMAAN,
//     dari FuelMaintenanceEngine.maintenanceRisk() -- persis definisi
//     "maintenance affects fuel efficiency", bukan sekadar servis lewat
//     jatuh tempo tanpa korelasi efisiensi).
//   - "Predicted fuel refill reminder"        -> insight id 'next-refuel',
//     ditembak kalau priority CRITICAL/HIGH (estimatedRemainingDays <= 3,
//     dari FuelPredictionEngine.predictNextRefuel()).
// Insight lain (fuel-consumption/monthly-cost/prediction, semua selalu
// INFO) & priority MEDIUM/LOW/INFO pada 4 insight di atas SENGAJA TIDAK
// ditembak jadi notifikasi push -- pola SAMA PERSIS VehicleNotifBridge
// (hanya severity 'overdue' yang aktif menembak, bukan 'due-soon'/'info')
// supaya notifikasi tetap actionable, bukan noise harian.
const FuelNotifBridge = {

// NOTIFY_RULES — 1 fungsi per insight id yang didukung, balikin true
// kalau insight tsb cukup mendesak utk ditembak jadi notifikasi push
// (lihat pemetaan di komentar atas). Insight id di luar daftar ini
// (fuel-consumption/monthly-cost/prediction) TIDAK PERNAH ditembak.
NOTIFY_RULES: {
  'reserve-fuel': (insight) => insight.priority === 'CRITICAL',
  'fuel-efficiency': (insight) => insight.priority === 'CRITICAL' || insight.priority === 'HIGH',
  maintenance: (insight) => insight.priority === 'CRITICAL',
  'next-refuel': (insight) => insight.priority === 'CRITICAL' || insight.priority === 'HIGH',
},

// TITLE_MAP — judul notifikasi siap tampil per insight id (body dari
// insight.description apa adanya, 100% REUSE teks yang sudah disusun
// FuelInsightEngine -- 0 penyusunan kalimat baru di sini selain judul).
TITLE_MAP: {
  'reserve-fuel': '⛽ BBM Masuk Cadangan (Reserve)',
  'fuel-efficiency': '📉 Penurunan Efisiensi BBM Signifikan',
  maintenance: '🔧 Servis Jatuh Tempo Memengaruhi Efisiensi BBM',
  'next-refuel': '🔮 Perkiraan Waktu Isi BBM Berikutnya',
},

// _vehicles(vehicleId) — pola SAMA PERSIS VehicleReminder._vehicles():
// baca D.vehicles apa adanya lewat guard typeof, difilter ke 1 kendaraan
// kalau vehicleId diberikan, atau SELURUH kendaraan kalau tidak (dipakai
// checkAndFireReminders() yang menembak lintas SELURUH kendaraan, sama
// persis pola VehicleNotifBridge.items(undefined, ...)).
_vehicles(vehicleId) {
  const list = (typeof D !== 'undefined' && D.vehicles) ? D.vehicles : [];
  if (vehicleId) return list.filter((v) => v.id === vehicleId);
  return list.filter((v) => (typeof isVehicleOwnershipSelf !== 'function') || isVehicleOwnershipSelf(v.id));
},

// items(vehicleId?, firedIds?) — daftar {fireKey,title,body,vehicleId}
// siap tembak notifikasi, dari FuelInsightEngine.getInsights() per
// kendaraan, difilter NOTIFY_RULES (di atas) + firedIds (default [],
// supaya item yang sudah pernah ditembak hari yang sama, disuplai
// pemanggil dari kw_notif_fired.ids, tidak diulang -- 100% REUSE
// mekanisme dedup kw_notif_fired yang SUDAH ADA di reminder-notif.js, 0
// storage/dedup baru dibuat di sini).
items(vehicleId, firedIds) {
  const fired = Array.isArray(firedIds) ? firedIds : [];
  if (typeof FuelInsightEngine === 'undefined' || typeof FuelInsightEngine.getInsights !== 'function') return [];
  const out = [];
  this._vehicles(vehicleId).forEach((v) => {
    if (!v || !v.id) return;
    const res = FuelInsightEngine.getInsights(v.id);
    if (!res.ok) return;
    res.insights.forEach((insight) => {
      const rule = this.NOTIFY_RULES[insight.id];
      if (!rule || !rule(insight)) return;
      const fireKey = 'fuel_' + insight.id + '_' + v.id;
      if (fired.includes(fireKey)) return;
      out.push({
        fireKey,
        title: this.TITLE_MAP[insight.id],
        body: insight.description,
        vehicleId: v.id,
      });
    });
  });
  return out;
},

};

// fuel-dashboard.js — Fuel Dashboard (TASK-150, Fuel Dashboard Integration).
// + Export Fuel Dashboard (TASK-155A, exportVehicleHTML()/exportVehicleJSON(),
// lihat blok "TASK-155A: Export (Single Vehicle)" di bawah).
//
// PRINSIP: UI HANYA presenter, 0 rumus/skoring baru. 100% REUSE:
//   - FuelInsightEngine.getSummary(vehicleId) (TASK-149/150A) -> healthScore/
//     fuel (bar/liter/persen/reserve)/highestInsight SEMUA dibaca APA
//     ADANYA, 0 kalkulasi ulang di sini.
//   - FuelModal.open()/FuelBarCorrection.open() (SUDAH ADA, TASK-141/144)
//     -> CTA "Lihat Detail"/"⚙️ Koreksi", pola SAMA PERSIS fuel-card.js.
//   - Class CSS SUDAH ADA (dashhub-cat-head/dashhub-cat-icon/
//     dashhub-cat-label/dashhub-cat-desc/btn/btn-ghost/btn-sm/btn-row/
//     chip-btn) — 0 CSS baru ditulis.
//   - Vehicle switcher (multi-kendaraan) pakai pola chip yang SAMA PERSIS
//     renderDashServisVehChips() (modules-render.js) — 0 komponen switcher
//     baru dibuat dari nol.
//
// TIDAK disentuh sama sekali (sesuai batasan TASK-150): FuelInsightEngine,
// FuelFleetSelector — dashboard ini mengelola kendaraan aktifnya SENDIRI
// (this.curVehicleId, pola sama persis FuelModal.curVehicleId/
// FuelBarCorrection.curVehicleId, SUDAH ADA) supaya tidak perlu mengubah
// FuelFleetSelector ataupun variabel global curVehicleId (dipakai tab Car
// Notes) sama sekali. 0 storage baru (tidak menulis ke D).
//
// KONTRAK render(vehicleId?): vehicleId opsional. Kalau tidak diberikan,
// pakai this.curVehicleId (kendaraan terakhir dipilih di dashboard ini)
// atau curVehicleId global (kendaraan aktif Car Notes, SUDAH ADA) sbg
// default, pola sama persis FuelModal.open()/FuelBarCorrection.open().
// Kalau vehicleId yang diminta tidak ditemukan di D.vehicles ("Invalid
// vehicle"), fallback ke kendaraan pertama (BUKAN menyembunyikan dashboard
// begitu saja) — supaya dashboard tetap berguna walau caller memberi id
// yang sudah tidak valid (mis. kendaraan baru saja dihapus). Dashboard
// disembunyikan (wrap.style.display='none') HANYA kalau: (a) 0 kendaraan
// sama sekali ("No vehicle"), atau (b) FuelInsightEngine belum dimuat, atau
// (c) FuelInsightEngine.getSummary() balikin {ok:false} utk SEMUA kendaraan
// yang dicoba (harusnya tidak pernah terjadi selama D.vehicles konsisten,
// tapi dijaga TIDAK PERNAH throw ke pemanggil).
const FuelDashboard = {

curVehicleId: null,

_vehicles() {
  return (typeof D !== 'undefined' && Array.isArray(D.vehicles)) ? D.vehicles : [];
},

// render(vehicleId?) — API publik satu-satunya utk menggambar dashboard.
// Dipanggil dari modules/shared/modules-render.js (renderCnTab(), pola
// sama persis FuelCard.render()) & FuelBarCorrection.save() (refresh
// setelah koreksi bar tersimpan).
render(vehicleId) {
  const wrap = document.getElementById('fuelDashWrap');
  const body = document.getElementById('fuelDashBody');
  if (!wrap || !body) return;

  const vehicles = this._vehicles();
  if (!vehicles.length) { wrap.style.display = 'none'; return; }
  if (typeof FuelInsightEngine === 'undefined' || typeof FuelInsightEngine.getSummary !== 'function') {
    wrap.style.display = 'none';
    return;
  }

  // Tentukan kendaraan aktif: parameter -> state dashboard sendiri ->
  // curVehicleId global (kendaraan aktif Car Notes, SUDAH ADA) -> fallback
  // kendaraan pertama kalau semuanya tidak valid/tidak ada di D.vehicles
  // ("Invalid vehicle" case — TIDAK menyembunyikan dashboard begitu saja).
  let vid = vehicleId || this.curVehicleId || (typeof curVehicleId !== 'undefined' ? curVehicleId : null);
  if (!vid || !vehicles.find((v) => v.id === vid)) vid = vehicles[0].id;

  let summary;
  try {
    summary = FuelInsightEngine.getSummary(vid);
  } catch (e) {
    wrap.style.display = 'none';
    return;
  }
  if (!summary || !summary.ok) {
    wrap.style.display = 'none';
    return;
  }

  this.curVehicleId = vid;
  wrap.style.display = '';
  body.innerHTML = this._body(vid, vehicles, summary);
},

// switchVehicle(vehicleId) — dipanggil dari tap chip kendaraan (data-action,
// lihat _vehicleChips()). Murni delegasi ke render() dgn vehicleId baru —
// 0 logic baru, supaya perilaku "kendaraan tidak ditemukan"/dsb konsisten
// dgn render() langsung.
switchVehicle(vehicleId) {
  this.render(vehicleId);
},

// _vehicleChips(vehicles, activeId) — switcher multi-kendaraan, pola SAMA
// PERSIS renderDashServisVehChips() (modules-render.js, SUDAH ADA) — 0
// komponen chip baru. Disembunyikan kalau cuma 1 kendaraan (Single
// vehicle case — tidak ada yang perlu di-switch).
_vehicleChips(vehicles, activeId) {
  if (vehicles.length < 2) return '';
  return `<div class="u-flex u-gap6 u-mb10" style="overflow-x:auto;padding-bottom:2px">`
    + vehicles.map((v) => `<button type="button" class="chip-btn${v.id === activeId ? ' active' : ''}" data-action="FuelDashboard.switchVehicle" data-args="${escapeHtml(JSON.stringify([v.id]))}">${escapeHtml(v.emoji ? v.emoji + ' ' : '')}${escapeHtml(v.name)}</button>`).join('')
    + `</div>`;
},

// _priorityColor(priority) — mapping tampilan murni (bukan rumus/skoring
// baru), pola sama persis statusCls di fuel-card.js (overdue->red/
// due-soon->orange).
_priorityColor(priority) {
  const map = { CRITICAL: 'red', HIGH: 'red', MEDIUM: 'orange', LOW: '', INFO: '' };
  return map[priority] || '';
},

// _fuelGaugeHtml(fuel) — fuel dari summary.fuel (FuelInsightEngine.
// getSummary(), TASK-150A) APA ADANYA — 0 rumus bar/liter/persen/reserve
// baru dihitung di sini. `null` (belum ada fuelState tersimpan) -> ajakan
// koreksi, pola sama persis pesan "Catat isi BBM" di fuel-card.js.
_fuelGaugeHtml(fuel) {
  if (!fuel) {
    return `<div class="u-fs12 u-t2" style="margin-bottom:10px">Belum ada estimasi BBM tersimpan — koreksi dulu dengan speedometer.</div>`;
  }
  const barLabel = (fuel.currentBar !== null && fuel.currentBar !== undefined && fuel.maxBar !== null && fuel.maxBar !== undefined)
    ? `${Math.round(fuel.currentBar)} / ${fuel.maxBar} Bar` : '-';
  const literLabel = (fuel.remainingLiter !== null && fuel.remainingLiter !== undefined) ? `${fuel.remainingLiter} Liter` : '-';
  const pctLabel = (fuel.fuelPercent !== null && fuel.fuelPercent !== undefined) ? `${fuel.fuelPercent}%` : '-';
  const reserveHtml = fuel.reserve
    ? `<div class="u-fs12 red" style="margin-top:4px;font-weight:700">⚠️ Sudah masuk cadangan (reserve)</div>`
    : '';
  return `
    <div style="background:var(--surface3);border-radius:12px;padding:14px;text-align:center;margin-bottom:10px">
      <div class="u-fs11 u-t2" style="text-transform:uppercase;letter-spacing:0.8px;font-weight:700">Sisa BBM</div>
      <div style="font-family:'Space Grotesk',sans-serif;font-size:22px;font-weight:800;color:var(--accent);margin-top:4px">${escapeHtml(barLabel)}</div>
      <div class="u-fs13 u-t2" style="margin-top:2px">${escapeHtml(literLabel)} · ${escapeHtml(pctLabel)}</div>
      ${reserveHtml}
    </div>`;
},

// _healthHtml(healthScore) — healthScore dari summary APA ADANYA (0 skor
// baru dihitung di sini). `null`/`undefined` (dependency belum
// dimuat/data belum cukup) -> baris ini dilewati, TIDAK memblokir bagian
// dashboard lain.
_healthHtml(healthScore) {
  if (healthScore === null || healthScore === undefined) return '';
  const col = healthScore >= 80 ? 'green' : (healthScore >= 50 ? 'orange' : 'red');
  return `<div class="u-flex u-jcb u-aic" style="margin-bottom:10px"><span class="u-fs12 u-t2">Skor Kesehatan BBM</span><span class="u-fw800 ${col}">${healthScore}/100</span></div>`;
},

// _highestInsightHtml(insight) — summary.highestInsight APA ADANYA
// (FuelInsightEngine.getInsights(), sudah diurutkan prioritas oleh engine
// itu sendiri) — 0 logic sortir/prioritas baru ditulis di sini. `null`
// (belum ada insight sama sekali) -> baris ini dilewati.
_highestInsightHtml(insight) {
  if (!insight) return '';
  const col = this._priorityColor(insight.priority);
  return `<div class="u-fs12${col ? ' ' + col : ''}" style="margin-bottom:10px;line-height:1.5"><b>${escapeHtml(insight.title)}</b><br>${escapeHtml(insight.description)}</div>`;
},

// _body(vid, vehicles, summary) — susun 1 kartu dashboard: header + (kalau
// >1 kendaraan) switcher + gauge BBM + skor kesehatan + insight prioritas
// tertinggi + CTA (100% reuse FuelModal.open()/FuelBarCorrection.open(),
// pola SAMA PERSIS baris CTA fuel-card.js).
_body(vid, vehicles, summary) {
  const veh = vehicles.find((v) => v.id === vid);
  const name = veh ? (veh.emoji ? veh.emoji + ' ' : '') + veh.name : '';
  return `
    <div class="dashhub-cat-head">
      <div class="dashhub-cat-icon">⛽</div>
      <div>
        <div class="dashhub-cat-label">Fuel Dashboard</div>
        <div class="dashhub-cat-desc">${escapeHtml(name)}</div>
      </div>
    </div>
    ${this._vehicleChips(vehicles, vid)}
    ${this._fuelGaugeHtml(summary.fuel)}
    ${this._healthHtml(summary.healthScore)}
    ${this._highestInsightHtml(summary.highestInsight)}
    <div class="btn-row" style="margin-bottom:0">
      <button class="btn btn-ghost btn-sm" data-action="FuelModal.open" data-args="${escapeHtml(JSON.stringify([vid]))}">📊 Lihat Detail</button>
      <button class="btn btn-ghost btn-sm" data-action="FuelBarCorrection.open" data-args="${escapeHtml(JSON.stringify([vid]))}" aria-label="Koreksi estimasi BBM dengan speedometer">⚙️ Koreksi</button>
      <button class="btn btn-ghost btn-sm" data-action="FuelDashboard.exportVehicleHTML" data-args="${escapeHtml(JSON.stringify([vid]))}" aria-label="Export Fuel Dashboard kendaraan ini">⬇️ Export</button>
    </div>
  `;
},

// ===================== TASK-155A: Export (Single Vehicle) =====================
// PRINSIP (sama persis prinsip file ini): 0 rumus/kalkulasi baru. Seluruh
// field export dibaca APA ADANYA dari FuelInsightEngine.getSummary(vid)
// (dependency yang SUDAH dipakai render() di atas) — export HANYA
// menyalin/menyusun ulang field yang sudah ada jadi JSON/HTML, tidak pernah
// menghitung ulang healthScore/fuel/monthlyCost/dst. 0 storage baru (tidak
// pernah menulis ke D) — pola download murni file-blob-di-browser, SAMA
// PERSIS pola modules/shared/data-archive.js / backup-restore.js
// (Blob + URL.createObjectURL + <a download> + click()).

// _buildExportData(vid) — kumpulkan 1 objek data export utk 1 kendaraan.
// `null` kalau kendaraan tidak ditemukan di D.vehicles ATAU
// FuelInsightEngine belum dimuat ATAU getSummary() {ok:false}/throw
// ("Invalid vehicle" case) — TIDAK PERNAH throw ke pemanggil.
_buildExportData(vid) {
  if (!vid) return null;
  const vehicles = this._vehicles();
  const veh = vehicles.find((v) => v.id === vid);
  if (!veh) return null;
  if (typeof FuelInsightEngine === 'undefined' || typeof FuelInsightEngine.getSummary !== 'function') return null;
  let summary;
  try {
    summary = FuelInsightEngine.getSummary(vid);
  } catch (e) {
    return null;
  }
  if (!summary || !summary.ok) return null;
  return {
    exportedAt: new Date().toISOString(),
    vehicle: { id: veh.id, name: veh.name || '', emoji: veh.emoji || null },
    healthScore: summary.healthScore,
    efficiencyScore: summary.efficiencyScore,
    monthlyCost: summary.monthlyCost,
    remainingDistance: summary.remainingDistance,
    maintenanceRisk: summary.maintenanceRisk,
    fuel: summary.fuel,
    highestInsight: summary.highestInsight,
  };
},

// _dateTag()/_slug() — helper murni format nama file, 0 logic bisnis.
_dateTag() {
  return new Date().toISOString().split('T')[0];
},

_slug(name) {
  const s = String(name || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  return s || 'kendaraan';
},

// _downloadFile(filename, content, mime) — trigger download via Blob +
// <a download>, pola SAMA PERSIS data-archive.js/backup-restore.js. `false`
// (bukan throw) kalau environment tidak mendukung (mis. Blob/URL/document
// tidak tersedia, seperti di harness test murni-logika) — dipakai caller
// utk memutuskan toast sukses/gagal.
_downloadFile(filename, content, mime) {
  if (typeof document === 'undefined' || typeof document.createElement !== 'function') return false;
  if (typeof Blob === 'undefined' || typeof URL === 'undefined' || typeof URL.createObjectURL !== 'function') return false;
  try {
    const blob = new Blob([content], { type: mime });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = filename;
    a.click();
    return true;
  } catch (e) {
    return false;
  }
},

// _vehicleHtmlReport(data) — susun laporan HTML standalone (self-contained,
// inline style — file diunduh & dibuka TERPISAH dari app, jadi TIDAK bisa
// mengandalkan var(--accent)/CSS class app). Seluruh angka/teks dibaca APA
// ADANYA dari `data` (hasil _buildExportData(), 0 kalkulasi baru).
_vehicleHtmlReport(data) {
  const v = data.vehicle;
  const fuel = data.fuel;
  const fuelLine = fuel
    ? `${(fuel.currentBar !== null && fuel.currentBar !== undefined && fuel.maxBar !== null && fuel.maxBar !== undefined) ? Math.round(fuel.currentBar) + ' / ' + fuel.maxBar + ' Bar' : '-'} &middot; ${(fuel.remainingLiter !== null && fuel.remainingLiter !== undefined) ? fuel.remainingLiter + ' Liter' : '-'} &middot; ${(fuel.fuelPercent !== null && fuel.fuelPercent !== undefined) ? fuel.fuelPercent + '%' : '-'}${fuel.reserve ? ' &mdash; ⚠️ Sudah masuk cadangan' : ''}`
    : 'Belum ada estimasi BBM tersimpan';
  const insightLine = data.highestInsight
    ? `<b>${escapeHtml(data.highestInsight.title)}</b> (${escapeHtml(data.highestInsight.priority)})<br>${escapeHtml(data.highestInsight.description)}`
    : '-';
  return `<!DOCTYPE html>
<html lang="id"><head><meta charset="UTF-8">
<title>Fuel Dashboard - ${escapeHtml(v.name)}</title>
<style>body{font-family:Arial,Helvetica,sans-serif;background:#f5f5f7;color:#1a1a2e;padding:24px;margin:0}
.card{max-width:520px;margin:0 auto;background:#fff;border-radius:12px;padding:24px;box-shadow:0 1px 4px rgba(0,0,0,.08)}
h1{font-size:20px;margin:0 0 4px}
.sub{color:#888;font-size:12px;margin-bottom:16px}
p{font-size:14px;line-height:1.6;margin:8px 0}
</style></head>
<body><div class="card">
<h1>⛽ ${escapeHtml((v.emoji ? v.emoji + ' ' : '') + v.name)}</h1>
<div class="sub">Fuel Dashboard Export &middot; ${escapeHtml(data.exportedAt)}</div>
<p><b>Skor Kesehatan BBM:</b> ${(data.healthScore !== null && data.healthScore !== undefined) ? data.healthScore + '/100' : '-'}</p>
<p><b>Skor Efisiensi:</b> ${(data.efficiencyScore !== null && data.efficiencyScore !== undefined) ? data.efficiencyScore : '-'}</p>
<p><b>Sisa BBM:</b> ${fuelLine}</p>
<p><b>Estimasi Jarak Tersisa:</b> ${(data.remainingDistance !== null && data.remainingDistance !== undefined) ? Math.round(data.remainingDistance) + ' km' : '-'}</p>
<p><b>Biaya BBM/Bulan:</b> ${(data.monthlyCost !== null && data.monthlyCost !== undefined) ? 'Rp' + Math.round(data.monthlyCost).toLocaleString('id-ID') : '-'}</p>
<p><b>Risiko Servis:</b> ${escapeHtml(data.maintenanceRisk || '-')}</p>
<p><b>Insight Prioritas Tertinggi:</b><br>${insightLine}</p>
</div></body></html>`;
},

// exportVehicleJSON(vehicleId?) — API publik. vehicleId opsional -> default
// this.curVehicleId (pola sama render()). "Invalid vehicle"/kendaraan tidak
// ditemukan -> toast peringatan + {ok:false}, TIDAK throw. Mengembalikan
// {ok,data} (data === objek export yang sama dipakai HTML) supaya bisa
// diverifikasi programatik (dites) tanpa membaca file yang diunduh.
exportVehicleJSON(vehicleId) {
  const vid = vehicleId || this.curVehicleId;
  const data = this._buildExportData(vid);
  if (!data) {
    if (typeof toast === 'function') toast('⚠️ Kendaraan tidak ditemukan, export dibatalkan');
    return { ok: false, reason: 'Kendaraan tidak ditemukan' };
  }
  const fname = 'fuel-dashboard-' + this._slug(data.vehicle.name) + '-' + this._dateTag() + '.json';
  const downloaded = this._downloadFile(fname, JSON.stringify(data, null, 2), 'application/json');
  if (downloaded && typeof toast === 'function') toast('✅ Export JSON berhasil');
  return { ok: downloaded, data };
},

// exportVehicleHTML(vehicleId?) — sama kontraknya dgn exportVehicleJSON(),
// bedanya isi file yang diunduh (laporan HTML, bukan JSON mentah).
exportVehicleHTML(vehicleId) {
  const vid = vehicleId || this.curVehicleId;
  const data = this._buildExportData(vid);
  if (!data) {
    if (typeof toast === 'function') toast('⚠️ Kendaraan tidak ditemukan, export dibatalkan');
    return { ok: false, reason: 'Kendaraan tidak ditemukan' };
  }
  const fname = 'fuel-dashboard-' + this._slug(data.vehicle.name) + '-' + this._dateTag() + '.html';
  const downloaded = this._downloadFile(fname, this._vehicleHtmlReport(data), 'text/html');
  if (downloaded && typeof toast === 'function') toast('✅ Export HTML berhasil');
  return { ok: downloaded, data };
},

};

// Ekspos ke window — WAJIB supaya delegasi klik global (data-action) bisa
// menemukan modul ini lewat window['FuelDashboard']['switchVehicle'] dst.
// `const FuelDashboard = {...}` di atas HANYA membuat binding lexical-
// scope (bukan properti window), pola fix sama persis window.DashboardHub
// di dashboard-hub-search.js. Tanpa baris ini, chip pilih kendaraan,
// "📊 Lihat Detail", "⚙️ Koreksi", & "⬇️ Export" di Fuel Dashboard tidak
// akan pernah berfungsi meski test lolos (test memanggil fungsi langsung,
// bukan lewat jalur klik data-action yang sesungguhnya).
if (typeof FuelDashboard !== 'undefined') window.FuelDashboard = FuelDashboard;

// fuel-compare.js — Multi Vehicle Fuel Comparison (TASK-154).
// + Export All FuelCompare (TASK-155A, exportFleetHTML()/exportFleetJSON(),
// lihat blok "TASK-155A: Export (Fleet)" di bawah).
//
// PRINSIP: presentation only, 0 UI baru rumus/kalkulasi. 100% REUSE:
//   - FuelInsightEngine.getSummary(vehicleId) (TASK-149/150A) -> healthScore/
//     efficiencyScore/monthlyCost/remainingDistance/maintenanceRisk/fuel/
//     highestInsight SEMUA dibaca APA ADANYA per kendaraan, 0 kalkulasi ulang
//     di sini (pola SAMA PERSIS fuel-dashboard.js).
//   - FuelFleetSelector.selectVehicle() (TASK-151A) -> dipakai HANYA utk
//     menandai kendaraan mana yang paling butuh perhatian fleet-wide (badge
//     "⚠️ Prioritas Tertinggi"), 0 logic seleksi/prioritas baru ditulis di
//     sini — insight & vehicleId-nya dibaca APA ADANYA dari hasil selector.
//   - FuelCostAnalytics/FuelPredictionEngine/FuelMaintenanceEngine -> TIDAK
//     dipanggil LANGSUNG di sini (sudah 100% dibungkus lewat
//     FuelInsightEngine.getSummary()), disebut di daftar Reuse task krn jadi
//     dependency transitif engine tsb.
//   - FuelModal.open(vehicleId) (SUDAH ADA, TASK-141) -> dipanggil saat 1
//     baris kendaraan di-tap ("Selecting a vehicle opens the existing Fuel
//     Intelligence Modal" — requirement task), 0 modal baru dibuat.
//
// TIDAK disentuh sama sekali (sesuai batasan task): FuelInsightEngine,
// FuelFleetSelector, FuelCostAnalytics, FuelPredictionEngine,
// FuelMaintenanceEngine (logic masing-masing), D.vehicles/D.bbmLogs/
// D.servisLogs (data). 0 storage baru dibuat (tidak pernah panggil save()
// atau menulis ke D) — state sort (this.sortKey/this.sortDir) murni state
// presenter di memori, pola sama persis this.curVehicleId di
// fuel-dashboard.js (hilang saat reload, tidak perlu persist).
//
// KONTRAK render(sortKey?): baca SEMUA D.vehicles, ambil getSummary() tiap
// kendaraan APA ADANYA. Kendaraan yang getSummary()-nya {ok:false} DILEWATI
// (bukan bikin seluruh comparison gagal) — pola sama persis
// FuelFleetSelector._candidates(). Wrap disembunyikan HANYA kalau: (a) 0
// kendaraan sama sekali ("No vehicles"), atau (b) FuelInsightEngine belum
// dimuat, atau (c) getSummary() {ok:false} utk SEMUA kendaraan yang dicoba —
// TIDAK PERNAH throw ke pemanggil.
const FuelCompare = {

curVehicleId: null, // dipakai HANYA utk highlight baris terakhir dibuka, pola sama persis FuelDashboard.curVehicleId
sortKey: 'healthScore', // default: Highest Health Risk -> Lowest (healthScore ASC = risk tertinggi dulu)
sortDir: 'asc',

// _vehicles() (Sesi 197, Ownership Sync — Report): TAMBAH 1 filter
// isVehicleOwnershipSelf(v.id) di atas D.vehicles (0 logic lama diubah) —
// kendaraan ber-ownership INVESTOR/CUSTOMER/THIRD_PARTY/FAMILY dikecualikan
// dari Multi Vehicle Fuel Comparison & Export All (exportFleetJSON/
// exportFleetHTML) — SATU titik ubah ini otomatis mencakup render()/_rows()/
// kedua fungsi export, karena semuanya memanggil _vehicles() ini. Pola sama
// persis isVehicleOwnershipSelf() di vehicle-core.js (Sesi 196)/_vehicles()
// di vehicle-reminder.js (Sesi 196). Guard typeof: kalau helper belum
// dimuat, anggap semua SELF (tidak exclude apa pun).
_vehicles() {
  const all = (typeof D !== 'undefined' && Array.isArray(D.vehicles)) ? D.vehicles : [];
  return all.filter((v) => typeof isVehicleOwnershipSelf !== 'function' || isVehicleOwnershipSelf(v.id));
},

// _rows() — kumpulkan {vehicle, summary} utk tiap kendaraan yang valid
// (FuelInsightEngine.getSummary() {ok:true}). Kendaraan invalid/gagal
// DILEWATI, bukan bikin seluruh rows gagal — pola sama persis
// FuelFleetSelector._candidates().
_rows() {
  const out = [];
  if (typeof FuelInsightEngine === 'undefined' || typeof FuelInsightEngine.getSummary !== 'function') return out;
  const vehicles = this._vehicles();
  for (let i = 0; i < vehicles.length; i++) {
    const veh = vehicles[i];
    if (!veh || !veh.id) continue;
    let summary;
    try {
      summary = FuelInsightEngine.getSummary(veh.id);
    } catch (e) {
      continue; // tidak pernah throw ke pemanggil, lewati kendaraan ini
    }
    if (!summary || !summary.ok) continue;
    out.push({ vehicle: veh, summary });
  }
  return out;
},

// _sortValue(row, key) — ambil 1 nilai pembanding dari row sesuai kunci
// sort yang didukung. Murni ekstraksi field yang SUDAH ADA di summary
// (getSummary()) / veh.name — 0 kalkulasi baru.
_sortValue(row, key) {
  switch (key) {
    case 'name': return (row.vehicle.name || '').toLowerCase();
    case 'monthlyCost': return row.summary.monthlyCost;
    case 'remainingFuel': return row.summary.fuel ? row.summary.fuel.remainingLiter : null;
    case 'healthScore':
    default: return row.summary.healthScore;
  }
},

// _sortRows(rows, key, dir) — sort menaik/menurun berdasarkan _sortValue().
// Nilai null/undefined SELALU ditaruh di akhir (data belum tersedia,
// bukan diperlakukan sebagai 0/terkecil) supaya urutan tetap masuk akal
// walau sebagian kendaraan datanya belum lengkap.
_sortRows(rows, key, dir) {
  const mul = dir === 'desc' ? -1 : 1;
  return rows.slice().sort((a, b) => {
    const va = this._sortValue(a, key);
    const vb = this._sortValue(b, key);
    const aNull = va === null || va === undefined;
    const bNull = vb === null || vb === undefined;
    if (aNull && bNull) return 0;
    if (aNull) return 1; // null selalu di akhir, apa pun arah sortnya
    if (bNull) return -1;
    if (typeof va === 'string' || typeof vb === 'string') {
      return String(va).localeCompare(String(vb)) * mul;
    }
    return (va - vb) * mul;
  });
},

// setSort(key) — dipanggil dari tap header kolom sortable (data-action).
// Tap kunci yang SAMA membalik arah (asc<->desc), tap kunci BARU reset ke
// asc — pola umum tabel sortable, 0 logic sort baru (delegasi ke
// _sortRows() lewat render()).
setSort(key) {
  if (this.sortKey === key) {
    this.sortDir = this.sortDir === 'asc' ? 'desc' : 'asc';
  } else {
    this.sortKey = key;
    this.sortDir = 'asc';
  }
  this.render();
},

// openVehicle(vehicleId) — "Selecting a vehicle opens the existing Fuel
// Intelligence Modal" (requirement task). 100% REUSE FuelModal.open()
// (SUDAH ADA, TASK-141) — 0 modal/logic buka baru, termasuk penanganan
// "Invalid vehicle" (FuelModal.open() sendiri sudah toast + tidak jadi
// buka modal kalau vehicleId tidak ditemukan, dibaca APA ADANYA).
openVehicle(vehicleId) {
  this.curVehicleId = vehicleId;
  if (typeof FuelModal !== 'undefined' && typeof FuelModal.open === 'function') {
    FuelModal.open(vehicleId);
  }
},

// _riskColor(riskLevel) — mapping tampilan murni (bukan rumus baru), pola
// sama persis _priorityColor() di fuel-dashboard.js.
_riskColor(riskLevel) {
  const map = { tinggi: 'red', sedang: 'orange', rendah: '' };
  return map[riskLevel] || '';
},

_fmtNum(v, suffix) {
  if (v === null || v === undefined) return '-';
  return Math.round(v).toLocaleString('id-ID') + (suffix || '');
},

_fmtRp(v) {
  if (v === null || v === undefined) return '-';
  return 'Rp' + Math.round(v).toLocaleString('id-ID');
},

_fmtFuel(fuel) {
  if (!fuel) return '-';
  if (fuel.remainingLiter === null || fuel.remainingLiter === undefined) return '-';
  return fuel.remainingLiter + ' L';
},

_sortHeaderBtn(label, key, activeKey, dir) {
  const active = key === activeKey;
  const arrow = active ? (dir === 'asc' ? ' ▲' : ' ▼') : '';
  return `<button type="button" class="chip-btn${active ? ' active' : ''}" data-action="FuelCompare.setSort" data-args="${escapeHtml(JSON.stringify([key]))}">${escapeHtml(label)}${arrow}</button>`;
},

// _rowHtml(row, priorityVehicleId) — 1 baris kendaraan. priorityVehicleId
// dari FuelFleetSelector.selectVehicle() (APA ADANYA) -> badge tambahan
// kalau baris ini kendaraan dgn insight prioritas tertinggi fleet-wide, 0
// logic prioritas baru ditulis di sini.
_rowHtml(row, priorityVehicleId) {
  const veh = row.vehicle;
  const s = row.summary;
  const name = (veh.emoji ? veh.emoji + ' ' : '') + veh.name;
  const healthCol = (s.healthScore === null || s.healthScore === undefined) ? ''
    : (s.healthScore >= 80 ? 'green' : (s.healthScore >= 50 ? 'orange' : 'red'));
  const riskCol = this._riskColor(s.maintenanceRisk);
  const insightHtml = s.highestInsight
    ? `<div class="u-fs11${this._riskColor(s.highestInsight.priority === 'CRITICAL' || s.highestInsight.priority === 'HIGH' ? 'tinggi' : '') ? ' red' : ''}" style="margin-top:2px;line-height:1.4">${escapeHtml(s.highestInsight.title)}</div>`
    : `<div class="u-fs11 u-t2" style="margin-top:2px">-</div>`;
  const priorityBadge = (priorityVehicleId && veh.id === priorityVehicleId)
    ? `<span class="u-fs11 red" style="font-weight:700;margin-left:6px">⚠️ Prioritas Tertinggi</span>` : '';
  return `
    <div class="u-flex u-jcb u-aic" style="padding:10px 0;border-bottom:1px solid var(--border);cursor:pointer" data-action="FuelCompare.openVehicle" data-args="${escapeHtml(JSON.stringify([veh.id]))}">
      <div style="flex:1;min-width:0">
        <div class="u-fw700">${escapeHtml(name)}${priorityBadge}</div>
        <div class="u-fs12 u-t2" style="margin-top:2px">
          Sisa: ${escapeHtml(this._fmtFuel(s.fuel))} · Jarak: ${escapeHtml(this._fmtNum(s.remainingDistance, ' km'))} · Biaya/bln: ${escapeHtml(this._fmtRp(s.monthlyCost))}
        </div>
        <div class="u-fs12 u-t2" style="margin-top:2px">
          Efisiensi: ${escapeHtml(this._fmtNum(s.efficiencyScore))} · Risiko Servis: <span class="${riskCol}">${escapeHtml(s.maintenanceRisk || '-')}</span>
        </div>
        ${insightHtml}
      </div>
      <div class="u-fw800 ${healthCol}" style="font-size:18px;margin-left:10px;white-space:nowrap">${this._fmtNum(s.healthScore)}${s.healthScore !== null && s.healthScore !== undefined ? '/100' : ''}</div>
    </div>`;
},

// render(sortKey?) — API publik satu-satunya utk menggambar comparison
// view. Dipanggil dari renderCnTab() (modules-render.js, pola sama persis
// FuelDashboard.render()) + refresh setelah transaksi BBM/servis (renderCnTab
// sendiri dipanggil ulang tiap ada perubahan tab kendaraan, pola sama
// persis refresh FuelCard/FuelDashboard).
render(sortKey) {
  const wrap = document.getElementById('fuelCompareWrap');
  const body = document.getElementById('fuelCompareBody');
  if (!wrap || !body) return;

  if (sortKey) this.sortKey = sortKey;

  const vehicles = this._vehicles();
  if (!vehicles.length) { wrap.style.display = 'none'; return; } // No vehicles

  const rows = this._rows();
  if (!rows.length) { wrap.style.display = 'none'; return; } // semua kendaraan invalid/gagal

  let priorityVehicleId = null;
  if (typeof FuelFleetSelector !== 'undefined' && typeof FuelFleetSelector.selectVehicle === 'function') {
    let sel;
    try {
      sel = FuelFleetSelector.selectVehicle();
    } catch (e) {
      sel = null;
    }
    if (sel && sel.ok) priorityVehicleId = sel.vehicleId;
  }

  const sorted = this._sortRows(rows, this.sortKey, this.sortDir);

  wrap.style.display = '';
  body.innerHTML = `
    <div class="dashhub-cat-head">
      <div class="dashhub-cat-icon">⛽</div>
      <div>
        <div class="dashhub-cat-label">Perbandingan Bahan Bakar Kendaraan</div>
        <div class="dashhub-cat-desc">${sorted.length} kendaraan</div>
      </div>
    </div>
    <div class="btn-row" style="margin-bottom:10px">
      <button class="btn btn-ghost btn-sm" data-action="FuelCompare.exportFleetHTML" aria-label="Export perbandingan seluruh armada">⬇️ Export All</button>
    </div>
    <div class="u-flex u-gap6 u-mb10" style="overflow-x:auto;padding-bottom:2px">
      ${this._sortHeaderBtn('Nama', 'name', this.sortKey, this.sortDir)}
      ${this._sortHeaderBtn('Skor Kesehatan', 'healthScore', this.sortKey, this.sortDir)}
      ${this._sortHeaderBtn('Biaya/Bulan', 'monthlyCost', this.sortKey, this.sortDir)}
      ${this._sortHeaderBtn('Sisa BBM', 'remainingFuel', this.sortKey, this.sortDir)}
    </div>
    <div>${sorted.map((r) => {
      // BUGFIX (audit pola sama S601/S608 "0 reaksi"): _rowHtml() TANPA
      // try/catch -- 1 kendaraan error bikin SELURUH .map() throw sebelum
      // body.innerHTML ke-assign, tabel tetap nampilin render sukses
      // SEBELUMNYA (tap = 0 reaksi).
      try { return this._rowHtml(r, priorityVehicleId); }
      catch (err) {
        if (typeof console !== 'undefined' && console.error) console.error('[FuelCompare.render] gagal render baris', r && r.vehicleId, err);
        return '<div class="dashhub-cat-item" style="opacity:.55">⚠️ Gagal menampilkan kendaraan ini</div>';
      }
    }).join('')}</div>
  `;
},

// ===================== TASK-155A: Export (Fleet) =====================
// PRINSIP (sama persis fuel-dashboard.js): 0 rumus/kalkulasi baru. Seluruh
// field export dibaca APA ADANYA dari _rows() (yang sendiri 100% reuse
// FuelInsightEngine.getSummary() per kendaraan, dependency yang SUDAH
// dipakai render() di atas) — export HANYA menyalin/menyusun ulang field
// yang sudah ada + urutan sort aktif (this.sortKey/this.sortDir, SUDAH
// ADA) jadi JSON/HTML. 0 storage baru. Pola download SAMA PERSIS
// fuel-dashboard.js (Blob + URL.createObjectURL + <a download> + click()).

// _buildFleetExportData() — kumpulkan 1 objek data export utk SELURUH
// armada, memakai urutan sort yang SEDANG aktif (this.sortKey/sortDir).
// `null` kalau "empty fleet" (0 kendaraan) ATAU "empty data" (semua
// kendaraan {ok:false}/tidak valid, _rows() balikin array kosong) — pola
// sama persis kondisi wrap disembunyikan di render().
_buildFleetExportData() {
  const rows = this._rows();
  if (!rows.length) return null;
  const sorted = this._sortRows(rows, this.sortKey, this.sortDir);
  return {
    exportedAt: new Date().toISOString(),
    sortKey: this.sortKey,
    sortDir: this.sortDir,
    vehicles: sorted.map((r) => ({
      id: r.vehicle.id,
      name: r.vehicle.name || '',
      emoji: r.vehicle.emoji || null,
      healthScore: r.summary.healthScore,
      efficiencyScore: r.summary.efficiencyScore,
      monthlyCost: r.summary.monthlyCost,
      remainingDistance: r.summary.remainingDistance,
      maintenanceRisk: r.summary.maintenanceRisk,
      fuel: r.summary.fuel,
      highestInsight: r.summary.highestInsight,
    })),
  };
},

// _dateTag()/_downloadFile() — helper murni, DUPLIKAT SENGAJA dari
// fuel-dashboard.js (pola yang sama dipakai project ini utk helper
// presentasi kecil, lihat _riskColor() vs _priorityColor() — bukan
// diekstrak jadi util bersama supaya kedua file tetap 100% independen,
// sama persis alasan duplikasi yang sudah ada di file ini).
_dateTag() {
  return new Date().toISOString().split('T')[0];
},

_downloadFile(filename, content, mime) {
  if (typeof document === 'undefined' || typeof document.createElement !== 'function') return false;
  if (typeof Blob === 'undefined' || typeof URL === 'undefined' || typeof URL.createObjectURL !== 'function') return false;
  try {
    const blob = new Blob([content], { type: mime });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = filename;
    a.click();
    return true;
  } catch (e) {
    return false;
  }
},

// _fleetHtmlReport(data) — laporan HTML standalone (self-contained, inline
// style, sama alasan/pola persis fuel-dashboard.js._vehicleHtmlReport()).
// Seluruh angka/teks dibaca APA ADANYA dari `data`.
_fleetHtmlReport(data) {
  const rowsHtml = data.vehicles.map((v) => `
    <tr>
      <td>${escapeHtml((v.emoji ? v.emoji + ' ' : '') + v.name)}</td>
      <td>${(v.healthScore !== null && v.healthScore !== undefined) ? v.healthScore + '/100' : '-'}</td>
      <td>${(v.fuel && v.fuel.remainingLiter !== null && v.fuel.remainingLiter !== undefined) ? v.fuel.remainingLiter + ' L' : '-'}</td>
      <td>${(v.remainingDistance !== null && v.remainingDistance !== undefined) ? Math.round(v.remainingDistance) + ' km' : '-'}</td>
      <td>${(v.monthlyCost !== null && v.monthlyCost !== undefined) ? 'Rp' + Math.round(v.monthlyCost).toLocaleString('id-ID') : '-'}</td>
      <td>${(v.efficiencyScore !== null && v.efficiencyScore !== undefined) ? v.efficiencyScore : '-'}</td>
      <td>${escapeHtml(v.maintenanceRisk || '-')}</td>
      <td>${v.highestInsight ? escapeHtml(v.highestInsight.title) : '-'}</td>
    </tr>`).join('');
  return `<!DOCTYPE html>
<html lang="id"><head><meta charset="UTF-8">
<title>Fuel Fleet Comparison</title>
<style>body{font-family:Arial,Helvetica,sans-serif;background:#f5f5f7;color:#1a1a2e;padding:24px;margin:0}
table{width:100%;border-collapse:collapse;background:#fff;border-radius:8px;overflow:hidden}
th,td{padding:8px 10px;font-size:13px;text-align:left;border-bottom:1px solid #eee}
th{background:#7c6fef;color:#fff}
.sub{color:#888;font-size:12px;margin-bottom:16px}
h1{font-size:20px;margin:0 0 4px}
</style></head>
<body>
<h1>⛽ Perbandingan Bahan Bakar Armada</h1>
<div class="sub">${data.vehicles.length} kendaraan &middot; Export ${escapeHtml(data.exportedAt)}</div>
<table><thead><tr><th>Kendaraan</th><th>Skor Kesehatan</th><th>Sisa BBM</th><th>Estimasi Jarak</th><th>Biaya/Bulan</th><th>Efisiensi</th><th>Risiko Servis</th><th>Insight Prioritas</th></tr></thead>
<tbody>${rowsHtml}</tbody></table>
</body></html>`;
},

// exportFleetJSON() — API publik. "Empty fleet"/"empty data" (0 kendaraan
// valid) -> toast peringatan + {ok:false}, TIDAK throw. Mengembalikan
// {ok,data} (data === objek export yang sama dipakai HTML) supaya bisa
// diverifikasi programatik tanpa membaca file yang diunduh.
exportFleetJSON() {
  const data = this._buildFleetExportData();
  if (!data) {
    if (typeof toast === 'function') toast('⚠️ Tidak ada data armada untuk diekspor');
    return { ok: false, reason: 'Armada kosong' };
  }
  const fname = 'fuel-fleet-' + this._dateTag() + '.json';
  const downloaded = this._downloadFile(fname, JSON.stringify(data, null, 2), 'application/json');
  if (downloaded && typeof toast === 'function') toast('✅ Export JSON armada berhasil');
  return { ok: downloaded, data };
},

// exportFleetHTML() — sama kontraknya dgn exportFleetJSON(), bedanya isi
// file yang diunduh (tabel HTML, bukan JSON mentah).
exportFleetHTML() {
  const data = this._buildFleetExportData();
  if (!data) {
    if (typeof toast === 'function') toast('⚠️ Tidak ada data armada untuk diekspor');
    return { ok: false, reason: 'Armada kosong' };
  }
  const fname = 'fuel-fleet-' + this._dateTag() + '.html';
  const downloaded = this._downloadFile(fname, this._fleetHtmlReport(data), 'text/html');
  if (downloaded && typeof toast === 'function') toast('✅ Export HTML armada berhasil');
  return { ok: downloaded, data };
},

};

// Ekspos ke window — WAJIB supaya delegasi klik global (data-action) bisa
// menemukan modul ini lewat window['FuelCompare']['setSort'] dst.
// `const FuelCompare = {...}` di atas HANYA membuat binding lexical-scope
// (bukan properti window), pola fix sama persis window.DashboardHub di
// dashboard-hub-search.js. Tanpa baris ini, tombol sort/urutan armada &
// "⬇️ Export All" tidak akan pernah berfungsi meski test lolos (test
// memanggil FuelCompare.setSort() langsung, bukan lewat jalur klik
// data-action yang sesungguhnya).
if (typeof FuelCompare !== 'undefined') window.FuelCompare = FuelCompare;

// fuel-trend-dashboard.js — Fuel Trend Dashboard (TASK-156).
//
// PRINSIP: UI HANYA presenter, 0 rumus/skoring/engine/storage baru. 100%
// REUSE (persis 4 dependency yang diminta task, dipanggil LANGSUNG — bukan
// cuma lewat FuelInsightEngine.getSummary() seperti FuelDashboard/
// FuelCompare — supaya field trend granular yang tidak diekspos
// getSummary() (mis. biaya AKTUAL vs PROYEKSI terpisah, tahun berjalan,
// rata-rata harga BBM, frekuensi isi, estimasi tanggal isi berikutnya,
// status degradasi efisiensi + dropPct, daftar rekomendasi perawatan)
// tetap 100% dibaca APA ADANYA dari engine yang sudah ada):
//   - FuelInsightEngine.getSummary(vehicleId) (TASK-149/150A) -> healthScore
//     + highestInsight dibaca apa adanya, pola SAMA PERSIS FuelDashboard.
//   - FuelCostAnalytics (TASK-147) -> monthlyCost()/yearlyCost() (histori
//     AKTUAL), projectedMonthlyCost()/projectedYearlyCost() (100% reuse
//     FuelPredictionEngine di baliknya), averageFuelPrice(),
//     refillFrequency() — SEMUA dibaca apa adanya, 0 SUM/rata-rata baru
//     dihitung ulang di sini.
//   - FuelPredictionEngine (TASK-146) -> predictRemainingDistance()/
//     predictNextRefuel()/predictMonthlyFuelUsage() — dibaca apa adanya, 0
//     rumus km/L/proyeksi baru.
//   - FuelMaintenanceEngine (TASK-148) -> fuelEfficiencyHealth() (status
//     degradasi + dropPct APA ADANYA)/maintenanceRisk()/
//     maintenanceRecommendation() (daftar teks rekomendasi APA ADANYA, 0
//     kalimat baru disusun di sini) — dibaca apa adanya.
//
// TIDAK ADA method di atas yang diubah sesi ini (audit: seluruh 4
// dependency dipakai HANYA lewat API publik yang sudah ada, 0 rumus servis/
// efisiensi/proyeksi/degradasi baru ditulis di file ini). 0 storage baru
// (tidak pernah menulis ke D). 0 chart/grafik visual (di luar scope task —
// kandidat "Chart/grafik visual utk VehicleTrendAPI.monthlyCostTrend()" di
// AI_TASK_QUEUE.md tetap BLOCKED, task ini murni tabel angka trend/
// proyeksi, bukan visualisasi grafis).
//
// Dashboard ini mengelola kendaraan aktifnya SENDIRI (this.curVehicleId,
// pola sama persis FuelDashboard.curVehicleId/FuelModal.curVehicleId/
// FuelBarCorrection.curVehicleId, SUDAH ADA) supaya TIDAK menyentuh
// FuelFleetSelector ataupun variabel global curVehicleId (dipakai tab Car
// Notes) sama sekali — konsisten dgn batasan "Jangan mengubah engine yang
// ada kecuali ditemukan bug" (tidak ada bug ditemukan sesi ini, 0 engine
// disentuh).
//
// KONTRAK render(vehicleId?): vehicleId opsional. Kalau tidak diberikan,
// pakai this.curVehicleId (kendaraan terakhir dipilih di dashboard ini)
// atau curVehicleId global (kendaraan aktif Car Notes, SUDAH ADA) sbg
// default, pola sama persis FuelDashboard.render(). Kalau vehicleId yang
// diminta tidak ditemukan di D.vehicles ("Invalid vehicle"), fallback ke
// kendaraan pertama (BUKAN menyembunyikan dashboard begitu saja), pola
// sama persis FuelDashboard. Dashboard disembunyikan
// (wrap.style.display='none') HANYA kalau: (a) 0 kendaraan sama sekali
// ("No vehicle"), atau (b) FuelInsightEngine belum dimuat, atau (c)
// FuelInsightEngine.getSummary() balikin {ok:false} utk kendaraan yang
// dicoba — sama persis kontrak FuelDashboard. Section trend individual
// (biaya/prediksi/efisiensi-perawatan) masing-masing DIJAGA per-dependency
// (guard typeof + try/catch) — kalau salah satu dependency (FuelCostAnalytics/
// FuelPredictionEngine/FuelMaintenanceEngine) belum dimuat atau method-nya
// balikin {ok:false}, section itu saja yang tampil placeholder "-",
// section lain TIDAK ikut terblokir.
const FuelTrendDashboard = {

curVehicleId: null,

_vehicles() {
  return (typeof D !== 'undefined' && Array.isArray(D.vehicles)) ? D.vehicles : [];
},

// render(vehicleId?) — API publik satu-satunya utk menggambar dashboard.
// Dipanggil dari modules/shared/modules-render.js (renderCnTab(), pola
// sama persis FuelDashboard.render()/FuelCompare.render()) &
// FuelBarCorrection.save() (refresh setelah koreksi bar tersimpan).
render(vehicleId) {
  const wrap = document.getElementById('fuelTrendWrap');
  const body = document.getElementById('fuelTrendBody');
  if (!wrap || !body) return;

  const vehicles = this._vehicles();
  if (!vehicles.length) { wrap.style.display = 'none'; return; }
  if (typeof FuelInsightEngine === 'undefined' || typeof FuelInsightEngine.getSummary !== 'function') {
    wrap.style.display = 'none';
    return;
  }

  // Tentukan kendaraan aktif: parameter -> state dashboard sendiri ->
  // curVehicleId global (kendaraan aktif Car Notes, SUDAH ADA) -> fallback
  // kendaraan pertama kalau semuanya tidak valid/tidak ada di D.vehicles
  // ("Invalid vehicle" case — TIDAK menyembunyikan dashboard begitu saja).
  let vid = vehicleId || this.curVehicleId || (typeof curVehicleId !== 'undefined' ? curVehicleId : null);
  if (!vid || !vehicles.find((v) => v.id === vid)) vid = vehicles[0].id;

  let summary;
  try {
    summary = FuelInsightEngine.getSummary(vid);
  } catch (e) {
    wrap.style.display = 'none';
    return;
  }
  if (!summary || !summary.ok) {
    wrap.style.display = 'none';
    return;
  }

  this.curVehicleId = vid;
  wrap.style.display = '';
  const trend = this._buildTrendData(vid);
  body.innerHTML = this._body(vid, vehicles, summary, trend);
},

// switchVehicle(vehicleId) — dipanggil dari tap chip kendaraan (data-action,
// lihat _vehicleChips()). Murni delegasi ke render() dgn vehicleId baru —
// 0 logic baru, supaya perilaku "kendaraan tidak ditemukan"/dsb konsisten
// dgn render() langsung.
switchVehicle(vehicleId) {
  this.render(vehicleId);
},

// _safeCall(fn) — panggil 1 method engine dgn guard typeof + try/catch,
// balikin hasilnya APA ADANYA kalau {ok:true}, atau null kalau method
// tidak ada/throw/{ok:false} — dipakai SELURUH pemanggilan engine di
// _buildTrendData() supaya 1 dependency gagal tidak menggagalkan section
// lain (pola sama semangatnya dgn guard per-field FuelInsightEngine.
// getSummary()).
_safeCall(fn) {
  if (typeof fn !== 'function') return null;
  try {
    const res = fn();
    return (res && res.ok) ? res : null;
  } catch (e) {
    return null;
  }
},

// _buildTrendData(vid) — kumpulkan SELURUH field trend/proyeksi dari 4
// dependency yang diminta task, masing-masing dibaca APA ADANYA (0 rumus
// baru). Setiap field individual bisa null (dependency belum dimuat/data
// belum cukup) — TIDAK memblokir field lain, pola sama persis
// FuelInsightEngine.getSummary().
_buildTrendData(vid) {
  const hasCost = typeof FuelCostAnalytics !== 'undefined';
  const hasPred = typeof FuelPredictionEngine !== 'undefined';
  const hasMaint = typeof FuelMaintenanceEngine !== 'undefined';
  return {
    monthlyCost: hasCost ? this._safeCall(() => FuelCostAnalytics.monthlyCost(vid)) : null,
    projectedMonthlyCost: hasCost ? this._safeCall(() => FuelCostAnalytics.projectedMonthlyCost(vid)) : null,
    yearlyCost: hasCost ? this._safeCall(() => FuelCostAnalytics.yearlyCost(vid)) : null,
    projectedYearlyCost: hasCost ? this._safeCall(() => FuelCostAnalytics.projectedYearlyCost(vid)) : null,
    averageFuelPrice: hasCost ? this._safeCall(() => FuelCostAnalytics.averageFuelPrice(vid)) : null,
    refillFrequency: hasCost ? this._safeCall(() => FuelCostAnalytics.refillFrequency(vid)) : null,
    remainingDistance: hasPred ? this._safeCall(() => FuelPredictionEngine.predictRemainingDistance(vid)) : null,
    nextRefuel: hasPred ? this._safeCall(() => FuelPredictionEngine.predictNextRefuel(vid)) : null,
    monthlyUsage: hasPred ? this._safeCall(() => FuelPredictionEngine.predictMonthlyFuelUsage(vid)) : null,
    efficiencyHealth: hasMaint ? this._safeCall(() => FuelMaintenanceEngine.fuelEfficiencyHealth(vid)) : null,
    maintenanceRisk: hasMaint ? this._safeCall(() => FuelMaintenanceEngine.maintenanceRisk(vid)) : null,
    maintenanceRecommendation: hasMaint ? this._safeCall(() => FuelMaintenanceEngine.maintenanceRecommendation(vid)) : null,
  };
},

// _vehicleChips(vehicles, activeId) — switcher multi-kendaraan, pola SAMA
// PERSIS FuelDashboard._vehicleChips() (duplikasi kecil disengaja, sama
// pola dgn duplikasi kecil lain yang sudah ada di project ini, mis.
// _priorityColor() vs _riskColor() — supaya modul ini tetap 100%
// independen). Disembunyikan kalau cuma 1 kendaraan.
_vehicleChips(vehicles, activeId) {
  if (vehicles.length < 2) return '';
  return `<div class="u-flex u-gap6 u-mb10" style="overflow-x:auto;padding-bottom:2px">`
    + vehicles.map((v) => `<button type="button" class="chip-btn${v.id === activeId ? ' active' : ''}" data-action="FuelTrendDashboard.switchVehicle" data-args="${escapeHtml(JSON.stringify([v.id]))}">${escapeHtml(v.emoji ? v.emoji + ' ' : '')}${escapeHtml(v.name)}</button>`).join('')
    + `</div>`;
},

// _priorityColor(priority) — mapping tampilan murni (bukan rumus/skoring
// baru), pola sama persis FuelDashboard._priorityColor().
_priorityColor(priority) {
  const map = { CRITICAL: 'red', HIGH: 'red', MEDIUM: 'orange', LOW: '', INFO: '' };
  return map[priority] || '';
},

// _rp(n) — format Rupiah tampilan murni, pola sama persis dipakai
// fuel-dashboard.js (Math.round + toLocaleString('id-ID')), 0 rumus baru.
_rp(n) {
  return (n === null || n === undefined) ? '-' : 'Rp' + Math.round(n).toLocaleString('id-ID');
},

// _row(label, value) — 1 baris label/value murni tampilan, dipakai
// berulang di seluruh section supaya markup konsisten & ringkas.
_row(label, value) {
  return `<div class="u-flex u-jcb u-aic u-fs12" style="margin-bottom:6px"><span class="u-t2">${escapeHtml(label)}</span><span class="u-fw700">${escapeHtml(String(value))}</span></div>`;
},

// _section(title, innerHtml) — bungkus 1 section trend dgn judul, pola
// tampilan murni dipakai berulang.
_section(title, innerHtml) {
  return `<div style="margin-bottom:12px">
    <div class="u-fs11 u-t2 u-fw800" style="text-transform:uppercase;letter-spacing:0.6px;margin-bottom:6px">${escapeHtml(title)}</div>
    ${innerHtml}
  </div>`;
},

// _costSectionHtml(trend) — biaya BBM AKTUAL (histori bulan/tahun
// berjalan, FuelCostAnalytics.monthlyCost()/yearlyCost()) DAN PROYEKSI
// (FuelCostAnalytics.projectedMonthlyCost()/projectedYearlyCost(), yang
// sendiri 100% reuse FuelPredictionEngine) berdampingan — SEMUA angka
// dibaca apa adanya, 0 rumus baru. Field yang datanya belum tersedia
// tampil "-" (tidak memblokir baris lain).
_costSectionHtml(trend) {
  const rows = [
    this._row('Bulan Ini (Aktual)', trend.monthlyCost ? this._rp(trend.monthlyCost.totalCost) : '-'),
    this._row('Proyeksi Bulan Ini', trend.projectedMonthlyCost ? this._rp(trend.projectedMonthlyCost.estimatedCost) : '-'),
    this._row('Tahun Ini (Aktual)', trend.yearlyCost ? this._rp(trend.yearlyCost.totalCost) : '-'),
    this._row('Proyeksi Tahun Ini', trend.projectedYearlyCost ? this._rp(trend.projectedYearlyCost.estimatedCost) : '-'),
    this._row('Rata-rata Harga BBM', trend.averageFuelPrice ? this._rp(trend.averageFuelPrice.averagePrice) + '/L' : '-'),
    this._row('Frekuensi Isi BBM', trend.refillFrequency ? `${trend.refillFrequency.refillCount}x, rata-rata ${trend.refillFrequency.averageIntervalDays} hari` : '-'),
  ].join('');
  return this._section('Biaya & Frekuensi BBM', rows);
},

// _predictionSectionHtml(trend) — prediksi jarak tersisa/isi ulang
// berikutnya/pemakaian bulan depan, 100% REUSE FuelPredictionEngine, 0
// rumus baru.
_predictionSectionHtml(trend) {
  const rows = [
    this._row('Estimasi Jarak Tersisa', trend.remainingDistance ? `${Math.round(trend.remainingDistance.remainingKm)} km` : '-'),
    this._row('Prediksi Isi BBM Berikutnya', trend.nextRefuel ? `${trend.nextRefuel.estimatedDate || '-'} (${trend.nextRefuel.estimatedRemainingDays} hari lagi)` : '-'),
    this._row('Proyeksi Pemakaian Bulan Depan', trend.monthlyUsage ? `${trend.monthlyUsage.estimatedLiter} L (${this._rp(trend.monthlyUsage.estimatedCost)})` : '-'),
  ].join('');
  return this._section('Prediksi', rows);
},

// _maintenanceSectionHtml(trend) — status kesehatan efisiensi (termasuk
// trend dropPct kalau terdeteksi degradasi) + risiko perawatan +
// rekomendasi teks, 100% REUSE FuelMaintenanceEngine, 0 rumus baru.
_maintenanceSectionHtml(trend) {
  const eff = trend.efficiencyHealth;
  const effRows = eff
    ? [
        this._row('Status Efisiensi', eff.status === 'menurun' ? `Menurun (-${eff.dropPct}%)` : 'Baik'),
        this._row('km/Liter Saat Ini', `${eff.kmPerLiter}`),
        this._row('Rp/km Saat Ini', this._rp(eff.rpPerKm)),
      ].join('')
    : this._row('Status Efisiensi', '-');
  const risk = trend.maintenanceRisk;
  const riskRow = this._row('Risiko Perawatan', risk ? risk.riskLevel : '-');
  const recs = trend.maintenanceRecommendation && trend.maintenanceRecommendation.recommendations && trend.maintenanceRecommendation.recommendations.length
    ? `<ul class="u-fs12 u-t2" style="margin:6px 0 0;padding-left:18px">${trend.maintenanceRecommendation.recommendations.map((r) => `<li>${escapeHtml(r)}</li>`).join('')}</ul>`
    : '';
  return this._section('Efisiensi & Perawatan', effRows + riskRow + recs);
},

// _highestInsightHtml(insight) — summary.highestInsight APA ADANYA
// (FuelInsightEngine.getInsights(), sudah diurutkan prioritas oleh engine
// itu sendiri) — 0 logic sortir/prioritas baru ditulis di sini, pola sama
// persis FuelDashboard._highestInsightHtml(). `null` -> baris ini
// dilewati.
_highestInsightHtml(insight) {
  if (!insight) return '';
  const col = this._priorityColor(insight.priority);
  return this._section('Insight Prioritas Tertinggi', `<div class="u-fs12${col ? ' ' + col : ''}" style="line-height:1.5"><b>${escapeHtml(insight.title)}</b><br>${escapeHtml(insight.description)}</div>`);
},

// _body(vid, vehicles, summary, trend) — susun 1 kartu Fuel Trend
// Dashboard: header + (kalau >1 kendaraan) switcher + section biaya &
// frekuensi + section prediksi + section efisiensi & perawatan + insight
// prioritas tertinggi + CTA (100% reuse FuelModal.open()/
// FuelBarCorrection.open(), pola SAMA PERSIS baris CTA fuel-dashboard.js).
_body(vid, vehicles, summary, trend) {
  const veh = vehicles.find((v) => v.id === vid);
  const name = veh ? (veh.emoji ? veh.emoji + ' ' : '') + veh.name : '';
  return `
    <div class="dashhub-cat-head">
      <div class="dashhub-cat-icon">📈</div>
      <div>
        <div class="dashhub-cat-label">Fuel Trend Dashboard</div>
        <div class="dashhub-cat-desc">${escapeHtml(name)}</div>
      </div>
    </div>
    ${this._vehicleChips(vehicles, vid)}
    ${this._costSectionHtml(trend)}
    ${this._predictionSectionHtml(trend)}
    ${this._maintenanceSectionHtml(trend)}
    ${this._highestInsightHtml(summary.highestInsight)}
    <div class="btn-row" style="margin-bottom:0">
      <button class="btn btn-ghost btn-sm" data-action="FuelModal.open" data-args="${escapeHtml(JSON.stringify([vid]))}">📊 Lihat Detail</button>
      <button class="btn btn-ghost btn-sm" data-action="FuelBarCorrection.open" data-args="${escapeHtml(JSON.stringify([vid]))}" aria-label="Koreksi estimasi BBM dengan speedometer">⚙️ Koreksi</button>
    </div>
  `;
},

};

// Ekspos ke window — WAJIB supaya delegasi klik global (data-action) bisa
// menemukan modul ini lewat window['FuelTrendDashboard']['switchVehicle']
// dst. `const FuelTrendDashboard = {...}` di atas HANYA membuat binding
// lexical-scope (bukan properti window), pola fix sama persis
// window.DashboardHub di dashboard-hub-search.js. Tanpa baris ini, chip
// pilih kendaraan, "📊 Lihat Detail" & "⚙️ Koreksi" di Fuel Trend
// Dashboard tidak akan pernah berfungsi meski test lolos (test memanggil
// fungsi langsung, bukan lewat jalur klik data-action yang sesungguhnya).
if (typeof FuelTrendDashboard !== 'undefined') window.FuelTrendDashboard = FuelTrendDashboard;

// modules/vehicle/vehicle-decision-api.js — Vehicle Decision API
// (Sesi 82, Batch 7). Lihat docs/BATCH_PLAN.md § Batch 7.
//
// PRINSIP (RULE #1 sesi ini): 100% REUSE VehicleAIHook.fleetSummary()/
// .vehicleInsight(vehicleId) (modules/vehicle/vehicle-ai-hook.js, Sesi 79
// — sendiri sudah gabungan VehicleIntelligence.summary() (Sesi 76) +
// VehicleReminder.summary() (Sesi 78)) — TIDAK ada rumus baru, TIDAK
// menghitung ulang health score/reminder/insight apa pun, TIDAK
// mengubah struktur data D. Satu-satunya "logic" di file ini adalah
// memilih apakah memanggil fleetSummary() (tanpa vehicleId) atau
// vehicleInsight(vehicleId) (dengan vehicleId) & membungkus hasilnya jadi
// bentuk seragam `{ok, vehicleId, intelligence, reminder}` — pola sama
// persis wrapper tipis VehicleAIHook sendiri terhadap Intelligence+
// Reminder.
//
// Tujuan: 1 pintu masuk TUNGGAL utk seluruh lapisan Decision Engine sesi
// ini (VehicleRecommendationEngine dst di bawahnya HANYA boleh baca lewat
// file ini, bukan panggil VehicleAIHook/VehicleIntelligence/
// VehicleReminder langsung — supaya kalau sumber data decision berubah di
// masa depan, cukup diubah di 1 tempat). TIDAK ada UI/panel di file ini.
const VehicleDecisionAPI = {

// context(vehicleId?) — titik masuk tunggal data mentah utk Decision
// Engine. Tanpa vehicleId: fleet-level (reuse VehicleAIHook.
// fleetSummary()). Dengan vehicleId: 1 kendaraan (reuse VehicleAIHook.
// vehicleInsight(vehicleId), termasuk {ok:false} kalau kendaraan tidak
// ditemukan — reuse apa adanya, TIDAK menduplikasi pengecekan). {ok:false}
// kalau VehicleAIHook belum dimuat (guard urutan load / dipakai headless
// di test, pola sama persis guard {ok:false} di VehicleAIHook sendiri).
context(vehicleId) {
  if (typeof VehicleAIHook === 'undefined') {
    return { ok: false, reason: 'VehicleAIHook belum dimuat' };
  }
  const hook = vehicleId ? VehicleAIHook.vehicleInsight(vehicleId) : VehicleAIHook.fleetSummary();
  if (!hook.ok) return hook;
  return {
    ok: true,
    vehicleId: vehicleId || null,
    intelligence: hook.intelligence,
    reminder: hook.reminder,
  };
},

};

// modules/vehicle/vehicle-recommendation-engine.js — Vehicle
// Recommendation Engine (Sesi 82, Batch 7). Lihat docs/BATCH_PLAN.md §
// Batch 7.
//
// PRINSIP (RULE #1 sesi ini): 100% REUSE VehicleDecisionAPI.context()
// (modules/vehicle/vehicle-decision-api.js, sesi ini — sendiri 100% reuse
// VehicleAIHook) — TIDAK menghitung ulang severity/status apa pun
// (severity 'overdue'/'due-soon' dari VehicleReminder & type
// 'warning' dari VehicleIntelligence.insights() dibaca APA ADANYA).
// Satu-satunya logic genuinely baru sesi ini: MEMILIH item mana dari
// reminder.all + insights yang layak jadi "recommendation" (filter, bukan
// recompute — pola sama persis VehicleAlertPanel/VehicleInsightFeed yang
// juga cuma filter array yang sudah ada) & MENYERAGAMKAN bentuknya jadi 1
// shape recommendation (`{id, source, type, vehicleId, vehicleName,
// severity, message}`) yang dipakai lapisan Priority Scoring & Action
// Recommendation di bawahnya.
//
// reminder.all severity 'info' (mis. data BBM belum cukup) SENGAJA
// dilewati — bukan hal yang perlu "direkomendasikan" tindakan, pola sama
// persis VehicleAlertPanel (HANYA overdue) & VehicleInsightFeed (overdue+
// due-soon, TANPA info). insights type 'info'/'positive' juga dilewati —
// HANYA 'warning' yang genuinely butuh tindakan (pola sama persis
// VehicleInsightFeed yang membedakan icon per type, tapi di sini
// benar-benar difilter krn recommendation ≠ feed tampilan).
//
// TIDAK ada UI/panel di file ini — presenter-nya file terpisah
// (modules/vehicle/vehicle-decision-presenter.js, sesi ini juga).
const VehicleRecommendationEngine = {

// _fromReminders(reminderAll) — helper internal: ubah item
// VehicleReminder.summary().all (severity 'overdue'/'due-soon' saja,
// 'info' dilewati) jadi bentuk recommendation seragam. message/severity/
// vehicleId/vehicleName dibaca APA ADANYA dari item reminder, TIDAK ada
// teks baru yang dikarang di sini (teks aksi konkret ada di
// VehicleActionRecommendation, terpisah dari message reminder ini).
_fromReminders(reminderAll) {
  return (Array.isArray(reminderAll) ? reminderAll : [])
    .filter((r) => r.severity === 'overdue' || r.severity === 'due-soon')
    .map((r) => ({
      id: `reminder-${r.type}-${r.vehicleId}-${r.categoryName || r.taxKey || 'fuel'}`,
      source: 'reminder',
      type: r.type,
      vehicleId: r.vehicleId,
      vehicleName: r.vehicleName,
      severity: r.severity,
      message: r.message,
    }));
},

// _fromInsights(insightsList, vehicleId) — helper internal: ubah insight
// VehicleIntelligence.insights() (type 'warning' saja, 'info'/'positive'
// dilewati) jadi bentuk recommendation seragam. vehicleId dilampirkan apa
// adanya dari parameter (fleet-level kalau null/undefined) krn insight
// fleet-level sendiri tidak menyimpan vehicleId per item.
_fromInsights(insightsList, vehicleId) {
  return (Array.isArray(insightsList) ? insightsList : [])
    .filter((i) => i.type === 'warning')
    .map((i) => ({
      id: `insight-${i.code}-${vehicleId || 'fleet'}`,
      source: 'insight',
      type: 'insight',
      vehicleId: vehicleId || null,
      vehicleName: null,
      severity: 'warning',
      message: i.message,
    }));
},

// recommendations(vehicleId?) — daftar recommendation gabungan reminder
// (overdue/due-soon) + insight (warning), 100% reuse VehicleDecisionAPI.
// context(). Tanpa vehicleId: insight fleet-level dari
// `intelligence.insights` (VehicleIntelligence.summary() base, SELALU
// fleet-level apa pun vehicleId-nya — lihat komentar VehicleIntelligence.
// summary()). Dengan vehicleId: insight KENDARAAN itu dari
// `intelligence.vehicleInsights` (bukan `intelligence.insights` yg tetap
// fleet-level). Array kosong (bukan throw) kalau VehicleDecisionAPI belum
// dimuat atau context() {ok:false} — pola sama persis VehicleAlertPanel/
// VehicleInsightFeed yang silent-kosong kalau data belum tersedia.
recommendations(vehicleId) {
  if (typeof VehicleDecisionAPI === 'undefined') return [];
  const ctx = VehicleDecisionAPI.context(vehicleId);
  if (!ctx.ok) return [];
  const reminderItems = this._fromReminders(ctx.reminder && ctx.reminder.all);
  const insightsList = vehicleId
    ? (ctx.intelligence && ctx.intelligence.vehicleInsights)
    : (ctx.intelligence && ctx.intelligence.insights);
  const insightItems = this._fromInsights(insightsList, vehicleId);
  return [...reminderItems, ...insightItems];
},

};

// modules/vehicle/vehicle-priority-scoring.js — Vehicle Priority Scoring
// (Sesi 82, Batch 7). Lihat docs/BATCH_PLAN.md § Batch 7.
//
// PRINSIP (RULE #1 sesi ini): 100% REUSE field `severity` yang SUDAH ADA
// di tiap recommendation (VehicleRecommendationEngine.recommendations(),
// sesi ini — severity itu sendiri reuse apa adanya dari VehicleReminder/
// VehicleIntelligence, TIDAK dihitung ulang) — TIDAK menyentuh D, TIDAK
// membaca service lain sama sekali. Satu-satunya logic genuinely baru
// sesi ini: tabel bobot skor per severity (`SEVERITY_WEIGHT`) & fungsi
// pengurutan berdasarkan skor itu — pola KOMPOSIT sama persis
// VehicleIntelligence.healthScore() (skor 0-100 dari bobot per komponen),
// bedanya di sini input-nya 1 field severity (bukan beberapa komponen
// digabung) jadi tabel lookup datar, bukan rata-rata tertimbang.
//
// Urutan prioritas (tertinggi→terendah), rasional bisnis: 'overdue'
// (servis/pajak/BBM sudah lewat jatuh tempo — risiko langsung) >
// 'warning' (insight VehicleIntelligence, mis. health score rendah —
// kondisi umum perlu perhatian tapi belum ada tenggat konkret) >
// 'due-soon' (akan jatuh tempo, masih ada waktu bersiap). TIDAK ada
// ambang baru diciptakan — urutan ini murni PEMOSISIAN 3 nilai severity
// yang SUDAH ADA, bukan threshold numerik baru atas data mentah.
//
// TIDAK ada UI/panel di file ini — presenter-nya file terpisah
// (modules/vehicle/vehicle-decision-presenter.js, sesi ini juga).
const VehiclePriorityScoring = {

// SEVERITY_WEIGHT — tabel skor 0-100 per severity, SATU-SATUNYA "rumus"
// baru sesi ini. Nilai lain (default 0) dijaga eksplisit di score() kalau
// suatu saat ada severity baru yang belum terdaftar di sini (fail-safe,
// bukan throw).
SEVERITY_WEIGHT: {
  overdue: 100,
  warning: 60,
  'due-soon': 40,
},

// score(recommendation) — skor prioritas 0-100 dari 1 recommendation,
// murni lookup SEVERITY_WEIGHT berdasarkan field `severity` yang sudah
// ada di recommendation (reuse VehicleRecommendationEngine, TIDAK ada
// input lain yang dibaca).
score(recommendation) {
  const severity = recommendation && recommendation.severity;
  return this.SEVERITY_WEIGHT[severity] || 0;
},

// rank(recommendations) — array recommendation yang sama, ditambah field
// `priorityScore` (dari score() di atas) & diurutkan menurun (skor
// tertinggi dulu). Urutan asli (sesama skor sama) dipertahankan (stable
// sort — Array.prototype.sort di Node.js modern sudah stable) — TIDAK ada
// tie-breaker tambahan yang dikarang di sini.
rank(recommendations) {
  return (Array.isArray(recommendations) ? recommendations : [])
    .map((r) => ({ ...r, priorityScore: this.score(r) }))
    .sort((a, b) => b.priorityScore - a.priorityScore);
},

};

// modules/vehicle/vehicle-action-recommendation.js — Vehicle Action
// Recommendation (Sesi 82, Batch 7). Lihat docs/BATCH_PLAN.md § Batch 7.
//
// PRINSIP (RULE #1 sesi ini): 100% REUSE field `type`/`severity` yang
// SUDAH ADA di tiap recommendation (VehicleRecommendationEngine.
// recommendations(), sesi ini) — TIDAK menyentuh D, TIDAK membaca service
// lain sama sekali, TIDAK menghitung apa pun. Satu-satunya "logic" sesi
// ini adalah tabel lookup teks aksi konkret (`ACTION_MAP`) murni
// presentasional — pola sama persis _icon(type) di VehicleAlertPanel/
// _insightIcon(type) di VehicleInsightFeed (pemetaan type→teks/ikon,
// BUKAN rumus baru, tipe & severity itu sendiri sudah final dari lapisan
// di bawahnya).
//
// TIDAK ada UI/panel di file ini — presenter-nya file terpisah
// (modules/vehicle/vehicle-decision-presenter.js, sesi ini juga).
const VehicleActionRecommendation = {

// ACTION_MAP — lookup [type][severity] → label aksi konkret Bahasa
// Indonesia. type 'service'/'tax'/'fuel' dari VehicleReminder (reuse apa
// adanya), type 'insight' dari VehicleIntelligence.insights() (SELALU
// severity 'warning' di recommendation — lihat VehicleRecommendationEngine
// ._fromInsights()). Murni teks tetap, TIDAK ada logic kondisional di
// balik tabel ini.
ACTION_MAP: {
  service: {
    overdue: 'Jadwalkan servis sekarang',
    'due-soon': 'Rencanakan servis dalam waktu dekat',
  },
  tax: {
    overdue: 'Segera perpanjang pajak/dokumen kendaraan',
    'due-soon': 'Siapkan perpanjangan pajak/dokumen kendaraan',
  },
  fuel: {
    overdue: 'Isi BBM sekarang',
    'due-soon': 'Rencanakan isi BBM dalam waktu dekat',
  },
  insight: {
    warning: 'Tinjau kondisi kendaraan',
  },
},

// DEFAULT_LABEL — fallback kalau kombinasi type/severity belum terdaftar
// di ACTION_MAP (fail-safe, bukan throw — pola sama persis fallback '⛔'
// di VehicleAlertPanel._icon()/'ℹ️' di VehicleInsightFeed._insightIcon()).
DEFAULT_LABEL: 'Tinjau kendaraan',

// actionFor(recommendation) — {label} aksi konkret utk 1 recommendation,
// murni lookup ACTION_MAP[type][severity] apa adanya, fallback
// DEFAULT_LABEL kalau kombinasi belum terdaftar.
actionFor(recommendation) {
  const type = recommendation && recommendation.type;
  const severity = recommendation && recommendation.severity;
  const byType = this.ACTION_MAP[type] || {};
  return { label: byType[severity] || this.DEFAULT_LABEL };
},

// withAction(recommendations) — array recommendation yang sama, ditambah
// field `action` (dari actionFor() di atas). 0 transformasi field lain.
withAction(recommendations) {
  return (Array.isArray(recommendations) ? recommendations : [])
    .map((r) => ({ ...r, action: this.actionFor(r) }));
},

};

// modules/vehicle/vehicle-decision-presenter.js — Vehicle Decision
// Presenter (Sesi 82, Batch 7). Lihat docs/BATCH_PLAN.md § Batch 7.
//
// PRINSIP (RULE #1 sesi ini): UI HANYA presenter. 100% REUSE
// VehicleRecommendationEngine.recommendations() + VehiclePriorityScoring.
// rank() + VehicleActionRecommendation.withAction() (ketiganya sesi ini)
// — TIDAK ada rumus baru, TIDAK menghitung ulang severity/priorityScore/
// action apa pun di file ini, TIDAK membaca D langsung sama sekali (pola
// sama persis VehicleAnalyticsPresenter/VehicleInsightPresenter yang juga
// 0 pembacaan D). Satu-satunya operasi presentasional di sini: pemetaan
// type→ikon & severity→warna border (MURNI tampilan, pola sama persis
// _icon(type) di VehicleAlertPanel/_insightIcon(type) di
// VehicleInsightFeed) & pembatasan maks 5 item ditampilkan (pola sama
// persis .slice(0, 8) di VehicleInsightFeed).
//
// Pola SILENT-kalau-kosong sama persis VehicleAlertPanel/VehicleInsightFeed
// — TIDAK menambah ruang kosong permanen kalau tidak ada recommendation
// (armada aman).
//
// Dipanggil dari renderCnTab() (modules/shared/modules-render.js) — DIPINDAH dari
// DashboardHub.render() di Sesi 133, live-wiring renderDashboard() DIHAPUS di Sesi 134
// (gap fix, sudah dobel dgn renderCnTab(), lihat CHANGELOG.md Sesi 134)
// (modules/shared/modules-render.js), TIDAK ada mekanisme render baru.
//
// CSS: TIDAK ada class baru — reuse penuh var(--accent)/var(--accent2)/
// var(--accent4) (styles.css, SUDAH ADA per-tema) & class utilitas
// u-fs11/u-fs12/u-lh15/u-t2/u-mb6/u-fw700 (SUDAH dipakai VehicleAlertPanel/
// VehicleInsightFeed) apa adanya.
const VehicleDecisionPresenter = {

// _icon(type) — pemetaan type recommendation ('service'/'tax'/'fuel'/
// 'insight') ke emoji, MURNI presentasional, pola sama persis
// VehicleAlertPanel._icon()/VehicleInsightFeed._insightIcon() (tipe itu
// sendiri sudah ada di tiap recommendation dari VehicleRecommendationEngine).
_icon(type) {
  return { service: '🔧', tax: '📋', fuel: '⛽', insight: '💡' }[type] || '⛔';
},

// _borderColor(severity) — pemetaan severity ('overdue'/'due-soon'/
// 'warning') ke token warna tema yang SUDAH ADA (styles.css), MURNI
// presentasional — TIDAK ada token CSS baru.
_borderColor(severity) {
  return { overdue: 'var(--accent4)', 'due-soon': 'var(--accent)', warning: 'var(--accent2)' }[severity] || 'var(--accent4)';
},

_row(r) {
  return `
    <div class="u-fs12 u-lh15 u-t2 u-mb6" style="border-left:3px solid ${this._borderColor(r.severity)};padding-left:8px;">
      <div>${this._icon(r.type)} ${escapeHtml(r.message)}</div>
      <div class="u-fs11 u-fw700 u-t2" style="opacity:.8;">→ ${escapeHtml(r.action.label)}</div>
    </div>
  `;
},

render() {
  const el = document.getElementById('vehDecisionBody');
  if (!el) return; // container belum ada di halaman ini, aman diam2.

  if (typeof VehicleRecommendationEngine === 'undefined'
    || typeof VehiclePriorityScoring === 'undefined'
    || typeof VehicleActionRecommendation === 'undefined') {
    el.innerHTML = '';
    return;
  }

  const recommendations = VehicleRecommendationEngine.recommendations();
  if (!recommendations.length) { el.innerHTML = ''; return; }

  const ranked = VehiclePriorityScoring.rank(recommendations);
  const withAction = VehicleActionRecommendation.withAction(ranked);
  const top = withAction.slice(0, 5);

  // BUGFIX (audit pola sama S601/S608 "0 reaksi"): _row() TANPA try/catch --
  // 1 rekomendasi error bikin SELURUH .map() throw sebelum el.innerHTML
  // ke-assign, kartu tetap nampilin render sukses SEBELUMNYA (tap = 0 reaksi).
  const rows = top.map((r) => {
    try { return this._row(r); }
    catch (err) {
      if (typeof console !== 'undefined' && console.error) console.error('[VehicleDecisionPresenter.render] gagal render baris', r && r.vehicleId, err);
      return '';
    }
  }).join('');
  el.innerHTML = `<div class="u-fs11 u-fw700 u-t2 u-mb6 u-mt10">🧭 Rekomendasi Kendaraan</div>${rows}`;
},

};

// modules/vehicle/vehicle-attention-presenter.js — Vehicle Attention Card
// (Sesi 156b, permintaan eksplisit user: gabungkan VehicleAlertPanel +
// VehicleInsightFeed + VehicleDecisionPresenter jadi SATU card ranked
// "🧭 Perlu Perhatian" — satu daftar/satu prioritas, bukan 3 versi beda
// dari info yang sama.
//
// PRINSIP: UI HANYA presenter, 0 rumus/skoring baru — 100% REUSE:
//  - Item actionable (servis/pajak/BBM/insight peringatan) diambil dari
//    VehicleRecommendationEngine.recommendations() -> VehiclePriorityScoring.
//    rank() -> VehicleActionRecommendation.withAction() — persis alur yang
//    dulu dipakai VehicleDecisionPresenter, TIDAK diubah sama sekali.
//    VehicleRecommendationEngine SUDAH mencakup reminder severity
//    'overdue'/'due-soon' (dulu tampil terpisah di VehicleAlertPanel/
//    VehicleInsightFeed) + insight type 'warning' (lihat komentar
//    _fromReminders()/_fromInsights() di vehicle-recommendation-engine.js)
//    — jadi sumber ini SUDAH superset dari isi VehicleAlertPanel & sebagian
//    besar VehicleInsightFeed, TIDAK perlu dihitung ulang di sini.
//  - Sisanya (insight fleet-level type 'info'/'positive' yang SENGAJA
//    dilewati VehicleRecommendationEngine krn bukan hal actionable) diambil
//    langsung dari VehicleAIHook.fleetSummary().intelligence.insights
//    (persis sumber data VehicleInsightFeed yang lama), ditampilkan SETELAH
//    item actionable sbg baris info tambahan (bukan actionable, tidak ada
//    CTA/action label).
//
// VehicleAlertPanel.render()/VehicleInsightFeed.render()/
// VehicleDecisionPresenter.render() (file lama, tidak dihapus utk histori)
// TIDAK LAGI dipanggil dari renderCnTab() (modules/shared/modules-render.js)
// — diganti panggilan tunggal VehicleAttentionPresenter.render(), mengisi
// container tunggal #vehAttentionBody (index.html/app_production.html).
//
// Pola SILENT-kalau-kosong sama persis panel lama — body dikosongkan kalau
// tidak ada actionable item maupun insight info/positive apa pun (armada
// aman).
const VehicleAttentionPresenter = {

  // _icon(type)/_borderColor(severity) — pemetaan MURNI presentasional,
  // persis sama dgn VehicleDecisionPresenter/VehicleAlertPanel yang lama
  // (tipe & severity itu sendiri sudah final dari engine yang direuse).
  _icon(type) {
    return { service: '🔧', tax: '📋', fuel: '⛽', insight: '💡' }[type] || 'ℹ️';
  },

  _borderColor(severity) {
    return { overdue: 'var(--accent4)', 'due-soon': 'var(--accent)', warning: 'var(--accent2)' }[severity] || 'var(--accent4)';
  },

  _insightIcon(type) {
    return { warning: '🟡', positive: '🟢', info: 'ℹ️' }[type] || 'ℹ️';
  },

  _actionRow(r) {
    return `
      <div class="u-fs12 u-lh15 u-t2 u-mb6" style="border-left:3px solid ${this._borderColor(r.severity)};padding-left:8px;">
        <div>${this._icon(r.type)} ${escapeHtml(r.message)}</div>
        <div class="u-fs11 u-fw700 u-t2" style="opacity:.8;">→ ${escapeHtml(r.action.label)}</div>
      </div>
    `;
  },

  _insightRow(item) {
    return `
      <div style="padding:8px 0;border-bottom:1px solid var(--border,rgba(255,255,255,.08));font-size:13px;">
        ${item.icon} ${escapeHtml(item.message)}
      </div>
    `;
  },

  render() {
    const el = document.getElementById('vehAttentionBody');
    if (!el) return; // container belum ada di halaman ini, aman diam2.

    // Bagian actionable (ranked) — persis alur VehicleDecisionPresenter lama.
    let actionRows = '';
    if (typeof VehicleRecommendationEngine !== 'undefined'
      && typeof VehiclePriorityScoring !== 'undefined'
      && typeof VehicleActionRecommendation !== 'undefined') {
      const recommendations = VehicleRecommendationEngine.recommendations();
      if (recommendations.length) {
        const ranked = VehiclePriorityScoring.rank(recommendations);
        const withAction = VehicleActionRecommendation.withAction(ranked);
        const top = withAction.slice(0, 6);
        // BUGFIX (audit pola sama S601/S608 "0 reaksi"): _actionRow() TANPA
        // try/catch -- 1 rekomendasi error bikin SELURUH .map() throw sebelum
        // el.innerHTML ke-assign, kartu tetap nampilin render sukses SEBELUMNYA.
        actionRows = top.map((r) => {
          try { return this._actionRow(r); }
          catch (err) {
            if (typeof console !== 'undefined' && console.error) console.error('[VehicleAttentionPresenter.render] gagal render actionRow', r && r.vehicleId, err);
            return '';
          }
        }).join('');
      }
    }

    // Bagian insight info/positive (non-actionable, SENGAJA dilewati
    // VehicleRecommendationEngine) — persis sumber data VehicleInsightFeed
    // lama, tapi HANYA type 'info'/'positive' (type 'warning' sudah masuk
    // di bagian actionable di atas lewat VehicleRecommendationEngine,
    // supaya tidak tampil dobel).
    let insightRows = '';
    if (typeof VehicleAIHook !== 'undefined') {
      const hook = VehicleAIHook.fleetSummary();
      if (hook.ok) {
        const insightItems = ((hook.intelligence && hook.intelligence.insights) || [])
          .filter((ins) => ins.type !== 'warning')
          .map((ins) => ({ icon: this._insightIcon(ins.type), message: ins.message }));
        insightRows = insightItems.slice(0, 3).map((item) => {
          try { return this._insightRow(item); }
          catch (err) {
            if (typeof console !== 'undefined' && console.error) console.error('[VehicleAttentionPresenter.render] gagal render insightRow', err);
            return '';
          }
        }).join('');
      }
    }

    if (!actionRows && !insightRows) { el.innerHTML = ''; return; }

    el.innerHTML = `<div class="u-fs11 u-fw700 u-t2 u-mb6 u-mt10">🧭 Perlu Perhatian</div>${actionRows}${insightRows}`;
  },

};

// modules/vehicle/vehicle-automation-api.js — Vehicle Automation API
// (Sesi 83, Batch 7). Lihat docs/BATCH_PLAN.md § Batch 7.
//
// PRINSIP (RULE #1 sesi ini): 100% REUSE VehicleRecommendationEngine.
// recommendations() + VehiclePriorityScoring.rank() + VehicleAction
// Recommendation.withAction() (modules/vehicle/vehicle-recommendation-
// engine.js, vehicle-priority-scoring.js, vehicle-action-recommendation.js
// — Sesi 82, Vehicle Decision Engine Foundation, sendiri sudah gabungan
// VehicleDecisionAPI -> VehicleAIHook -> VehicleIntelligence+
// VehicleReminder) — TIDAK ada rumus baru, TIDAK menghitung ulang
// severity/priorityScore/action apa pun, TIDAK membaca D langsung sama
// sekali, TIDAK mengubah struktur data D. Satu-satunya "logic" di file
// ini adalah menjalankan PIPELINE Decision Engine yang SUDAH ADA
// (recommendations() -> rank() -> withAction(), pola sama persis
// pipeline VehicleDecisionPresenter.render()) & membungkus hasilnya jadi
// bentuk seragam `{ok, vehicleId, items}` — pola sama persis wrapper
// tipis VehicleDecisionAPI.context() terhadap VehicleAIHook.
//
// Tujuan: 1 pintu masuk TUNGGAL utk seluruh lapisan Automation Foundation
// sesi ini (VehicleReminderScheduler dst di bawahnya HANYA boleh baca
// lewat file ini, bukan panggil VehicleRecommendationEngine/
// VehiclePriorityScoring/VehicleActionRecommendation langsung — supaya
// kalau sumber data automation berubah di masa depan, cukup diubah di 1
// tempat, pola sama persis VehicleDecisionAPI terhadap VehicleAIHook).
// TIDAK ada UI/panel di file ini.
const VehicleAutomationAPI = {

// context(vehicleId?) — titik masuk tunggal data mentah utk lapisan
// Automation. {ok:false} kalau salah satu dari ketiga modul Decision
// Engine belum dimuat (guard urutan load / dipakai headless di test,
// pola sama persis guard {ok:false} di VehicleDecisionAPI). items = hasil
// pipeline recommendations() -> rank() -> withAction() APA ADANYA, 0
// transformasi tambahan.
context(vehicleId) {
  if (typeof VehicleRecommendationEngine === 'undefined'
    || typeof VehiclePriorityScoring === 'undefined'
    || typeof VehicleActionRecommendation === 'undefined') {
    return { ok: false, reason: 'Vehicle Decision Engine belum dimuat' };
  }
  const recommendations = VehicleRecommendationEngine.recommendations(vehicleId);
  const ranked = VehiclePriorityScoring.rank(recommendations);
  const items = VehicleActionRecommendation.withAction(ranked);
  return {
    ok: true,
    vehicleId: vehicleId || null,
    items,
  };
},

};

// modules/vehicle/vehicle-reminder-scheduler.js — Smart Reminder
// Scheduler (Sesi 83, Batch 7). Lihat docs/BATCH_PLAN.md § Batch 7.
//
// PRINSIP (RULE #1 sesi ini): 100% REUSE VehicleAutomationAPI.context()
// (modules/vehicle/vehicle-automation-api.js, sesi ini) — TIDAK
// menghitung ulang severity/priorityScore/action apa pun (field-field
// itu dibaca APA ADANYA dari tiap item). Satu-satunya logic genuinely
// baru sesi ini: tabel lookup severity -> {bucket,label} "kapan"
// (`SCHEDULE_MAP`), MURNI klasifikasi/presentasional (pola sama persis
// ACTION_MAP di VehicleActionRecommendation / SEVERITY_WEIGHT di
// VehiclePriorityScoring — bukan ambang numerik baru atas data mentah,
// severity itu sendiri SUDAH final dari VehicleReminder/
// VehicleIntelligence, jauh sebelum sampai di sini).
//
// TIDAK ada UI/panel di file ini — presenter-nya file terpisah
// (modules/vehicle/vehicle-automation-presenter.js, sesi ini juga).
const VehicleReminderScheduler = {

// SCHEDULE_MAP — lookup severity -> {bucket, label}, SATU-SATUNYA
// "rumus" baru sesi ini. 'overdue' => hari ini (risiko langsung, sama
// urutan bisnis dgn SEVERITY_WEIGHT VehiclePriorityScoring), 'warning'
// (insight VehicleIntelligence) => perlu ditinjau (belum ada tenggat
// konkret), 'due-soon' => minggu ini (masih ada waktu bersiap).
SCHEDULE_MAP: {
  overdue: { bucket: 'today', label: 'Segera (Hari Ini)' },
  warning: { bucket: 'soon', label: 'Perlu Ditinjau' },
  'due-soon': { bucket: 'upcoming', label: 'Minggu Ini' },
},

// DEFAULT_SCHEDULE — fallback kalau severity belum terdaftar di
// SCHEDULE_MAP (fail-safe, bukan throw — pola sama persis DEFAULT_LABEL
// di VehicleActionRecommendation).
DEFAULT_SCHEDULE: { bucket: 'upcoming', label: 'Minggu Ini' },

// _scheduleFor(item) — {bucket,label} murni lookup SCHEDULE_MAP
// berdasarkan field `severity` yang sudah ada di item (reuse
// VehicleAutomationAPI, TIDAK ada input lain yang dibaca).
_scheduleFor(item) {
  const severity = item && item.severity;
  return this.SCHEDULE_MAP[severity] || this.DEFAULT_SCHEDULE;
},

// schedule(vehicleId?) — array item VehicleAutomationAPI.context().items
// yang sama, ditambah field `schedule` ({bucket,label}) dari
// _scheduleFor() di atas. Array kosong (bukan throw) kalau
// VehicleAutomationAPI belum dimuat atau context() {ok:false} — pola
// sama persis VehicleRecommendationEngine.recommendations().
schedule(vehicleId) {
  if (typeof VehicleAutomationAPI === 'undefined') return [];
  const ctx = VehicleAutomationAPI.context(vehicleId);
  if (!ctx.ok) return [];
  return ctx.items.map((item) => ({ ...item, schedule: this._scheduleFor(item) }));
},

// summary(vehicleId?) — Reminder Scheduler Summary API, hitungan per
// bucket (today/soon/upcoming) dari schedule() di atas, 0 recompute
// field lain — satu pintu masuk ringkas utk presenter/consumer lain
// (pola sama persis summary() di VehicleReminder/VehicleIntelligence).
summary(vehicleId) {
  const items = this.schedule(vehicleId);
  const counts = { today: 0, soon: 0, upcoming: 0 };
  items.forEach((item) => {
    const bucket = item.schedule.bucket;
    if (Object.prototype.hasOwnProperty.call(counts, bucket)) counts[bucket] += 1;
  });
  return { total: items.length, counts, items };
},

};

