function lifeOSFindLink(key) {
  return LIFEOS_LINK_REGISTRY.find((l) => l.key === key) || null;
}

// lifeos-plugin-manifest.js — Plugin Manifest, LifeOS Plugin System MVP
// (Sesi 65, Batch 5). Scope MVP sesi ini SENGAJA sempit: manifest MURNI
// METADATA (id/name/version/areaKey/description) — TIDAK ada `entry`/kode
// eksekusi apa pun. Plugin Runtime (menjalankan kode plugin) & Plugin UI/
// Marketplace SENGAJA di luar scope (keputusan eksplisit user, 1 sesi =
// 1 milestone) — menyusul di sesi lanjutan kalau ada keputusan produk.
//
// `areaKey` opsional TAPI kalau diisi WAJIB salah satu `LIFEOS_AREAS.key`
// (`lifeos-registry.js`, REUSE apa adanya — 0 registry/taksonomi baru).
//
// Sesi 69 (Plugin Runtime MVP): tambah `capabilities` opsional (array
// string) — deklarasi "izin" murni bookkeeping yang divalidasi terhadap
// `LIFEOS_PLUGIN_CAPABILITIES` (di bawah). Plugin Runtime (lihat
// `lifeos-plugin-runtime.js`) TIDAK mengeksekusi kode plugin apa pun,
// jadi capability di sini TIDAK men-gate akses nyata — murni deklarasi
// yang divalidasi bentuknya, dipakai Runtime buat cegah `enable()`
// plugin yang deklarasi capability-nya tidak dikenal. Manifest TETAP
// tanpa `entry`/kode eksekusi (keputusan Sesi 65 tidak berubah).

const LIFEOS_PLUGIN_MANIFEST_REQUIRED_FIELDS = ['id', 'name', 'version'];
const LIFEOS_PLUGIN_MANIFEST_OPTIONAL_FIELDS = ['areaKey', 'description', 'capabilities'];

// Daftar capability yang dikenal Plugin Runtime MVP (Sesi 69). Generik,
// TIDAK terikat domain LIFEOS_AREAS tertentu — merefleksikan jenis
// interaksi plugin dgn LifeOS (baca data read-only, render panel UI,
// kirim notifikasi), bukan sumber data spesifik.
const LIFEOS_PLUGIN_CAPABILITIES = ['read-data', 'ui-panel', 'notify'];

// Factory murni (tidak menulis ke registry/store) — sekadar bentuk objek
// manifest yang konsisten, dipakai pemanggil sebelum diserahkan ke
// lifeOSPluginValidateManifest()/LifeOSPluginRegistry.register().
function lifeOSPluginCreateManifest({ id, name, version, areaKey = null, description = '', capabilities = [] } = {}) {
  return { id, name, version, areaKey, description, capabilities: Array.isArray(capabilities) ? capabilities.slice() : [] };
}

// lifeos-plugin-validation.js — Plugin Validation, LifeOS Plugin System MVP
// (Sesi 65, Batch 4). Validasi MURNI bentuk manifest (tidak menulis apa
// pun, tidak menyentuh registry) — dipakai oleh LifeOSPluginRegistry.
// register() SEBELUM plugin apa pun terdaftar. Pola kontrak sama dgn
// lifeOSObjectRefValidate() (lifeos-object-ref.js): balik
// {valid:true} | {valid:false, error}, TIDAK PERNAH throw.
//
// areaKey (opsional) divalidasi terhadap LIFEOS_AREAS yang SUDAH ADA
// (lifeos-registry.js) — REUSE penuh, 0 taksonomi/registry baru dibuat di
// sini. Kalau LIFEOS_AREAS belum ter-load (guard typeof, sama pola dgn
// LIFEOS_OBJECT_REF_SOURCES.goal.resolver), areaKey manapun ditolak aman
// (tidak throw) drpd diterima diam-diam.
//
// Sesi 69 (Plugin Runtime MVP): tambah validasi `capabilities` (opsional,
// array string) — tiap elemen WAJIB ada di `LIFEOS_PLUGIN_CAPABILITIES`
// (lifeos-plugin-manifest.js). Dipakai `LifeOSPluginRuntime.enable()`
// supaya plugin dgn capability tidak dikenal ditolak sebelum diaktifkan.

function lifeOSPluginValidateManifest(manifest) {
  if (!manifest || typeof manifest !== 'object' || Array.isArray(manifest)) {
    return { valid: false, error: 'manifest wajib berupa object' };
  }

  for (const field of LIFEOS_PLUGIN_MANIFEST_REQUIRED_FIELDS) {
    if (!manifest[field] || typeof manifest[field] !== 'string') {
      return { valid: false, error: `manifest.${field} wajib diisi (string)` };
    }
  }

  if (!/^\d+\.\d+\.\d+$/.test(manifest.version)) {
    return { valid: false, error: 'manifest.version wajib format semver "x.y.z" (mis. "1.0.0")' };
  }

  if (manifest.areaKey !== undefined && manifest.areaKey !== null) {
    const areas = typeof LIFEOS_AREAS !== 'undefined' ? LIFEOS_AREAS : [];
    const found = areas.some((a) => a.key === manifest.areaKey);
    if (!found) {
      return { valid: false, error: `manifest.areaKey "${manifest.areaKey}" tidak terdaftar di LIFEOS_AREAS` };
    }
  }

  if (manifest.capabilities !== undefined && manifest.capabilities !== null) {
    if (!Array.isArray(manifest.capabilities)) {
      return { valid: false, error: 'manifest.capabilities wajib berupa array' };
    }
    for (const cap of manifest.capabilities) {
      if (typeof cap !== 'string' || !LIFEOS_PLUGIN_CAPABILITIES.includes(cap)) {
        return { valid: false, error: `manifest.capabilities berisi capability tidak dikenal: "${cap}"` };
      }
    }
  }

  return { valid: true };
}

// lifeos-plugin-registry.js — Plugin Registry, LifeOS Plugin System MVP
// (Sesi 65, Batch 5). SATU-SATUNYA tempat menyimpan plugin yang berhasil
// terdaftar (in-memory, `_plugins` map by id) — pola sama dgn EIERegistry
// (economic-intelligence/eie-registry.js, "arsitektur yang sudah ada" yang
// dipakai ulang sesi ini): object tunggal + `register()`/getter, TANPA
// side-effect ke `D`/`LifeOSStore` (LifeOS Plugin System TIDAK menyentuh
// data app inti — beda total dari `LifeOSStore.objects` dkk).
//
// register() SELALU validasi via lifeOSPluginValidateManifest() dulu
// (lifeos-plugin-validation.js) — manifest tidak valid TIDAK PERNAH masuk
// registry. id duplikat DITOLAK eksplisit (bukan overwrite diam-diam) —
// pemanggil yang mau update harus unregister() dulu.
//
// TIDAK ADA di sini (sesuai scope MVP eksplisit sesi ini): eksekusi kode
// plugin apa pun (Plugin Runtime), UI, Marketplace — registry ini murni
// bookkeeping metadata manifest.

const LifeOSPluginRegistry = {
  _plugins: {},

  register(manifest) {
    const check = lifeOSPluginValidateManifest(manifest);
    if (!check.valid) return check;

    if (this._plugins[manifest.id]) {
      return { valid: false, error: `Plugin "${manifest.id}" sudah terdaftar` };
    }

    this._plugins[manifest.id] = manifest;
    return { valid: true, plugin: manifest };
  },

  unregister(id) {
    if (!this._plugins[id]) return false;
    delete this._plugins[id];
    return true;
  },

  get(id) {
    return this._plugins[id] || null;
  },

  list() {
    return Object.values(this._plugins);
  },

  has(id) {
    return !!this._plugins[id];
  },
};

// lifeos-plugin-loader.js — Plugin Loader, LifeOS Plugin System MVP
// (Sesi 65, Batch 5). Loader MURNI batch-register: terima array manifest,
// panggil LifeOSPluginRegistry.register() satu-satu, dan kumpulkan hasil
// —TIDAK menjalankan/mengeksekusi kode plugin apa pun (Plugin Runtime di
// luar scope sesi ini, keputusan eksplisit user). "Loader" di sini berarti
// "memuat manifest ke registry", bukan "menjalankan plugin".
//
// Satu manifest gagal (invalid/duplikat id) TIDAK menghentikan proses
// batch — sisanya tetap diproses, hasil gagal dikumpulkan di `rejected`
// (pola sama dgn error-per-item, bukan fail-fast) supaya pemanggil bisa
// lapor semua masalah sekaligus.

function lifeOSPluginLoad(manifests) {
  const loaded = [];
  const rejected = [];

  for (const manifest of manifests || []) {
    const result = LifeOSPluginRegistry.register(manifest);
    if (result.valid) {
      loaded.push(result.plugin.id);
    } else {
      rejected.push({ id: manifest && manifest.id, error: result.error });
    }
  }

  return { loaded, rejected };
}

// lifeos-plugin-runtime.js — Plugin Runtime MVP, LifeOS Plugin System
// (Sesi 69, Batch 5, target eksplisit user: "Plugin Runtime" di atas
// Registry + Manifest + Loader yang sudah ada — TIDAK Marketplace, TIDAK
// Plugin UI baru). Layer BARU murni tambahan, TIDAK mengubah perilaku
// `LifeOSPluginRegistry`/`lifeOSPluginValidateManifest`/`lifeOSPluginLoad`
// yang sudah ada (Sesi 65/66) — Runtime cuma mengonsumsinya.
//
// PENTING — TETAP TIDAK ADA eksekusi kode plugin arbitrer (keputusan
// arsitektur Sesi 65 tidak berubah): manifest tidak punya `entry`, dan
// Runtime ini TIDAK men-`eval`/`import()` apa pun. "Runtime" di sini
// berarti *state machine lifecycle* (loaded → enabled ⇄ disabled →
// unloaded) + gerbang capability, BUKAN sandbox eksekusi kode. Hook
// opsional (`onEnable`/`onDisable`, lihat `load()`) sengaja hanya
// callback JS yang pemanggil sendiri yang sediakan di sesi runtime yang
// sama (mis. dari kode app, bukan dari isi manifest/file plugin) — jadi
// tidak ada "kode plugin dari luar" yang dijalankan di sini.
//
// State machine per plugin id:
//   loaded → enabled  (enable())
//   enabled → disabled (disable())
//   disabled → enabled (enable() lagi)
//   loaded|enabled|disabled|error → unloaded (unload(), state akhir permanen)
// Transisi di luar itu (mis. enable() saat sudah 'unloaded', disable() saat
// 'loaded') DITOLAK eksplisit ({ok:false, error}), bukan silent no-op.
//
// Capability validation: `enable()` menolak plugin yang manifest-nya
// mengandung capability di luar `LIFEOS_PLUGIN_CAPABILITIES` (harusnya
// sudah tertolak dari `register()`/`lifeOSPluginValidateManifest()` —
// pengecekan di sini lapisan kedua/defense-in-depth, jaga-jaga manifest
// masuk lewat jalur lain).
//
// Error isolation: hook `onEnable`/`onDisable` (kalau ada) dibungkus
// try/catch. Hook yang throw TIDAK PERNAH merambat ke pemanggil
// `enable()`/`disable()` dan TIDAK PERNAH menjatuhkan plugin lain — state
// plugin yang error ditandai 'error' + `lastError` disimpan, plugin lain
// di runtime registry tidak terpengaruh sama sekali (pola: satu plugin
// gagal, sisanya tetap jalan — sama semangat dgn `lifeOSPluginLoad()`
// yang satu manifest gagal tidak menghentikan batch).

const LIFEOS_PLUGIN_RUNTIME_STATES = ['loaded', 'enabled', 'disabled', 'unloaded', 'error'];

const LifeOSPluginRuntime = {
  // _runtime[id] = { state, manifest, hooks: {onEnable, onDisable}, lastError }
  _runtime: {},

  // Lifecycle: load — daftarkan manifest ke LifeOSPluginRegistry (reuse
  // penuh, 0 duplikasi validasi) lalu buat entri runtime state='loaded'.
  // `hooks` opsional ({onEnable, onDisable}), disimpan di memori runtime
  // SAJA (tidak pernah masuk manifest/registry).
  load(manifest, hooks = {}) {
    const result = LifeOSPluginRegistry.register(manifest);
    if (!result.valid) return result;

    const id = result.plugin.id;
    this._runtime[id] = {
      state: 'loaded',
      manifest: result.plugin,
      hooks: {
        onEnable: typeof hooks.onEnable === 'function' ? hooks.onEnable : null,
        onDisable: typeof hooks.onDisable === 'function' ? hooks.onDisable : null,
      },
      lastError: null,
    };
    return { valid: true, plugin: result.plugin };
  },

  // Lifecycle: enable — capability validation dulu (defense-in-depth),
  // lalu transisi state, lalu panggil onEnable() (kalau ada) dgn error
  // isolation. Boleh dipanggil dari 'loaded' ATAU 'disabled' (re-enable).
  enable(id) {
    const entry = this._runtime[id];
    if (!entry) return { ok: false, error: `Plugin "${id}" belum di-load ke runtime` };
    if (entry.state !== 'loaded' && entry.state !== 'disabled') {
      return { ok: false, error: `Plugin "${id}" tidak bisa enable() dari state "${entry.state}"` };
    }

    const capCheck = this._checkCapabilities(entry.manifest);
    if (!capCheck.ok) return capCheck;

    const hookResult = this._runHookIsolated(entry, 'onEnable');
    if (!hookResult.ok) return hookResult;

    entry.state = 'enabled';
    return { ok: true, state: 'enabled' };
  },

  // Lifecycle: disable — hanya dari 'enabled'. onDisable() (kalau ada)
  // dgn error isolation yang sama.
  disable(id) {
    const entry = this._runtime[id];
    if (!entry) return { ok: false, error: `Plugin "${id}" belum di-load ke runtime` };
    if (entry.state !== 'enabled') {
      return { ok: false, error: `Plugin "${id}" tidak bisa disable() dari state "${entry.state}"` };
    }

    const hookResult = this._runHookIsolated(entry, 'onDisable');
    if (!hookResult.ok) return hookResult;

    entry.state = 'disabled';
    return { ok: true, state: 'disabled' };
  },

  // Lifecycle: unload — state akhir permanen, dari state manapun (termasuk
  // 'error'). Unregister dari LifeOSPluginRegistry (reuse) + hapus entri
  // runtime sepenuhnya (bukan cuma tandai 'unloaded').
  unload(id) {
    const entry = this._runtime[id];
    if (!entry) return { ok: false, error: `Plugin "${id}" belum di-load ke runtime` };

    LifeOSPluginRegistry.unregister(id);
    delete this._runtime[id];
    return { ok: true, state: 'unloaded' };
  },

  getState(id) {
    const entry = this._runtime[id];
    return entry ? entry.state : null;
  },

  isEnabled(id) {
    const entry = this._runtime[id];
    return !!entry && entry.state === 'enabled';
  },

  lastError(id) {
    const entry = this._runtime[id];
    return entry ? entry.lastError : null;
  },

  list() {
    return Object.keys(this._runtime).map((id) => ({
      id,
      state: this._runtime[id].state,
      manifest: this._runtime[id].manifest,
    }));
  },

  // Internal — defense-in-depth capability check (lihat catatan header).
  _checkCapabilities(manifest) {
    const caps = (manifest && manifest.capabilities) || [];
    for (const cap of caps) {
      if (!LIFEOS_PLUGIN_CAPABILITIES.includes(cap)) {
        return { ok: false, error: `Plugin "${manifest.id}" punya capability tidak dikenal: "${cap}"` };
      }
    }
    return { ok: true };
  },

  // Internal — jalankan hook (onEnable/onDisable) dgn error isolation.
  // Hook yang throw/tidak ada TIDAK PERNAH merambat: kalau throw, state
  // ditandai 'error' + lastError disimpan, dan hasil balik {ok:false}
  // supaya pemanggil enable()/disable() tahu transisi dibatalkan — tapi
  // exception itu sendiri TIDAK PERNAH lolos ke luar fungsi ini.
  _runHookIsolated(entry, hookName) {
    const hook = entry.hooks && entry.hooks[hookName];
    if (!hook) return { ok: true };

    try {
      hook(entry.manifest);
      return { ok: true };
    } catch (err) {
      entry.state = 'error';
      entry.lastError = err && err.message ? err.message : String(err);
      return { ok: false, error: `Hook "${hookName}" plugin "${entry.manifest.id}" gagal: ${entry.lastError}` };
    }
  },
};

// adapters/area-adapter.js — READ-ONLY. Ringkasan per AREA (lifeos-registry.js:
// LIFEOS_AREAS) — murni menjumlah panjang tiap D.* yang terdaftar di
// `dSources` per area. Tidak ada skor/logic bisnis baru, cuma menghitung
// jumlah item yang sudah ada di D. Tidak pernah menulis ke D.
//
// Depends on: lifeos-registry.js (LIFEOS_AREAS). Sebelum file ini dibuat,
// LIFEOS_AREAS hanya deklaratif — tidak dikonsumsi kode apa pun (lihat
// README.md § LifeOS > Status Implementasi). Adapter ini adalah konsumen
// otomatis pertama: kalau LIFEOS_AREAS bertambah/berkurang entri, hasil
// areaAdapterList() otomatis ikut berubah tanpa perlu ubah file ini.

function areaAdapterList(D) {
  const areas = typeof LIFEOS_AREAS !== 'undefined' ? LIFEOS_AREAS : [];
  return areas.map((area) => {
    const itemCount = (area.dSources || []).reduce((sum, key) => {
      const arr = D[key];
      return sum + (Array.isArray(arr) ? arr.length : 0);
    }, 0);
    return {
      key: area.key,
      label: area.label,
      icon: area.icon,
      itemCount,
    };
  });
}

function areaAdapterFindOne(D, key) {
  return areaAdapterList(D).find((a) => a.key === key) || null;
}

// adapters/goal-adapter.js — READ-ONLY. Menyeragamkan sumber goal lama
// (D.targets, D.eduFunds, D.pensiun, D.finansialFreedom, D.wishlist,
// D.debtStrategy) jadi satu bentuk "goal card". Tidak menyimpan apa pun,
// dihitung ulang tiap dipanggil. Tidak pernah menulis ke D.
//
// goalAdapterList() SEKARANG registry-driven (pola SAMA PERSIS dgn
// today-adapter.js/TODAY_SOURCE_BUILDERS — Sesi 24): iterasi
// LIFEOS_GOAL_SOURCES (lifeos-registry.js) lalu dispatch ke builder di
// GOAL_SOURCE_BUILDERS berdasar `key` registry — kalau builder utk 1 key
// belum terdaftar, key itu dilewati (aman, tidak throw), TIDAK ada key
// yang diproses tanpa terdaftar di registry duluan. Sebelum sesi ini,
// docstring file ini SUDAH mengaku "Depends on: LIFEOS_GOAL_SOURCES" tapi
// kode-nya belum benar-benar membaca array itu (3 sumber di-hardcode
// langsung) — sekarang benar-benar dikonsumsi otomatis: kalau
// LIFEOS_GOAL_SOURCES bertambah/berkurang entri (dan builder-nya ada),
// goalAdapterList() otomatis ikut berubah tanpa perlu ubah file ini.
//
// Depends on: lifeos-registry.js (LIFEOS_GOAL_SOURCES).
//
// Builder utk key pensiun/fi/debt — DIIMPLEMENTASIKAN Sesi 49, setelah
// keputusan produk final (`docs/PRODUCT_DECISIONS.md` § LifeOS — Goal
// source pensiun/fi/debt, sebelumnya "BELUM final"):
//
// 1) pensiun/fi — currentAmount REUSE LANGSUNG `Pensiun.danaTerkumpul()`/
//    `FI.netAssetFund()` (guard `typeof X!=='undefined'`), BUKAN dihitung
//    ulang dari parameter `D`. Konsekuensi yang disadari & diterima
//    (keputusan eksplisit user Sesi 49): kedua fungsi itu membaca `D` dari
//    CLOSURE modul masing-masing, jadi kalau builder ini dipanggil dgn `D`
//    palsu (mis. di test terisolasi lewat `loadSource` TANPA memuat
//    `modules-calc.js`), `Pensiun`/`FI` TIDAK terdefinisi -> guard aktif ->
//    builder balik `[]` (aman, TIDAK throw, TIDAK menebak angka) — bukan
//    pakai `D` palsu yang di-pass. targetAmount/meta tetap dibaca dari `D`
//    parameter (`D.pensiun`, `D.finansialFreedom`) spy tetap konsisten dgn
//    pola builder lain. Alasan TIDAK menghitung ulang murni dari `D`:
//    `FI.netAssetFund()` berantai ke banyak helper global lain
//    (`totalSaldoAkun`, `totalCicilanOutstanding`, `totalDebtValue`, dll)
//    — menduplikasi logic itu di sini melanggar "Larangan duplikasi"
//    (`docs/PRODUCT_DECISIONS.md` § Umum).
// 2) debt — sumber data BUKAN `D.debtStrategy` ({method,extra}, tanpa
//    nominal) tapi `D.debts` (array per-utang, field `nilai`/`lunas` —
//    lihat `modules/finance/piutang-utang.js`), keputusan eksplisit user
//    Sesi 49. Registry `LIFEOS_GOAL_SOURCES` (`lifeos-registry.js`) `dArr`
//    utk key `debt` diubah dari `debtStrategy` -> `debts` sesi ini supaya
//    konsisten (dArr cuma dipakai sbg dokumentasi sumber di registry,
//    builder di bawah yang jadi sumber kebenaran aktual — pola sama dgn
//    builder lain yg baca field D langsung).
//
// Audit Sesi 35 (target eksplisit user: "Registry Driven Goal
// Adapter"): dikonfirmasi ulang lewat pembacaan langsung file ini +
// `tests/lifeos-goal-adapter.test.js` (11 test, termasuk test yang
// menghapus 1 entri dari `LIFEOS_GOAL_SOURCES` lalu membuktikan
// sumbernya otomatis berhenti diproses) — migrasi registry-driven ini
// SUDAH selesai (Sesi 25, lihat README.md § LifeOS), TIDAK ada
// hardcode daftar sumber yang tersisa. Tidak ada perubahan kode yang
// diperlukan sesi ini.

function goalSourceTarget(D) {
  return (D.targets || []).map((t) => ({
    id: `target:${t.id}`, sourceKind: 'target', sourceId: t.id,
    name: t.name, emoji: t.emoji || '🎯',
    targetAmount: t.amount, currentAmount: t.saved,
    progressPct: t.amount ? Math.min(100, Math.round((t.saved / t.amount) * 100)) : 0,
    deadline: null, areaKey: 'finance',
    isDanaDarurat: !!t.isDanaDarurat,
  }));
}

function goalSourceEduFund(D) {
  return (D.eduFunds || []).map((e) => ({
    id: `eduFund:${e.id}`, sourceKind: 'eduFund', sourceId: e.id,
    name: e.name || 'Dana Pendidikan', emoji: '🎓',
    targetAmount: e.target ?? null, currentAmount: e.saved ?? null,
    progressPct: e.target ? Math.min(100, Math.round(((e.saved || 0) / e.target) * 100)) : null,
    deadline: null, areaKey: 'finance',
  }));
}

function goalSourceWishlist(D) {
  return (D.wishlist || []).filter((w) => !w.bought).map((w) => ({
    id: `wishlist:${w.id}`, sourceKind: 'wishlist', sourceId: w.id,
    name: w.name, emoji: '🛍️',
    targetAmount: w.price, currentAmount: 0, progressPct: 0,
    deadline: null, areaKey: 'finance',
  }));
}

function goalSourcePensiun(D) {
  const p = D.pensiun;
  // Guard konfigurasi: sama persis dgn kondisi "Belum diatur" di
  // Pensiun.renderDashMini() (modules-calc.js) — usiaSekarang/usiaPensiun/
  // accId wajib ada dulu, kalau belum jangan tampilkan goal card kosong.
  if (!p || !p.usiaSekarang || !p.usiaPensiun || !p.accId) return [];
  let current = 0;
  if (typeof Pensiun !== 'undefined' && typeof Pensiun.danaTerkumpul === 'function') {
    try { current = Number(Pensiun.danaTerkumpul()) || 0; } catch (e) { current = 0; }
  } else {
    return [];
  }
  const target = Number(p.targetDana) || 0;
  return [{
    id: 'pensiun:main', sourceKind: 'pensiun', sourceId: 'main',
    name: 'Dana Pensiun', emoji: '🏖️',
    targetAmount: target, currentAmount: current,
    progressPct: target > 0 ? Math.max(0, Math.min(100, Math.round((current / target) * 100))) : 0,
    deadline: null, areaKey: 'finance',
  }];
}

function goalSourceFI(D) {
  const fi = D.finansialFreedom;
  if (!fi) return [];
  if (typeof FI === 'undefined' || typeof FI.targetNominal !== 'function' || typeof FI.netAssetFund !== 'function') return [];
  let target = 0, current = 0;
  try { target = Number(FI.targetNominal()) || 0; } catch (e) { target = 0; }
  try { current = Number(FI.netAssetFund()) || 0; } catch (e) { current = 0; }
  // Belum ada data transaksi yang cukup utk hitung target (annualExpense
  // 0 -> targetNominal 0) — jangan tampilkan goal card kosong/menyesatkan,
  // pola sama dgn guard pensiun di atas.
  if (!isFinite(target) || target <= 0) return [];
  return [{
    id: 'fi:main', sourceKind: 'fi', sourceId: 'main',
    name: 'Financial Independence', emoji: '🕊️',
    targetAmount: target, currentAmount: current,
    progressPct: Math.max(0, Math.min(100, Math.round((current / target) * 100))),
    deadline: null, areaKey: 'finance',
  }];
}

// FIX (S456): entri utang "dana titipan" (linkedAssetId terisi, auto-sync
// dari Aset._syncOwnerDebts()) BUKAN kewajiban yang perlu jadi target Goal
// -- sama alasan/pola dgn DebtStrategy.activeDebts() (S455,
// piutang-utang.js): lunas selalu false & tidak ada jatuhTempo asli, jadi
// tanpa exclude ini nongol permanen sbg goal card 0% yg gak pernah selesai.
function goalSourceDebt(D) {
  return (D.debts || []).filter((d) => (d.nilai || 0) > 0 && !d.linkedAssetId).map((d) => ({
    id: `debt:${d.id}`, sourceKind: 'debt', sourceId: d.id,
    name: d.name, emoji: '📕',
    targetAmount: d.nilai, currentAmount: d.lunas ? d.nilai : 0,
    progressPct: d.lunas ? 100 : 0,
    deadline: d.jatuhTempo || null, areaKey: 'finance',
  }));
}

const GOAL_SOURCE_BUILDERS = {
  target: goalSourceTarget,
  eduFund: goalSourceEduFund,
  wishlist: goalSourceWishlist,
  pensiun: goalSourcePensiun,
  fi: goalSourceFI,
  debt: goalSourceDebt,
};

function goalAdapterList(D) {
  const out = [];
  const sources = typeof LIFEOS_GOAL_SOURCES !== 'undefined' ? LIFEOS_GOAL_SOURCES : [];
  sources.forEach((src) => {
    const builder = GOAL_SOURCE_BUILDERS[src.key];
    if (typeof builder !== 'function') return;
    out.push(...builder(D));
  });
  return out;
}

function goalAdapterFindOne(D, sourceKind, sourceId) {
  return goalAdapterList(D).find((g) => g.sourceKind === sourceKind && g.sourceId === sourceId) || null;
}

// adapters/project-adapter.js — merge READ-ONLY antara dua sumber:
//   1. D.renovProjects        (legacy, milik renovasi.js — tidak disentuh)
//   2. LifeOSStore.projects   (generic, milik Life OS — lihat services/project-service.js untuk tulis)
//
// Adapter ini hanya membaca kedua sumber & menyatukan bentuknya. Tidak
// pernah menulis ke D.renovProjects. Penulisan project generik lewat
// project-service.js, bukan di sini.
//
// Sesi 36 (target eksplisit user: "Registry Driven Project Adapter"):
// bagian legacy SEKARANG registry-driven — pola SAMA dgn
// today-adapter.js/TODAY_SOURCE_BUILDERS & goal-adapter.js/
// GOAL_SOURCE_BUILDERS (dispatch per `key` registry, key tanpa builder
// dilewati aman/tidak throw), disesuaikan dgn bentuk registry project yang
// SUDAH ADA (`LIFEOS_PROJECT_LEGACY_SOURCE`, lifeos-registry.js — 1 objek,
// bukan array, krn baru ada 1 sumber legacy sejauh ini). String
// 'renovasi'/'business'/'renovProjects' yang sebelumnya hardcode di badan
// fungsi sekarang dibaca dari `src.key`/`src.areaKey`/`src.dArr` — kalau
// registry ini nanti berubah jadi array (>1 sumber legacy), builder di
// bawah tinggal didaftarkan di `PROJECT_LEGACY_SOURCE_BUILDERS` tanpa ubah
// `projectAdapterList()`. Bagian generic (LifeOSStore.projects) TIDAK
// disentuh — itu bukan "sumber D" yang perlu didaftarkan di registry,
// melainkan penyimpanan generik Life OS sendiri (lihat project-service.js).
//
// Depends on: lifeos-registry.js (LIFEOS_PROJECT_LEGACY_SOURCE).

function projectSourceRenovasi(D, src) {
  return (D[src.dArr] || []).map((p) => ({
    id: `${src.key}:${p.id}`, kind: src.key, sourceRef: { arr: src.dArr, id: p.id },
    name: p.name, areaKey: src.areaKey, status: 'active',
    dueDate: null, createdAt: p.createdAt,
    checklistCount: (p.items || []).length,
  }));
}

const PROJECT_LEGACY_SOURCE_BUILDERS = {
  renovasi: projectSourceRenovasi,
};

function projectAdapterLegacyList(D) {
  const src = typeof LIFEOS_PROJECT_LEGACY_SOURCE !== 'undefined' ? LIFEOS_PROJECT_LEGACY_SOURCE : null;
  if (!src) return [];
  const builder = PROJECT_LEGACY_SOURCE_BUILDERS[src.key];
  if (typeof builder !== 'function') return [];
  return builder(D, src);
}

function projectAdapterList(D, lifeOSStore) {
  const legacy = projectAdapterLegacyList(D);

  const generic = (lifeOSStore.projects || []).map((p) => ({
    id: `generic:${p.id}`, kind: 'generic', sourceRef: null,
    name: p.name, areaKey: p.areaKey, status: p.status,
    dueDate: p.dueDate || null, createdAt: p.createdAt,
    checklistCount: (p.checklist || []).length,
  }));

  return [...legacy, ...generic];
}

function projectAdapterFindOne(D, lifeOSStore, id) {
  return projectAdapterList(D, lifeOSStore).find((p) => p.id === id) || null;
}

// adapters/today-adapter.js — READ-ONLY. TODAY bukan penyimpanan sendiri,
// cuma lensa waktu di atas AREAS/PROJECTS/GOALS (lihat
// personal-life-os-blueprint.md Langkah 2). Depends on: lifeos-registry.js
// (LIFEOS_TODAY_SOURCES). Tidak pernah menulis ke D.
//
// todayAdapterList() SEKARANG registry-driven: iterasi LIFEOS_TODAY_SOURCES
// (bukan blok if/forEach hardcoded per sumber) lalu dispatch ke builder di
// TODAY_SOURCE_BUILDERS berdasar `key` registry — kalau builder untuk 1 key
// belum ada, key itu dilewati (aman, tidak throw), TIDAK ada key yang
// diproses tanpa terdaftar di registry duluan. Ini bikin LIFEOS_TODAY_SOURCES
// benar-benar dikonsumsi otomatis (bukan cuma dokumentasi) — lihat
// README.md § LifeOS > Status Implementasi.
//
// Builder selfcare/payroll/tukang di bawah ini murni REUSE field D yang
// sudah ada (dipakai modul lamanya masing-masing) + helper murni yang
// sudah ada (getWeekRange/todayStr/dateToISO) — TIDAK ada rumus/aturan
// bisnis baru, dan TIDAK memanggil fungsi yang baca/tulis DOM
// (checkWeeklySalaryReset() dkk sengaja tidak dipanggil dari sini, krn itu
// bukan fungsi murni — lihat modules/business/reset-gaji-mingguan.js).

function todaySourceBills(D) {
  const items = [];
  (D.bills || []).forEach((b) => {
    if (b.dueDate && isDueSoon(b.dueDate)) {
      items.push({ id: `bills:${b.id}`, sourceKind: 'bills', sourceId: b.id, label: b.name, dueDate: b.dueDate });
    }
  });
  return items;
}

function todaySourceReminders(D) {
  const items = [];
  (D.reminders || []).forEach((r) => {
    if (!r.done) items.push({ id: `reminders:${r.id}`, sourceKind: 'reminders', sourceId: r.id, label: r.text || r.title });
  });
  return items;
}

// selfcare — reuse D.refleksi.selfCareLog (bentuk & field sama persis dgn
// yang dibaca SelfCareReko.compute() di modules/home/refleksi-selfcare.js:
// map tanggal ISO -> array id item checklist). Urgent hari ini = checklist
// hari ini masih kosong/belum diisi sama sekali.
function todaySourceSelfcare(D) {
  const ref = D.refleksi;
  if (!ref || typeof dateToISO !== 'function') return [];
  const today = dateToISO(new Date());
  const log = ref.selfCareLog || {};
  const doneToday = (log[today] || []).length > 0;
  if (doneToday) return [];
  return [{
    id: 'selfcare:today',
    sourceKind: 'selfcare',
    sourceId: today,
    label: 'Checklist Self-Care & Jurnal Syukur hari ini',
  }];
}

// payroll — reuse getWeekRange() (helper murni, sudah ada di
// modules/business/reset-gaji-mingguan.js) + field D.workDays/
// D.lastResetPromptDate yang SAMA PERSIS dipakai checkWeeklySalaryReset()
// utk menentukan kapan notif reset gaji mingguan muncul — versi di sini
// murni baca kondisinya tanpa efek samping DOM/openModal (checkWeeklySalaryReset
// sendiri tidak dipanggil krn itu bukan fungsi murni).
function todaySourcePayroll(D) {
  if (typeof getWeekRange !== 'function') return [];
  const now = new Date();
  if (now.getDay() !== 6) return []; // sama dgn checkWeeklySalaryReset(): cuma relevan hari Sabtu
  if (typeof todayStr === 'function' && D.lastResetPromptDate === todayStr()) return []; // sudah pernah ditawarkan hari ini
  const { start, end } = getWeekRange(now);
  const weekDays = (D.workDays || []).filter((w) => {
    const d = new Date(w.date);
    return d >= start && d <= end;
  });
  if (!weekDays.length) return [];
  const total = weekDays.reduce((s, w) => s + (w.total || 0), 0);
  return [{
    id: 'payroll:weekly-reset',
    sourceKind: 'payroll',
    sourceId: null,
    label: `Gajian mingguan belum di-reset (${weekDays.length} hari absensi, total ${total})`,
  }];
}

// tukang — reuse D.tukangWorkers (daftar pekerja aktif) + D.tukangAbsensi
// (entri absensi harian, field `date`/`workerId` sama persis dgn yang
// dibaca modules/business/tukang-absensi.js). Urgent hari ini = pekerja
// yang belum ada entri absensi utk tanggal hari ini.
function todaySourceTukang(D) {
  const workers = D.tukangWorkers || [];
  if (!workers.length || typeof dateToISO !== 'function') return [];
  const today = dateToISO(new Date());
  const absensi = D.tukangAbsensi || [];
  const recordedIds = new Set(absensi.filter((a) => a.date === today).map((a) => String(a.workerId)));
  return workers
    .filter((w) => !recordedIds.has(String(w.id)))
    .map((w) => ({
      id: `tukang:${w.id}`,
      sourceKind: 'tukang',
      sourceId: w.id,
      label: `Absensi ${w.name} belum dicatat hari ini`,
    }));
}

const TODAY_SOURCE_BUILDERS = {
  bills: todaySourceBills,
  reminders: todaySourceReminders,
  selfcare: todaySourceSelfcare,
  payroll: todaySourcePayroll,
  tukang: todaySourceTukang,
};

function todayAdapterList(D) {
  const items = [];
  const sources = typeof LIFEOS_TODAY_SOURCES !== 'undefined' ? LIFEOS_TODAY_SOURCES : [];
  sources.forEach((src) => {
    const builder = TODAY_SOURCE_BUILDERS[src.key];
    if (typeof builder !== 'function') return;
    items.push(...builder(D));
  });
  return items;
}

function isDueSoon(dateStr, withinDays = 3) {
  const due = new Date(dateStr);
  const today = new Date();
  const diffDays = Math.ceil((due - today) / (1000 * 60 * 60 * 24));
  return diffDays <= withinDays;
}

// adapters/review-adapter.js — READ-ONLY. Menggabungkan histori pasif
// existing (D.wealthSnapshots, D.lifeBalanceSnapshots, D.assetAllocation)
// dengan sesi review Life OS sendiri (LifeOSStore.reviewLog). Tidak pernah
// menulis ke D. Penulisan sesi review lewat services/review-service.js.
//
// Sesi 37 (target eksplisit user: "Registry Driven Review Adapter"):
// reviewAdapterLatestSnapshots() SEKARANG registry-driven — pola SAMA dgn
// today-adapter.js/TODAY_SOURCE_BUILDERS, goal-adapter.js/
// GOAL_SOURCE_BUILDERS, & project-adapter.js/PROJECT_LEGACY_SOURCE_BUILDERS
// (Sesi 36): iterasi LIFEOS_REVIEW_SOURCES (lifeos-registry.js) lalu
// dispatch ke builder di REVIEW_SOURCE_BUILDERS berdasar `key` registry —
// key tanpa builder terdaftar dilewati aman (tidak throw). String nama
// array D ('wealthSnapshots'/'lifeBalanceSnapshots'/'assetAllocation')
// yang sebelumnya hardcode 3x di badan fungsi sekarang dibaca dari
// `src.dArr`. 2 builder ('wealth'/'lifeBalance') ambil item TERAKHIR dari
// array snapshot; 1 builder ('assetAlloc') baca objek tunggal langsung
// (bukan array) — dibedakan krn bentuk datanya memang beda, bukan
// arsitektur baru. Nama field output tetap sama persis dgn sebelum
// migrasi (wealth/lifeBalance/assetAllocation, dipetakan lewat
// `REVIEW_OUTPUT_FIELD`) supaya `lifeos/ui/review.js` yang sudah baca
// `snapshots.wealth`/`snapshots.lifeBalance` TIDAK perlu berubah — 0
// perubahan output, backward compatible penuh.
//
// Depends on: lifeos-registry.js (LIFEOS_REVIEW_SOURCES).

function reviewSourceLastSnapshot(D, src) {
  return (D[src.dArr] || []).slice(-1)[0] || null;
}

function reviewSourceDirect(D, src) {
  return D[src.dArr] || null;
}

const REVIEW_SOURCE_BUILDERS = {
  wealth: reviewSourceLastSnapshot,
  lifeBalance: reviewSourceLastSnapshot,
  assetAlloc: reviewSourceDirect,
};

// Nama field output legacy (dipakai lifeos/ui/review.js) berbeda dari
// `key` registry untuk 1 sumber (`assetAlloc` -> `assetAllocation`) —
// dipetakan di sini supaya bentuk hasil TIDAK berubah, bukan hardcode
// ulang nama array D-nya (itu tetap dari `src.dArr`).
const REVIEW_OUTPUT_FIELD = {
  wealth: 'wealth',
  lifeBalance: 'lifeBalance',
  assetAlloc: 'assetAllocation',
};

function reviewAdapterLatestSnapshots(D) {
  const out = {};
  const sources = typeof LIFEOS_REVIEW_SOURCES !== 'undefined' ? LIFEOS_REVIEW_SOURCES : [];
  sources.forEach((src) => {
    const builder = REVIEW_SOURCE_BUILDERS[src.key];
    if (typeof builder !== 'function') return;
    const field = REVIEW_OUTPUT_FIELD[src.key] || src.key;
    out[field] = builder(D, src);
  });
  return out;
}

function reviewAdapterLogFor(lifeOSStore, period) {
  return (lifeOSStore.reviewLog || [])
    .filter((r) => r.period === period)
    .sort((a, b) => new Date(b.completedAt) - new Date(a.completedAt));
}

function reviewAdapterIsOverdue(lifeOSStore, period, thresholdDays) {
  const last = reviewAdapterLogFor(lifeOSStore, period)[0];
  if (!last) return true;
  const daysSince = Math.floor((Date.now() - new Date(last.completedAt)) / (1000 * 60 * 60 * 24));
  return daysSince >= thresholdDays;
}

// adapters/knowledge-adapter.js — READ-ONLY. D.catatan (catatan privat
// manual, milik keamanan-pin.js/refleksi-selfcare.js dll) dibaca sebagai
// REFERENSI saja — Knowledge base Life OS yang sebenarnya (insight AI
// tersimpan) hidup di LifeOSStore.knowledge, ditulis lewat
// services/knowledge-service.js. Tidak pernah menulis ke D.catatan.
//
// Sesi 38 (target eksplisit user: "Registry Driven Knowledge Adapter"):
// bagian referensi D SEKARANG registry-driven — pola SAMA dgn
// projectAdapterLegacyList()/PROJECT_LEGACY_SOURCE_BUILDERS
// (project-adapter.js, Sesi 36): dispatch per `key` registry lewat
// KNOWLEDGE_REF_SOURCE_BUILDERS, disesuaikan dgn bentuk registry knowledge
// yang SUDAH ADA (`LIFEOS_KNOWLEDGE_REF_SOURCE`, lifeos-registry.js — 1
// objek, bukan array, krn baru ada 1 sumber referensi sejauh ini, sama
// persis kasusnya dgn LIFEOS_PROJECT_LEGACY_SOURCE). String 'catatan' yang
// sebelumnya hardcode di badan fungsi (`D.catatan`) sekarang dibaca dari
// `src.dArr` — kalau registry ini nanti berubah jadi array (>1 sumber
// referensi), builder di bawah tinggal didaftarkan di
// `KNOWLEDGE_REF_SOURCE_BUILDERS` tanpa ubah `knowledgeAdapterCatatanRef()`.
// Bagian utama (LifeOSStore.knowledge, knowledgeAdapterList/ByTag) TIDAK
// disentuh — itu bukan "sumber D" yang perlu didaftarkan di registry,
// melainkan penyimpanan Knowledge base Life OS sendiri (lihat
// services/knowledge-service.js). 0 perubahan output, TIDAK ada
// registry/helper/adapter/storage baru.
//
// Depends on: lifeos-registry.js (LIFEOS_KNOWLEDGE_REF_SOURCE).

function knowledgeAdapterList(lifeOSStore) {
  return (lifeOSStore.knowledge || []).slice().sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
}

function knowledgeAdapterByTag(lifeOSStore, tag) {
  return knowledgeAdapterList(lifeOSStore).filter((k) => (k.tags || []).includes(tag));
}

function knowledgeRefSourceCatatan(D, src) {
  return D[src.dArr] || {};
}

const KNOWLEDGE_REF_SOURCE_BUILDERS = {
  catatan: knowledgeRefSourceCatatan,
};

function knowledgeAdapterCatatanRef(D) {
  // Referensi read-only ke catatan privat lama — ditampilkan sebagai
  // "lihat juga", bukan dimigrasikan/disalin ke LifeOSStore.
  const src = typeof LIFEOS_KNOWLEDGE_REF_SOURCE !== 'undefined' ? LIFEOS_KNOWLEDGE_REF_SOURCE : null;
  if (!src) return {};
  const builder = KNOWLEDGE_REF_SOURCE_BUILDERS[src.key];
  if (typeof builder !== 'function') return {};
  return builder(D, src);
}

// lifeos-object-ref.js — resolver & validator utk `sourceRef` milik Life
// Object `kind:"ref"`. Sesi 58 (Batch 4, keputusan produk FINAL — lihat
// docs/PRODUCT_DECISIONS.md § LifeOS — Life Object sourceRef):
//
//   sourceRef = { domain: "...", id: "..." }
//
// `domain` WAJIB terdaftar di LIFEOS_OBJECT_REF_SOURCES (lifeos-registry.js:
// goal/project/knowledge/review). Ini BUKAN referensi ke Life Object lain,
// BUKAN generic resolver bebas {kind,id}, BUKAN recursive, BUKAN wildcard
// domain — file ini SATU-SATUNYA tempat sourceRef divalidasi/di-resolve,
// pola read-only sama persis dgn lifeos-nav.js (LIFEOS_NAV_MAP: satu-satunya
// tempat yg tahu cara "pergi ke sourceKind" — di sini satu-satunya tempat yg
// tahu cara "resolve sourceRef domain").
//
// Depends on: lifeos-registry.js (LIFEOS_OBJECT_REF_SOURCES).

/**
 * Resolve 1 sourceRef ke object aslinya di domain terdaftar.
 * @param {string} domain kunci di LIFEOS_OBJECT_REF_SOURCES (mis. 'goal').
 * @param {string} id id di dalam domain tsb.
 * @returns {*} object hasil resolve, atau `null` kalau domain tidak
 *   terdaftar / id tidak ketemu / adapter sumbernya belum ter-load.
 */
function lifeOSObjectRefResolve(domain, id) {
  const src = typeof LIFEOS_OBJECT_REF_SOURCES !== 'undefined' ? LIFEOS_OBJECT_REF_SOURCES[domain] : null;
  if (!src || typeof src.resolver !== 'function') return null;
  return src.resolver(id);
}

/**
 * Cek keberadaan id di domain terdaftar tanpa perlu resolve object penuh.
 * @param {string} domain kunci di LIFEOS_OBJECT_REF_SOURCES.
 * @param {string} id id di dalam domain tsb.
 * @returns {boolean}
 */
function lifeOSObjectRefExists(domain, id) {
  const src = typeof LIFEOS_OBJECT_REF_SOURCES !== 'undefined' ? LIFEOS_OBJECT_REF_SOURCES[domain] : null;
  if (!src || typeof src.exists !== 'function') return false;
  return !!src.exists(id);
}

/**
 * Validator sourceRef — dipanggil saat create/update Life Object
 * `kind:"ref"`. TIDAK PERNAH membuat/menulis object apa pun (itu
 * tanggung jawab pemanggil) — murni mengembalikan hasil validasi supaya
 * pemanggil bisa menolak pembuatan object kalau `valid:false`.
 * @param {{domain?: string, id?: string}} sourceRef
 * @returns {{valid: true} | {valid: false, error: string}}
 */
function lifeOSObjectRefValidate(sourceRef) {
  if (!sourceRef || typeof sourceRef !== 'object') {
    return { valid: false, error: 'sourceRef wajib diisi' };
  }
  const { domain, id } = sourceRef;
  if (!domain || typeof LIFEOS_OBJECT_REF_SOURCES === 'undefined' || !LIFEOS_OBJECT_REF_SOURCES[domain]) {
    return { valid: false, error: `domain "${domain || ''}" tidak terdaftar di LIFEOS_OBJECT_REF_SOURCES` };
  }
  if (!id) {
    return { valid: false, error: 'id wajib diisi' };
  }
  if (!lifeOSObjectRefExists(domain, id)) {
    return { valid: false, error: `id "${id}" tidak ditemukan di domain "${domain}"` };
  }
  return { valid: true };
}

if (typeof window !== 'undefined') {
  window.lifeOSObjectRefResolve = lifeOSObjectRefResolve;
  window.lifeOSObjectRefExists = lifeOSObjectRefExists;
  window.lifeOSObjectRefValidate = lifeOSObjectRefValidate;
}

// services/project-service.js — SATU-SATUNYA tempat menulis
// LifeOSStore.projects (generic project). Tidak pernah menulis ke
// D.renovProjects atau array D.* lain — kalau butuh baca renovasi, pakai
// adapters/project-adapter.js. Setiap fungsi di sini memanggil
// lifeOSSave() di akhir (dari lifeos-store.js).

function projectServiceCreate({ name, areaKey, dueDate = null }) {
  const store = lifeOSGetStore();
  const project = {
    id: uid(), name, areaKey, kind: 'generic', sourceRef: null,
    status: 'active', dueDate, checklist: [], goalIds: [],
    createdAt: new Date().toISOString(),
  };
  store.projects.push(project);
  return lifeOSSave().then(() => project);
}

function projectServiceAddChecklistItem(projectId, text) {
  const store = lifeOSGetStore();
  const p = store.projects.find((x) => x.id === projectId);
  if (!p) return Promise.resolve(null);
  p.checklist.push({ id: uid(), text, done: false });
  return lifeOSSave().then(() => p);
}

function projectServiceToggleChecklistItem(projectId, itemId) {
  const store = lifeOSGetStore();
  const p = store.projects.find((x) => x.id === projectId);
  const item = p && p.checklist.find((c) => c.id === itemId);
  if (!item) return Promise.resolve(null);
  item.done = !item.done;
  return lifeOSSave().then(() => item);
}

function projectServiceSetStatus(projectId, status) {
  const store = lifeOSGetStore();
  const p = store.projects.find((x) => x.id === projectId);
  if (!p) return Promise.resolve(null);
  p.status = status; // 'active' | 'done' | 'paused'
  return lifeOSSave().then(() => p);
}

function projectServiceDelete(projectId) {
  const store = lifeOSGetStore();
  store.projects = store.projects.filter((x) => x.id !== projectId);
  return lifeOSSave();
}

// services/review-service.js — SATU-SATUNYA tempat menulis
// LifeOSStore.reviewLog. Boleh MEMBACA D.wealthSnapshots/
// D.lifeBalanceSnapshots (lewat adapters/review-adapter.js) untuk
// menyimpan referensi id-nya, tapi tidak pernah menulis ke D.

function reviewServiceStartSession(period, periodKey) {
  const store = lifeOSGetStore();
  const session = {
    id: uid(), period, periodKey, completedAt: null,
    snapshotRefs: { wealthSnapshotId: null, lifeBalanceSnapshotId: null },
    notes: '', actionItems: [],
  };
  store.reviewLog.push(session);
  return lifeOSSave().then(() => session);
}

function reviewServiceComplete(sessionId, { notes = '', snapshotRefs = {} } = {}) {
  const store = lifeOSGetStore();
  const s = store.reviewLog.find((x) => x.id === sessionId);
  if (!s) return Promise.resolve(null);
  s.completedAt = new Date().toISOString();
  s.notes = notes;
  s.snapshotRefs = { ...s.snapshotRefs, ...snapshotRefs };
  return lifeOSSave().then(() => s);
}

function reviewServiceAddActionItem(sessionId, text) {
  const store = lifeOSGetStore();
  const s = store.reviewLog.find((x) => x.id === sessionId);
  if (!s) return Promise.resolve(null);
  s.actionItems.push({ id: uid(), text, done: false });
  return lifeOSSave().then(() => s);
}

// services/knowledge-service.js — SATU-SATUNYA tempat menulis
// LifeOSStore.knowledge. Tidak pernah menulis ke D.catatan — kalau butuh
// baca catatan lama, pakai adapters/knowledge-adapter.js
// (knowledgeAdapterCatatanRef).

function knowledgeServiceSave({ sourceKind, title, content, tags = [], relatedRefs = [] }) {
  const store = lifeOSGetStore();
  const entry = {
    id: uid(), createdAt: new Date().toISOString(),
    sourceKind, title, content, tags, relatedRefs,
  };
  store.knowledge.push(entry);
  return lifeOSSave().then(() => entry);
}

function knowledgeServiceUpdateTags(entryId, tags) {
  const store = lifeOSGetStore();
  const k = store.knowledge.find((x) => x.id === entryId);
  if (!k) return Promise.resolve(null);
  k.tags = tags;
  return lifeOSSave().then(() => k);
}

function knowledgeServiceDelete(entryId) {
  const store = lifeOSGetStore();
  store.knowledge = store.knowledge.filter((x) => x.id !== entryId);
  return lifeOSSave();
}

// services/life-object-service.js — SATU-SATUNYA tempat menulis
// LifeOSStore.objects (Life Object). Sesi 58 (Batch 4, lanjutan Sesi 57 —
// registry+resolver+validator sourceRef). Tidak pernah menulis ke D atau
// array D.* lain. Setiap fungsi tulis di sini memanggil lifeOSSave() di
// akhir (dari lifeos-store.js) — SAMA POLA dgn project-service.js.
//
// Scope MVP sesi ini: HANYA 2 kind yang didukung, `kind:"generic"` &
// `kind:"ref"` (kind lain BELUM didesain — ditolak eksplisit dgn
// validation error, bukan diterima diam-diam):
//   - kind:"generic" -> sourceRef SELALU dipaksa `null`, tidak pernah
//     divalidasi via lifeOSObjectRefValidate() (tidak ada sourceRef utk
//     divalidasi) — pola identik dgn project kind:'generic' di
//     project-service.js.
//   - kind:"ref"     -> sourceRef WAJIB lolos lifeOSObjectRefValidate()
//     (lifeos-object-ref.js) SEBELUM object dibuat/diupdate. Kalau gagal,
//     balik `{valid:false, error:'...'}` dan TIDAK PERNAH menulis apa
//     pun ke store (kontrak sama persis dgn lifeOSObjectRefValidate()
//     sendiri — lihat docs/PRODUCT_DECISIONS.md § LifeOS — Life Object
//     sourceRef).
//
// create()/update() balik Promise<{valid:true, object} | {valid:false,
// error}> (beda dari project-service.js yang balik object/null langsung)
// KARENA di sini validasi bisa gagal dgn alasan yang perlu ditunjukkan ke
// pemanggil (mis. ke UI di sesi lanjutan) — bukan sekadar "ketemu/tidak
// ketemu" spt project-service.js. delete()/get()/list() tetap pola lama
// (delete() balik Promise dari lifeOSSave(), get()/list() sync, TIDAK ada
// UI yang mengonsumsi ini di sesi ini — CRUD service layer saja).

const LIFE_OBJECT_KINDS = ['generic', 'ref'];

function _lifeObjectValidateInput({ name, areaKey, kind, sourceRef }) {
  if (!name) return { valid: false, error: 'name wajib diisi' };
  if (!areaKey) return { valid: false, error: 'areaKey wajib diisi' };
  if (LIFE_OBJECT_KINDS.indexOf(kind) === -1) {
    return { valid: false, error: `kind "${kind}" tidak didukung (hanya 'generic'|'ref')` };
  }
  if (kind === 'ref') {
    const refCheck = typeof lifeOSObjectRefValidate === 'function'
      ? lifeOSObjectRefValidate(sourceRef)
      : { valid: false, error: 'lifeOSObjectRefValidate belum ter-load' };
    if (!refCheck.valid) return refCheck;
  }
  return { valid: true };
}

function lifeObjectServiceCreate({ name, areaKey, kind = 'generic', sourceRef = null } = {}) {
  const check = _lifeObjectValidateInput({ name, areaKey, kind, sourceRef });
  if (!check.valid) return Promise.resolve(check);

  const store = lifeOSGetStore();
  const object = {
    id: uid(),
    name,
    areaKey,
    kind,
    sourceRef: kind === 'ref' ? sourceRef : null,
    createdAt: new Date().toISOString(),
  };
  store.objects.push(object);
  return lifeOSSave().then(() => ({ valid: true, object }));
}

function lifeObjectServiceUpdate(id, { name, areaKey, kind, sourceRef } = {}) {
  const store = lifeOSGetStore();
  const obj = store.objects.find((x) => x.id === id);
  if (!obj) return Promise.resolve({ valid: false, error: `Life Object "${id}" tidak ditemukan` });

  const nextName = name !== undefined ? name : obj.name;
  const nextAreaKey = areaKey !== undefined ? areaKey : obj.areaKey;
  const nextKind = kind !== undefined ? kind : obj.kind;
  const nextSourceRef = sourceRef !== undefined ? sourceRef : obj.sourceRef;

  const check = _lifeObjectValidateInput({ name: nextName, areaKey: nextAreaKey, kind: nextKind, sourceRef: nextSourceRef });
  if (!check.valid) return Promise.resolve(check);

  obj.name = nextName;
  obj.areaKey = nextAreaKey;
  obj.kind = nextKind;
  obj.sourceRef = nextKind === 'ref' ? nextSourceRef : null;
  return lifeOSSave().then(() => ({ valid: true, object: obj }));
}

function lifeObjectServiceDelete(id) {
  const store = lifeOSGetStore();
  store.objects = store.objects.filter((x) => x.id !== id);
  return lifeOSSave();
}

function lifeObjectServiceGet(id) {
  const store = lifeOSGetStore();
  return store.objects.find((x) => x.id === id) || null;
}

function lifeObjectServiceList() {
  const store = lifeOSGetStore();
  return store.objects.slice();
}

// ui/lifeos-home.js — halaman masuk Life OS. Hanya membaca lewat adapter,
// menulis (kalau ada aksi) hanya lewat services/*.js. Tidak pernah akses D
// atau LifeOSStore langsung dari file UI — selalu lewat adapter/service.
//
// CATATAN NAVIGASI (keputusan sesi ini): LifeOS BUKAN page terpisah — dia
// section di dalam #page-dashboard-hub (lihat index.html/app_production.html
// wrapper #lifeOSWrap). showPage() tidak dipakai sama sekali di sini karena
// showPage() akses document.getElementById('page-'+name) TANPA null-check
// (lihat modal-navigasi.js) dan renderPageContent() (modules-render.js)
// tidak punya case untuk page LifeOS — menambah case di situ berarti
// mengubah modul lama, dilarang. Sebagai gantinya dipakai switchPanel()
// lokal, cuma toggle class 'u-dnone' (utility class yang sudah ada) di
// antara panel-panel sibling di dalam #lifeOSWrap. Router lama tidak
// disentuh sama sekali.

// Preferensi tampil/sembunyi section Life OS di Dashboard Hub (Setelan →
// Profil & Tampilan → 🌱 Life OS di Dashboard Hub). Disimpan di localStorage
// (bukan D atau LifeOSStore) — pola sama persis dengan `dashHubMainTab`
// (lihat dashboard-hub.js applyMainTab()): preferensi tampilan murni,
// bukan data pengguna, jadi tidak perlu ikut siklus save()/IDBStore.
// DEFAULT: false (tersembunyi) — LifeOS sebelumnya sengaja disembunyikan
// permanen lewat class u-dnone hardcoded di index.html/app_production.html
// (lihat komentar lama di situ); default ini menjaga perilaku existing user
// tetap sama persis sebelum mereka aktifkan sendiri lewat Setelan.
const LIFEOS_VISIBLE_KEY = 'lifeOSVisible';

const LifeOSHome = {
  isVisiblePref() {
    return localStorage.getItem(LIFEOS_VISIBLE_KEY) === '1';
  },

  /** Terapkan preferensi ke DOM (#lifeOSWrap) — dipanggil dari render() di
   * bawah, dan juga langsung dari toggleVisibility() saat user klik switch
   * di Setelan supaya efeknya langsung terlihat tanpa perlu buka ulang
   * Dashboard Hub. */
  applyVisibility() {
    const wrap = document.getElementById('lifeOSWrap');
    if (!wrap) return;
    wrap.classList.toggle('u-dnone', !this.isVisiblePref());
  },

  /** Dipanggil dari toggle switch di Setelan (id=lifeOSVisibleToggle, lihat
   * index.html/app_production.html stgGroup1). Tidak perlu await apa pun —
   * localStorage synchronous — supaya switch terasa instan. */
  toggleVisibility(checked) {
    localStorage.setItem(LIFEOS_VISIBLE_KEY, checked ? '1' : '0');
    this.applyVisibility();
    // Kalau baru dinyalakan dan grid belum pernah terisi (mis. user aktifkan
    // pertama kali di sesi ini), render sekarang juga supaya tidak muncul
    // section kosong sebelum Dashboard Hub dibuka ulang.
    const grid = document.getElementById('lifeOSHomeGrid');
    if (checked && grid && !grid.innerHTML.trim()) this.render();
    if (typeof toast === 'function') {
      toast(checked ? '🌱 Life OS ditampilkan di Dashboard Hub' : '🌱 Life OS disembunyikan dari Dashboard Hub');
    }
  },

  async render() {
    this.applyVisibility();
    const el = document.getElementById('lifeOSHomeGrid');
    if (!el) return;
    if (!this.isVisiblePref()) return; // tersembunyi -> tidak perlu hitung/render isinya sama sekali.

    await lifeOSEnsureLoaded();

    const store = lifeOSGetStore();

    const today = todayAdapterList(D);
    const goals = goalAdapterList(D);
    const projects = projectAdapterList(D, store);
    const knowledge = knowledgeAdapterList(store);
    const areas = areaAdapterList(D);
    const lifeObjects = typeof lifeObjectServiceList === 'function' ? lifeObjectServiceList() : [];
    const plugins = typeof LifeOSPluginRegistry !== 'undefined' ? LifeOSPluginRegistry.list() : [];
    // Reuse reviewAdapterIsOverdue() (review-adapter.js, sudah dipakai
    // LifeOSReview.render()) supaya caption kartu Review di grid ini juga
    // data-driven lewat adapter — bukan teks statis "Weekly/Monthly" yang
    // tidak mencerminkan status sebenarnya.
    const reviewOverdueCount = ['weekly', 'monthly'].filter((period) => {
      const threshold = period === 'weekly' ? 7 : 30;
      return reviewAdapterIsOverdue(store, period, threshold);
    }).length;

    // Reuse class dashhub-feature-card/-name (sudah ada di styles.css,
    // dipakai DashboardHub.render()) + modifier --icon (icon-grid) supaya
    // konsisten dgn grid fitur utama — sengaja, supaya tidak perlu CSS
    // baru selain .dashhub-feature-count kecil utk angka count (info yang
    // sebelumnya ada di .dashhub-feature-desc, tetap dipertahankan, cuma
    // dipindah ke caption pendek di bawah nama).
    //
    // Sesi 39 (target eksplisit user: "Executive Dashboard Integration"):
    // kartu "Area Summary" ditambahkan di sini — area-adapter.js sudah ada
    // & sudah dites sejak Sesi 24 tapi sebelumnya TIDAK PERNAH dikonsumsi
    // UI manapun. Sekarang seluruh 6 adapter LifeOS (area/today/goal/
    // project/review/knowledge) benar-benar terpakai di satu grid ini.
    el.innerHTML = `
      <div class="dashhub-feature-card dashhub-feature-card--icon" data-action="LifeOSHome.switchPanel" data-args='["today"]'>
        <div class="dashhub-feature-icon">📅</div>
        <div class="dashhub-feature-name">Today</div>
        <div class="dashhub-feature-count">${today.length} item</div>
      </div>
      <div class="dashhub-feature-card dashhub-feature-card--icon" data-action="LifeOSHome.switchPanel" data-args='["goals"]'>
        <div class="dashhub-feature-icon">🎯</div>
        <div class="dashhub-feature-name">Goals</div>
        <div class="dashhub-feature-count">${goals.length} goal</div>
      </div>
      <div class="dashhub-feature-card dashhub-feature-card--icon" data-action="LifeOSHome.switchPanel" data-args='["projects"]'>
        <div class="dashhub-feature-icon">📁</div>
        <div class="dashhub-feature-name">Projects</div>
        <div class="dashhub-feature-count">${projects.length} project</div>
      </div>
      <div class="dashhub-feature-card dashhub-feature-card--icon" data-action="LifeOSHome.switchPanel" data-args='["review"]'>
        <div class="dashhub-feature-icon">🔁</div>
        <div class="dashhub-feature-name">Review</div>
        <div class="dashhub-feature-count">${reviewOverdueCount > 0 ? reviewOverdueCount + ' jatuh tempo' : 'Up to date'}</div>
      </div>
      <div class="dashhub-feature-card dashhub-feature-card--icon" data-action="LifeOSHome.switchPanel" data-args='["knowledge"]'>
        <div class="dashhub-feature-icon">💡</div>
        <div class="dashhub-feature-name">Knowledge</div>
        <div class="dashhub-feature-count">${knowledge.length} insight</div>
      </div>
      <div class="dashhub-feature-card dashhub-feature-card--icon" data-action="LifeOSHome.switchPanel" data-args='["areas"]'>
        <div class="dashhub-feature-icon">🗂️</div>
        <div class="dashhub-feature-name">Area Summary</div>
        <div class="dashhub-feature-count">${areas.length} area</div>
      </div>
      <div class="dashhub-feature-card dashhub-feature-card--icon" data-action="LifeOSHome.switchPanel" data-args='["life-objects"]'>
        <div class="dashhub-feature-icon">🧩</div>
        <div class="dashhub-feature-name">Life Object</div>
        <div class="dashhub-feature-count">${lifeObjects.length} object</div>
      </div>
      <div class="dashhub-feature-card dashhub-feature-card--icon" data-action="LifeOSHome.switchPanel" data-args='["plugins"]'>
        <div class="dashhub-feature-icon">🔌</div>
        <div class="dashhub-feature-name">Plugin</div>
        <div class="dashhub-feature-count">${plugins.length} plugin</div>
      </div>
    `;

    // Render tiap panel sekali di sini (skala data personal, murah). Yang
    // aktif/terlihat ditentukan switchPanel() lewat CSS class, bukan re-render.
    if (typeof LifeOSToday !== 'undefined') LifeOSToday.render();
    if (typeof LifeOSGoals !== 'undefined') LifeOSGoals.render();
    if (typeof LifeOSProjects !== 'undefined') LifeOSProjects.render();
    if (typeof LifeOSReview !== 'undefined') LifeOSReview.render();
    if (typeof LifeOSKnowledge !== 'undefined') LifeOSKnowledge.render();
    if (typeof LifeOSAreas !== 'undefined') LifeOSAreas.render();
    if (typeof LifeOSLifeObjects !== 'undefined') LifeOSLifeObjects.render();
    if (typeof LifeOSPlugins !== 'undefined') LifeOSPlugins.render();
  },

  switchPanel(name) {
    const panels = ['today', 'goals', 'projects', 'review', 'knowledge', 'areas', 'life-objects', 'plugins'];
    panels.forEach((p) => {
      const panelEl = document.getElementById('lifeOSPanel-' + p);
      if (panelEl) { panelEl.classList.toggle('u-dnone', p !== name); panelEl.style.display = ''; }
    });
  },
};
if (typeof LifeOSHome !== 'undefined') window.LifeOSHome = LifeOSHome;

// ui/areas.js — render-only lewat areaAdapterList(D). Ringkasan jumlah
// item per AREA (lihat adapters/area-adapter.js — LIFEOS_AREAS,
// lifeos-registry.js). Sebelum Sesi 39, area-adapter.js sudah ADA & sudah
// dites (Sesi 24) tapi TIDAK PERNAH dikonsumsi UI manapun — bagian dari
// "Executive Dashboard Integration" (target eksplisit user Sesi 39) yang
// melengkapi LifeOSHome supaya SEMUA 6 adapter (area/today/goal/project/
// review/knowledge) benar-benar terpakai sebagai satu pintu masuk.
//
// Beda dari Today/Goals/Projects: 1 Area = gabungan BANYAK dSources
// sekaligus (bukan 1 item -> 1 sumber tunggal), jadi tidak ada
// sourceKind/sourceId per-entri utk lifeOSNavigateToSource() — murni
// ringkasan angka, tanpa aksi/navigasi apa pun (read-only agregat).
//
// Sesi 281 (KNOWN-ISSUES.md §4.1): ikon area sebelumnya emoji literal
// (escapeHtml(a.icon)) — sekarang lewat FeatureIcons.render() (pola
// SAMA PERSIS dashboard-hub.js/dashboard-hub-search.js), konsisten
// dgn ikon fitur lain di app. `a.icon` bersumber dari LIFEOS_AREAS
// (lifeos-registry.js) — data statis terdaftar di source, BUKAN input
// user, jadi aman dipakai tanpa escapeHtml (sama seperti FEATURE_REGISTRY
// yang juga tidak di-escape). Guard `typeof FeatureIcons` menjaga
// fallback ke emoji asli kalau file belum di-load / emoji belum
// terpetakan di `_MAP` (0 kemungkinan kosong/pecah).

const LifeOSAreas = {
  render() {
    const el = document.getElementById('lifeOSAreasGrid');
    if (!el) return;
    const areas = areaAdapterList(D);
    el.innerHTML = areas.length
      ? areas.map((a) => `
        <div class="lifeos-area-card">
          <div class="lifeos-area-icon">${(typeof FeatureIcons !== 'undefined') ? FeatureIcons.render(a.icon || '🗂️') : escapeHtml(a.icon || '🗂️')}</div>
          <div class="lifeos-area-name">${escapeHtml(a.label || '')}</div>
          <div class="lifeos-area-count">${a.itemCount} item</div>
        </div>
      `).join('')
      : '<div class="empty"><div class="empty-text">Belum ada data area</div></div>';
  },
};

// ui/today.js — render-only lewat todayAdapterList(D). Aksi "selesaikan"
// tetap dispatch ke fungsi modul LAMA (mis. dismiss bill), Life OS tidak
// menduplikasi logic itu.

const LifeOSToday = {
  render() {
    const el = document.getElementById('lifeOSTodayList');
    if (!el) return;
    const items = todayAdapterList(D);
    el.innerHTML = items.length
      ? items.map((it) => `
        <div class="lifeos-today-item u-pointer" data-action="lifeOSNavigateToSource" data-args='${escapeHtml(JSON.stringify([it.sourceKind, it.sourceId]))}' title="Buka referensi data">
          <div class="lifeos-today-label">${escapeHtml(it.label || '')}</div>
          ${it.dueDate ? `<div class="lifeos-today-due">${escapeHtml(it.dueDate)}</div>` : ''}
        </div>
      `).join('')
      : '<div class="empty"><div class="empty-text">Tidak ada item hari ini</div></div>';
  },
};

// ui/goals.js — render-only lewat goalAdapterList(D). Tidak ada
// goal-service.js karena Goals tidak punya data tulis sendiri di Life OS
// (murni agregasi 6 sumber lama, lihat Gap #2). Aksi "tambah tabungan"
